CREATE TEMP TABLE import_courses (code TEXT, name TEXT, credits_min INTEGER, credits_max INTEGER, description TEXT, prerequisite_text TEXT, corequisite_text TEXT, prerequisites_complete BOOLEAN, gen_ed_text TEXT, restriction_text TEXT, credit_only_granted_for TEXT, catalog_year TEXT, source_url TEXT, prerequisite_status TEXT, gen_ed_status TEXT, gen_ed_term TEXT, formerly TEXT, cross_listed_with TEXT, jointly_offered_with TEXT, repeatable_to TEXT, recommended TEXT, additional_information TEXT) ON COMMIT DROP;
INSERT INTO import_courses (code, name, credits_min, credits_max, description, prerequisite_text, corequisite_text, prerequisites_complete, gen_ed_text, restriction_text, credit_only_granted_for, catalog_year, source_url, prerequisite_status, gen_ed_status, gen_ed_term, formerly, cross_listed_with, jointly_offered_with, repeatable_to, recommended, additional_information) VALUES
    ('AAAS100', 'Introduction to African American and Africana Studies', 3, 3, 'Significant aspects of the history of African Americans with particular emphasis on the evolution and development of black communities from slavery to the present. Interdisciplinary introduction to social, political, legal and economic roots of contemporary problems faced by blacks in the United States with applications to the lives of other racial and ethnic minorities in the Americas and in other societies.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'AASP100 or AAAS100.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'verified', '202608', 'AASP100.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS101', 'Public Policy and the Black Community', 3, 3, 'The impact of public policies on the Black community and the role of the policy process in affecting the social, economic and political well-being of minorities. Particular attention given to the post-1960 to present era.', NULL, NULL, TRUE, 'DSHS', NULL, 'AASP101 or AAAS101.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'verified', '202608', 'AASP101.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS187', 'The New Jim Crow: African-Americans, Mass Incarceration and the Prison Industrial Complex', 3, 3, 'Students will examine the birth of the racial caste system following the abolition of slavery, the parallels between the racial hierarchy of the Jim Crow system and contemporary mass incarceration, and the rise of the prison industrial complex as a multi-billon business which thrives on the oppression of low-income populations and poor communities of color.', NULL, NULL, TRUE, 'DSHS, DVUP, SCIS', NULL, 'AASP187 or AAAS187.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'verified', '202608', 'AASP187.', NULL, NULL, NULL, 'AASP100.', NULL),
    ('AAAS190', 'HIV/AIDS in a Global Perspective', 3, 3, 'Who is getting infected with HIV/AIDS? Who is dying from it? These are two questions that feature prominently on both the domestic and international health agendas. Even though the statistics from Africa garner the greatest global attention, the situation in the US, in particular the DC/Baltimore area and among certain groups, has recently raised concern and intensified the call for action. The goal of this "I" course is to engage students in a critical examination of 1) the factors that put people at risk for getting infected and 2) the factors that determine the type of treatment that people receive in the US as well as globally with a particular focus on Africa and the African diaspora.', NULL, NULL, TRUE, NULL, NULL, 'AASP189I or AAAS190.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'AASP189I.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS200', 'African Civilization', 3, 3, 'A survey of African civilizations from 4500 B.C. to present. Analysis of traditional social systems. Discussion of the impact of European colonization on these civilizations. Analysis of the influence of traditional African social systems on modern African institutions as well as discussion of contemporary processes of Africanization.', NULL, NULL, TRUE, 'DSHU', NULL, 'AASP200 or AAAS200.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'verified', '202608', 'AASP200.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS202', 'Black Culture in the United States', 3, 3, 'The course examines important aspects of African American life and thought which are reflected in African American literature, drama, music and art. Beginning with the cultural heritage of slavery, the course surveys the changing modes of Black creative expression from the 19th-century to the present.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'AASP202 or AAAS202.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'verified', '202608', 'AASP202.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS210', 'Intro to Research Design and Analysis in African American and Africana Studies', 3, 3, 'Introduces students to quantitative and qualitative research methods used in social science with a focus on Black populations and African American Studies Research. Uses practical exercises, such as class surveys and mock focus groups, to examine fundamental concepts of the research process from conceptualization of research questions to interpretation of data and research articles. The course is designed for undergraduate students with little or no background knowledge in social science research methods.', NULL, NULL, TRUE, NULL, NULL, 'AASP210 or AAAS210.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'AASP210.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS211', 'Get Out: The Sunken Place of Race Relations in the Post-Racial Era', 3, 3, 'Prevailing thought suggests that we live in an era that is post-racial, particularly after the election of Barack Obama. Media often serves to drive our assessment of where our nation stands on issues like race, gender and sexuality. This course uses the film Get Out to delve into the production, evolution and significance of race in present day America. The course will engage multiple forms of media to investigate life in "Post-Racial" America, including but not limited to the role of stereotypes, interracial relationships, police-community relations, etc.', NULL, NULL, TRUE, 'DSHS, DVUP, SCIS', NULL, 'AASP211 or AAAS211.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'verified', '202608', 'AASP211.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS230', 'Social (In)Justice and African-American Health and Well-Being', 3, 3, 'African Americans suffer worse outcomes than non-Hispanic whites on nearly every health measure and outcomes that link to overall well-being like depressive symptoms or homicides. Health disparities are experienced by other underrepresented minority groups, but because of the unique historic and current experiences of African Americans, the determinants and solutions to African American health disparities are unique. The premise of this course is that African American health disparities are due to social injustices perpetuated on the institutional level that have permeated the lived experiences of African Americans leading to racial disparities in health and well-being. As such, the solutions on the both policy, and community, level must have a social justice approach.', NULL, NULL, TRUE, 'DSHS, DVUP, SCIS', NULL, 'AASP230 or AAAS230.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'verified', '202608', 'AASP230.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS234', 'African-American Literature and Culture', 3, 3, 'An exploration of the stories black authors tell about themselves, their communities, and the nation as informed by time and place, gender, sexuality, and class. African American perspective themes such as art, childhood, sexuality, marriage, alienation and mortality, as well as representations of slavery, Reconstruction, racial violence and the Nadir, legalized racism and segregation, black patriotism and black ex-patriots, the optimism of integration, and the prospects of a post-racial America.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, 'ENGL234, AAAS234 or AASP298L.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'verified', '202608', NULL, 'ENGL234.', NULL, NULL, NULL, NULL),
    ('AAAS254', 'African-American History to 1865', 3, 3, 'Survey of the principal developments in the history and culture of the peoples of African descent in colonial North America and the United States to 1865. Examines the African past, the Atlantic slave trade, variation in slavery, the growth of free black communities, the transformations of families and cultural forms, and patterns of resistance.', NULL, NULL, TRUE, 'DVUP', NULL, 'HIST254, AAAS254 or AASP298C.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'verified', '202608', NULL, 'HIST254.', NULL, NULL, NULL, NULL),
    ('AAAS255', 'African-American History, 1865 - Present', 3, 3, 'An introductory course in the African-American experience in the United States from 1865 to the present. Topics include the aftermath of the Civil War on US race relations, the rise of segregation, northern migration, World War I and II, Civil Rights Movements, and the Black Power Movement.', NULL, NULL, TRUE, NULL, NULL, 'HIST255, AASP255, AAAS255 or AASP298A.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, NULL, 'HIST255.', NULL, NULL, NULL, NULL),
    ('AAAS260', 'Africa in World Politics', 3, 3, 'Introduction to the politics of Africa, especially Sub-Saharan Africa, on the world stage from the colonial period era to recent push towards democracy in Africa and the rise of religious extremism. It also engages such themes as culture, religion and progress, dictatorship, former colonial powers and international influence, etc.', NULL, NULL, TRUE, NULL, NULL, 'AASP260 or AAAS260 .', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'AASP260.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS263', 'Introduction to Black Women''s Studies', 3, 3, 'Interdisciplinary exploration of Black women, culture and society in the United States. Drawn primarily from the social sciences and history with complementary material from literature and the arts.', NULL, NULL, TRUE, NULL, NULL, 'WMST263, AASP298I, WGSS263, AAAS263 or AASP263.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'WMST263.', 'WGSS263.', NULL, NULL, NULL, NULL),
    ('AAAS264', 'Quare/Queer Contentions: Exploration of Sexualities in the Black Community', 3, 3, 'Centering the subjectivities of queer people of color generally and more specifically, Black people (as the word "quare" invites us to do), Quare/Queer Contentions takes up key moments within the history of the Black community and asks us to consider the work and presence of LGBTQ people in these moments. The course also contends with the everyday experiences of LGBTQ subjects in the Black community. Quare/Queer Contentions, therefore, interrogates the material realities of Black queer people in the context of family, religion, cultural/creative work, among others. Interdisciplinary in orientation, the course will employ primary and secondary texts, film, art, autobiographical narratives and policy data.', NULL, NULL, TRUE, NULL, NULL, 'LGBT264, AASP264, AAAS264, WMST264 or WGSS264.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, NULL, 'LGBT264, WGSS264.', NULL, NULL, NULL, NULL),
    ('AAAS265', 'Constructions of Manhood and Womanhood in the Black Community', 3, 3, 'Investigates the ways that African Americans are represented and constructed in public and private spheres and explores the social constructions and representations of Black manhood and womanhood from various disciplinary perspectives.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'WMST265, AASP298B, AAAS265, WGSS265 or AASP265.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'verified', '202601', 'WMST265.', 'WGSS265.', NULL, NULL, NULL, NULL),
    ('AAAS271', 'Monsters and Racism: Black Horror and Speculative Fiction', 3, 3, 'The previous decade has been considered a renaissance for Black Horror. From Get Out to Lovecraft Country, the genre has enjoyed unprecedented mainstream media buzz and accolades. This course looks at contemporary Black horror and speculative fiction as cultural texts which put into question our notions of human(e) and inhuman(e) through critiques of white supremacy and accompanying oppressions. Students will learn a host of critical skills through close reading and analysis of literature and film by Black creators such as Jordan Peele, Misha Green, Toni Morrison, Jewelle Gomez, and Octavia Butler. With the ability to interpret cultural texts using literary criticism, film analysis, history, cultural studies, ethnic studies, feminist theory, and the social sciences, students will connect these texts to continuing historical and contemporary issues of racial and cultural oppression such as medical discrimination, policing and criminalization, misogynoir, and racialized capitalism.', NULL, NULL, TRUE, 'DSHU', NULL, 'AAAS271, ENGL289J, HONR299Y, HNUH238W, WGSS271 or WGSS298W.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'verified', '202608', 'HNUH238W.', 'WGSS271, ENGL289J.', NULL, NULL, NULL, NULL),
    ('AAAS297', 'Research Methods in African American and Africana Studies', 3, 3, 'Introduces African American and Africana Studies majors to the basic research skills, methodologies, sources, and repositories for studying African Diaspora. Students will be required to select a research topic, write a research proposal, develop an annotated bibliography, and in the process will be prepared for completing their senior thesis or other significant writing projects necessary to fulfill the requirements of the major.', 'AAAS101 or AAAS202.', NULL, TRUE, NULL, 'Must be in African American and Africana Studies program.', 'AASP297 or AAAS297.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'parsed', 'none_found', NULL, 'AASP297.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS298', 'Special Topics in African American and Africana Studies', 3, 3, 'An introductory multi-disciplinary and inter-disciplinary educational experience to explore issues relevant to black life, cultural experiences, and political, economic, and artistic development.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'AASP298.', NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AAAS298E', 'Reproductive Justice: An Introduction', 3, 3, 'Developed by feminists of color, reproductive justice frameworks offer a roadmap for economic, social, and medical justice advocacy attentive to the intersections of race, class, gender, sexuality, and disability. This course reviews the historical, legal, and social bases of reproductive rights in the U.S.; discusses the history of feminist organizing for reproductive freedom; surveys critical theories of reproductive justice that go beyond abortion law to advocate for broader social transformation; and evaluates the possible futures of intersectional feminist activism after the overturning of Roe v. Wade.', NULL, NULL, TRUE, NULL, NULL, 'WGSS205, AMST298J, or AAAS298E.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, NULL, 'WGSS205, AMST298J.', NULL, NULL, NULL, NULL),
    ('AAAS298M', 'Martin Luther King Jr.', 3, 3, 'Examines the life and work of Martin Luther King, Jr. We immediately rethink the image of King who liberals and conservatives construct as a dreamer of better race relations. We engage the complexities of an individual, who articulated a moral compass of the nation, to explore racial justice in post-World War II America. This course gives special attention to King''s post-1965 radicalism when he called for a reordering of American society, an end to the war in Vietnam, and supported sanitation workers striking for better wages and working conditions. Topics include King''s notion of the "beloved community", the Social Gospel, liberalism, "socially conscious democracy", militancy, the politics of martyrdom, poverty and racial justice, and compensatory treatment. Primary sources form the core of our readings.', NULL, NULL, TRUE, NULL, NULL, 'HIST108C, AASP298M, AAAS298M, or AMST189C.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, NULL, 'HIST108C, AMST189C.', NULL, NULL, NULL, NULL),
    ('AAAS299', 'Selected Topics in African American and Africana Studies', 1, 3, 'An introductory multi-disciplinary academic exploration of the cultural, political, and economic issues relevant to Africans and African-Americans.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'AASP299.', NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AAAS301', 'Applied Policy Analysis and the Black Community', 3, 3, 'Development and application of the tools needed for examining the effectiveness of alternative policy options confronting minority communities. Review policy research methods used in forming and evaluating policies. Examination of the policy process.', 'AAAS101.', NULL, TRUE, NULL, NULL, 'AASP301 or AAAS301.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'parsed', 'none_found', NULL, 'AASP301.', NULL, NULL, NULL, 'Completion of one semester of statistics is recommended.', NULL),
    ('AAAS306', 'Race, Gender and Artificial Intelligence (AI)', 3, 3, 'With the recent rise of accessible AI technologies, concerns about not only the potential flaws built into technology but also the impact of those issues on already marginalized communities loom large. From medical applications of AI in the personalizing of treatment and disease diagnosis, to the use of facial recognition software in the criminal justice system, AI is being integrated into all facets of everyday life. This class will explore the intersection of Artificial Intelligence (AI), race, and gender. There will be assigned readings on race, gender, difference, algorithms, and artificial intelligence. Students will engage with AI platforms, such as ChatGPT or Peo to gain hands-on experience about the platforms and how they work.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AAAS310', 'African Slave Trade', 3, 3, 'The relationship of the slave trade of Africans to the development of British capitalism and its industrial revolution; and to the economic and social development of the Americas.', 'AAAS202 or AAAS100; or permission of BSOS-African American and Africana Studies department.', NULL, FALSE, NULL, NULL, 'AASP310 or AAAS310.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'partial', 'none_found', NULL, 'AASP310.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS311', 'History of South Africa', 3, 3, 'Explores the roots of Apartheid and the anti-Apartheid movement from precolonial times to the present: the social history of work and identity, the rise of kingdoms (Zulu, Sotho), conquest and colonial administration, urban and rural mass politics, gender relations, and the transition to democracy.', NULL, NULL, TRUE, NULL, NULL, 'HIST310 or AAAS311.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, NULL, 'HIST310.', NULL, NULL, NULL, NULL),
    ('AAAS313', 'Black Women in United States History', 3, 3, 'Black American women''s history from slavery to the present. Focused on gaining a fuller understanding of the effect of race, class and gender on the life cycles and multiple roles of Black women as mothers, daughters, wives, workers and social-change agents.', NULL, NULL, TRUE, NULL, 'Sophomore standing or higher.', 'AASP313, AAAS313, WMST314 or WGSS314.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'WMST314.', 'WGSS314.', NULL, NULL, NULL, NULL),
    ('AAAS317', 'Black in Latin America and the Caribbean', 3, 3, 'The goal of this course is to have an understanding of race, color, and blackness across the Americas. We will compare and contrast forms of racial categorization, discrimination, and ideologies, whether in the form of nation-building projects, addressing racial inequality, or sexuality and family formation. We will draw primarily on social science perspectives, including the work of sociologists and political scientists.', NULL, NULL, TRUE, NULL, NULL, 'AASP317 or AAAS317.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'AASP317.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS320', 'Poverty and African American Children', 3, 3, 'The United States has high levels of child poverty compared to other industrialized nations. Poverty rates are particularly high among African American children. This course focuses on how poverty and race intersect to influence the development of children and youth. Specific topics that we will consider include definitions of poverty, theories about the causes of poverty, racial disparities in child poverty, family functioning in the context of poverty, neighborhood influences, risk and protective processes, and social policies and programs designed to mitigate the impact of poverty.', NULL, NULL, TRUE, NULL, NULL, 'AASP320, AAAS320, AASP298P or SOCY320.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'AASP298P.', 'SOCY320.', NULL, NULL, NULL, NULL),
    ('AAAS330', 'Music of the African Diaspora: From Jazz to Modern Black Music', 3, 3, 'The goal of this course is to explore a myriad of musical traditions created by Africans in the Diaspora, especially the music of African Americans. Explorations will notably encompass the infusion of Western/Classical Music and its mixing with "Black Music." The traditions and musical styles are related to experiences of culture, history, customs, legends, aesthetic musical forms, and the functional use of this music (e.g., Blues, Jazz, Gospel, Spirituals, Black Message Music, Neo Soul, RAP, and Hip-Hop) as a cultural repository. This cultural repository has subsequently impacted American history, the arts, literature, global values, and Diaspora Studies.', NULL, NULL, TRUE, NULL, NULL, 'AASP330 or AAAS330.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'AASP330.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS350', 'Cinema of the Black Atlantic', 3, 3, 'Examines cinema from the black Atlantic world, treating key films from Africa, the Caribbean, Latin America, and the United States. Anticolonial work by Ousmane Sembene and Sarah Maldoror, memory work by Haile Gerima and Julie Dash, and vernacular filmmaking by Charles Burnett, Spike Lee, Perry Henzell, Melvin Van Peebles, and others will introduce us to the varied concerns of Black filmmakers in moments of independence struggle and post-emancipation identity formation. While eclectic in selection, our examination of these films will be oriented around a pair of questions. What is antiblackness and how does cinema encounter, contemplate, and critique it? How do different geographies and historical experiences shift cultural and political concerns, as well as the methods of cinema along with those differing concerns?', NULL, NULL, TRUE, NULL, NULL, 'AAAS350, AASP350 or CINE350.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'AASP350.', 'CINE350.', NULL, NULL, NULL, NULL),
    ('AAAS361', 'Caribbean Women', 3, 3, 'An interdisciplinary analysis of the lives and experiences of women across the Caribbean region, through an examination of their roles in individual, national, social and cultural formations. Special emphasis on contemporary women''s issues and organizations.', NULL, NULL, TRUE, NULL, NULL, 'WGSS360, WMST360, AAAS361 or AASP361.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'WMST360.', 'WGSS360.', NULL, NULL, NULL, NULL),
    ('AAAS370', 'Spike Lee''s Joints', 3, 3, 'In offering extended formal considerations of Spike Lee''s cinematic oeuvre--in particular his uses of light, sound, and color--this course is interested in how various modes of critical inquiry can enable or broaden our cultural, political, or historical engagement with a film. We will pay special attention to the question of what it means to encapsulate a specific cultural moment, particularly in relation to differing demands of fictional and non-fictional representation, in sound and image. As well, we will attend to how Lee''s aesthetic techniques, cultural politics, and wide-ranging critique of the American racial caste system helps us think about the role of film in ongoing struggles for racial justice.', NULL, NULL, TRUE, NULL, NULL, 'AASP370, AAAS370, or CINE353.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'AASP370.', 'CINE353.', NULL, NULL, NULL, NULL),
    ('AAAS371', 'Black Feminist Thought', 3, 3, 'Examines the ideas, words and actions of Black women writers, speakers, artists, and activists in the United States.', '1 course in AASP; or 1 course in WGSS.', NULL, FALSE, NULL, NULL, 'WMST370, WGSS370, AAAS371 or AASP371.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'unstructured', 'none_found', NULL, 'WMST370.', 'WGSS370.', NULL, NULL, NULL, NULL),
    ('AAAS386', 'Experiential Learning', 3, 6, 'Updating course code to align with department name change', NULL, NULL, TRUE, NULL, 'Permission of BSOS-African American and Africana Studies department; and junior standing or higher.', 'AASP386 or AAAS386.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'AASP386.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS395', 'Fundamentals of Quantitative Research in Socio-Cultural Perspective', 3, 3, 'Introduction to quantitative methods for African American and Africana Studies majors in the cultural and social analysis concentration. Basics of survey design and experimental design and data analysis and use of statistical software programs.', NULL, NULL, TRUE, NULL, 'Must be in African American and Africana Studies program; and junior standing or higher.', 'AASP395 or AAAS395.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'AASP395.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS397', 'Senior Thesis', 3, 3, 'Directed research in African American Studies resulting in the completion and defense of a senior thesis.', NULL, NULL, TRUE, NULL, 'Permission of BSOS-African American and Africana Studies department.', 'AASP397 or AAAS397.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'AASP397.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS398', 'Selected Topics in the African Diaspora', 3, 3, 'Analysis of the historical experiences and cultures of African-descendant peoples globally.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'AASP398.', NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AAAS399', 'Research in African-American and Africana Studies', 1, 3, 'African American Studies research labs are the settings in which the most recent scholarly work of each faculty member takes place with the enterprise of conducting and disseminating research. Faculty members operate as the team leader and faculty mentor working with undergraduate students around a specific research topic or project. Students will have the opportunity to assist with reviewing literature, data gathering, data management, coding analysis, and the preparation of conference presentations and scholarly publications while advancing their own scholarship and interests, cultivating integrative skills, and gain training in a specialized aspect of the African American Studies discipline, which may not be otherwise available from other experiences on campus.', 'Two of the following courses: AAAS100, AAAS101, AAAS200, or AAAS202.', NULL, FALSE, NULL, 'Must be in the Africa-American and Africana Studies major; and must have completed 30 credits; and must have earned a minimum cumulative GPA of 2.00.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'unstructured', 'none_found', NULL, 'AASP399.', NULL, NULL, '6 credits.', 'AASP210 or equivalent.', NULL),
    ('AAAS400', 'Directed Readings in African American and Africana Studies', 3, 3, 'The readings will be directed by the faculty of African American Studies. Topics to be covered will be chosen to meet the needs and interests of individual students.', 'AAAS202 or AAAS100.', NULL, TRUE, 'DSHS, DVUP', NULL, 'AASP400 or AAAS400.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'parsed', 'verified', '202608', 'AASP400.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS402', 'Classic Readings in African American and Africana Studies', 3, 3, 'Classic readings of the social, economic and political status of Blacks and other minorities in the United States and the Americas.', 'AAAS202 or AAAS100.', NULL, TRUE, NULL, NULL, 'AASP402 or AAAS402.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'parsed', 'none_found', NULL, 'AASP402.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS403', 'The Development of a Black Aesthetic', 3, 3, 'An analysis of selected areas of black creative expression in the arts for the purpose of understanding the informing principles of style, techniques, and cultural expression which make up a Black aesthetic.', 'ENGL443 or AAAS302; or permission of instructor.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AAAS410', 'Contemporary African Ideologies', 3, 3, 'Analysis of contemporary African ideologies. Emphasis on philosophies of Nyerere, Nkrumah, Senghor, Sekou Toure, Kaunda, Cabral, et al. Discussion of the role of African ideologies on modernization and social change.', NULL, NULL, TRUE, NULL, NULL, 'AASP410 or AAAS410.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'AASP410.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS411', 'Black Resistance Movements', 3, 3, 'A comparative study of the Black resistance movements in Africa and America; analysis of their interrelationships as well as their impact on contemporary pan-Africanism.', 'AAAS100.', NULL, TRUE, NULL, NULL, 'AASP411 or AAAS411.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'parsed', 'none_found', NULL, 'AASP411.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS413', 'Gentrification: Have You Met the New Neighbors?: Issues of Belonging and Displacement in Urban Areas', 3, 3, 'Explores and considers current scholarship on the history, modes and implications of the process of gentrification in various areas within the United States. The course will engage with history, culture, and policy factors related to the redevelopment of urban areas. Course texts will be interdisciplinary in their methodology and genre, and will include themes of race, gender, and class. These texts, combined with student engagement, class discussion, and directed assignments will help to develop a theoretical framework for the understanding of gentrification as systematic, profound and in most if not all cases, irreversibly detrimental.', NULL, NULL, TRUE, NULL, NULL, 'AASP413 or AAAS413.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'AASP413.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS414', 'History of Women and Gender in Africa', 3, 3, 'An examination of socio-economic and cultural change in Africa from the dawn of the colonial era in the 19th century to independence in the mid-twentieth century. Major focus on how African women understood and responded to the expansion of European empires, changes in the colonial economy, and impact of westernization and urbanization.', NULL, NULL, TRUE, NULL, NULL, 'HIST412 or AAAS414.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, NULL, 'HIST412.', NULL, NULL, NULL, NULL),
    ('AAAS416', 'Black Queer Studies', 3, 3, 'Black Queer Studies is an intersectional and interdisciplinary approach to LGBTQ+ Studies and Black Studies. In this course, we will center Blackness to meditate upon the overlapping and interwoven categories of race, gender, and sexuality with the goal of decoupling whiteness from LGBTQ+ studies and decoupling heterosexuality from Black studies. We will look at texts from the humanities and social sciences as well literature and film in order to trace topical trajectories of Black queer thought. We will explore the meaning of queerness in relation to blackness, touch upon moments in black queer history, analyze questions of black queer representation and erasure, and press upon "hot button" topics such as queer identity and the black church, African and global queer and trans identities, Blackness and homophobia, white LGBTQ+ racism, and Black queer pleasure. Throughout we will consider how Black queer liberation can and has provided tools and a guide for our collective liberation.', NULL, NULL, TRUE, NULL, NULL, 'LGBT411, WGSS411, LGBT448L, or AAAS416.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'LGBT448L.', 'LGBT411, WGSS411.', NULL, NULL, NULL, NULL),
    ('AAAS417', 'Emotions and Culture in the African American Community', 3, 3, 'This course introduces students to the role of culture and racism in shaping the ways in which African Americans experience, express, understand, and control emotions on a behavioral, physiological, and psychological level. We will begin with exploration of historical influences such as the role of African culture on contemporary African American norms of expressivity and the role of antebellum slavery, the eugenics movement, and blackface on stimulating contemporary stereotypes about African American emotional temperament (e.g., stereotypes regarding aggressiveness, anger, and violence). We will conclude with discussions of the impact of discrimination on emotional and physiological reactivity and factors that promote emotional resiliency. Students will grapple with the contemptuous disconnect between the African American cultural tradition of free emotional expressivity and the survival strategy to control emotions in response to a society threatened by Black emotionality.', NULL, NULL, TRUE, NULL, NULL, 'AASP417, AASP498E, PSYC498O, or SOCY417.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'AASP498E and AASP417.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS441', 'Science, Technology, and the Black Community', 3, 3, 'Scientific knowledge and skills in solving technological and social problems, particularly those faced by the Black community. Examines the evolution and development of African and African, African American, and Africa Diasporic contributions to science. Surveys the impact of technological changes on minority communities.', 'HIST255, AAAS202, or AAAS100; or permission of BSOS-African American and Africana Studies department.', NULL, FALSE, NULL, NULL, 'AASP441 or AAAS441.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'partial', 'none_found', NULL, 'AASP441.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS443', 'Law and the Black Community', 3, 3, 'The relationship between Black Americans and the law, particularly criminal law, criminal institutions and the criminal justice system. Examines historical changes in the legal status of blacks and changes in the causes of racial disparities in criminal involvement and punishments.', 'HIST255, AAAS202, or AAAS100; or permission of BSOS-African American and Africana Studies department.', NULL, FALSE, NULL, NULL, 'AASP443 or AAAS443.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'partial', 'none_found', NULL, 'AASP443.', NULL, NULL, NULL, NULL, NULL),
    ('AAAS468', 'Special Topics in Africa and the Americas', 3, 3, 'Cultural, historical and artistic dimensions of the African experience in Africa, the Americas and the African Diaspora.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'AASP468.', NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AAAS475', 'Magical Black Femmes: Queering Black Femininity', 3, 3, 'Queer femme identity, rooted in 1940s and 1950s bar culture, continues to resonate. Often linked with butch, femme is a queer, feminine expression that challenges the binary tying femininity to cisgender, heterosexual women. Femme exists outside that frame. Black women have long moved beyond white heteropatriarchal norms, and Black femmes of all genders have turned that resistance into power. This course explores Black femme identity as a radical critique of gender, sexuality, and whiteness. Through cultural studies and humanities methods, we will examine femme''s complexity and how it unsettles what we assume about queerness, femininity, and identity.', NULL, NULL, TRUE, NULL, NULL, 'LGBT475, WGSS475, AAAS475 or LGBT448E.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'LGBT448E.', 'LGBT475, WGSS475.', NULL, NULL, 'LGBT200 or another LGBT course.', NULL),
    ('AAAS479', 'Special Research in African-American Studies', 1, 9, 'Supervised research activity within the African American and Africana Studies Department. This course is designed for both majors and non-majors who wish to collaborate with a faculty member on their research project(s) and/or work in their research lab as a Research Assistant (RA). The purpose of this course is to expose students to theories and methods used to understand the lives and experiences of Black people across the diaspora via hands-on/applied research experience. A faculty member must agree to supervise your research activity before students can enroll for course credit.', NULL, NULL, TRUE, NULL, 'Permission of BSOS- African American and Africana Studies department; and sophomore standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, NULL, NULL, NULL, '9 credits if content differs.', 'AASP210.', NULL),
    ('AAAS490', 'Seven Revolutions in Modern Africa (1945-)', 3, 3, 'Seven Revolutions samples theoretical, contemporaneously produced, and leading scholarly (secondary) texts about seven revolutionary situations faced by Africans from ca. 1952 through to the 21st century. In past years we have devoted weeks or double weeks to the Mau Mau (Kenya), Ethiopian derg, Zimbabwe''s factions and structural racism, Guinea and women''s subalternity, Patrice Lumumba''s assassination, race vs. settler as a framework, Liberia''s intersection with continental history in the 1980s, among other focuses.', NULL, NULL, TRUE, NULL, NULL, 'HIST428B, HIST490, or AAAS490.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'none', 'none_found', NULL, 'HIST428B.', 'HIST490.', NULL, NULL, NULL, NULL),
    ('AAAS498', 'Special Topics in Black Culture', 3, 3, 'Advanced study of the cultural and historical antecedents of contemporary African and African American society. Emphasis on the social, political, economic and behavioral factors affecting blacks and their communities. Topics vary.', 'AASP100, AAAS100, AASP202, or AAAS202.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'unstructured', 'none_found', NULL, 'AASP498.', NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AAAS499', 'Advanced Topics in Public Policy and the Black Community', 3, 3, 'Examination of specific areas of policy development and evaluation in black and other communities. Application of advanced tools of policy analysis, especially quantitative, statistical and micro-economic analysis.', 'AASP301 or AAAS301; or permission of BSOS-African American and Africana Studies department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aaas/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AAST200', 'Introduction to Asian American Studies', 3, 3, 'The aggregate experience of Asian Pacific Americans, from developments in the countries of origin to their contemporary issues. The histories of Asian Pacific American groups as well as culture, politics, the media, and stereotypes, viewed from an interdisciplinary perspective.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'AAST200 or AMST298C.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'verified', '202608', NULL, 'AMST298C.', NULL, NULL, NULL, NULL),
    ('AAST201', 'Asian American History', 3, 3, 'Introduction to the history of Asian Americans and Asians in the United States and the Americas and to the field of Asian American Studies, from an interdisciplinary perspective. Topics include theories of race and ethnicity; Asian migration and diaspora to the Americas; Asian American work and labor issues; gender, family, and communities; nationalism and nativism, and anti-Asian movements; Asian Americans in World War II, the Cold War, and the issues in the civil rights & post-civil rights era.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'AAST201 or HIST221.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'verified', '202601', NULL, 'HIST221.', NULL, NULL, NULL, NULL),
    ('AAST233', 'Asian American Literature and Culture', 3, 3, 'What is the role of literature in the lives of contemporary Asian Americans? How do Asian American authors imagine identity, violence, and social justice? Consider the role of Asian American literature in forming our understanding of past and present Asian America, and explore Asian American cultures and experiences.', NULL, NULL, TRUE, NULL, NULL, 'ENGL233 or AAST233.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'none_found', NULL, NULL, 'ENGL233.', NULL, NULL, NULL, NULL),
    ('AAST250', 'Asian American Foodways', 3, 3, 'Kimchi, chop suey, Spam, "curry," poke: while these foods are now widely embraced, we will inquire how "hallmark" Asian/American foods have assumed cultural meaning and significance in the U.S., often through their transnational entanglements with histories of colonialism, exclusion, immigration, war, and globalization. We will think about how the aesthetics and significations of taste are bound up in the ways Asian Americans perceive themselves and are perceived by others, inquiring how ideas of the "perpetual foreigner" and the "model minority" might inform consumption practices. As the title of this course suggests, foodways will be a central area of analysis, never static but defined by mobility and transmission for Asian American communities. You will also be invited to explore your own relationships to Asian American food cultures through personal and academic accounts, a diverse range of media (TV, film, social media), cookbooks, and memoirs.', NULL, NULL, TRUE, 'DSHU', NULL, 'AAST298G or AAST250.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'verified', '202601', 'AAST298G.', NULL, NULL, NULL, NULL, NULL),
    ('AAST262', 'Asian American Psychology', 3, 3, 'An overview of how socio-cultural influences impact the development and psychological health of Asian Americans. Other topics include how minority group status, adaptation and identity development influence various aspects of psychological functioning; the role of historic systematic racism; and, how the COVID-19 pandemic has negatively impacted Asian Americans. Students develop a deeper understanding of the role of stereotypes and racism, acculturation, racial identity development, cultural values, gender socialization, behavioral norms, family roles, stressors and social support systems on the mental health, well-being and health of Asian Americans.', NULL, NULL, TRUE, NULL, NULL, 'PSYC262, AAST262 or PSYC489Z.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'none_found', NULL, 'PSYC489Z.', 'PSYC262.', NULL, NULL, NULL, NULL),
    ('AAST298', 'Special Topics in Asian American Studies', 3, 3, 'An introductory multidisciplinary and interdisciplinary educational experience to explore issues relevant to Asian American life, cultural experiences; and political, economic, and artistic development.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AAST310', 'Introduction to Comparative Ethnic and Racial Studies', 3, 3, 'Introduces students to the study of race and ethnicity in the United States. The class is organized according to the following five units: (1) Introduction; (2) Key concepts; (3) Mechanisms of racial formation; (4) Prevailing myths about race; and (5) Contemporary issues related to race and ethnicity. Through readings, film clips, and presentations, we will explore how the concept of race has developed and endured over time and become familiar with key concepts, such as "race" and "intersectionality". We will attempt to better understand how race is associated with other forms of difference, such as class, gender and ethnicity. We will identify and confront the prevailing myths about race and ethnicity in the United States. Finally, we examine the ways in which contemporary issues reveal the dynamics of race and ethnicity.', NULL, NULL, TRUE, NULL, NULL, 'AMST310, AAST398F, AAST310, or AMST328L.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'none_found', NULL, 'AMST328L and AAST398F.', 'AMST310.', NULL, NULL, NULL, NULL),
    ('AAST322', 'Immigration and Ethnicity in the US', 3, 3, 'Explores historical and contemporary Asian immigration to the US in comparison to and in the context of other immigrant groups. From low-skilled laborers to highly-skilled professionals, Asian and other immigrants have been an integral part of the shifting US economy and society since its inception. The course includes theories on why immigration occurs, determinants of its continuation, the uses of migrant labor, and immigrant adaptation and settlement. The second part of the course focuses on theories of ethnicity and racial formation and how immigrants develop and challenge the definitions of race, ethnicity, the "other", and ultimately, who is American. Students will also have the opportunity to gain first-hand knowledge of the immigrant experience through a life history interview project.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'AAST322, SOCY222, HIST322 or SOCY322.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'verified', '202608', 'AAST222, SOCY222.', 'SOCY322.', NULL, NULL, NULL, NULL),
    ('AAST350', 'South Asian American Experiences', 3, 3, 'Explores the historical and current day experiences of diverse South Asian groups in the United States. Drawing from an array of materials, including historical, literary, visual and media texts, the course examines several key issues-- such as immigrant family and generational gap, racial stereotyping, media representation, the intersections of gender, race, and sexuality, the model minority and identity politics, casteism, and interracial relations and ethnic identity formation-- from both national and transnational frameworks for understanding historical and contemporary experiences of South Asian Americans.', NULL, NULL, TRUE, 'DSHU', NULL, 'AAST298O or AAST350.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'verified', '202601', 'AAST298O.', NULL, NULL, NULL, NULL, NULL),
    ('AAST351', 'Asian Americans and Media', 3, 3, 'From yellow peril invaders to model minority allies, Asian Americans have crafted their own dynamic cultural expressions in a number of media from film, television, and music to fashion, sports, and food that reveal and contest the contradictions of the U.S. nation-state. Asian American culture also uniquely sits at the nexus of immigration flows and digital technologies, providing a transnational lens to view the US place in the world. This advanced course, then, will introduce students to the study and practice of Asian American culture as multiple , hybrid, and heterogeneous. It will do so through three sections: section one will introduce students to classical, cultural, and media concepts as well as relevant keywords outlined by Asian American Studies scholars; section two will review the work of Asian American cultural theorists; section three will focus on analyses of particular Asian American cultural productions. In doing so, students will gain an understanding of the shifting and interlocking tensions among the local, the national, and the global that form the cultural geographies of Asian America.', NULL, NULL, TRUE, 'DSSP, DVUP', NULL, 'AAST351, AAST398M or AAST398N.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'verified', '202608', 'AAST398M, AAST398N.', NULL, NULL, NULL, NULL, NULL),
    ('AAST355', 'Asian Americans in Film', 3, 3, 'Explores how Asian Americans have historically been represented in the U.S. by Hollywood, and in turn, how independent and Hollywood Asian American filmmakers have represented themselves. It covers the history of racial, gendered, and sexualized representations of Asian Americans in Hollywood, as well as Asian American filmic responses within and outside Hollywood. It also introduces how four basic tools of film analysis mise-en-scene, cinematography, editing and sound work together to create meaning in moving images. It examines how these elements are put together in three different types of films by Asian American filmmakers: narrative, documentary, and experimental. How films function in society to circulate ideas that reproduce and challenge stereotypes about Asian Americans.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, 'AAST355, AAST398L or AMST328W.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'verified', '202608', '398L.', 'AMST328W.', NULL, NULL, NULL, NULL),
    ('AAST363', 'Filipino American History and Biography', 3, 3, 'Focus is placed on Filipino American experiences with an emphasis on identity, community building and organizing to influence public policy We will cover pertinent events from the US and Philippine history in order to understand the impact of colonialism, migration, immigration and assimilation on Filipino Americans.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'AAST363, AMST323, AAST398D, or AMST328J.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'verified', '202508', 'AAST398D.', 'AMST323.', NULL, NULL, NULL, NULL),
    ('AAST378', 'Experiential Learning', 3, 3, 'Field experience/internship in professional organizations and appropriate private and governmental agencies serving the Asian American community.', NULL, NULL, TRUE, NULL, 'Permission of UGST-Undergraduate Studies.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits.', NULL, NULL),
    ('AAST388', 'Independent Research', 1, 3, 'Directed, independent study in Asian American Studies resulting in the completion of an original research paper.', NULL, NULL, TRUE, NULL, 'Permission of UGST-Undergraduate Studies.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AAST394', 'Growing Up Asian American: The Asian Immigrant Family and the Second Generation', 3, 3, 'An interdisciplinary course examines the experiences of children of Asian immigrants in the U.S., focusing on intergenerational dynamics in the Asian immigrant family, their intersections with race, gender, class, sexuality, and religion, and how these shape second-generation Asian American life. Topics include identity and personhood, the model minority myth and education, work and leisure, language and communication, filiality and disownment, mental health and suicide.', NULL, NULL, TRUE, 'DVCC', NULL, 'AAST394, AAST398E, AMST324, AMST328V, IMMR319G or IMMR394.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'verified', '202608', 'AAST398E.', 'AMST324, IMMR394.', NULL, NULL, NULL, NULL),
    ('AAST398', 'Selected Topics in Asian American Studies', 3, 3, 'Study of a specific theme or issue involving the Asian America experience.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AAST421', 'Asian American Public Policy', 3, 3, 'Using Asian Pacific Americans as a case study, this course will analyze the development of public policy in America. Each week, topics such as community development, voting rights, and the movement to redress the wartime internment of Japanese Americans will serve as backdrops for discussion. We will explore the policy-making roles of legislators, judges, local and national political leaders, journalists, writers, unions, social movements, and community organizations.', NULL, NULL, TRUE, 'DVCC', NULL, 'AAST421, AAST498M or AMST418N.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'verified', '202608', 'AAST498M.', 'AMST418N.', NULL, NULL, NULL, NULL),
    ('AAST422', 'Asian American Women and Gender', 3, 3, 'Examines Asian/American cultural production along with theories of gender and sexuality in the field of Asian American Studies. We consider how Asian American femininities/masculinities are conceived and circulated, drawing from a diverse selection of twentieth-century and contemporary texts, films and images that connect Asian American bodies to ideas of absence, danger, inscrutability, hyper- or hypo-sexuality, and virulence. Beginning with early to mid-twentieth century representations, the course attends to theories that clarify the contested relationship between the East/West and Asia/U.S. Also examined are the methods through which bodies differentiated by sex, gender, and race are managed, surveilled, and rehabilitated, with close attention to the enduring legacies of American expansionism and conquest, anti-immigration policies in the U.S., and twentieth-century wars and occupations in Asia. The course engages Women of Color feminisms, queer theory, and disability studies.', NULL, NULL, TRUE, NULL, NULL, 'AAST498G, AAST422, or WGSS 422.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'none_found', NULL, 'AAST498G.', 'WGSS422.', NULL, NULL, NULL, NULL),
    ('AAST424', 'Sociology of Race Relations', 3, 3, 'Encourages sociological thinking about US racial and ethnic minority populations, with a focus on African Americans, Latinos, Asian Americans, and Native Americans. The central concern is to understand and explain racial/ethnic inequality. A wide array of topics are discussed, including prejudice and discrimination, slavery, residential segregation, cultural inequality, skin tone stratification, economic and educational disparities, and assimilation/generational processes.', '6 credits in SOCY courses; or permission of the Sociology department.', NULL, FALSE, NULL, NULL, 'SOCY424 or AAST424.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'unstructured', 'none_found', NULL, NULL, 'SOCY424.', NULL, NULL, NULL, NULL),
    ('AAST440', 'South Asian American Literature and Culture', 3, 3, 'Examines writing by South Asian American authors and authors writing about South Asian American issues. It explores major South Asian diaspora themes, considering how migration, war, the events of 9/11, global capitalism, and the changing socio-political and racial scene have affected South Asians in the United States. We will use a transnational approach to consider how writers and filmmakers explore gender, class, religious, caste, and other differences amongst South Asian Americans. We will also examine the place of South Asian Americans in relation to other Asian American populations. We will consider how South Asian American texts disrupt traditional literary classifications based on national identities by reflecting the complex global conditions, imperialistic and capitalistic expansion, and interconnectedness of peoples, nations, and cultures that have transformed American literature and conceptions of American identity.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, 'AAST440 or AAST498W.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'verified', '202608', 'AAST498W.', NULL, NULL, NULL, NULL, NULL),
    ('AAST443', 'Asian American Politics', 3, 3, 'Students will gain a greater understanding of 1) the role of Asian Americans in US politics, 2) the political attitudes and behaviors of Asian Americans and 3) how to conduct research on Asian American politics. Though the class will concentrate on Asian Americans, issues related to Asian American politics will be examined within the larger context of America''s multicultural political landscape.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'AAST498T, AAST443, GVPT368C or AMST 498J.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'verified', '202608', 'AAST498T.', 'AMST498J, GVPT368C.', NULL, NULL, NULL, NULL),
    ('AAST498', 'Advanced Topics in Asian American Studies', 3, 3, 'Advanced study of the cultural and historical antecedents of contemporary Asian American society. Emphasis on the social, political, economic, and behavioral factors affecting Asian Americans and their communities.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AAST499', 'Senior Thesis', 3, 3, 'Under the supervision of faculty, research regarding a specific topic of the Asian American experience will be completed.', 'AAST201 and AAST200.', NULL, TRUE, NULL, 'Permission of UGST-Undergraduate Studies; and must be in Asian American Studies program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aast/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('ABRM330', 'Introduction to Anti-Black Racism', 3, 3, 'This interdisciplinary course seeks to provide a broad overview of this rich and dynamic history. Built around the expertise of top UMD faculty in five colleges, this course will introduce students to the history and legacy of anti-Black racism from the perspective of multiple disciplines. In this course you will examine the development, spread, and articulations of anti-Black racism in the United States.', NULL, NULL, TRUE, 'DVUP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/abrm/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, 'This interdisciplinary course will consist of two-week modules from key faculty/scholars in College of Behavioral and Social Sciences, College of Arts and Humanities, School of Public Health, School of Public Policy, and College of Education to explore how anti-Black racism operates in society.'),
    ('ABRM450', 'Applied Anti-Black Racism', 3, 3, 'The purpose of this course is to apply knowledge rooted in Anti-Black Racism to a real-world problem or issue within your chosen discipline or planned career path. You will meet with the course instructor and each other to discuss the readings, ideas and frameworks of anti-Black racism. The rest of the course will operate similar to an independent study; you will choose a mentor from your home department to work with on a self-directed, practice-oriented project. Beginning with a framework rooted in understanding anti-Black racism, you will identify issues of anti-Black racism specific to your discipline, select one of those issues within which to explore current solutions and their shortcomings, and draft a proposal that addresses the anti-Black racism embedded within the issue itself.', 'ABRM330.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/abrm/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AGNR100', 'Agriculture Discovery: An Educational Odyssey Exploring Food, Culture, and the Environment', 3, 3, 'Explores the history, cultural impact, and current issues of agriculture. Students are exposed to the wide range of professional opportunities associated with the use of plants and animals in the production and processing of food for human consumption. Students learn from Agriculture and Natural Resources (AGNR) faculty and USDA collaborators through lectures, labs and field trips to facilities in the Baltimore-Washington area.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/agnr/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AGNR200', 'AGNR 2+2 Program Extended Orientation Seminar', 1, 1, 'Introduces AGNR 2+2 students to University and "American" life. Assists with their successful transition to the College and Agriculture and Natural Resources and the University of Maryland. Helps students to understand their place in AGNR at to learn about the resources available to them.', 'Must be a first semester international student enrolled in the AGNR 2+2 Program.', NULL, FALSE, NULL, 'Must be a first year international student enrolled in the College of Agriculture and Natural Resources 2+2 Program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/agnr/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'It is strongly recommended that AGNR 2+2 students take AGNR 200 during the first semester at the University. One class meeting per week. This courses is initiated by International Programs and will be coordinated in conjunction with the College of AGNR.'),
    ('AGNR230', 'Artificial Intelligence: Transforming Food, Agricultural, and Environmental Systems', 3, 3, 'Artificial intelligence is fundamentally transforming agriculture, food, and environmental sciences, disciplines at the heart of the College of Agriculture and Natural Resources (AGNR). This course introduces students to the core concepts and practical realities of AI within these fields. Through a blend of theory, case studies, and expert seminars, students will examine how AI models (from Large Language Models to computer vision) function. Students will critically evaluate real-world applications, such as precision farming, environmental impact modeling, and veterinary diagnostics. The course will challenge the students to consider both the benefits and drawbacks of this rapidly expanding set of technological tools. By the end of the course, students will possess the foundational literacy to navigate the AI landscape and make informed decisions about integrating these tools into their education and future careers.', NULL, NULL, TRUE, 'DSSP, SCIS', NULL, 'AGNR230 or ENST231.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/agnr/', 'none', 'verified', '202608', NULL, 'ENST231.', NULL, NULL, NULL, NULL),
    ('AGNR301', 'Sustainability', 3, 3, 'Designed for students whose academic majors would be enhanced by the complementary study of a widely shared but hard-to-operationalize aspiration: that present choices should preserve or improve future options rather than foreclose or degrade them. How should we understand sustainability? How might we achieve it? How would we know if we had achieved it? And how could sustainability activists of a rising generation lead by example?', NULL, NULL, TRUE, NULL, NULL, 'AGNR301 or PLCY301.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/agnr/', 'none', 'none_found', NULL, NULL, 'PLCY301.', NULL, NULL, NULL, NULL),
    ('AGNR386', 'Experiential Learning', 3, 6, '', NULL, NULL, TRUE, NULL, 'Permission of AGNR-College of Agriculture & Natural Resources.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/agnr/', 'none', 'none_found', NULL, 'AGRI386.', NULL, NULL, NULL, NULL, NULL),
    ('AGNR388', 'Honors Thesis Research', 3, 6, 'Undergraduate honors thesis research conducted under the direction of an AGNR faculty member in partial fulfillment of the requirements of the College of AGNR Honors Program. The thesis will be defended to a faculty committee.', NULL, NULL, TRUE, NULL, 'Must be admitted to AGNR Honors program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/agnr/', 'none', 'none_found', NULL, 'AGRI388.', NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AGNR489', 'Field Experience', 1, 4, 'Credit according to time scheduled and organization of the course. A lecture series organized to study in depth a selected phase of agriculture not normally associated with one of the existing programs.', NULL, NULL, TRUE, NULL, 'Permission of AGNR-College of Agriculture & Natural Resources.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/agnr/', 'none', 'none_found', NULL, 'AGRI489.', NULL, NULL, '4 credits if content differs.', NULL, NULL),
    ('AGNR499', 'Special Problems', 1, 3, '', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/agnr/', 'none', 'none_found', NULL, 'AGRI499.', NULL, NULL, NULL, NULL, NULL),
    ('AGST130', 'Did Yeast Create Civilization?', 3, 3, 'Did yeast create civilization? Fermented foods have played a major role in the transition from nomadic to settled agrarian societies, the establishment of social and religious customs, the expansion of empires, and modern economies. To what extent are our past and current attitudes towards fermented foods rooted in historical and cultural imprints? Explore the central role of fermentation in human history and culture, the basic microbiological processes underlying fermentation processes, and the processes used to produce and distribute fermented foods. Find out how the fruits, grains, and dairy products used to produce fermented foods are grown and selected. Students will learn about the development and modern use of fermented dairy products, pickles, bread, tea, chocolate, wine, beer, distilled liquors, and pharmaceutical/manufactured products.', NULL, NULL, TRUE, 'DSHS, SCIS', NULL, 'AGST130 or PLSC130.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/agst/', 'none', 'verified', '202608', NULL, 'PLSC130.', NULL, NULL, 'CHEM103, CHEM131, CHEM135, or CHEM146.', NULL),
    ('AGST275', 'Fundamentals of Agricultural and Environmental Chemistry', 3, 3, 'An in-depth discussion of chemistry targeted to students enrolled in plant and animal management curricula offered in AGNR. Covers the nomenclature and basic functional groups in organic chemistry, natural products and pesticides. Current practices of crop, agriculture and environmental management and genetic engineering also discussed.', 'Minimum grade of C- in CHEM131 and CHEM132; and minimum grade of C- in (PLSC110 and PLSC11) or (PLSC112 and PLSC113) or (BSCI160 and BSCI180 or BSCI161) or (BSCI170 and BSCI180 or BSCI171).', NULL, FALSE, NULL, 'Must not have completed CHEM104 or CHEM105; and must be in a major within the AGNR-College of Agriculture and Natural Resources; or permission of instructor.', 'AGST275 or PLSC275.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/agst/', 'unstructured', 'none_found', NULL, 'PLSC275.', NULL, NULL, NULL, NULL, NULL),
    ('AGST333', 'Crafty Beverage Crops', 3, 3, 'From soda to wine, a scientific introduction to "crafty beverage crops". Students will expand their horticulture knowledge and gain an appreciation for craft beverages and the plants that made them. Topics include history, biology, production and management techniques, harvest, storage and market potential for crafty beverage crops.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/agst/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, 'PLSC110 or PLSC112; or 1 course in BSCI, BCHM, BIOL.', NULL),
    ('AGST389', 'Internship in Agricultural Education', 1, 3, 'An experiential learning course with a focus on non-formal agricultural education. This is a supervised learning experience within a career focused environment to assist in refinement of a student''s career interests prior to graduation.', NULL, NULL, TRUE, NULL, 'Permission of the instructor.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/agst/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AGST399', 'Special Problems in Agricultural Science & Technology', 1, 3, 'A problem based learning course with a focus on class or group based research projects in Agricultural Science and Technology with a focus on addressing outreach targeted needs.', NULL, NULL, TRUE, NULL, 'Permission of the instructor.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/agst/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AGST400', 'Advanced Crop Science', 3, 3, 'Focuses on the study of the agronomic principles and practices required for the production of food, feed, fiber and fuel crops. This is a project-based course where students will develop a farm plan from knowledge gained in previous courses and built upon in this course. Students will learn to integrate data and information from many sources in order to build and operate a successful and sustainable agronomic farm operation using current and new technology. The use of farm management software will be an integral part of the course and farm project.', '(PLSC110 and PLSC111) OR (PLSC112 and PLSC113), BSCI160 and (BSCI180 or BSCI161), and MATH113 or higher.', NULL, FALSE, NULL, NULL, 'PLSC407 or AGST400.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/agst/', 'unstructured', 'none_found', NULL, 'PLSC407.', NULL, NULL, NULL, 'ANSC101.', 'There will be two required Saturday field trips during the semester. Because of the changing nature of agriculture, the dates of these field trips will be decided upon at the beginning of the semester by discussion among the students and based on cooperators availability and environmental factors. Students will have a minimum of two weeks notice as to the dates of the field trips.'),
    ('AGST401', 'Tractor and Equipment Operation, Safety and Maintenance', 1, 1, 'Provides students with basic skills needed to safely operate and maintain farm equipment, such as tractors and implements used in agronomic production. Students will receive introductory background training in the basic safety and operation of tractors through hands-on learning. Emphasis will also be placed on the mechanical functioning of equipment and the functional similarities and differences between gasoline (two-stroke and four-stroke) and diesel engines as well as electric motors as they relate to farm equipment (mobile and stationary). This knowledge will be used to teach students to safely perform basic care and maintenance of different tractor types as well as various implements. Students will also learn basic implement connection and disconnection, including the safe use of implements that employ a power take-off unit. Included in the course will be an introduction to the equipment and use of satellite navigation systems used in agronomic production.', '(PLSC110 and PLSC111) OR (PLSC112 and PLSC113); MATH113 or higher MATH course; and must have completed or be concurrently enrolled in AGST400.', NULL, FALSE, NULL, 'Must have earned a minimum of 60 credits; and permission of the Department of Plant Sciences and Landscape Architecture.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/agst/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'Course location will be the University of Maryland Wye Research & Education Center, Queenstown, Maryland. Because students will be working around machinery with moving parts, there is a strict dress code based on information from the United State Department of Agriculture Cooperative States Research, Education and Extension Service''s Hazardous Occupations Safety Training for Agriculture (HOSTA), National Safe Tractor and Machinery Operation Program (NSTMOP) standards. YContact instructor for more information?.'),
    ('AGST426', 'Scientists Teaching and Translating Science', 3, 3, 'Explore methods in pedagogy, andragogy, and heutagogy to facilitate science learning through the development of a teaching philosophy, outreach teaching skills, motivation in learning, assessment foundations, and review of current literature on instruction in science fields.', NULL, NULL, TRUE, NULL, NULL, 'AGST426 or PLSC489L.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/agst/', 'none', 'none_found', NULL, 'PLSC489L.', NULL, NULL, NULL, NULL, NULL),
    ('AGST440', 'Exploring Maryland Agriculture, Agricultural Industry, and Agricultural Literacy', 3, 3, 'Explore the mission and history of the Land Grant System as well as current work conducted through the University of Maryland to extend research to citizens. Often referred to as America in miniature, Maryland boasts diverse people, agricultural practices, cultures, and ecosystems which students will examine to perceive the decision making processes within and across ecological systems as well as the development of advisory boards.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/agst/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AGST442', 'Examining Leadership in Youth and Volunteers', 3, 3, 'Explore fundamental leadership theories and practice related skills utilized in helping youth and adults build community relationships in a variety of teaching environments. Fundamentals of youth development will be the basis for examining how to foster positive learning environments for dynamic learning. The identification of empowerment processes will be explored through case-study discussions.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/agst/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AGST489', 'Special Topics in Agricultural Science and Technology', 1, 3, 'Selected novel topics of study in Agricultural Science & Technology (AGST).', NULL, NULL, TRUE, NULL, 'Permission of the instructor.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/agst/', 'none', 'none_found', NULL, NULL, NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('AGST499', 'Independent Studies in Agricultural Science and Technology', 1, 3, 'An inquiry based learning course with individualized projects designed by student and faculty focused on: research or advanced learning experiences in Agricultural Science and Technology including field, greenhouse, laboratory, educational site, travel abroad and/or library studies. Conducted under the direction of a faculty member.', NULL, NULL, TRUE, NULL, 'By permission of instructor.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/agst/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AIME298', 'Special Topics in Artificial Intelligence', 1, 4, 'Thematic exploration of a topic in artificial intelligence (A.I.).', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aime/', 'none', 'none_found', NULL, NULL, NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('AIME399', 'Independent Study in Artificial Intelligence', 1, 3, 'An individualized course of study under the guidance of a faculty mentor or affiliate faculty mentor within the Artificial Intelligence Interdisciplinary Institute at Maryland (AIM). Students are required to create their own course of study in consultation with their faculty advisor; content must not duplicate coursework already offered at the university.', NULL, NULL, TRUE, NULL, 'Permission of CMNS-Artificial Intelligence Interdisciplinary Institute at Maryland; and junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aime/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AIME498', 'Interdisciplinary Topics in Artificial Intelligence', 1, 4, 'Seminar course covering interdisciplinary topics in artificial intelligence.', NULL, NULL, TRUE, NULL, 'Permission of CMNS-Artificial Intelligence Interdisciplinary Institute at Maryland; and junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aime/', 'none', 'none_found', NULL, NULL, NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('AIME499', 'Independent Research in Artificial Intelligence', 1, 6, 'Directed research under the supervision of a faculty member or affiliate faculty member in artificial intelligence. Students and supervising faculty member will agree to a research plan which must be approved by the Artificial Intelligence Interdisciplinary Institute at Maryland (AIM). As part of each research plan, students should produce a final paper on their research.', NULL, NULL, TRUE, NULL, 'Permission of CMNS-Artificial Intelligence Interdisciplinary Institute at Maryland; and junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aime/', 'none', 'none_found', NULL, NULL, NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('AMSC420', 'Mathematical Modeling', 3, 3, 'The course will develop skills in data-driven mathematical modeling through individual and group projects. Emphasis will be placed on both analytical and computational methods, and on effective oral and written presentation of results.', '1 course with a minimum grade of C- from (MATH240, MATH461, MATH341, ENEE290, MATH243); and 1 course with a minimum grade of C- from (MATH241, MATH340); and 1 course with a minimum grade of C- from (MATH246, MATH341, ENEE290, MATH243); and 1 course with a minimum grade of C- from (STAT400, STAT410); and 1 course with a minimum grade C- from (CMSC106, CMSC131).', NULL, FALSE, NULL, NULL, 'AMSC420 or MATH420.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amsc/', 'unstructured', 'none_found', NULL, NULL, 'MATH420.', NULL, NULL, 'AMSC460 or AMSC466.', NULL),
    ('AMSC452', 'Introduction to Dynamics and Chaos', 3, 3, 'An introduction to mathematical dynamics and chaos. Orbits, bifurcations, Cantor sets and horseshoes, symbolic dynamics, fractal dimension, notions of stability, flows and chaos. Includes motivation and historical perspectives, as well as examples of fundamental maps studied in dynamics and applications of dynamics.', 'MATH341; or MATH246 and one of (MATH240 or MATH461).', NULL, FALSE, NULL, NULL, 'AMSC452 or MATH452.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amsc/', 'unstructured', 'none_found', NULL, NULL, 'MATH452.', NULL, NULL, NULL, NULL),
    ('AMSC460', 'Computational Methods', 3, 3, 'Basic computational methods for interpolation, least squares, approximation, numerical quadrature, numerical solution of polynomial and transcendental equations, systems of linear equations and initial value problems for ordinary differential equations. Emphasis on methods and their computational properties rather than their analytic aspects. Intended primarily for students in the physical and engineering sciences.', '1 course with a minimum grade of C- from (MATH240, MATH341, MATH461, ENEE290, MATH243); and 1 course with a minimum grade of C- from (MATH241, MATH340); and 1 course with a minimum grade of C- from (CMSC106, CMSC131); and 1 course with a minimum grade of C- from (MATH246, MATH341, ENEE290, MATH243).', NULL, TRUE, NULL, NULL, 'AMSC460, AMSC466, CMSC460, or CMSC466.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amsc/', 'parsed', 'none_found', NULL, NULL, 'CMSC460.', NULL, NULL, NULL, NULL),
    ('AMSC466', 'Introduction to Numerical Analysis I', 3, 3, 'Floating point computations, direct methods for linear systems, interpolation, solution of nonlinear equations.', '1 course with a minimum grade of C- from (CMSC106, CMSC131); and minimum grade of C- in MATH410.', NULL, TRUE, NULL, NULL, 'AMSC460, CMSC460, AMSC466, or CMSC466.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amsc/', 'parsed', 'none_found', NULL, NULL, 'CMSC466.', NULL, NULL, NULL, NULL),
    ('AMSC498', 'Selected Topics in Applied Mathematics', 1, 3, 'Topics in applied mathematics of special interest to advanced undergraduate students.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amsc/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AMST101', 'Introduction American Studies', 3, 3, 'Introduces students to the interdisciplinary field of American Studies by examining concepts such as culture, identity, cultural practices, and globalization, as well as theories underlying these concepts. Engages key themes, especially constructions of difference and identity, cultures of everyday life, and America and the world.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, 'AMST101 or AMST201.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'verified', '202608', 'AMST201.', NULL, NULL, NULL, NULL, NULL),
    ('AMST189C', 'Martin Luther King Jr.', 3, 3, 'Examines the life and work of Martin Luther King, Jr. We immediately rethink the image of King who liberals and conservatives construct as a dreamer of better race relations. We engage the complexities of an individual, who articulated a moral compass of the nation, to explore racial justice in post-World War II America. This course gives special attention to King''s post-1965 radicalism when he called for a reordering of American society, an end to the war in Vietnam, and supported sanitation workers striking for better wages and working conditions. Topics include King''s notion of the "beloved community", the Social Gospel, liberalism, "socially conscious democracy", militancy, the politics of martyrdom, poverty and racial justice, and compensatory treatment. Primary sources form the core of our readings.', NULL, NULL, TRUE, NULL, NULL, 'HIST108C, AASP298M, AAAS298M, or AMST189C.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'none_found', NULL, NULL, 'HIST108C, AAAS298M.', NULL, NULL, NULL, NULL),
    ('AMST202', 'Cultures of Everyday Life in America', 3, 3, 'Examine the structures and patterns of everyday life in the U.S., utilizing methods such as ethnography, oral history, survey research, and textual, visual, and material cultural analysis.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AMST203', 'Popular Culture in America', 3, 3, 'An introduction to American popular culture, its historical development, and its role as a reflection of and influence on our culture and society.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('AMST204', 'Film and American Culture Studies', 3, 3, 'Exploration of the American film from a historical perspective, illustrating the motion picture''s role as an institutional phenomenon, as a form of communication, and as a source of cross-cultural study.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('AMST205', 'American Material Culture: The Study of People, Places, and Things', 3, 3, 'Historical survey of American material culture. Ways of describing and interpreting accumulated material evidence (e.g., buildings, town plans) introduced by stressing relationship between artifact and culture.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('AMST210', 'Introduction to Ethnography', 3, 3, 'A qualitative research method course used to study social worlds communities, cultures, institutions, and other social groups from the perspectives of the people who inhabit those social worlds. Ethnographic research involves understanding cultural traditions from an insider''s perspective by studying the everyday lives of people steeped in those traditions.', NULL, NULL, TRUE, 'DSSP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'verified', '202601', NULL, NULL, NULL, NULL, NULL, NULL),
    ('AMST213', 'Heroes and Villains in American Film', 3, 3, 'We will examine the complex, changing, and ever-present representations of heroes and villains in American film. Beginning with a foundational understanding of how heroes and, conversely, villains have been defined through classic Hollywood film, we will explore how these definitions have shifted throughout the 20th and 21st century in various narrative genres, including westerns, war films, film noir, fantasy, science fiction, and, of course, superhero movies. In particular, we will be focusing on how the hero and villain maintain or disrupt specific cultural ideologies concerning race/ethnicity, gender, sexuality, and ability. This course will examine how these various ideologies have evolved throughout the 20th and 21st century, impacting the ways in which heroes and villains are both represented in American film and perceived by diverse audiences. Finally, we will examine our own complicated and sometimes troubling identification with these heroes, even when they might stand in stark contrast to our cultural values and identities.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, 'AMST213, HONR219F, or CINE282.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'verified', '202601', 'HONR219F.', 'CINE282.', NULL, NULL, NULL, NULL),
    ('AMST215', 'Introduction to Disability Studies', 3, 3, 'Explores theories of disability justice as they intersect with feminist and antiracist struggles. Analyzing how disability has been an important aspect of institutions and social experience in the United States and beyond, the course considers how disability activists have responded to ableism by developing art, political strategies, and subcultures that promote a more just society built for a wider variety of human bodies.', NULL, NULL, TRUE, NULL, NULL, 'WGSS105, AMST215, or AMST298D.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'none_found', NULL, 'AMST298D.', 'WGSS105.', NULL, NULL, NULL, NULL),
    ('AMST250', 'Empire and Settler Colonialism', 3, 3, 'Engages with the connections between settler colonialism and empire/imperialism and what their effects are on race, land, dispossession, and migration. The course will begin by grounding students in course key concepts including Settler Colonialism, Empire, Imperialism, Sovereignty, and Legality, situating these concepts in relation to space, place, and geography. The second half of the course will use these theoretical lenses to analyze the social conditions faced by BIPOC peoples. These topics will cover criminalization and police violence, Indigenous and women of color feminist and two spirit/queer experience, environmental racism, and state-based forms of racial documentation. The course will end with a discussion of decolonization and what it means in relation to settler colonialism and empire.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AMST260', 'American Culture in the Information Age', 3, 3, 'Examines the ways in which content and form of public information interact with the culture, families & individuals.', NULL, NULL, TRUE, 'DSHS, SCIS', NULL, 'AMST260 or AMST298I.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'verified', '202608', 'AMST298I.', NULL, NULL, NULL, NULL, NULL),
    ('AMST262', 'Houses, Schools, and Prisons in American Life', 3, 3, 'This interdisciplinary course explores the role of property, discipline, and punishment in American life. By exploring the ideological underpinnings in property, discipline, and punishment and their manifestations in houses, schools, and prisons we will explore how these entities reflect American society and its values.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AMST269', 'Special Topics in Study Abroad II', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('AMST290', 'Constructing Cultural Mainstreams and Margins in the U.S.', 3, 3, 'Examines the construction, operation, and meaning of cultural mainstreams and margins in a range of contexts, spaces, and times in the U.S. Using a variety of primary sources, research methods, and interdisciplinary scholarship, we will explore how Americans make and assign meaning to cultural mainstreams and margins. We will examine how and why cultural margins and mainstreams shift over time and what their consequences have been for social policies, laws, power relations, and national identity.', NULL, NULL, TRUE, 'DSHS or DSHU, DVUP, SCIS', NULL, 'AMST289A or AMST290.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'verified', '202605', 'AMST289A.', NULL, NULL, NULL, NULL, NULL),
    ('AMST298', 'Selected Topics in American Studies', 3, 3, 'Cultural study of a specific theme or issue involving artifacts and documents from both past and contemporary American experience.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AMST298J', 'Reproductive Justice: An Introduction', 3, 3, 'Developed by feminists of color, reproductive justice frameworks offer a roadmap for economic, social, and medical justice advocacy attentive to the intersections of race, class, gender, sexuality, and disability. This course reviews the historical, legal, and social bases of reproductive rights in the U.S.; discusses the history of feminist organizing for reproductive freedom; surveys critical theories of reproductive justice that go beyond abortion law to advocate for broader social transformation; and evaluates the possible futures of intersectional feminist activism after the overturning of Roe v. Wade.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'WGSS205, AMST298J, or AAAS298E.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'verified', '202608', NULL, 'WGSS205, AAAS298E.', NULL, NULL, NULL, NULL),
    ('AMST298Q', 'U.S. Latinx Literature and Culture', 3, 3, 'Examines the poetry, prose, and theater of Latinx communities in the United States from their origins in the Spanish colonization of North America to their ongoing development in the 21st century. Considers how authors use literary form to gain insight into human experience, including mortality, religious belief, gender and sexuality, war and peace, family, language use, scientific inquiry, cultural tradition, ecology, and labor. Also studies how Latinx literary traditions have shaped and been shaped by broader currents in American literature, as well as what connections exist between Latinx literature and social and artistic developments in other parts of the world, particularly Latin America and the Caribbean. Authors may include Alvar Nunez Cabeza de Vaca, Eulalia Perez, Juan Nepomuceno Seguin, Maria Amparo Ruiz de Burton, Jose Marti, Arthur A. Schomburg, Jesus Colon, Julia de Burgos, Cesar Chavez, Ariel Dorfman, Gloria Anzaldua, Junot Diaz, and Cristina Garcia.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, 'ENGL235 or AMST298Q.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'verified', '202608', NULL, 'ENGL235.', NULL, NULL, NULL, NULL),
    ('AMST310', 'Introduction to Comparative Ethnic and Racial Studies', 3, 3, 'Introduces students to the study of race and ethnicity in the United States. The class is organized according to the following five units: (1) Introduction; (2) Key concepts; (3) Mechanisms of racial formation; (4) Prevailing myths about race; and (5) Contemporary issues related to race and ethnicity. Through readings, film clips, and presentations, we will explore how the concept of race has developed and endured over time and become familiar with key concepts, such as "race" and "intersectionality". We will attempt to better understand how race is associated with other forms of difference, such as class, gender and ethnicity. We will identify and confront the prevailing myths about race and ethnicity in the United States. Finally, we examine the ways in which contemporary issues reveal the dynamics of race and ethnicity.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'AMST310, AAST398F, AAST310, or AMST328L.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'verified', '202608', 'AMST328L and AAST398F.', 'AAST310.', NULL, NULL, NULL, NULL),
    ('AMST312', 'Introduction to Native American and Indigenous Studies', 3, 3, 'Key concepts and theories in Native American Studies beginning with an overview of the field and some of its foundational readings and history, then will move into an understanding of Native American identity and representation and a discussion of Indigenous sovereignty and self-determination. The course will outline past and present genocidal practices that seek to eliminate Native people and Indigenous responses to those structures such as the concept of survivance, Native feminisms, and theories of Indigenous resurgence. The course seeks to move students through an understanding of past and present structures affecting Native American people in the United States and Canada and move into readings that highlight Native articulations of present and future agency. While the focus of the course is Native peoples with the United States and Canada, understanding Indigenous histories and concepts always includes a hemispheric and transnational analysis.', NULL, NULL, TRUE, NULL, NULL, 'AMST328N, ANTH468F, RELS319N, or AMST312.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'none_found', NULL, 'AMST328N, ANTH468F, or RELS319N.', NULL, NULL, NULL, NULL, NULL),
    ('AMST315', 'Religion in American Culture', 3, 3, 'Introduces students to the world''s major religious traditions and examines how American culture informs, and is informed by, the variety of religious beliefs and practices in the U.S. This course is primarily concerned with religion as a system of meaning. The focus of the course is not on the history of religion or on analysis of religious texts, but rather on the meaning of a religion to its believers.', NULL, NULL, TRUE, NULL, NULL, 'AMST315 or AMST328R.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'none_found', NULL, 'AMST328R.', NULL, NULL, NULL, 'AMST101.', NULL),
    ('AMST320', '(Dis)ability in American Film', 3, 3, 'Explores the connection between film and disability through an analysis of independent and mainstream American films in various film genres. Specifically, we will consider how these film representations reflect and/or challenge the shifting social perspectives of disability over the 20th and 21st centuries. Beginning with the presentation of disability as theatrical spectacle in the traveling sideshow and early cinema, we will work our way through film history to develop an understanding of our society''s complicated relationship with disability.', NULL, NULL, TRUE, 'DSHU or DSSP, DVUP', NULL, 'AMST320 or AMST328X.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'verified', '202608', 'AMST328X.', NULL, NULL, NULL, NULL, NULL),
    ('AMST323', 'Filipino American History and Biography', 3, 3, 'Focus is placed on Filipino American experiences with an emphasis on identity, community building and organizing to influence public policy We will cover pertinent events from the US and Philippine history in order to understand the impact of colonialism, migration, immigration and assimilation on Filipino Americans.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'AAST363, AMST323, AAST398D, or AMST328J.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'verified', '202508', 'AAST398D.', 'AAST363.', NULL, NULL, NULL, NULL),
    ('AMST324', 'Growing Up Asian American: The Asian Immigrant Family and the Second Generation', 3, 3, 'An interdisciplinary course examines the experiences of children of Asian immigrants in the U.S., focusing on intergenerational dynamics in the Asian immigrant family, their intersections with race, gender, class, sexuality, and religion, and how these shape second-generation Asian American life. Topics include identity and personhood, the model minority myth and education, work and leisure, language and communication, filiality and disownment, mental health and suicide.', NULL, NULL, TRUE, 'DVCC', NULL, 'AAST394, AAST398E, AMST324, AMST328V, IMMR319G or IMMR394.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'verified', '202608', 'AAST398E.', 'AAST394, IMMR394.', NULL, NULL, NULL, NULL),
    ('AMST328', 'Perspectives on Identity and Culture', 3, 3, 'Analysis of the cultural aspect of identity formation and the role of individual or community identities in cultural production. Examination of cultural texts such as film, literature, fashion, artifacts, archival records, architecture, monuments, sports, and paintings.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'none_found', NULL, NULL, NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('AMST328Q', 'Indigenous Feminisms', 3, 3, 'Students will engage with scholarship concerning Indigenous conceptions of gender, sexuality, family, and governance. In each unit, participants will study traditional practices, conceptions, and expressions of Indigenous feminisms; identify the disruptive tactics of settler colonialism, centering the resilience and resurgence of Indigenous communities. In a collaborative "pod" framework, students will engage in discussions and projects throughout the term. By the end of the course, students will craft a creative project reflecting their insights and intended contribution to Indigenous feminist movements. Key focal points include the deep dive into traditional conceptions of gender, the impact of colonial interventions, the complexities of Indigenous sexualities, familial adaptations under colonial strain, Indigenous governance, and Indigenous-led resistance and reclamation such as pipeline protests, protection of sacred Mauna Kea, and the MMIW movement.', NULL, NULL, TRUE, NULL, NULL, 'WGSS379I, WGSS330, or AMST328Q.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'none_found', NULL, 'WGSS379I.', 'WGSS330.', NULL, NULL, NULL, NULL),
    ('AMST328W', 'Asian Americans in Film', 3, 3, 'Explores how Asian Americans have historically been represented in the U.S. by Hollywood, and in turn, how independent and Hollywood Asian American filmmakers have represented themselves. It covers the history of racial, gendered, and sexualized representations of Asian Americans in Hollywood, as well as Asian American filmic responses within and outside Hollywood. It also introduces how four basic tools of film analysis mise-en-scene, cinematography, editing and sound work together to create meaning in moving images. It examines how these elements are put together in three different types of films by Asian American filmmakers: narrative, documentary, and experimental. How films function in society to circulate ideas that reproduce and challenge stereotypes about Asian Americans.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, 'AAST355, AAST398L or AMST328W.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'verified', '202608', '398L.', 'AAST355.', NULL, NULL, NULL, NULL),
    ('AMST340', 'Introduction to History, Theories and Methods in American Studies', 3, 3, 'Introduction to the process of interdisciplinary research, including research literatures, questions, first-hand sources and library and analytic methods in American Studies. Each student will craft a prospectus for original research.', 'Must have completed AMST201; and 2 courses in AMST.', NULL, FALSE, NULL, 'Must be in American Studies program; and sophomore standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AMST369', 'Special Topics in Study Abroad III', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('AMST386', 'Experiential Learning', 3, 6, '', NULL, NULL, TRUE, NULL, 'Permission of ARHU-American Studies department; and junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AMST388', 'Honors Thesis', 3, 6, 'Individual research, thesis and oral defense. The research project will be conducted under the supervision of a faculty member.', NULL, NULL, TRUE, NULL, 'Must be admitted to AMST honors program; and permission of ARHU-American Studies department; and senior standing.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AMST398', 'Independent Studies', 1, 3, 'Provides the student with the opportunity to pursue independent, interdisciplinary research and reading in specific areas of American culture studies.', NULL, NULL, TRUE, NULL, 'Permission of ARHU-American Studies department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AMST418', 'Cultural Themes in America', 3, 3, 'Examination of structure and development of American culture through themes such as "growing up American," "culture and mental disorders," "race," "ethnicity," "regionalism," "landscape," and "humor."', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AMST418N', 'Asian American Public Policy', 3, 3, 'Using Asian Pacific Americans as a case study, this course will analyze the development of public policy in America. Each week, topics such as community development, voting rights, and the movement to redress the wartime internment of Japanese Americans will serve as backdrops for discussion. We will explore the policy-making roles of legislators, judges, local and national political leaders, journalists, writers, unions, social movements, and community organizations.', NULL, NULL, TRUE, 'DVCC', NULL, 'AAST421, AAST498M or AMST418N.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'verified', '202608', 'AAST498M.', 'AAST421.', NULL, NULL, NULL, NULL),
    ('AMST425', 'Film and American Landscape', 3, 3, 'Explores how representations of various geographic spaces in American film impact our understanding of community, identity, and place. In particular, we will think about how these spaces are culturally produced and changeable rather than static. The same space can hold diverse meanings for various groups of people and how such a space is represented in film is often wrapped up with issues of power, the reinforcement of stereotypes, and the creation of self/other dichotomies. By analyzing a variety of narrative, documentary, major studio, and independent films, we will seek to understand how American films'' representations of rural, urban, and suburban spaces both reflect, contradict, and often influence our lived experiences of these spaces; in other words, this course will examine how the "reel" intersects with the "real".', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, 'AMST418K or AMST425.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'verified', '202601', 'AMST418K.', NULL, NULL, NULL, NULL, NULL),
    ('AMST428', 'American Cultural Eras', 3, 3, 'Investigation of a decade, period, or generation as a case study in significant social change within an American context. Case studies include "Antebellum America, 1840-1860" and "American culture in the Great Depression."', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AMST429', 'Perspectives on Popular Culture', 3, 3, 'Topics in popular culture studies, including the examination of particular genres, themes, and issues.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AMST450', 'Seminar in American Studies', 3, 3, 'Developments in theories and methods of American Studies scholarship, with emphasis upon interaction between the humanities and the social sciences in the process of cultural analysis and evaluation.', 'AMST201 and AMST340; and 1 course in AMST.', NULL, FALSE, 'DSSP', 'Senior standing; and must be in American Studies program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'unstructured', 'verified', '202601', NULL, NULL, NULL, NULL, NULL, NULL),
    ('AMST498', 'Special Topics in American Studies', 3, 3, 'Topics of special interest.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'none_found', NULL, NULL, NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('AMST498J', 'Asian American Politics', 3, 3, 'Students will gain a greater understanding of 1) the role of Asian Americans in US politics, 2) the political attitudes and behaviors of Asian Americans and 3) how to conduct research on Asian American politics. Though the class will concentrate on Asian Americans, issues related to Asian American politics will be examined within the larger context of America''s multicultural political landscape.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'AAST498T, AAST443, GVPT368C or AMST 498J.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'verified', '202608', 'AAST498T.', 'AAST443, GVPT368C.', NULL, NULL, NULL, NULL),
    ('AMST499', 'Independent Studies', 1, 3, 'Provides the student with the opportunity to pursue independent, interdisciplinary research and reading in specific areas of American culture studies.', NULL, NULL, TRUE, NULL, 'Permission of ARHU-American Studies department; and must be in American Studies program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/amst/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('ANSC101', 'Principles of Animal Science', 3, 3, 'A comprehensive overview of the application of biology in the care and use of animals that live in close association with humans including food animals, companion animals, lab animals, zoo animals, etc. The role of science in modern food production using animals will be emphasized.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC103', 'Principles of Animal Science Laboratory', 1, 1, 'Laboratory focusing on the application of biology in the care and use of animals that live in close association with humans including livestock and companion animals. Labs will include live animals.', 'Must have completed or be concurrently enrolled in ANSC101.', NULL, TRUE, NULL, 'Must be in one of the following programs (Environmental Sci & Pol-Environment & Agriculture; Agricultural and Veterinary Medicine; Agricultural Science and Technology) ; or must be in a major within the AGNR-Animal & Avian Sciences department; or permission of department required for students in other College of AGNR programs.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC105', 'Horse Care Practicum', 1, 1, 'This practicum course provides the opportunity for students to be involved in the routine care of the horses housed at the Campus Farm including grooming, feeding, turnout, first aid, record-keeping, and cleaning. Practical skills are supplemented with online learning.', NULL, NULL, TRUE, NULL, 'Permission of the instructor.', 'ANSC108 or ANSC105.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'none', 'none_found', NULL, 'ANSC108.', NULL, NULL, NULL, NULL, NULL),
    ('ANSC115', 'Careers in the Animal Sciences', 1, 1, 'Discussion of current employment opportunities in Animal Science, primarily by invited speakers. In addition, students will have the opportunity to prepare resumes and improve oral presentation skills while working with their peers.', 'ANSC101 and ANSC103.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC120', 'Introduction to Dairy Judging', 2, 2, 'Students will establish an understanding of dairy cattle anatomy and importance in dairy production, while gaining the ability to evaluate dairy cattle for soundness and show-ring appeal. Additionally, the class aims to provide students with confidence in justifying decisions of evaluation and gain confidence in public speaking.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC121', 'Introduction to Livestock Judging', 2, 2, 'Students will establish a working understanding of the structural anatomy of several livestock species- cattle, sheep, pigs, goats- and their individual importance in the Agricultural Industry, while gaining the ability to evaluate these species for soundness and show-ring appeal. Additionally, the class aims to provide students with confidence in justifying decisions of based on their evaluations and gain skills in public speaking. The course will include two weekend field trips to farms in order to practice judging skills.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC201', 'Anatomy and Physiology of Domestic Animals', 4, 4, 'The anatomy and physiology of domesticated animals with emphasis on functions related to homeostasis. Students will be developing an ability to think about material in processes. They will also gain experience in scientific writing and data analysis.', 'ANSC101, ANSC103, BSCI170, and (BSCI180 or BSCI171).', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC210', 'Veterinary Terminology', 1, 1, 'Students will learn terminology related to the clinical practice of small and large animal medicine including medical record terminology and a systems-based consideration of common practices and pathologies.', 'ANSC204 and ANSC205; or ANSC201.', NULL, FALSE, NULL, 'Must be a major in Animal Sciences.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'The course is offered on-line through a series of self-paced modules on ELMS.'),
    ('ANSC226', 'The Future of Animal Agriculture', 3, 3, 'Offers students the opportunity to learn about the history of animal agriculture in the United States and envision what its future might be as it adapts to major challenges such as our growing global population, climate change, food injustice, antimicrobial and insecticide resistance, animal welfare concerns, and farmer distress. The course will examine technological & biotechnological, agroecological, and social innovations that address these issues while providing healthy, safe, nutritious food. Students are invited to learn about these issues and to create and propose their own solutions through weekly "extend your learning" opportunities and a course project in animal agricultural extension.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'The course is hosted on ELMS-Canvas and will require students to have reliable access to the internet.'),
    ('ANSC227', 'Eating with Eyes Wide Open', 3, 3, 'Are our diet and agricultural production methods sustainable? Students will investigate tensions created by trade-offs made by consumers relative to dietary choices which, in turn, can influence agricultural production methods. The course will inform students about their food supply so they can make informed dietary decisions and practice intentional/informed eating.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC232', 'Horse Management', 3, 3, 'An introductory course on the care, management, and use of horses. Major topics include the industry, breeds, conformation, feeding, health, reproduction, facilities and business.', 'ANSC101 and ANSC103.', NULL, TRUE, NULL, NULL, 'ANSC232 or ANSC332.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'parsed', 'none_found', NULL, 'ANSC332.', NULL, NULL, NULL, NULL, NULL),
    ('ANSC237', 'Equine Reproductive Management', 3, 3, 'Students learn the fundamental skills necessary to manage an equine breeding herd including anatomy/physiology of genital tracts, estrus detection, manipulation of the estrous cycle, semen collection, pre- and post-foaling techniques, infertility, and health and nutrition of the mare, foal and stallion. Students will be required to spend ~ 30 hours during the spring semester caring for broodmares and foals and attending at least one foaling and estrous detection checks on broodmares outside of regularly scheduled class time.', 'ANSC232.', NULL, TRUE, NULL, NULL, 'ANSC237 or INAG233.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'Course participation will include nightly checks of mares in the two weeks prior to parturition, and out-of-class time imprinting and working with newborn foals.'),
    ('ANSC242', 'Dairy Cattle Management', 3, 3, 'All aspects of dairy production, including nutrition, reproduction, mastitis control, milking management, farmstead facilities, financial management and forage production.', 'ANSC101 and ANSC103.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'parsed', 'none_found', NULL, 'ANSC240 and ANSC241.', NULL, NULL, NULL, NULL, NULL),
    ('ANSC245', 'Sheep Management', 3, 3, 'Popularly known as "Lamb Watch", this course provides an immersion environment for learning and understanding pre- and post-natal care of ewes and lambs through direct, hands-on involvement in the birthing process and care of the neonate through weaning on the campus farm. Course topics include zoonoses, basic reproductive physiology of the sheep, normal and abnormal parturition, management of lambs, qualitative assessment, breeding principles, nutrition, products and their marketing, and ram management.', 'Minimum grade of C- in ANSC101 and ANSC103.', NULL, TRUE, NULL, 'Must be in one of the following programs (Animal Sciences: Animal Care & Management; Animal Sciences: Equine Studies; Animal Sciences: Laboratory Animal Care; Animal Sciences: Sciences/Preprofessional; Animal Sciences: Animal Biotechnology; Agricultural and Veterinary Medicine).', 'ANSC235 or ANSC245.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC246', 'Beef Management', 3, 3, 'Provides an interactive environment for learning and understanding all areas of beef cattle management including hands-on involvement in the birthing process and care of newborn calves on the campus farm. Course topics will include: An introduction to Beef Production, Breeding and Selection, Reproduction, Nutrition, Cattle Health and Diseases, Cattle Behavior, facility design and management, and Careers working in the American Beef industry.', 'ANSC101 and ANSC103.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'Students will participate in night watches at the campus farm.'),
    ('ANSC250', 'Companion Animal Care and Management', 3, 3, 'Care and management of the companion small animals. Species covered include the cat, dog, rodents, lagomorphs, reptiles, amphibians, birds and others as class interest and schedule dictate. Basic description, evolutionary development, breeding, nutritional and environmental requirements, and public health aspects will be presented for each species.', NULL, NULL, TRUE, 'DSSP', NULL, 'ANSC250 and ANSC305.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'none', 'verified', '202601', 'ANSC305.', NULL, NULL, NULL, NULL, NULL),
    ('ANSC255', 'Introduction to Aquaculture', 3, 3, 'Introduces the art and science of rearing aquatic animals and the essential principles of aquaculture. Students receive hands-on training in the methods required for successful husbandry and management of aquatic animals in their water environment.', 'ANSC101 and ANSC103; or must have completed an introductory biology course (BSCI170 and BSCI171; OR BSCI160 and BSCI161).', NULL, FALSE, 'DSSP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC260', 'Laboratory Animal Management', 3, 3, 'A comprehensive course in care and management of laboratory animals. Topics covered include regulations governing the use of animals in research, laboratory animal facility design and management, animal research models, animal health management and husbandry, responsibilities of lab animal workers and career opportunities in the field. Hands-on labs focus on lab animal handling, husbandry and common techniques. Field trips are required, and you must attend a minimum number of field trips which will be held during lab time.', 'ANSC101 and ANSC103.', NULL, TRUE, NULL, NULL, 'ANSC260 or ANSC413.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'parsed', 'none_found', NULL, 'ANSC413.', NULL, NULL, NULL, NULL, NULL),
    ('ANSC262', 'Poultry Management', 3, 3, 'This course introduces the theory and science of poultry management and flock health, with an emphasis on basic poultry epidemiology in both commercial and backyard settings. Topics include poultry rearing, marketing of poultry meat and eggs, current industry issues, industry organization, and the fundamental biology of poultry. Students learn how management practices influence disease occurrence and spread, and apply introductory epidemiologic concepts to biosecurity, vaccination, and flock health decision-making in vertically integrated and small-scale systems. Students will examine the vertical integration of the commercial poultry industry through field trips and study backyard and small-scale poultry production, including biosecurity, housing, nutrition, and flock health management. During the semester, students will help raise flocks of broiler chickens and laying hens.', 'ANSC101 and ANSC103.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC270', 'Animal Enterprise Management', 3, 3, 'General principles of enterprise organization, management, and operation as applicable to food, livestock, and companion animals. Enterprise planning and establishment, management of financial, human, and animal resources, and other related topics will be investigated.', 'ANSC101 and ANSC103; or permission of instructor.', NULL, FALSE, NULL, NULL, 'ANSC270 or AREC306.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC282', 'Grazing Animal Management', 3, 3, 'For students interested in acquiring knowledge and skills in pasture management, grazing management of livestock (large and small ruminants, horses), and hay production. Fundamental information regarding best management practices for soils, plants, and grazing livestock will be covered', 'ANSC101 and ANSC103; or permission of instructor.', NULL, FALSE, NULL, NULL, 'ANSC110, ANSC282, or INAG116.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'partial', 'none_found', NULL, 'ANSC110.', NULL, NULL, NULL, NULL, NULL),
    ('ANSC314', 'Comparative Animal Nutrition', 3, 3, 'The fundamental role and implications of dietary preference, gastrointestinal physiology and nutrients in animal nutrition. Biochemical roles of nutrients in metabolism, digestion, absorption and assimilation as it relates to various life processes.', 'ANSC101 and ANSC103; and (CHEM231, PLSC275 or AGST275).', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC315', 'Applied Animal Nutrition', 3, 3, 'Elements of nutrition, source characteristics and adaptability of various feedstuffs to several classes of livestock. A study of the composition of feeds, nutrient requirements and computerized formulation of economic diets and rations for livestock.', 'ANSC314.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC327', 'Molecular and Quantitative Animal Genetics', 3, 3, 'Classical, molecular, and population genetics with specific emphasis on animal systems will be covered. Also, disseminate information on molecular approaches for manipulating genetics at the whole animal level (transgenic and cloning). Other model organisms will be discussed to provide a conceptual framework.', 'ANSC101, CHEM131, and BSCI170.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC330', 'Equine Science', 3, 3, 'Students will explore key principles of equine anatomy, physiology, exercise, genetics, nutrition, and health management. Emphasis is placed on recognizing, managing, and preventing common equine disorders, providing students with the skills to address challenges faced by horse owners and farm managers. Through case studies and practical applications, students will develop a comprehensive understanding of maintaining equine well-being and optimizing performance.', 'ANSC232; or permission of instructor.', NULL, FALSE, NULL, NULL, 'ANSC230 or ANSC330.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'partial', 'none_found', NULL, 'ANSC230.', NULL, NULL, NULL, 'ANSC212 and ANSC214; or ANSC201.', NULL),
    ('ANSC340', 'Health Management of Animal Populations', 3, 3, 'A study of common and emerging animal infectious diseases and their prevention and control. The main focus will be on diseases of livestock, poultry, and companion animals; however, zoonotic, wildlife, and laboratory animal diseases will also be discussed along with biosecurity measures.', 'BSCI223; and (ANSC232, ANSC237, ANSC242, ANSC245, ANSC246, ANSC247, ANSC250, ANSC255, ANSC260, ANSC262, or ANSC282).', NULL, FALSE, 'DSSP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'verified', '202601', NULL, NULL, NULL, NULL, 'ANSC212 or ANSC201.', NULL),
    ('ANSC359', 'Internship Experience in Animal and Avian Sciences', 3, 6, 'Experiential learning is a key component in an animal science education. Through the internship program, you will have the opportunity to develop your expertise in a specific species and discipline within the animal science curriculum. You will arrange an on- or off-campus internship experience related to animal science. You will spend a specified number of hours at the internship site each week and attend biweekly classroom sessions where we will discuss how the study of animal science fits into your specific internship experience as well as understand how to achieve each of the course learning outcomes.', 'ANSC232, ANSC237, ANSC242, ANSC245, ANSC246, ANSC247, ANSC250, ANSC255, ANSC260, ANSC262, or ANSC282.', NULL, FALSE, 'DSSP', 'Must be in a major within the AGNR-Animal & Avian Sciences department; and permission of instructor.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'verified', '202608', NULL, NULL, NULL, '6 credits if content differs.', NULL, 'Students are required to submit an application to the Animal Science Internship Coordinator to enroll in this course.'),
    ('ANSC371', 'Sustainable Agriculture and Environment: Global Seminar', 1, 1, 'Students will learn how developing countries are building their agricultural economies to address multiple goals including reducing poverty, improving food security, as well as decreasing impacts from climate change and decreasing greenhouse gas emissions. The historical, political and social context will be discussed, and perspectives will be provided from representatives from diverse groups including farm workers, farm owners, women, and indigenous peoples. We will discuss examples of sustainable agroecology and incentives and impediments to their implementation.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'This course is a prerequisite and companion to an optional winter-term study abroad course, ANSC372. Together these courses provide 3 General Education credits for Scholarship in Practice (DSSP) and Diversity: Cultural Competence (DVCC), and an elective for the Sustainability Minor.'),
    ('ANSC372', 'Sustainable Agriculture and Environment: Study Abroad', 2, 2, 'A short-term study abroad course on agriculture in developing countries. Travel destination will vary from year to year among member countries with campuses of the Latin American Institute of Agroecology, and member organizations in the international farm organization, La Via Campesina. Travel will include farm visits, women''s cooperatives, and cultural organizations. Students will focus on poverty reduction, food security, and climate change, and the historical, political, and social context. A research paper is required based on interviews.', 'ANSC371.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'This course and the prerequisite (ANSC371) together provide 3 General Education credits for Scholarship in Practice (DSSP) and Diversity: Cultural Competence (DVCC), and an elective for the Sustainability Minor.'),
    ('ANSC379', 'Animal Science Undergraduate Teaching Assistant Seminar', 2, 2, 'Seminar course for undergraduate teaching assistants within ANSC.', 'Permission of instructor.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'none_found', NULL, 'ANSC390.', NULL, NULL, '8 credits.', NULL, NULL),
    ('ANSC386', 'Experiential Learning', 3, 6, '', 'Permission of AGNR-Animal & Avian Sciences department.', NULL, FALSE, NULL, 'Junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC388', 'Honors Thesis Research', 3, 6, 'Undergraduate honors thesis research conducted under the direction of an AGNR faculty member in partial fulfillment of the requirements of the College of AGNR Honors Program. The thesis will be defended to a faculty committee.', NULL, NULL, TRUE, NULL, 'Must be in the AGNR Honors program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('ANSC389', 'Experiential Learning', 3, 6, '', 'Permission of AGNR-Animal & Avian Sciences department.', NULL, FALSE, NULL, 'Junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'none_found', NULL, 'ANSC386.', NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('ANSC398', 'Seminar - Research', 1, 1, 'Presentation and discussion of current literature and research work in animal science.', 'ANSC101 and ANSC103.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, '2 credits if content differs.', NULL, NULL),
    ('ANSC399', 'Special Problems in Animal Science', 1, 2, 'Work assignments are designed to be proportional to the amount of credit. Students are expected to develop an abstract, fact sheet, manuscript, oral presentation, poster, webpage, journal-log, or other scholarly product associated with their study and/or project.', 'ANSC101 and ANSC103.', NULL, TRUE, NULL, 'Permission of AGNR-Animal & Avian Sciences department; and junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('ANSC401', 'Animal Growth and Development for Production Agriculture', 3, 3, 'An integration of the physiological, genetic, and nutritional bases of animal growth, development, and body composition with application to livestock production.', 'ANSC201.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC410', 'The Gut Microbiome and its Roles in Health and Disease', 3, 3, 'A comprehensive study of the gut microbiome and its role in nutrition, metabolism, immunity, and disease prevention, with applications to farm animal health, food value, and human gastrointestinal health.', '1 course from (BSCI223, ANSC201, ANSC212, ANSC327, EPIB301, BSCI222, BSCI421, NFSC430); or students who have taken courses with comparable content may contact the department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC417', 'Regulatory Issues in Animal Care and Management', 3, 3, 'A study of regulatory issues affecting animal care and management in the livestock industry. Guest speakers and classroom discussions will focus on key topics including animal welfare, feed and drug regulations, animal identification, CAFO management, processing and marketing of animal products.', 'ANSC232, ANSC237, ANSC242, ANSC245, ANSC246, ANSC247, ANSC250, ANSC255, ANSC260, ANSC262, or ANSC282; or permission of instructor.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'Field trips may be required for this course.'),
    ('ANSC435', 'Experimental Embryology', 3, 3, 'Experimental approaches in animal embryology with emphasis on domestic livestock systems as applied to research and production systems. Lab will include hands-on experiments and demonstrations of techniques that are commonly used in industry and research.', 'ANSC212 or ANSC201.', NULL, FALSE, 'DSSP', NULL, 'ANSC435 or ANSC489M.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'verified', '202608', 'ANSC489M.', NULL, NULL, NULL, 'ANSC446.', NULL),
    ('ANSC436', 'Animal Health Policy and Communication', 3, 3, 'Intended for upper level students in Veterinary Medicine or Animal Science as well as other students who are interested in understanding how science and politics interact and influence animal health policy and how veterinarians and animal scientists can effectively communicate science to non-scientists such as legislators and policymakers.', NULL, NULL, TRUE, NULL, 'Must be in a major within the AGNR-Animal & Avian Sciences department; or permission of AGNR-VA-MD Regional COL Veterinary Med.', 'ANSC489A, ANSC436, or VMSC436.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'none', 'none_found', NULL, 'ANSC489A.', 'VMSC436.', NULL, NULL, 'Completion of ANSC225 and ANSC340 recommend.', NULL),
    ('ANSC437', 'Animal Biotechnology', 3, 3, 'Key concepts and current issues in animal biotechnology are covered. Current techniques and applications systems as well as social, ethical, and regulatory issues associated with biotechnology will be discussed.', 'ANSC327; or students who have taken courses with comparable content may contact the department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC440', 'Zoonotic Diseases and Control', 3, 3, 'Examines zoonotic diseases of importance in the United States and worldwide, with an emphasis on those originating from farm animals as well as those transmitted by vectors such as rodents and arthropods. Topics include major foodborne and vector-borne zoonoses, principles of transmission and control, human risk factors, and surveillance methods. Students will also explore the historical and emerging significance of zoonotic diseases, approaches to vector management, alternatives to pesticide use, and relevant regulations and safety measures.', '1 course from (BSCI223, ANSC201, ANSC212, ANSC327, BSCI222, BSCI421, NFSC430); or students who have taken courses with comparable content may contact the department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC444', 'Domestic Animal Endocrinology', 3, 3, 'A comprehensive course covering the major endocrine systems in domestic animals. Topics include each of the major endocrine axes, hormonal regulation of homeostasis, growth and reproduction, molecular endocrinology and endocrine mechanisms of action.', 'ANSC212 or ANSC201.', NULL, FALSE, NULL, 'Must not have completed ANSC644.', 'ANSC444 or ANSC644.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC445', 'Comparative Gut Physiology & Diseases', 3, 3, 'Explores the anatomy, histology, and physiology of the gastrointestinal (GI) system in humans and animals, including dogs, pigs, horses, cattle, and birds. Students will study how gut function supports health and development, and how it becomes disrupted in common and emerging diseases. The course also explores the gut''s functions beyond the GI tract, including its roles in the gut-liver and gut-brain axes, while reviewing important research on gastrointestinal disorders. It prepares students for careers in veterinary and human medicine, industry, and scientific research.', 'ANSC212 or ANSC201.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC446', 'Physiology of Mammalian Reproduction', 3, 3, 'Provides an in-depth examination of reproductive anatomy and physiology in domesticated livestock species, emphasizing the biological mechanisms and management strategies that influence reproductive efficiency. Students will explore the endocrine regulation of reproduction, assisted reproductive technologies, and factors affecting fertility, pregnancy, parturition, and lactation. The course integrates scientific principles with practical applications in animal agriculture, preparing students to evaluate and apply reproductive management techniques in livestock production systems.', 'ANSC212, ANSC201 or BSCI440.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC447', 'Physiology of Mammalian Reproduction Laboratory', 1, 1, 'Gross and micro-anatomy, artificial insemination, estrous cycle synchronization and invitro-fertilization procedures and analytical techniques useful in animal management and reproduction.', 'Must have completed or be concurrently enrolled in ANSC446.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC450', 'Animal Breeding Plans', 3, 3, 'Design of animal breeding programs for the genetic improvement of livestock and companion animal species. Principles of population and quantitative genetics. Genetic evaluations of animals, selection strategies and crossbreeding systems. Incorporation of statistics and biotechnology into animal breeding plans.', 'ANSC101; and 1 course with a minimum grade of C- from (MATH120, MATH136, MATH140, or BIOM301).', NULL, TRUE, NULL, 'Junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC452', 'Avian Physiology', 3, 3, 'Provides a comparative study of avian and mammalian physiology, with emphasis on similarities and differences across systems. Students will analyze the reproductive, digestive, renal, respiratory, circulatory, immune, endocrine, and nervous systems of birds, as well as physiological adaptations unique to avian species such as flight and migration.', 'ANSC201 or ANSC212.', NULL, FALSE, NULL, 'Junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC453', 'Animal Welfare and Bioethics', 3, 3, 'Ethical concerns related to the use of animals in modern society. Historical and philosophical overview of animal welfare and bioethics. Applied ethical discussions on human/animal interrelationships, physical and genetic manipulation, and other current issues associated with the treatment of animals used in food production, research, zoos, and as pets.', 'ANSC101 and ANSC103; or BSCI160 and (BSCI180 or BSCI161); or permission of instructor.', NULL, FALSE, NULL, 'Junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC454', 'Nutritional Aspects of Metabolic Disease', 3, 3, 'Biochemical and physiological fundamentals of nutrition. Discussion of protein, fat,carbohydrate, minerals and vitamins and their roles and interrelationships innutrition, metabolism and diseases in humans and animals. The course will use recommended texts for foundation material as well as research papers to provide in-depth coverage and illustrate emerging themes in metabolic aspects of nutrition and disease.', 'CHEM131 and ANSC101, or BSCI170; or students who have taken courses with comparable content may contact the department.', NULL, FALSE, NULL, NULL, 'ANSC4890 or ANSC454.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'none_found', NULL, 'ANSC489O.', NULL, NULL, NULL, NULL, NULL),
    ('ANSC455', 'Applied Animal Behavior', 3, 3, 'Principles of animal behavior applied to production systems in animal agriculture.', 'ANSC101 and ANSC103; or BSCI106; or (BSCI160 and BSCI161).', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC460', 'Comparative Vertebrate Immunology', 3, 3, 'Basic concepts in immunology, and comparing immunity in different vertebrates, including organization of immune systems, innate and adaptive immune responses. Special attention will be paid to how cell-mediated and humoral immune responses are induced in natural infections, and what are the effector mechanisms in both of these processes. Immune response in representative disease models such as infections with viruses and bacteria, cancer, and autoimmune disease will be discussed. Lectures concerning cutting-edge research will also be given.', 'ANSC212, ANSC201, BSCI201, or BSCI440.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANSC489', 'Current Topics in Animal Science', 1, 3, 'Examination of current developments in the animal sciences.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('ANSC497', 'Animal Biotechnology Recombinant DNA Laboratory', 3, 3, 'An advanced course offering hands-on experience in performing recombinant DNA experiments. Current molecular biology techniques used for cloning genes, analyzing the gene products, and modifying the genes of animals will be performed. Techniques include isolation of DNA, use of restriction enzymes; cloning procedures, PCR analysis, and Southern hybridizations. Lecture material focuses on interpretation of results generated in the laboratory.', 'ANSC327; or students who have taken courses with comparable content may contact the department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ansc/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, 'ANSC437 and ANSC435.', NULL),
    ('ANTH138', 'Special Topics in Study Abroad I', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('ANTH210', 'Introduction to Medical Anthropology and Global Health', 3, 3, 'An introduction to the central concepts in medical anthropology and the anthropology of global health. This course is a survey of anthropological notions of health, disease, and the body in cross-cultural and global contexts, including classic and contemporary texts. It will provide an examination of systems of knowledge and practice with regard to illness, healing, and global health inequities.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH221', 'Introduction to Forensic Sciences', 3, 3, 'Provides a brief history of forensic sciences, an introduction to some of the techniques used, and a demonstration of some of the applications of forensic sciences. A survey course designed to give the student some exposure to the kinds of scientific knowledge and techniques applied to the medico-legal investigation of death and other crimes.', NULL, NULL, TRUE, 'DSSP', NULL, 'ANTH298A or ANTH221.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'verified', '202605', 'ANTH298A.', NULL, NULL, NULL, NULL, NULL),
    ('ANTH222', 'Introduction to Ecological and Evolutionary Anthropology', 4, 4, 'An introduction to the evolution of human physiology and human behavior, the relationship between hominid and non-hominid primates, and the study of relationships between a population of humans and their biophysical environment.', NULL, NULL, TRUE, 'DSNL, DVUP', NULL, 'ANTH220 or ANTH222.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH238', 'Special Topics Study Abroad II', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('ANTH240', 'Introduction to Archaeology', 3, 3, 'Exploration of the variety of past human societies and cultures through archaeology, from the emergence of anatomically modern humans to the more recent historical past.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH242', 'Fire, Farming and Climate Change: An Archaeology Take on the History of Human Impacts on our Planet', 3, 3, 'An examination of why climate changes, the methods for recording climate change, and case studies of the varied responses of past human societies to climate change in different geographic regions and time periods with varying socio-political and economic systems.', NULL, NULL, TRUE, 'DSHS, SCIS', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'verified', '202601', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH252', 'Playing Games: Virtual Worlds & the Human Experience', 3, 3, 'How do games and virtual worlds inform anthropological understanding of the human experience?', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH260', 'Introduction to Sociocultural Anthropology and Linguistics', 3, 3, 'Culture and social relationships in a wide variety of settings from small-scale to complex societies. An overview of how anthropology analyzes human behavior. Particular attention to the relationship between language and culture.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH263', 'Sexuality and Culture', 3, 3, 'An overview of sexuality from an anthropological perspective, looking at aspects of sexuality within our own culture and in cultures around the world. Course topics include the biology and culture of sex, gender, physical attraction, sexual orientation, marriage and mating taboos, fertility control, sexually transmitted diseases, and commercial aspects of sex.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'ANTH298K or ANTH263.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'verified', '202605', 'ANTH298K.', NULL, NULL, NULL, NULL, NULL),
    ('ANTH264', 'Immigration Policy, Immigrant Lives', 3, 3, 'An examination of the phenomenon of international migration, or immigration. Students develop awareness of how immigration has been framed in the general public and examined by social science disciplines, most prominently anthropology. Examination of case studies of different immigrant groups in distinct geographic contexts will illuminate the varied incorporation experiences of immigrants into U.S. society.', NULL, NULL, TRUE, 'DSHS, DVUP, SCIS', NULL, 'ANTH264 or IMMR219C.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'verified', '202605', NULL, 'IMMR219C.', NULL, NULL, NULL, NULL),
    ('ANTH265', 'Anthropology of Global Health', 3, 3, 'An overview of the growing field of global health including health care systems, medical practices, ideas about illness in cross-cultural contexts, issues of health development, global health inequity, and human rights issues. The course will focus on the history of global health, the critique of major international health agencies and their development paradigms, and the political economy of social inequalities and health.', NULL, NULL, TRUE, 'DSHS, DVUP, SCIS', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH266', 'Changing Climate, Changing Cultures', 3, 3, 'Explore past, present, and future interactions between humans and climate. Discussions, methods-oriented activities, and case study analyses provide students a foundation for appreciating the role of anthropology in understanding, responding to, and preparing for climate change.', NULL, NULL, TRUE, 'DSHS, DVCC, SCIS', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH267', 'Organic, Mechanical, Digital', 3, 3, 'Beginning in the middle to late 20th century, human organization and experience has increasingly been influenced by digital forms of communication and production. Do these changes make us new types of people and societies? By putting the digital world in the context of the major periods associated with organic and mechanical technology, this course examines who contemporary people are and whether or not they are unique. The answer to this question will focus on how technological changes the individual, social organization and the relationship with the natural world. Sources from historians, anthropologists, sociologists, philosophers, political scientists and ecologists will be used to reconstruct these worlds.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH298', 'Special Topics in Anthropology', 3, 3, 'Anthropological perspectives on selected topics of broad general interest.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('ANTH299', 'Student Initiated Course', 1, 3, 'Student Initiated Course (STIC) in Anthropology. Course is student initiated and taught under close supervision of a faculty mentor.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, 'ANTH299 will serve as a "special topics" kind of number for any Student Initiated Courses (STIC) offered in Anthropology. So far, we have only offered one ANTH299A, sample syllabus attached.'),
    ('ANTH305', 'Archaeological Methods and Practice', 3, 3, 'A team-taught, interdisciplinary course discussing theories, methods, and ethical issues in the practice of archaeology.', 'ANTH240, ARTH200, CLAS180, or CLAS190.', NULL, TRUE, 'DSHS', NULL, 'ANTH305, ARTH305, CLAS305, or JWST319Y.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'parsed', 'verified', '202608', NULL, 'ARTH305, CLAS305, JWST319Y.', NULL, NULL, NULL, NULL),
    ('ANTH310', 'Method & Theory in Medical Anthropology and Global Health', 3, 3, 'Provides a critical perspective to global health that encompasses key political, economic, and cultural factors associated with the nature and magnitude of global health issues such as HIV/AIDS, tuberculosis and malaria, paying particular attention to how poverty and inequalities within and between societies has accelerated current global health challenges. Introduces students to how medical anthropologists have contributed to the debates surrounding the globalization of health.', 'ANTH210. Jointly offered with ANTH665.', NULL, FALSE, 'DSSP, DVUP', NULL, 'ANTH310, ANTH465, or ANTH665.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'unstructured', 'verified', '202605', 'ANTH465.', NULL, NULL, NULL, NULL, NULL),
    ('ANTH322', 'Method and Theory in Ecological Anthropology', 3, 3, 'A theoretical consideration of ecological anthropology, focusing on issues related to cooperation, the management of common property, resilience, and sustainability. Explores the methods of sociocultural anthropology, including ethnology, evolutionary game theory and agent-based modeling; and natural-science approaches including behavioral and systems ecology.', 'ANTH220 or ANTH222.', NULL, FALSE, NULL, 'Must be in a major within the BSOS-Anthropology department.', 'ANTH320, ANTH322, ANTH425, or ANTH625.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH323', 'Plagues, Pathogens and Public Policy', 3, 3, 'The impact of diseases on populations from prehistoric times through the present will be examined, along with public perceptions of disease, scientific breakthroughs on treatment and prevention, and the ways that politics and public health policies can enhance or impede the advancement of disease treatment. The natural history of disease, population structure, and immunity will be discussed. The class will address emerging and re-emerging diseases and the ways that first responders, researchers, and policy makers may affect the outcome of an outbreak.', NULL, NULL, TRUE, 'DSHS, SCIS', NULL, 'ANTH429A or ANTH323.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'verified', '202608', 'ANTH429A.', NULL, NULL, NULL, NULL, NULL),
    ('ANTH338', 'Special Topics in Study Abroad III', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('ANTH340', 'Method and Theory in Archaeology', 3, 3, 'Theory, method, and practice which guides modern anthropological archaeology. Includes research design and execution (from survey through excavation and interpretation), the reconstruction of aspects of past cultures, and the understanding of cultural change and meaning.', 'ANTH240.', NULL, TRUE, NULL, 'Must be in Anthropology program; or permission of BSOS-Anthropology department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH341', 'Introduction to Zooarchaeology', 3, 3, 'Zooarchaeology is the study of animal remains, especially bones, from archaeological contexts. This course will address both methodology as well as many of the main issues in contemporary zooarchaeology. Zooarchaeology stands at the intersection of a number of social and biological sciences, such as Biology, Osteology, Ecology, History, Anthropology and Economics. We will discuss basic animal osteology and the concepts and practices behind the identification of animal remains from archaeological contexts. We will cover the nature of the data in zooarchaeology, especially issues around using proxy data.', NULL, NULL, TRUE, 'DSSP', NULL, 'ANTH298D, ANTH641 or ANTH341.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'verified', '202601', 'ANTH298D.', NULL, NULL, NULL, NULL, NULL),
    ('ANTH345', 'Introduction to Laboratory Methods in Archaeology', 3, 3, 'The processing, curation, cataloging and analysis of data is an important part of any archaeology field project. Students will learn the basics of laboratory techniques necessary for the final analysis and interpretation of field data.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH357', 'Approaches to Sustainable Development', 3, 3, 'An overview of the history of sustainable development, major development and environmental theories, and development strategies as they relate to an anthropological concern for an integrated, holistic, comparative, and humane approach to sustainable development.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'ANTH357 or ANTH657.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'verified', '202605', NULL, NULL, 'ANTH657.', NULL, NULL, NULL),
    ('ANTH358', 'Undergraduate Teaching Assistant', 1, 3, 'Individual instruction course: contact department or instructor to obtain section and index numbers.', 'ANTH220, ANTH260, or ANTH240.', NULL, FALSE, NULL, 'Junior standing or higher; and must be in Anthropology program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('ANTH360', 'Method and Theory in Sociocultural Anthropology', 3, 3, 'Theoretical approaches and research methods in sociocultural anthropology. Emphasis on current debates, new directions, and their historical antecedents.', 'ANTH260.', NULL, TRUE, NULL, 'Must be in Anthropology program; or permission of BSOS-Anthropology department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH368', 'Regional Ethnography', 3, 3, 'Peoples and cultures of a particular region of the world, on the basis of ethnographies, archaeological evidence, and relevant works by social historians and political economists. The regional focus and thematic emphasis will vary by semester.', 'ANTH260; or permission of BSOS-Anthropology department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'partial', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('ANTH386', 'Experiential Learning', 1, 6, '', NULL, NULL, TRUE, NULL, 'Permission of BSOS-Anthropology department; and junior standing or higher; and must be in Anthropology program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, 'Completion of advanced courses in relevant subfield of anthropology recommended.', NULL),
    ('ANTH398', 'Independent Study', 1, 3, 'Independent interdisciplinary research and reading in specific areas of anthropology.', NULL, NULL, TRUE, NULL, 'Permission of BSOS-Anthropology department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('ANTH403', 'Queer Anthropology', 3, 3, '', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH407', 'Anthropology and Development', 3, 3, 'An examination of the intersection of Anthropology, international development and foreign policy. The course provides students with conceptual tools to engage with international development and other assistance projects in areas including conservation and climate change, governance and human security, gender, human rights, and political stability from a variety of viewpoints.', NULL, NULL, TRUE, 'DSSP', NULL, 'ANTH407 or ANTH607.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'verified', '202512', NULL, NULL, 'ANTH607.', NULL, NULL, NULL),
    ('ANTH411', 'Global Migration and Health', 3, 3, 'The United Nations estimates that some 230 million people around the world are migrants who live outside their country of birth. This course focuses on these migrant populations, considering the implications of movement across borders and settlement in new societies on their health and well-being. We will investigate the social, political, and economic structures that shape disease and illness and produce differential access to health care for migrants. Within that context, we will explore the health effects of migration itself and particular health conditions from which migrants suffer. We will also examine how migrants interface with differently configured health care systems as well as strategies they and their advocates use to promote health and well-being.', NULL, NULL, TRUE, NULL, NULL, 'ANTH411 or ANTH611.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, 'ANTH611.', NULL, NULL, NULL),
    ('ANTH412', 'Hypermarginality and Urban Health', 3, 3, 'Using perspectives from medical and urban anthropology, we examine the phenomenon of hypermarginality--the clustering of extreme poverty, chronic disease, addiction, violence and trauma in certain social and spatial contexts, often urban. We will explore both the broader social, political, and economic structures of exclusion that produce hypermarginality, as well as the illness experiences associated with these conditions. As we consider both social suffering and the related institutional responses, we will also discuss the role of anthropological approaches in national discussions about health inequities.', NULL, NULL, TRUE, NULL, NULL, 'ANTH412 or ANTH612.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH413', 'Health Inequities, Care, and Justice in the United States', 3, 3, 'Systematic health inequities in the United States are well documented, shaped by structural forces that determine who gets sick, what illnesses/diseases they are vulnerable to, what their care options are, how they are treated while seeking care, and their ultimate health outcomes. This course applies the concepts, methods, and theoretical approaches of medical anthropology to examine the roots and implications of these health inequities. Students will also assess efforts to address these inequities through tailored interventions and social movements organized around equity and justice.', NULL, NULL, TRUE, NULL, NULL, 'ANTH413 or ANTH613.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, 'ANTH613.', NULL, NULL, NULL),
    ('ANTH415', 'Critical Global Health', 3, 3, 'Extends understandings of diverse health conditions facing world populations today and the science being made around them. Critically examines key issues in global aid and public health, with an emphasis on the theories, concepts, and methods of anthropology.', NULL, NULL, TRUE, NULL, NULL, 'ANTH415 or ANTH615.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, 'ANTH615.', NULL, 'ANTH210, ANTH310, or ANTH265 or a similar course focused on global health or medical anthropology course.', NULL),
    ('ANTH416', 'Anthropology of Global Violence', 3, 3, 'An examination of anthropological approaches to the study of violence, drawing from key texts to analyze how violence operates along a continuum: from routine, sometimes invisible forms of violence embedded in everyday life, to more overt and exceptional forms. Consideration of the role of ethnography in elucidating both the subjective experiences of violence and the ways in which violence is embedded in institutions, structures, and global political-economic processes. Analysis of the specific relationships between violence, health, mental health, and trauma in local and global contexts.Jointly offered with ANTH616.', NULL, NULL, TRUE, NULL, NULL, 'ANTH468O, ANTH66 8O, ANTH416 or ANTH616.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, 'ANTH468O.', NULL, NULL, NULL, NULL, NULL),
    ('ANTH421', 'Nutritional Anthropology', 3, 3, 'The study of nutrition from an anthropological perspective which includes both biological and cultural aspects of nutrition. We will explore how nutrition can affect culture how culture can affect nutrition. Nutritional anthropology includes the study of cross-cultural variation in diet, nutritional status and subsistence systems as well as variation in these factors over the evolutionary course of human existence, from prehistoric and historic to modem times. Students will be introduced to nutritional anthropology and provided with the basics for assessing reliability and feasibility of nutritional advice and policy encountered in everyday modern life in a global setting.', NULL, NULL, TRUE, NULL, NULL, 'ANTH421, ANTH428N, or ANTH621.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, 'ANTH428N.', NULL, NULL, NULL, NULL, NULL),
    ('ANTH428', 'Special Topics in Bioanthropology', 3, 3, 'Advanced research courses in biological anthropology on changing topics that correspond to new theoretical interests, faculty research interests, or the specialties of visiting scholars. Prerequisites or background knowledge vary with the topic. Check with the department for requirements.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('ANTH429', 'Advanced Special Topics in Biological Anthropology', 3, 3, 'Upper level biological anthropology courses on varying topics derived from new interests of the faculty or the specialties of visiting scholars.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('ANTH433', 'Archaeology of Slavery: Classical, Caribbean and North American Contexts', 3, 3, 'Has slavery always existed? Does it come and go? North American plantation archaeology has become one of the foundations for understanding African American culture from the 1960s. Slavery in Antiquity existed in Greece and Rome on large scales and was essential to making commercial agriculture profitable work. Slavery in the Caribbean showed Europeans how to make a profit from African bodies. Trafficking in human persons today is recorded by the U.S. State Department annually and is regarded as modern slavery. These varying contexts of slavery will be compared in an attempt to understand slavery scientifically.', NULL, NULL, TRUE, NULL, NULL, 'ANTH433 or ANTH633.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, 'ANTH633.', NULL, NULL, NULL),
    ('ANTH435', 'Archaeological Ethnography and Heritage Ethnography', 3, 3, 'Archaeologists and other heritage experts are increasingly incorporating ethnographic approaches as part of their methodological toolkit. This course explores key methods and frameworks in archaeological ethnography and heritage ethnography, set within the broader contexts of the historical development of anthropological theory and the current rapid growth of heritage studies as an interdisciplinary field of research and practice.', NULL, NULL, TRUE, NULL, NULL, 'ANTH435 or ANTH635.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, 'ANTH635.', NULL, NULL, NULL),
    ('ANTH436', 'Norse Archaeology', 3, 3, 'The archaeology of the Norse world from the 8th century through to the end of the 11th century. We will investigate the possible causes of the Norse expansion out of Scandinavia. The various settlements and colonies of Norse Russia, the Baltic, Britain, Ireland and the North Atlantic Islands (Orkney, the Shetlands, the Faroes, Iceland, Greenland and Newfoundland) will be examined. While we will look at the Norse in detail we will also attempt to put their raiding, trading, and settlements into a larger Eurasian context through a study of the archaeology of this period.', NULL, NULL, TRUE, NULL, NULL, 'ANTH436 or ANTH636.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH438', 'Special Topics in Study Abroad IV', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('ANTH440', 'Theory and Practice of Historical Archaeology', 3, 3, 'Historical archaeology enhances cultural heritage by providing voice for groups who were often unable to record their own histories, such as women, laborers, working class families, and enslaved people. The course provides insight into issues related to race, gender, and ethnicity as they relate to multicultural histories.', 'ANTH240. Jointly offered with ANTH640.', NULL, FALSE, NULL, NULL, 'ANTH440 or ANTH640.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH441', 'Archaeology of Diaspora', 3, 3, '"Diaspora" is defined, theorized, deconstructed, and employed throughout the social sciences. There are context specific relations that define who leaves, when, and how they are received in the new place of settlement. Over the course of the semester the class will actively and critically examine the relevance of historical archaeology and material culture studies in the understanding of the formation, experiences, and transformation of diasporic groups over time and space.', 'ANTH240.', NULL, TRUE, NULL, NULL, 'ANTH448A, ANTH688Z, or ANTH441.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'parsed', 'none_found', NULL, 'ANTH448A.', NULL, NULL, NULL, NULL, NULL),
    ('ANTH447', 'Material Culture Studies in Archaeology', 3, 3, 'An in-depth introduction to the world of material culture studies with a focus on the methods and theories in historical archaeology. Students will look at archaeological data as historical documents, commodities and as symbols expressing ideas.', 'ANTH240.', NULL, TRUE, 'DSSP', NULL, 'ANTH447, ANTH448C, ANTH647, or ANTH689C.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'parsed', 'verified', '202601', 'ANTH448C.', NULL, NULL, NULL, NULL, NULL),
    ('ANTH448', 'Special Topics in Archaeology', 3, 3, 'Advanced topics in archaeological research, corresponding to new theoretical developments, faculty research interests, or specialties of visiting scholars. Prerequisites may vary with course topic; check with the department for requirements.', 'ANTH240.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('ANTH449', 'Advanced Special Topics in Archaeology', 3, 3, 'Upper level archaeology courses on varying topics derived from new interests of the faculty or the specialties of visiting scholars.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('ANTH451', 'Environmental Archaeology', 3, 3, 'An overview of modern environmental archaeology as a tool for the interdisciplinary investigation of past and present global change and to engage the long term past with current issues of sustainability and rapid environmental change.', NULL, NULL, TRUE, 'DSSP', NULL, 'ANTH451, ANTH651, ANTH448F, ANTH668F.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'verified', '202508', 'ANTH448F.', NULL, NULL, NULL, NULL, NULL),
    ('ANTH452', 'Anthropology and Climate Change', 3, 3, 'Human activities now influence ongoing global climatic change, and the outcome remains uncertain for communities and cultures around the world. This interaction between humans and climate provides a rich area of study for anthropologists in an interdisciplinary context. Case studies of historic and contemporary evidence will be used to understand impacts of global climate change and assess opportunities and barriers to successful responses and adaptation.', 'ANTH220, ANTH222, ANTH240, or ANTH260.', NULL, FALSE, NULL, NULL, 'ANTH452 or ANTH652.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH453', 'Archaeology of the Modern City', 3, 3, 'An overview of how social scientists, in particular historical archaeologists, approach modern cities as being part of the materiality of the social structure and order.', 'ANTH240; or permission of instructor.', NULL, FALSE, NULL, NULL, 'ANTH448Q or ANTH453.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'partial', 'none_found', NULL, 'ANTH448Q.', NULL, NULL, NULL, NULL, NULL),
    ('ANTH454', 'Political Ecology', 3, 3, 'The use of the environment is contested and negotiated within historic and contemporary societies. Incorporating methods and perspectives from across the social sciences through specific case studies in the Americas, Europe, Asia and Africa, this course offers a survey to coupled human-environmental systems.', NULL, NULL, TRUE, NULL, NULL, 'ANTH454 or ANTH654.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, 'ANTH654.', NULL, NULL, NULL),
    ('ANTH461', 'Language as Practice', 3, 3, 'An introduction to linguistic variation and the construction of identity, relationship, and community membership through language use. The approach emphasizes language as community-based practice and examines the dynamic construction of social relations through linguistic interactions.', NULL, NULL, TRUE, NULL, NULL, 'ANTH461, ANTH468I or ANTH661.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, 'ANTH468I.', NULL, 'ANTH661.', NULL, NULL, NULL),
    ('ANTH463', 'Climate Cultures', 3, 3, 'Climate change is an inherently global problem. To a significant degree, its causes and consequences are cultural in nature: Climate change impacts, mitigation and adaptation efforts are perceived and addressed in culture-specific ways. This course will be an overview of the holistic and anthropological approaches to the study of how culture frames what we know and how we respond to climate change. Readings, lectures, and discussions will focus on how culture is expressed through the interplay of processes and practices in specific economic, social and political contexts.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH464', 'Anthropology of Cultural Heritage', 3, 3, 'A global exploration of how the past is remade in the present. Covers the breadth of scope and specific interventions of heritage practice at the global scale, including the social, political, economic, and ethical dimensions of cultural heritage.', 'ANTH260. Jointly offered with ANTH664. Credit only grant ed for: ANTH469T, ANTH689T, ANTH464, ANTH664.', NULL, FALSE, 'DSSP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'unstructured', 'verified', '202608', 'ANTH469T.', NULL, NULL, NULL, NULL, NULL),
    ('ANTH465', 'Applied Ethnoecology', 3, 3, 'Introduces theory and methodology for applied ethnoecology, the study of human relationships with and knowledge about the environment. Students will examine human relationships with both biotic (e.g. plants and animals) and abiotic (e.g. glaciers, weather) elements of ecological systems to better understand how knowledge frameworks and cultural practices shape human experiences of the natural world. The history of ethnoecology as a discipline will be covered, before moving to applied case studies where different ecological knowledge systems intersect as a result of conservation projects, bioprospecting, and other contemporary environmental issues. This course involves both discussion and project-based learning including StoryMaps, cultural domain analysis and text analysis.', NULL, NULL, TRUE, NULL, NULL, 'ANTH465 or ANTH688E.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH466', 'Anthropology of Work', 3, 3, 'Examines the concept and meaning of work, the different types of work, and how the development of time discipline became essential for the creation of capitalist labor. Explores the contemporary social justice movement and its impact on gender and racialized inequities. Includes an exploration of deindustrialized regions in the Rust Belt.', NULL, NULL, TRUE, 'DSSP', NULL, 'ANTH466 or ANTH666.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'verified', '202601', NULL, NULL, 'ANTH666.', NULL, NULL, NULL),
    ('ANTH467', 'Researching Environment and Culture', 3, 3, 'In this applied course, students use mixed methods to research a locally-based, environmental sustainability issue. Classroom time will be split between seminar discussions of theory, methods, and relevant case studies, and lab work focused on project development, data analysis, and report write up. Students are expected to spend additional time outside class on data collection, analysis, and writing', NULL, NULL, TRUE, 'DSSP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'verified', '202601', NULL, NULL, NULL, NULL, 'ANTH322, ANTH360, ENSP101, or ENSP102.', NULL),
    ('ANTH468', 'Special Topics in Cultural Anthropology', 3, 3, 'Advanced courses in varying specialty areas of cultural anthropology that respond to new theoretical developments, faculty research interests, or specialties of visiting scholars.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('ANTH469', 'Advanced Special Topics in Cultural Anthropology', 3, 3, 'Upper level cultural anthropology courses on varying topics derived from new interests of the faculty or the specialties of visiting scholars.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('ANTH473', 'Native American Languages and Cultures', 3, 3, 'An introduction to Native American Languages and Cultures from a linguistic anthropological perspective. Topics to be explored include Native American identities, the stucture of Native languages, oral traditions, narrative story-telling, Native language and thought (Sapir/Whorf), language shift, linguistic revitalization, documentation of endangered languages, indigenous representation and appropriation, and racializing discourses.', NULL, NULL, TRUE, NULL, NULL, 'ANTH473 or ANTH673.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, 'ANTH673.', NULL, NULL, NULL),
    ('ANTH474', 'Language Racism & Identity', 3, 3, 'An exploration of the relationship between language, identity and racism in a variety of social contexts, in the U.S. and elsewhere.', NULL, NULL, TRUE, NULL, NULL, 'ANTH474, ANTH469R, ANTH674, or ANTH689R.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, 'ANTH674.', NULL, NULL, NULL),
    ('ANTH478', 'Special Topics in Linguistics', 3, 3, 'Advanced courses in specialty areas that respond to new theoretical developments and faculty research interests in linguistics.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', 'LING200.', NULL),
    ('ANTH481', 'Environmental Ethnographies of Asia', 3, 3, 'Examines social and ecological environments in Asia through the lens of classic and contemporary ethnographies from across the continent. Considers how cultural, political and economic dynamics interact with ecological systems in both recurring and unexpected ways. Ethnographies include case studies of global commodity chains, technoscientific management, borders and migration, conservation, and local knowledge as they intersect with changing environments.', NULL, NULL, TRUE, NULL, NULL, 'ANTH481 or ANTH681.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH485', 'Honors Research Preparation', 3, 3, 'Honors Research Preparation is an independent study course during which the Honors candidate will work with their Honors Thesis Advisor to establish not only the structure of the thesis and timeline, but also the formation of Thesis Review Committee.', NULL, NULL, TRUE, NULL, 'Permission of BSOS-Anthropology department; and must be in Anthropology program; and must be admitted to University Honors Program or Anthropology Honors Program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH486', 'Honors Research', 3, 4, 'Capstone course in which students pursue independent research into a current problem in anthropology, selected with assistance of a committee of faculty. Research leads to the writing of an honors thesis in anthropology.', NULL, NULL, TRUE, NULL, 'Permission of BSOS-Anthropology department; and must be in Anthropology program; and must be admitted to University Honors Program or Anthropology Honors Program.', 'ANTH486 or ANTH476.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH487', 'Honors Thesis', 3, 4, 'Capstone course in which students write a thesis on the results of independent research into a current problem in anthropology.', 'ANTH486.', NULL, TRUE, NULL, 'Permission of BSOS-Anthropology department; and must be in Anthropology program; and must be admitted to University Honors Program or Anthropology Honors Program.', 'ANTH487 or ANTH477.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH496', 'Field Methods in Archaeology', 6, 6, 'Field training in the techniques of archaeological survey and excavation.', NULL, NULL, TRUE, 'DSSP, DVUP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'verified', '202605', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ANTH498', 'Advanced Field Training in Ethnography', 1, 8, 'Experience in field research utilizing a variety of ethnographic methods of inquiry.', NULL, NULL, TRUE, NULL, NULL, 'ANTH498 or ANTH698.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/anth/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('AOSC123', 'Causes and Consequences of Global Change', 3, 3, 'Study of the major components of Earth''s climate system and climate change history. Discussion of 21st century climate change prediction, mitigation and adaptation efforts.', NULL, NULL, TRUE, 'DSNS, SCIS', NULL, 'AOSC123, GEOG123, or GEOL123.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'none', 'verified', '202608', NULL, 'GEOL123.', NULL, NULL, NULL, NULL),
    ('AOSC125', 'Wicked Problems and Solutions in Climate Change', 3, 3, 'If you were born after 1970, climate change is a part of the world you know. Why has it been so difficult for individuals, communities, nations and the global community to mitigate, adapt and reduce societal vulnerability to its present and future dangers? Climate change is a wicked problem: difficult to unravel because it has so many tangled dimensions. Using Kim Stanley Robinson''s climate fiction novel "Ministry for the Future" to introduce the complexity of climate problems and solutions, we will develop the scientific, economic, psychological and social aspects of not only the wicked problem but wicked solutions - pathways to sustainability in the 21st century - your century. Along the way we will role play the conditions, choices, actions and events by which these same problems, illustrated on the UMD campus, could untangle the wickedness of the problem and illuminate the wickedness of plausible solutions.', NULL, NULL, TRUE, NULL, NULL, 'GEOL125 or AOSC125.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'none', 'none_found', NULL, NULL, 'GEOL125.', NULL, NULL, NULL, NULL),
    ('AOSC200', 'Weather and Climate', 3, 3, 'What are weather and climate? Most people think they know but if you ask people to explain the differences and similarities you''re bound to get a range of answers. Weather affects not just our daily activities but other important aspects of society such as transportation, commerce, security and agriculture. Most people understand what weather is to some extent. Climate and climate change are concepts that evoke strong emotional responses from people but are less well understood. In this class, students examine fundamental issues such as the greenhouse effect, severe weather, and global weather patterns and how they relate to a changing climate. Instruction in the lectures will provide the basic knowledge needed to understand these issues. In the discussion sections, students will be divided into groups to address the implications of these topics through group projects.', 'MATH107, MATH110, or MATH115.', NULL, FALSE, 'DSNL (if taken with AOSC201) or DSNS, SCIS', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'unstructured', 'verified', '202608', NULL, NULL, NULL, NULL, 'Concurrent enrollment in AOSC201.', NULL),
    ('AOSC201', 'Weather and Climate Laboratory', 1, 1, 'Laboratory exercises to supplement AOSC200, including weather observations, weather map analysis, forecasting practice and climate modeling.', NULL, 'AOSC200.', TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AOSC247', 'Scientific Programming: Python', 3, 3, 'A comprehensive introduction to scientific computation and visualization techniques with Python applied to data intensive questions in the Natural Sciences. The class emphasizes real-world applications, providing students with essential hands-on experience using Python for data analysis and visualization, developing analytical skills for observational and modeling data, and performing virtual experiments to distinguish data contributing factors. Students will gain an understanding of the scientific data issues including: signal vs noise, trend vs periodicity, mean vs extreme changes, and accuracy vs uncertainty. Students will gain extensive experience using command line linux. Skills including local and remote file transfer and synchronization, file and directory permission, utilities for diagnosing performance issues, and data compression.', 'MATH140.', NULL, TRUE, NULL, NULL, 'AOSC458J or AOSC247.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'parsed', 'none_found', NULL, 'AOSC458J.', NULL, NULL, NULL, 'Familiarity with basic descriptive statistics.', NULL),
    ('AOSC358', 'Special Topics in Atmospheric and Oceanic Science', 1, 4, 'Special topics in atmospheric and oceanic science are given intensive study. The topic of concentration varies, from semester to semester and depends on student and faculty interests. Often, specialists from other institutions are invited to the campus on a visiting lectureship basis to conduct the course.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'none', 'none_found', NULL, NULL, NULL, NULL, '12 credits.', NULL, NULL),
    ('AOSC375', 'Introduction to the Blue Ocean', 3, 3, 'The global ocean is a major component of the Earth System that shapes life on earth, including our weather and climate. We explore the observation-based interdisciplinary science of oceanography, identifying its strong connections to related sciences like meteorology, and geography. We apply this developing understanding to environmental issues such as marine pollution, fish and fisheries, as well as to climate variability and to the changes to the marine environment that are resulting from steadily rising levels of atmospheric greenhouse gasses. Focusses include the biogeochemical and physical changes we can observe in the nearby Chesapeake Bay and the coastal waters of Eastern Shore, Maryland.', 'MATH120 or higher.', NULL, FALSE, 'DSNS', NULL, 'AOSC375 or GEOL375.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'unstructured', 'verified', '202608', NULL, 'GEOL375.', NULL, NULL, 'MATH121, MATH141, PHYS161, or PHYS171.', NULL),
    ('AOSC386', 'Experiential Learning', 3, 6, 'Experiential learning in atmospheric and oceanic science.', NULL, NULL, TRUE, NULL, 'Junior standing or higher; and must have a learning proposal approved by the Office of Experiential Learning Programs, faculty sponsor and student''s internship sponsor.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AOSC399', 'Independent Study in Academic Peer Mentoring', 1, 3, 'Earn academic credit for the time spent supporting an AOSC course in the Academic Peer Mentoring Program (AMP).', NULL, 'TLTC333.', TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, '6 credits.', NULL, NULL),
    ('AOSC400', 'Physical Meteorology', 3, 3, 'The application of basic classical physics, chemistry and mathematics to the study of the atmosphere. Composition of the atmosphere; energy sources and sinks (radiation in the atmosphere; radiative balance and radiative forcing of atmospheric processes); atmospheric thermodynamics; clouds and precipitation physics; atmospheric electricity and optics; mesoscale processes (e.g., orographic mesoscale phenomena and instabilities); air mass boundaries; severe weather, tropical cyclones; storms; global circulation.', '1 course with a minimum grade of C- from (PHYS171, PHYS161, MATH141); or permission of CMNS-Atmospheric & Oceanic Science department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AOSC401', 'Climate Dynamics and Earth System Science', 3, 3, 'Introduction of the earth and global climate systems and their major components: atmosphere, land, ocean, biosphere and cryosphere. Key processes governing the function of the earth''s climate: Global energy balance and water cycle, climate dynamics (general circulation of the atmosphere and ocean) and climate physics (aerosol, cloud and rain), as well as climate variability and climate changes. Phenomena resulting from this coupled system including El Nino-Southern Oscillation, monsoons, and the hydrological cycle will be discussed, with a focus on how the Earth System responds to global warming.', 'AOSC400 or AOSC200; and MATH141; and (PHYS161 or PHYS171). Or permission of instructor.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AOSC420', 'Physical Oceanography', 3, 3, 'Ocean observations. Water masses, sources of deep, intermediate, and surface water. Mass, heat, and salt transport, and the meridional overturning circulation. Geochemical tracers and cycles, including carbon. Western boundary currents, mixed layers, and processes maintaining the thermocline. Coastal and estuarine processes. Surface waves and tides. the ocean''s role in climate.', 'MATH141 and PHYS141.', NULL, TRUE, NULL, NULL, 'AOSC420, AOSC670, or GEOL670.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, 'AOSC200. Also offered as: GEOL670, AOSC670.', NULL),
    ('AOSC424', 'Remote Sensing of the Atmosphere and Ocean', 3, 3, 'Many of the properties of the atmosphere, ocean, and land surface are most easily observed from satellite remote sensing. This course will provide students with a hands-on introduction to a variety of passive and active sensing techniques and sensors observing our changing environment. Topics include: orbital dynamics and electromagnetic properties of the atmosphere and surface; atmospheric emission characteristics and scattering; chemical composition and spectroscopy; temperature retrievals; detection and retrieval of aerosol, cloud and rain; ocean surface properties; sea surface temperature and color; active sensing of wind stress, sea level, and internal waves; time-dependent gravity; properties of vegetation and ice.', '1 course with a minimum grade of C- from (PHYS171, PHYS161, MATH141); or permission of instructor.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AOSC431', 'Atmospheric Thermodynamics', 3, 3, 'Classical thermodynamics applied to both the dry and the moist atmosphere. Composition; phase changes of water; stability concepts; Properties of aerosols and clouds, cloud nucleation and precipitation processes, atmospheric electricity, cloud and precipitation chemistry.', '1 course with a minimum grade of C- from (PHYS171, PHYS161, MATH141).', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, 'MATH246.', NULL),
    ('AOSC432', 'Dynamics of the Atmosphere and Ocean', 3, 3, 'Equations of motion and their approximation, scale analysis for the atmosphere and the ocean. Conservation properties. Fluid motion in the atmosphere and oceans. Geostrophic/balanced and ageostrphic/unbalanced motion. Circulation, vorticity, and potential vorticity. Introduction to the boundary layer.', 'AOSC431.', 'MATH246.', TRUE, NULL, NULL, 'AOSC432 or AOSC632.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'parsed', 'none_found', NULL, 'METO432.', NULL, NULL, NULL, NULL, NULL),
    ('AOSC433', 'Atmospheric Chemistry and Climate', 3, 3, 'The effects of human activity on atmospheric composition, focused on global warming, the carbon cycle, air pollution, and the ozone layer. Fundamentals of atmosphereic chemistry (spectroscopy, kinetics, isotopic analysis, and biogeochemical cycles) are related to the modern understanding of climate change, air quality, and ozone depletion, based on resources such as satellite missions, field campaigns, and scientific assessments published by international agencies. We also examine how society''s energy needs could be met, in the future, in a manner with less impact on atmospheric composition than the present heavy reliance on combusion of fossil fuels.', 'CHEM131, CHEM135, or CHEM146. And MATH241; or permission of CMNS-Atmospheric & Oceanic Science department; or permission of CMNS-Chemistry & Biochemistry department. Cross-listed with CHEM433.', NULL, FALSE, NULL, NULL, 'AOSC433, AOSC633, CHEM433, or CHEM633.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'unstructured', 'none_found', NULL, 'AOSC434.', NULL, NULL, NULL, NULL, NULL),
    ('AOSC434', 'Air Pollution and Environmental Justice', 3, 3, 'Basic concepts in physics and chemistry of the atmosphere as applied to air pollution and environmental justice. Production, transformation, spatial scales, transport, and removal of air pollutants. The problems of photochemical smog, the greenhouse effect & climate change, stratospheric ozone, visibility. Numerical simulation of air pollution. Health and environmental effects of air pollution in the developed and developing world; why some communities suffer disproportionately', 'CHEM131 and MATH241; or permission of instructor.', NULL, FALSE, NULL, NULL, 'AOSC434 or CHEM434.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'partial', 'none_found', NULL, NULL, 'CHEM434.', NULL, NULL, NULL, NULL),
    ('AOSC436', 'Principles of Biogeochemistry', 3, 3, 'An introduction to the basic principles of biogeochemistry including aspects of organic geochemistry, biochemistry, microbiology, global geochemical cycles, the origin of life and paleoenvironmental evolution.', 'MATH120 or MATH140; or must have completed MATH220. And (GEOL100 or GEOL120); and GEOL322. And CHEM131 and CHEM132; or (CHEM135 and CHEM136).', NULL, FALSE, NULL, 'Non-degree-seeking students require the permission of the instructor.', 'GEOL436 or AOSC436.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'unstructured', 'none_found', NULL, NULL, 'GEOL436.', NULL, NULL, NULL, NULL),
    ('AOSC437', 'Global Climate Change: Past and Present', 3, 3, 'Introduction to the processes by which climate varies, the paleoclimate record, and projections of climate change into the 21st century, including discussion of climate sensitivity to external radiative forcing.', 'MATH115 or MATH140; and (GEOL100 or GEOL120); and (CHEM131 or CHEM135); and (CHEM132 or CHEM136).', NULL, TRUE, NULL, NULL, 'GEOL437, GEOL637, AOSC437 or AOSC685.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'parsed', 'none_found', NULL, NULL, 'GEOL437.', 'GEOL637, AOSC685.', NULL, NULL, NULL),
    ('AOSC440', 'Polar Remote Sensing', 3, 3, 'The harsh environment of the vast polar regions makes them some of the most inaccessible places on Earth. With widespread environmental change already underway, satellite remote sensing provides the only means by which to obtain year-round observations of the polar climate system. The objective of this course is to provide students with an overview of polar remote sensing techniques, including the physical principles of active and passive sensors, orbits, electromagnetic radiation, atmospheric transmission, calibration and validation. We will focus on measurements of the polar oceans, sea ice, glaciers, ice sheets, snow and permafrost, and examine the response of the cryosphere to climate change.', 'PHYS171 or PHYS161; and AOSC401 or GEOG301; or with permission of instructor.', NULL, FALSE, NULL, NULL, 'AOSC440, GEOG440, AOSC642, or GEOG640.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'partial', 'none_found', NULL, NULL, 'GEOG440.', 'AOSC642.', NULL, NULL, NULL),
    ('AOSC447', 'Machine Learning in Earth Science', 3, 3, 'A comprehensive introductory course designed to prepare undergraduate and graduate students for applying machine learning techniques to solve real-world problems in Earth science. It emphasizes practical solution implementation, providing students with essential hands-on experience using the most popular open-source analytics tools based on Python, a general-purpose programming language. The course works through all steps in machine learning, from problem specification, data analytics to analytical solution, and applies advanced statistical and analytical algorithms to uncover hidden data relationships and transform them into predictive understanding or decision support. The topics covered include: Python programming, SciPy and Scikit-learn utility, data engineering, visualization, classifiers, regression models, canonical correlation analysis, structural equation models, decision trees, random forests, boosting machines, support vector machines, clustering, dimensionality reduction, principal component analysis, and neural networks.', 'Must have completed MATH140.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AOSC458', 'Advanced Topics in Atmospheric and Oceanic Science', 1, 4, 'Special topics in atmospheric and oceanic science are given intensive study. The topic of concentration varies, from semester to semester and depends on student and faculty interests. Often, specialists from other institutions are invited to the campus on a visiting lectureship basis to conduct the course.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'none', 'none_found', NULL, NULL, NULL, NULL, '12 credits.', NULL, NULL),
    ('AOSC462', 'Ecohydrology', 3, 3, 'Focuses on the study of hydrologically-controlled ecosystems, e.g. systems in which either excess and/or deficit of water and nutrients are determinants of its structure and function. Such systems have complex dynamic characteristics that depend on many interrelated links between climate, soil and vegetation.', 'MATH240, MATH241 and MATH246; or permission of instructor.', NULL, FALSE, NULL, NULL, 'AOSC462 or AOSC662.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'partial', 'none_found', NULL, NULL, NULL, 'AOSC662.', NULL, NULL, NULL),
    ('AOSC463', 'Water and Climate Systems', 3, 3, 'Focuses on exploring the relationships between water, climate, land, energy, and the economy (the so called "nexus") through an interwoven understanding of the physical, economic, and institutional relationships and constraints that influence management and decision-making process in water supply, energy generation and food production. The course emphasizes the use of integrated assessment (IA) modeling tools as a way to formalize these relationships and explore their implications. Lectures will be complemented with online discussion sessions and applied modeling exercises to get hands-on knowledge of practical solutions to nexus challenges.', 'MATH240, MATH241 and MATH246; or permission of instructor.', NULL, FALSE, NULL, NULL, 'AOSC463 or AOSC663.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'partial', 'none_found', NULL, NULL, NULL, 'AOSC663.', NULL, NULL, 'This course is offered through a joint effort of the Earth System Science Interdisciplinary Center (ESSIC, part of UMDb Sciences) and the Joint Global Change Research Institute (a collaboration between UMD and the US Dept of Energyb Northwest National Laboratory).'),
    ('AOSC470', 'Synoptic Meteorology', 3, 3, 'Atmospheric properties and observations, meteorological analysis and charts, operational numerical forecasts. Application of quasigeostrophic theory, baroclinic instability, midlatitiude and mesoscale weather systems. Tropical meteorology. Weather forecasting using numerical and statistical models. Prediction of weather phenomena on the global, syoptic, meso, and local scales. Analysis of surface and upper air data; Norwegian cyclone model; introduction to weather forecasting.', 'Minimum grade of C- in AOSC431 and AOSC432.', NULL, TRUE, NULL, NULL, 'AOSC470, AOSC600, or METO600.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AOSC472', 'Mesoscale Meteorology', 3, 3, 'Survey a broad range of mesoscale meteorological features with emphasis on convection and associated phenomena. Define the mesoscale and understand its underlying principles; Introduce non-convective circulations and their importance for weather forecasting; Understand the precursors and occurrence of deep moist convection.', 'AOSC432, AOSC600, AOSC610, or AOSC470.', NULL, FALSE, NULL, 'Non-degree-seeking students require the permission of the instructor.', 'AOSC472 or AOSC602.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'unstructured', 'none_found', NULL, NULL, NULL, 'AOSC602.', NULL, NULL, NULL),
    ('AOSC475', 'Carbon Cycle and Climate: Past, Present, and Future', 3, 3, 'The fundamentals of the Earth''s carbon cycle, a key biogeochemical cycl that controls Earth''s climate and life. The changing characteristics of the carbon cycle on several timescales, ranging from geological, interannual, and the more recent anthropogenic influences on carbon cycle and climate. The carbon cycle in the atmosphere, land, ocean, and the biosphere. The underlying human activities such as fossil fuel burning and deforestation that are responsible for the increase in the atmosphere CO2 and our future options in dealing with the carbon problem such as alternative energy and carbon sequestration.', NULL, NULL, TRUE, NULL, NULL, 'AOSC475 or AOSC6 75.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'none', 'none_found', NULL, NULL, NULL, 'AOSC675.', NULL, NULL, NULL),
    ('AOSC480', 'Introduction to Earth System Science', 3, 3, 'Focuses on exploring the relationships between the atmosphere, the oceans, water, climate, land, vegetation, energy, and human systems through an interwoven understanding of the physical, biogeochemical and socioeconomic relationships and constraints that influence management and decision-making processes in societal issues such as water supply, power generation, food production, ecosystem services and others. The course introduces integrated assessment (IA) science as a framework to formalize these relationships and explore their implications.', 'MATH240, MATH241 and MATH246; or permission of instructor.', NULL, FALSE, NULL, NULL, 'AOSC480 or AOSC680.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'partial', 'none_found', NULL, NULL, NULL, 'AOSC680.', NULL, NULL, 'This course is offered through a joint effort of the Department of Atmospheric and Oceanic Science (AOSC) and the Earth System Science Interdisciplinary Center (ESSIC).'),
    ('AOSC484', 'Climate System Modeling', 3, 3, 'Fundamentals in building computer models to simulate the components of the climate system: atmosphere, ocean ice, land-surface, terrestrial and marine ecosystems, and the biogeochemical cycles embedded in the physical climate system, in particular, the carbon cycle. Simple to state-of-the-art research models to tackle problems such as the Daisy World, El Nino and global warming.', NULL, NULL, TRUE, NULL, NULL, 'AOSC484 or AOSC6 84.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'none', 'none_found', NULL, NULL, NULL, 'AOSC684.', NULL, NULL, NULL),
    ('AOSC493', 'Senior Research Project I', 3, 3, 'Technical writing and oral presentation skills. Planning, writing, and presenting a plan for research in the geosciences.', 'Permission of CMNS-Atmospheric & Oceanic Science department.', NULL, FALSE, NULL, 'Must be in Atmospheric and Oceanic Science program; or permission of instructor.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AOSC494', 'Atmospheric and Oceanic Science Seminar', 1, 1, 'Exposure to a wide range of contemporary topics in atmospheric, oceanic, and climate sciences, to foster research interests and promote critical thinking through the weekly AOSC departmental seminar series.', 'Minimum grade of C- in AOSC431 and AOSC432.', NULL, TRUE, NULL, 'Permission of the Atmospheric and Oceanic Science Department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AOSC498', 'Senior Research Project II', 3, 3, 'The project will be based on the research or development plan created in AOSC493. It may be completed with the approval of a faculty advisor in conjunction with an internship. Final written thesis and oral defense will be expected.', 'AOSC493.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('AOSC499', 'Special Problems in Atmospheric Science', 1, 3, 'Research or special study in the field of meteorology and the atmospheric and oceanic sciences.', 'Permission of CMNS-Atmospheric & Oceanic Science department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/aosc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, '6 credits.', NULL, NULL),
    ('ARAB101', 'Elementary Arabic I', 3, 3, 'Introduction to modern standard Arabic in both its spoken and written form. Equal emphasis on all four skill areas: speaking, listening, reading, and writing.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB102', 'Elementary Arabic II', 3, 3, 'Continuation of ARAB101. Introduction to both spoken and written Arabic. Equal emphasis on all four skill areas: speaking, listening, reading, and writing.', 'ARAB101; or must have appropriate World Language Placement (WLP) score.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB104', 'Elementary Modern Standard Arabic I-II', 6, 6, 'An intensive course focusing on developing functional proficiency in the standard Arabic language, both written and formal spoken. Begins with script and phonology, and develops into a limited range of situation-based texts and topics that build vocabulary, grammar, general communicative competence and cultural awareness.', 'Must have appropriate World Language Placement (WLP) score.', NULL, FALSE, NULL, 'Must not be a fluent/native speaker of Arabic.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB105', 'Elementary Modern Standard Arabic III-IV', 6, 6, 'Continuation of ARAB104, developing further linguistic proficiency in Standard Arabic, both written and formal spoken. Covers an extended range of situation-based texts and topics that build vocabulary, grammar, general communicative competence and cultural awareness.', 'ARAB104; or must have appropriate World Language Placement (WLP) score.', NULL, FALSE, NULL, 'Must not be a fluent/native speaker of Arabic.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB169', 'Special Topics in Study Abroad I', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('ARAB190', 'Introduction to Arab Cultures & Societies', 3, 3, 'Provides an introduction to key topics related to the study of the Arabic-speaking world, including features of Arab identity in the Middle East North Africa as well as in the diaspora. Addresses religious, racial, and ethnic diversity, the history of language and culture, political economy, and migration. Students will learn about the diverse cultures and societies that have formed the changing conceptions of the Arab world through history and across different geographies. A fundamental premise is that the "Arab world" is not a monolithic, unchanging, bounded region "over there," but has long been deeply intertwined with other societies, including our own. Taught in English.', NULL, NULL, TRUE, 'DSHU', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'none', 'verified', '202605', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB201', 'Intermediate Arabic I', 3, 3, 'The study of Arabic in both its spoken and written forms at the intermediate level. Course will continue to develop all four skills of language acquisition: listening, speaking, reading, and writing.', 'ARAB102; or must have appropriate World Language Placement (WLP) score.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB202', 'Intermediate Arabic II', 3, 3, 'Continuation of ARAB201, the study of Arabic in both its spoken and written forms at the intermediate level. Course will continue to develop all four skills of language acquisition: listening, speaking, reading, and writing.', 'ARAB201; or must have appropriate World Language Placement (WLP) score.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB204', 'Intermediate Modern Standard Arabic I', 6, 6, 'Covers topics related to contemporary Arabic society, literature and culture in standard written and formal spoken Arabic. Acquisition of more complex grammatical structures, expanding vocabulary, and reading, to develop a better understanding of the formal aspects of using MSA.', 'ARAB105; and must have appropriate World Language Placement (WLP) score.', NULL, FALSE, NULL, 'Must not be a fluent/native speaker of Arabic.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB205', 'Intermediate Modern Standard Arabic II', 6, 6, 'Continuation of ARAB204, with exposure to a wide range of Arabic texts from different domains. Focus on vocabulary, more complex grammatical forms, and a better understanding of the formal aspects of using MSA as well as the cultural aspects of using the language.', 'ARAB204; or must have appropriate World Language Placement (WLP) score.', NULL, FALSE, NULL, 'Must not be a fluent/native speaker of Arabic.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB206', 'Egyptian Colloquial Arabic I', 3, 3, 'Develops communicative skills and cultural knowledge in Egyptian Arabic. Focuses on various social interactions, work and school situations, as well as specifics of pronunciation and grammar of the Egyptian dialect. Designed for students who have completed two years of the regular Arabic sequence classes (104-105 and 204-205) or equivalent.', 'ARAB205; or permission of ARHU-School of Languages, Literatures, and Cultures department.', NULL, FALSE, NULL, 'Must not be a fluent/native speaker of Arabic.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB207', 'Egyptian Colloquial Arabic II', 3, 3, 'Further develops communicative skills and cultural knowledge in Egyptian Arabic, extending range of contexts and types of social interaction. Focuses on various aspects of Egyptian popular culture.', 'ARAB206; or students who have taken courses with comparable content may contact the department.', NULL, FALSE, NULL, 'Must not be a fluent/native speaker of Arabic.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB222', 'Arabic for Daily Life I', 3, 3, 'Develops students'' speaking and listening abilities in both formal Arabic and a dialect. Focus on activating vocabulary and grammar structures, speaking at the sentence level, and selecting an appropriate register based on context.', 'ARAB102; or equivalent; or must have appropriate World Language Placement (WLP) score.', NULL, FALSE, NULL, 'Must not have completed ARAB202.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB225', 'Roots and Patterns: Verb Meaning in Arabic', 3, 3, 'Examines the templatic morphology of the Arabic verb system, and asks what the workings of such a system tell us about the way that humans construct and encode meaning. Moves beyond the traditional labels that are used to name the different categories of Arabic verb, to explore the conceptual structures that are coded linguistically by the various verb patterns.', NULL, NULL, TRUE, NULL, NULL, 'ARAB499K or ARAB225.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'none', 'none_found', NULL, 'ARAB499K.', NULL, NULL, NULL, 'Assumes basic reading ability in Arabic, perhaps gained through exposure to the Quran or through taking ARAB101 or its equivalent.', NULL),
    ('ARAB250', 'Food Cultures in the Global Middle East', 3, 3, 'Food is the stuff of everyday routine and rich symbolic meaning, from holiday meals to daily staples. Studying food offers new perspectives on modernization, colonialism, and nationalism, and illuminates popular experiences of major historical events. This course introduces students to the history and cultures of the modern Middle East and North Africa using secondary literature and primary source materials addressing the sources and methods used in humanistic food studies scholarship. Students will gain a nuanced understanding of the diversity and complexities of the region as well as a lens for analyzing its cultures and societies from an everyday human perspective.', NULL, NULL, TRUE, NULL, NULL, 'ARAB250 or ARAB499C.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'none', 'none_found', NULL, 'ARAB499C.', NULL, NULL, NULL, NULL, NULL),
    ('ARAB269', 'Special Topics in Study Abroad II', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('ARAB298', 'Special Topics in Arabic Studies', 1, 3, 'Language and content to be announced when course is offered.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'none', 'none_found', NULL, NULL, NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('ARAB301', 'Arab Culture and Society: Skills and Topics I', 3, 3, 'Discussion of factors that drive migration from and across Arab societies, including structures of economic and social marginalization and experiences within Arab diaspora communities. Continued study of Arabic in both its spoken and written forms and study of daily life in Arabic-speaking societies. Listening, speaking, reading and writing are emphasized through engagement with increasingly advanced authentic materials.', 'ARAB202; or must have appropriate World Language Placement (WLP) score.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB302', 'Arab Culture & Society: Skills and Topics II', 3, 3, 'Discussion of cultural, ethnic, and religious diversity in the Arabic-speaking world, including social norms and practices related to religious occasions. Continued study of Arabic in both its spoken and written forms through texts that cover major social issues in the Arab world. Listening, speaking, reading and writing are emphasized through engagement with increasingly advanced authentic materials.', 'ARAB301; or must have appropriate World Language Placement (WLP) score.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB304', 'Advanced Modern Standard Arabic I', 3, 3, 'Advanced grammar, reading, writing, speaking in Arabic; study of contemporary Arabic society, politics, and culture.', 'ARAB205; or permission of ARHU-School of Languages, Literatures, and Cultures department.', NULL, FALSE, NULL, 'Must not be a fluent/native speaker of Arabic.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'partial', 'none_found', NULL, 'ARAB301.', NULL, NULL, NULL, NULL, NULL),
    ('ARAB305', 'Advanced Modern Standard Arabic II', 3, 3, 'Further advanced grammar, reading, writing, speaking in Arabic; study of current issues within the Arab World.', 'ARAB304; or students who have taken courses with comparable content may contact the department.', NULL, FALSE, NULL, 'Must not be a fluent/native speaker of Arabic.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB315', 'Intensive Advanced Arabic I', 6, 6, 'Intensive training in written and spoken Arabic at the Advanced-low level of proficiency. Additional intensive training in effective listening and reading skills. Substantial cultural component exploring traditions and customs of the Middle East in addition to current social issues.', 'ARAB205; or permission of ARHU-School of Languages, Literatures, and Cultures department.', NULL, FALSE, NULL, 'Must not have completed ARAB304.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB316', 'Intensive Advanced Arabic II', 6, 6, 'Intensive training in written and spoken Arabic at the Advanced-mid level of proficiency. Additional training in effective listening and reading skills. Substantial cultural component exploring traditions and customs of the Middle East in addition to current social issues.', 'ARAB304 or ARAB315; or permission of ARHU-School of Languages, Literatures, and Cultures department.', NULL, FALSE, NULL, 'Must not have completed ARAB305.', 'ARAB305 or ARAB316.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB317', 'Key Moments in the History of the Middle East', 3, 3, 'Provides students with an overview of major political and social events in the history of the Middle East and North Africa, with a focus on Arabic-speaking regions in the modern period. Makes use of a range of source materials and secondary readings (in Arabic and English) to illuminate how major events and changes impacted everyday life for different groups across the region. Assessments are intended to develop linguistic competence in Arabic and to guide students to become self-directed language learners and to conduct and present research on a topic of their choosing in modern Arab history.', 'ARAB202 or must have appropriate World Language Placement (WLP) score.', NULL, FALSE, NULL, NULL, 'ARAB499I or ARAB317.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'unstructured', 'none_found', NULL, 'ARAB499I.', NULL, NULL, NULL, NULL, NULL),
    ('ARAB321', 'Arabic Media', 3, 3, 'Examines the role of the Arabic media in shaping public opinion and influencing relations between the Arab world and the non-Arab world. Focus on content and acquistion of Modern Standard Arabic. Taught in Arabic.', 'ARAB305; or permission of instructor.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB322', 'Arabic for Daily Life II', 3, 3, 'Develops students'' speaking and listening abilities in both formal Arabic and a dialect, aiming to bring them to the advanced low level in speaking. Focus on activating vocabulary and grammar structures, speaking at the paragraph level, self-correction, and using both formal and informal registers of Arabic.', 'ARAB202; or equivalent, or must have appropriate World Language Placement (WLP) score.', NULL, FALSE, 'DVCC', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'partial', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB325', 'Structure and Function of the Arabic Language', 3, 3, 'Facilitates logic-based understanding of Arabic grammar and syntax. Explores different grammatical structures and related elements, including through writing and translation.', 'ARAB102; or must have appropriate World Language Placement (WLP) score.', NULL, FALSE, NULL, NULL, 'ARAB398I or ARAB325.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'partial', 'none_found', NULL, 'ARAB398I.', NULL, NULL, NULL, NULL, NULL),
    ('ARAB341', 'Filming War Zones: Representations of Wars in Iraq & Chechnya', 3, 3, 'Comparative study of ideological and cultural discourses in war films covering military conflicts in Iraq and Chechnya in late 20th-early 21st centuries. Materials include American, Middle Eastern, and Russian feature films and documentaries; theories of propaganda, ideology and popular culture. Taught in English.', NULL, NULL, TRUE, NULL, NULL, 'ARAB341 or CINE341.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'none', 'none_found', NULL, NULL, 'CINE341.', NULL, NULL, NULL, NULL),
    ('ARAB369', 'Special Topics in Study Abroad III', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('ARAB386', 'Experiential Learning', 3, 6, 'Pre-professional experience in research, analysis and writing in a work setting. Project proposal approved by faculty and internship sponsor. Junior standing.', NULL, NULL, TRUE, NULL, 'Permission of ARHU-School of Languages, Literatures, and Cultures department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB398', 'Special Topics in Arabic Studies', 3, 3, 'In-depth study of a particular aspect of Arabic culture, literature, and language. Specific topic to be announced when offered. Taught in Arabic.', 'ARAB304.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('ARAB399', 'Independent Study In Arabic', 1, 3, 'Research and writing or specific readings on a topic selected by the student and supervised by a faculty member on the Department of Arabic Studies. To be planned during semester preceding registration.', 'Permission of ARHU-School of Languages, Literatures, and Cultures department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB401', 'Readings in Arabic Literature', 3, 3, 'A survey of Modern Arabic literature is given through a range of selected texts. Texts are studied as literature with constant reference to the social, cultural and political contexts in which they were written. Taught in Arabic.', 'ARAB305; or permission of ARHU-School of Languages, Literatures, and Cultures department.', NULL, FALSE, NULL, 'Must not be a fluent/native speaker of Arabic.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARAB410', 'Ideology of Stereotyping: American and Middle Eastern Film and Television', 3, 3, 'Exploration of cultural stereotyping, using examples from American and Middle Eastern cinema and television. Students will examine ideological constructs of Otherness and its history, including Orientalism; propaganda techniques; and audiovisual aspects of stereotyping. While the focus is on American and Middle Eastern cultural production, the course will engage broader issues of stereotyping in contemporary society and media. Readings include theories of propaganda and cultural ideology.', NULL, NULL, TRUE, 'DVCC', NULL, 'ARAB410 or CINE429Q.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'none', 'verified', '202601', NULL, 'CINE429Q.', NULL, NULL, NULL, NULL),
    ('ARAB499', 'Special Topics in Arabic Studies', 3, 3, 'In-depth study of particular aspect of Arabic culture, literature and language. Specific topic to be announced when course is offered.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arab/', 'none', 'none_found', NULL, NULL, NULL, NULL, '18 credits if content differs.', NULL, NULL),
    ('ARCH150', 'Discovering Architecture', 3, 3, 'Introduction to architecture and design studio education. The course examines fundamental design principles and skills related to architecture. The design studio projects apply ideas and concepts introduced in lectures, readings and on site visits. The design studio projects are both analytic and synthetic in nature. The explicit goals of the course are: To explore the discipline of architecture; To promote visual thinking and representational skills; To develop analytic design thinking skills; To learn some of the conventions of architectural representation; To enhance cultural awareness of architecture and design.', 'Permission of ARCH-Architecture Program.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARCH170', 'Design Thinking and Architecture', 3, 3, 'Examines conceptual, perceptual, behavioral, and technical aspects of the built environment, and methods of analysis, problem-solving, and design implementation.', NULL, NULL, TRUE, 'DSHU', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARCH171', 'Design Thinking and Making in Architecture', 3, 3, 'Examines iterative design processes and critical thinking skills through active learning and design thinking methodologies to solve problems and apply design as a lens of inquiry and exploration. Students will understand Design Thinking through interactive and experiential learning.', NULL, NULL, TRUE, 'DSSP', 'Must be a major in ARCH-Architecture Program; and must be a freshman; or have permission of the School of Architecture, Planning and Preservation.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARCH200', 'Design Media and Representation I', 3, 3, 'Study of architectural representation in physical and digital design media. Examine visual literacy and visual communications through applied drawing, modeling and visual making to explore the role of design media and representation in design and design thinking.', 'ARCH171; or permission of ARCH-Architecture Program.', NULL, FALSE, NULL, 'Must be in a major in ARCH-Architecture Program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARCH201', 'Elements and Principles of Architecture', 1, 1, 'Survey of fundamental elements and principals of architecture and architectural education. Frames study of architecture as a profession, discipline and critical practice.', NULL, NULL, TRUE, NULL, 'Must be in a major in ARCH-Architecture Program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARCH225', 'History of World Architecture I', 3, 3, 'Pre-1500 World Architecture survey course - History of Architecture structured to develop critical thinking and visually literacy with regard to the worldwide legacy of design thinking and cultural production through architecture', NULL, NULL, TRUE, 'DSHU', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'none', 'verified', '202601', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARCH226', 'History of World Architecture II', 3, 3, 'Post-1500 - History of Architecture survey course - History of Architecture structured to develop critical thinking and visually literacy with regard to the worldwide legacy of design thinking and building innovation in architecture', NULL, NULL, TRUE, 'DSHU', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARCH230', 'AI and the Built Environment', 3, 3, 'How do AI tools reshape how we represent, interpret, and create the built environment? This GenEd course engages enduring questions about human-AI collaboration, cultural values, and the ethics of representation. Students analyze texts, images, archives, and media about architecture, landscapes, and cities, while practicing humanities methods (close reading, visual analysis, historiography) and applied practice (design critique, collaborative projects, real-time feedback). It culminates in a thesis-driven essay, public presentation, and collaborative applied project.', NULL, NULL, TRUE, 'DSSP, SCIS', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARCH270', 'Design in Practice', 3, 3, 'Case studies and hands-on design projects ranging in scale from a product to a building to give students insight into the process by which architects work both individually and collaboratively to put disciplinary knowledge and expertise into practice to shape our built environment.', NULL, NULL, TRUE, 'DSSP, SCIS', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'none', 'verified', '202508', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARCH271', 'People, Planet, and Profit: Building Sustainable Places', 3, 3, 'An introduction to the four disciplines represented in the School: architecture and urban design, community planning, historic preservation, and real estate development, that work to create a more sustainable environment for the future to create a more sustainable environment for the future using our interpretation of the quadruple bottom line: socio-cultural, economic, environmental, and design sustainability. Students will be provided with an understanding of the fundamental scholarship and processes of each of these disciplines and examine the intersections between them. Additionally, they will learn by applying the approaches of the four disciplines through a series of field studies.', NULL, NULL, TRUE, 'DSSP', NULL, 'ARCH271 or RDEV250.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'none', 'verified', '202608', NULL, 'RDEV250.', NULL, NULL, NULL, NULL),
    ('ARCH272', 'Sustainability at College Park', 3, 3, 'Explore the ways and the degrees to which University of Maryland, College Park campus master planning and operations incorporate principles of sustainability including smart growth, LEED and other building rating systems, higher education rating systems, sustainable agriculture and transportation planning. Among other subjects, students will learn about the Campus and the City of College Park and survey the relationship between local, national and global sustainability concerns. Students will learn about the University''s Climate Action Plan and the roles, and extent to which, the UMD Office of Sustainability and other campus units are helping develop a carbon-neutral and resource-efficient campus infrastructure.', NULL, NULL, TRUE, 'DSNS or DSSP, SCIS', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'none', 'verified', '202601', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARCH289', 'Independent Studies in Architectural Sustainability', 1, 4, 'Independent Studies in Architectural Sustainability. Proposed work must have a faculty sponsor and receive approval of the Architecture Program Curriculum Committee and Program Director.', NULL, NULL, TRUE, NULL, 'Must be in a major in ARCH-Architecture Program; and permission of ARCH-Architecture Program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('ARCH300', 'Design Media and Representation II', 3, 3, 'Study of architectural representation in physical and digital design media. Examine visual communications and speculative visual studies through applied drawing, modeling and making to explore expanded roles of representation in design and design thinking.', 'ARCH200; or permission of ARCH-Architecture Program.', NULL, FALSE, NULL, 'Must be in a major in ARCH-Architecture Program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARCH350', 'Intro to Creative Placemaking: Practices & Principles', 3, 3, 'This case-study based seminar introduces students to Creative Placemaking as a practice that leverages the power of the arts, culture, and design to support equitable, vibrant, and sustainable communities. Students analyze Creative Placemaking initiatives that elevate our shared humanity and address critical challenges, such as conversations about racial injustice, inequitable development, climate change or celebrations of the diverse communities and cultures around us. Such projects enable us to consider and imagine ethical development practices, especially in underserved and historically marginalized neighborhoods. Based on participation in creative placemaking and presentations from practitioners, they will capture the ways that artists and designers in partnership with local culture bearers and knowledge keepers can play a vital role in shaping, keeping, and making meaningful places.', NULL, NULL, TRUE, NULL, 'Must be in the Creative Placemaking Minor; or by permission of instructor or program director.', 'ARCH458 or ARCH350.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'none', 'none_found', NULL, 'ARCH458.', NULL, NULL, NULL, NULL, 'Priority will be given to students in the Creative Placemaking Minor or interested in the minor. Course may include off-campus field trips.'),
    ('ARCH386', 'Experiential Learning', 1, 6, 'Learning experience tied to internship of specified duration with targeted learning outcomes.', NULL, NULL, TRUE, 'DSSP', 'Must have learning proposal approved by faculty sponsor and student''s internship sponsor; and sophomore standing or higher; and permission of ARCH-Architecture Program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'none', 'verified', '202605', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARCH400', 'Architecture Design Studio I', 6, 6, 'Introduction to architectural design with particular emphasis on conventions and principles of architecture, visual and verbal communication skills, formal analysis, design process, spatial composition, architectural promenade, basic program distribution, and elementary constructional and environmental responses.', 'ARCH300; or permission of ARCH-Architecture Program.', NULL, FALSE, NULL, 'Must be in a major in ARCH-Architecture Program; and permission of ARCH-Architecture Program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARCH401', 'Architecture Design Studio II', 6, 6, 'Continuation of ARCH 400 with introduction to building typology, urban and contextual issues, design of the vertical surface, and architectural interiors.', 'Minimum grade of C- in ARCH400.', NULL, TRUE, NULL, 'Must be in Architecture (B.S.) program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARCH402', 'Architecture Design Studio III', 6, 6, 'Architectural design studio with emphasis on building and facade typologies, the development of architectural promenade and sequence, public and/or civic infill buildings dependent upon the architectural promenade, and urban housing types of varying densities. The architect''s obligations to urban context are explored in many dimensions including historical, typological, and physical.', 'Minimum grade of C- in ARCH401.', NULL, TRUE, 'DSSP', 'Must be in Architecture (B.S.) program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'parsed', 'verified', '202601', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARCH403', 'Architecture Design Studio IV', 6, 6, 'Investigations into the relationship between the man-made and the natural world including introductory issues of assembly and material value. Design of the site and the building are combined into an integral process delimiting and probing the boundaries of each and exploring their reciprocal relationship. The architect''s obligations to the natural and urban contexts are explored in many dimensions including historical, typological, environmental, and physical.', 'Minimum grade of C- in ARCH402.', NULL, TRUE, 'FSOC', 'Must be in Architecture (B.S.) program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'parsed', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ARCH404', 'Graduate Architecture Design Studio I', 6, 6, 'Introduction to architectural design with particular emphasis on conventions and principles of architecture , visual and verbal communication skills, formal analysis, design process, spatial composition, architectural promenade, basic program distribution, and elementary constructional and environmental responses. Offered fall only.', NULL, NULL, TRUE, NULL, 'Must be in Architecture (Master''s) program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, 'For 3 1/2 year graduate students only.', NULL),
    ('ARCH405', 'Graduate Architecture Design Studio II', 6, 6, 'Architectural design studio with emphasis on building and facade typologies, the development of architectural promenade and sequence, public and/or civic infill buildings dependent upon the architectural promenade, and urban housing types of varying densities. The architect''s obligations to urban context are explored in many dimensions including historical, typological, and physical. Offered spring only.', 'Minimum grade of B- in ARCH404.', NULL, TRUE, NULL, 'Must be in Architecture (Master''s) program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/arch/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
