    ('ARTT389', 'Department of Art Undergraduate Teaching Assistantship', 3, 3, 'Individual contractual agreement with faculty/mentor. Individualized assistantship in the teaching of a specified department course offering. Must have previously received an "A" grade for the class to be assisting.', 'Permission of ARHU-Art department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/artt/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('ARTT399', 'Department of Art Research Assistantship', 1, 3, 'Individual contractual agreement with faculty/mentor. Individualized experiential learning developed in relation to art-related research issues.', 'Permission of ARHU-Art department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/artt/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
