    ('CCJS405', 'Gangs', 3, 3, 'Provides students with a historical and contemporary examination of street and institutional gangs. We will address the nature and definition of gangs, types of gangs, and diversity of membership of gangs, theoretical explanations, and criminal and deviant behavior. In addition, we will analyze law enforcement responses, intervention and prevention strategies, and public policy issues.', 'CCJS100 and CCJS105.', NULL, TRUE, NULL, NULL, 'CCJS405 or CCJS498G.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ccjs/', 'parsed', 'none_found', NULL, 'CCJS498G.', NULL, NULL, NULL, NULL, NULL),
    ('CCJS418', 'Seminar in Criminology and Criminal Justice', 3, 3, 'Selected topics of interest in the field of Criminology and Criminal Justice will be covered.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ccjs/', 'none', 'none_found', NULL, NULL, NULL, NULL, '18 credits if content differs.', NULL, NULL),
