    ('COMM376', 'Communication through Advocacy Short Film', 3, 3, 'Explores the theory and practice of contemporary communication and advocacy short form video.', NULL, NULL, TRUE, NULL, 'Must be in Communication program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/comm/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('COMM377', 'Digital Media in London', 3, 3, 'Provides students with skills in production practice while also incorporating theory and cultural studies. Students are challenged to understand societal problems around economy, race, gender, identity and power and to extend that exploration by building projects that utilize high demand skills in the digital communication and documentary professions. Students will write, record voice over, interview people, and build projects with compelling narrative structure. The projects will be an important component of their portfolio when applying to graduate school or their first professional efforts post-graduation. Classroom discussions will contain balance between practical instruction and critical discussion built around racial, social, and economic structures and systems.', NULL, NULL, TRUE, NULL, NULL, 'COMM369D or COMM377.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/comm/', 'none', 'none_found', NULL, 'COMM369D.', NULL, NULL, NULL, NULL, NULL),
