    ('CPGH100', 'College Park Scholars: Global Public Health First-Year Colloquium I', 1, 1, 'Introductory colloquium: Examination of factors that determine the health status of populations around the world.', NULL, NULL, TRUE, NULL, 'Students must be enrolled in the College Park Scholars Global Public Health (CPGH) program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpgh/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
