    ('CPGH200', 'College Park Scholars: Global Public Health Second-Year Colloquium', 1, 1, 'Building on knowledge and skills gained from the first-year colloquia, students will develop public health interventions that address a public health issue of a particular community.', 'CPGH101.', NULL, TRUE, 'DSSP', 'Students must be enrolled in the College Park Scholars Global Public Health (CPGH) program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpgh/', 'parsed', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
