    ('CPGH270', 'College Park Scholars: Global Public Health Education Abroad Practicum', 1, 3, 'Education abroad experience in an interest area related to global public health.', 'CPGH200.', NULL, TRUE, NULL, 'Students must be enrolled in the College Park Scholars Global Public Health (CPGH) program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpgh/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('CPJT100', 'College Park Scholars: Justice & Legal Thought: First-Year Colloquium', 1, 1, 'Students will gain an experiential understanding of law and justice by investigating concepts and frameworks of justice and apply them to real-world experience.', NULL, NULL, TRUE, NULL, 'Students must be enrolled in the College Park Scholars Justice & Legal Thought (CPJT) program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpjt/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('CPJT101', 'Colloquium in Justice and Legal Thought', 1, 1, 'An exploration of contemporary issues related to justice and legal thought.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpjt/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('CPJT200', 'Justice and legal Thought Second Year Colloquium', 1, 1, 'Advanced colloquium for second year students related to research skill development', NULL, NULL, TRUE, NULL, 'Students must be enrolled in the College Park Scholars Justice and Legal Thought (CPJT) program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpjt/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'When combined with the first year CPJT colloquia, students will learn how to research issues discussed and debated throughout year one.'),
    ('CPJT230', 'Capstone for Justice and Legal Thought: Internship', 2, 3, 'The capstone of the four-semester College Park Scholars Justice and Legal thought citation program is an exploration of justice and law within a rigorous academic and experiential framework. Students must develop and perform practicum internships in professional law related settings. In all settings, students must interact directly with legal professionals in law related fields and through law-related institutions under the supervision of legal professionals and program staff. In conjunction with the experiential component, students will synthesize their experience within the learning outcomes of the Justice and Legal Thought Program through an innovative final project culminating in a poster presentation.', NULL, NULL, TRUE, 'DSSP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpjt/', 'none', 'verified', '202601', NULL, NULL, NULL, NULL, NULL, NULL),
    ('CPJT240', 'Capstone for Justice and Legal Thought: Service-Learning', 2, 3, 'The capstone of the four-semester College Park Scholars Justice and Legal Thought citation program is an exploration of justice and law within a rigorous academic and experiential framework. Students must develop and perform practicum volunteer experiences in professional law related settings. In all settings, students must interact directly with legal professionals in law related fields and through law-related institutions under the supervision of legal professionals and program staff. In conjunctions with the experiential component, students will synthesize their experience within the learning outcomes of the Justice and Legal Thought program through an innovative final project culminating in a poster presentation.', 'CPJT200.', NULL, TRUE, 'DSSP', 'Must be in the College Park Scholars Justice & Legal Thought (CPJT) Program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpjt/', 'parsed', 'verified', '202601', NULL, NULL, NULL, NULL, NULL, NULL),
    ('CPJT250', 'Capstone for Justice and Legal Thought: Research', 2, 2, 'The capstone of the four-semester College Park Scholars Justice and Legal Thought citation program is an exploration of justice and law within a rigorous academic and experiential framework. Students must develop and perform applied research in a law related setting. Students must interact directly with legal professionals under the supervision of program staff. Students will synthesize their experience within the learning outcomes of the Justice and Legal Thought Program through an innovative final research project culminating in a poster presentation.', NULL, NULL, TRUE, 'DSSP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpjt/', 'none', 'verified', '202601', NULL, NULL, NULL, NULL, NULL, NULL),
