    ('CPSN100', 'College Park Scholars: International Studies First-Year Colloquium I', 1, 1, 'Introductory colloquium: Examination of issues related to international studies.', NULL, NULL, TRUE, NULL, 'Students must be enrolled in the College Park Scholars International Studies (CPSN) program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpsn/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('CPSN101', 'College Park Scholars: International Studies First-Year Colloquium II', 1, 1, 'Introductory colloquium II: Continued examination of issues related to international studies.', 'CPSN100.', NULL, TRUE, 'DVCC', 'Students must be enrolled in the College Park Scholars International Studies (CPSN) program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpsn/', 'parsed', 'verified', '202601', NULL, NULL, NULL, NULL, NULL, 'When paired with the successful completion of CPSN 100, students will earn Diversity/Cultural Competence General Education credits.'),
    ('CPSN200', 'College Park Scholars: International Studies Second-Year Colloquium I', 1, 1, 'This sophomore colloquium aims to help prepare College Park Scholars International Studies students with practical, translatable knowledge and capabilities that are required to enter and contribute constructively to addressing pressing challenges as global citizens. Building on their previous two colloquiua, students are (1) introduced to practical realities of developing projects, programs, and policies to address the world''s grand challenges, including those associated with exposures to new settings, cultures, and issues; (2) trained in hard skills necessary to design, plan, implement, and evaluate projects and policies effectively and ethically; (3) instructed in practical, efficient research with applied relevance; and (4) exposed to strategies of entrepreneurship and innovation.', 'CPSN101.', NULL, TRUE, NULL, 'Must be enrolled in the College Park Scholars International Studies (CPSN) program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpsn/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('CPSN230', 'College Park Scholars: International Studies - Internship Practicum', 1, 3, 'Supervised internship project in an area related to international studies.', 'CPSN101.', NULL, TRUE, NULL, 'Students must be enrolled in the College Park Scholars International Studies (CPSN) program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpsn/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('CPSN240', 'College Park Scholars: International Studies - Service-Learning Practicum', 1, 3, 'Supervised Service-Learning project in an area related to international studies.', 'CPSN101.', NULL, TRUE, NULL, 'Students must be enrolled in the College Park Scholars International Studies (CPSN) program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpsn/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('CPSN250', 'College Park Scholars: International Studies - Research Practicum', 1, 3, 'Supervised research in an area related to international studies.', 'CPSN101.', NULL, TRUE, NULL, 'Students must be enrolled in the College Park Scholars International Studies (CPSN) program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpsn/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('CPSP110', 'Bridging Divides thru Intergroup Dialogue Across Disciplines', 1, 1, 'Through deliberate reflections on the past and current patterns of exclusion and inclusion within your disciplinary field, you will develop skills for engaging in equitable and inclusive processes and practices that can transform your collaborations and approach to your discipline. This course engages students, from multiple social identity groups, in facilitated dialogue that focus on the tensions, similarities, and differences of experience that exist within, between, and/or across groups.', NULL, NULL, TRUE, 'DVCC', 'CPSP110 restricted to students in College Park Scholars.', 'EDDI110 or CPSP110.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpsp/', 'none', 'verified', '202608', NULL, 'EDDI110.', NULL, NULL, NULL, NULL),
    ('CPSP118', 'College Park Scholars First-Year Colloquium I', 1, 3, 'Introductory colloquium for specific College Park Scholars Program.', NULL, NULL, TRUE, NULL, 'Must be in the College Park Scholars Program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpsp/', 'none', 'none_found', NULL, NULL, NULL, NULL, '3 credits.', NULL, NULL),
    ('CPSP119', 'College Park Scholars First-Year Colloquium II', 1, 3, 'Intermediate colloquium for specific College Park Scholars Programs.', 'CPSP118.', NULL, TRUE, NULL, 'Must be in the College Park Scholars Program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpsp/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, '3 credits.', NULL, NULL),
    ('CPSP210', 'Art-Tech Studio: Integrations of the Arts and Technology for Change Making', 3, 3, 'Students will investigate various cultures of the arts and technology through ethnographic study. We will work collaboratively to make meaning of the relationships among these cultures in the context of social justice for communities. We will learn arts techniques and each student will envision a fusion of the arts and technology to support a more just and equitable future for a community of interest.', NULL, NULL, TRUE, 'DSSP, DVCC, SCIS', 'Must be in the College Park Scholars Program; or permission of College Park Scholars.', 'CPSP318 or CPSP210.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpsp/', 'none', 'verified', '202601', NULL, NULL, NULL, NULL, NULL, 'If seats are available after CPS students have registered, permission will be granted to students outside CPS to take the course.'),
    ('CPSP218', 'College Park Scholars Second-Year Colloquium I', 1, 3, 'Colloquium for specific College Park Scholars Program.', 'CPSP118.', NULL, TRUE, NULL, 'Must be in the College Park Scholars Program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpsp/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, '3 credits.', NULL, NULL),
    ('CPSP219', 'College Park Scholars Second-Year Colloquium II', 1, 3, 'Intermediate colloquium for specific, second year, College Park Scholars Program.', 'CPSP218.', NULL, TRUE, NULL, 'Must be in the College Park Scholars Program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpsp/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, '3 credits if content differs.', NULL, NULL),
    ('CPSP220', 'Where the Waters Blend: Contemporary Indigenous Perspectives on History, Traditions, and Modern Issues', 3, 3, 'In this unique cultural and personal learning experience, students will explore the history, traditions, and contemporary issues faced by Maryland''s Indigenous people, particularly the Piscataway. The course emphasizes the interconnectedness of culture and environment, highlighting how Indigenous Ecological Knowledges shape our understanding of biodiversity and interconnected life. The experiential work of the course asks students to consider how the past matters, particularly when it is embodied in the land they live on, and their present obligations to it. On-campus and place-based learning focuses on the impacts of colonization on the Piscataway - cultural suppression, land displacement, and their effects today - and fosters students'' capacity to challenge paradigms that marginalize Indigenous people in our region, nation, and world. Students will emerge with a greater understanding of Maryland''s land, the critical role of biodiversity, and the resilience of the Piscataway culture.', NULL, NULL, TRUE, 'DSHS, DVCC', NULL, 'HNUH268W, HNUH258Q or CPSP220.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpsp/', 'none', 'verified', '202608', 'HNUH268W.', 'HNUH258Q.', NULL, NULL, NULL, NULL),
