    ('CPSP279', 'Practicum: Study Abroad', 1, 3, 'Supervised international experience that satisfies students'' College Park Scholars practicum requirement.', NULL, NULL, TRUE, NULL, 'Must be in the College Park Scholars Program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpsp/', 'none', 'none_found', NULL, NULL, NULL, NULL, '3 credits if content differs.', NULL, NULL),
    ('CPSP300', 'Intergroup Dialogue Facilitator Development & Practicum', 3, 3, 'Facilitation is an artform and a science. This course is designed to introduce students to foundational dialogue facilitation skills and social justice frameworks needed to effectively facilitate group interactions across and within social differences. Students will apply the skills learned by facilitating a multi-session dialogue course with either the Common Ground or the Words of Engagement Intergroup Dialogue Program (WeIDP).', NULL, NULL, TRUE, NULL, 'Permission of the Counseling, Higher Education, and Special Education department.', 'WEID300, CPSP300, HONR300, or EDDI300.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpsp/', 'none', 'none_found', NULL, 'WEID300.', 'EDDI300, HONR300.', NULL, NULL, NULL, 'Students must be given permission to enroll and be admitted to the intergroup dialogue facilitator program.'),
