    ('CPSP339', 'Advanced Practicum: Internship', 1, 3, 'Independent study designed for students who wish to extend in greater depth and detail projects begun in sophomore year. Subject varies. Overseen by faculty director or mentor.', 'CPSP239.', NULL, TRUE, NULL, 'Must be in the College Park Scholars Program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/cpsp/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, '3 credits.', NULL, NULL),
