    ('FREN211', 'French Reading and Conversation', 3, 3, 'Practice in spoken French at intermediate level based on readings in a variety of genres. Written homework and exams.', 'FREN203.', NULL, TRUE, NULL, 'Must not be a native/fluent speaker of French.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/fren/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('FREN241', 'Women Writers of French Expression in Translation', 3, 3, 'Works and ideas of 20th century women writers of French in Canada, Africa, the Caribbean and France. Taught in English.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/fren/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('FREN242', 'Francophone Writers of Africa and the African Diaspora', 3, 3, 'An analysis of the works and ideas of 20th and 21st century Francophone writers (Africa, the Caribbeans, France). Taught in English.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/fren/', 'none', 'verified', '202508', NULL, NULL, NULL, NULL, NULL, NULL),
    ('FREN243', 'Masterpieces in French and Francophone Cinemas', 3, 3, 'This course, taught in English, will present a large array of films directed by famous French directors (Jean Renoir, Robert Bresson, Jean-Luc Godard, Agnes Varda, etc..) and Francophone filmmakers (Arcand, Sembene) who were internationally known in their time and have had a considerable influence on today''s filmmakers in the U.S. (Tarantino, Lynch, Lee, etc..) and abroad (Sissoko, Angelopoulos, VonTrier, ect..).', NULL, NULL, TRUE, 'DSHU', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/fren/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('FREN250', 'Introduction to Cultural and Textual Analysis', 3, 3, 'Introduction to cultural and textual analysis of selected readings from various genres in French literature. Taught in French.', 'FREN204; or students who have taken courses with comparable content may contact the department.', NULL, FALSE, 'DSHU', 'Must not be a native/fluent speaker of French.', 'FREN250 or FREN250H.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/fren/', 'partial', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
