    ('FREN301', 'Composition and Style', 3, 3, 'Grammatical analysis, elements of style; range of written genres.', 'FREN250; or students who have taken courses with comparable content may contact the department.', NULL, FALSE, NULL, 'Must not be a native/fluent speaker of French.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/fren/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('FREN302', 'Introduction to Translation', 3, 3, 'Hands-on practice in translation to include a variety of formats and texts (for example, advertising, legal, technical, literary, journalistic, media...) into French and/or English. Includes an extensive overview of translation techniques, theories and approaches. Taught mainly in French.', 'FREN301; or students who have taken courses with comparable content may contact the department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/fren/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('FREN306', 'Commercial French I', 3, 3, 'Introduction to commercial French including correspondence and business terminology. Emphasis on cross-cultural concepts needed for successful interaction within business settings. Taught in French.', 'FREN301; or students who have taken courses with comparable content may contact the department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/fren/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
