    ('FREN472', 'The Construction of French Identity II: From the Revolution to the Early Twentieth Century', 3, 3, 'French life, customs, culture, traditions (1750 to the early twentieth century).', 'FREN387; or permission of ARHU-French & Italian Languages & Literatures department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/fren/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('FREN474', 'Contemporary France: A Sociocritical Approach', 3, 3, 'A sociocritical approach to understanding modern French society through the study of print and non-print media documents (autobiography, film, and paraliterature), with reference to the Francophone world. Taught in French.', 'FREN387; or permission of ARHU-French & Italian Languages & Literatures department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/fren/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, 'FREN473.', NULL),
    ('FREN478', 'Themes and Movements of French Literature in Translation', 3, 3, 'Studies treatments of thematic problems or literary or historical movements in French literature. Topic to be determined each semester. Taught in English.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/fren/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
