    ('GERS320', 'Survey of German Studies', 3, 3, 'Approaches to analysis of German cultural products such as literature, film, poetry, architecture and works of art. Taught in German.', 'GERS301; or students who have taken courses with comparable content may contact the department.', NULL, FALSE, NULL, NULL, 'GERM320 or GERS320.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/gers/', 'partial', 'none_found', NULL, 'GERM320.', NULL, NULL, NULL, NULL, NULL),
    ('GERS322', 'Highlights of German Literature and Culture', 3, 3, 'Selected literary masterworks, social and cultural issues, and historical events in German-speaking countries from the Enlightenment, Romanticism, Junges Deutschland, Realism, Naturalism and its counter currents, Expressionism to the present. Taught in German.', 'GERS302; or students who have taken courses with comparable content may contact the department.', NULL, FALSE, 'DSHU', NULL, 'GERM322 or GERS322.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/gers/', 'partial', 'verified', '202608', 'GERM322.', NULL, NULL, NULL, NULL, NULL),
    ('GERS331', 'Kafka and Film: The Uncanny in Literature and Film', 3, 3, 'Analysis of major works by Franz Kafka (1883-1924), his affinity to the cinema and use of cinematic means and techniques (e.g. the gaze, flashback, parallel action, gesture and body language, etc.) in his writings, as well as examination of adaptations of Kafka narratives (e.g. the Orson Welles and David Jones adaptations of The Trial, 1961, 1992) and other films that use Kafkaian themes (e.g. Steven Soderbergh''s ''Kafka'', 1991).', NULL, NULL, TRUE, NULL, NULL, 'GERM331, GERS331, or CINE331.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/gers/', 'none', 'none_found', NULL, NULL, 'CINE331.', NULL, NULL, NULL, NULL),
    ('GERS339', 'German Literature In Translation', 3, 3, 'Selected movements, genres or other special topics in German literature. Readings and instruction in English. May not be counted in the fulfillment of German major requirements in German literature.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/gers/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
