    ('GERS356', 'German for the Professions', 3, 3, 'An examination of the structures and work conditions of various industries in the German-speaking world including understanding and navigating company culture, professional development, and preparation for an internship or job where German is spoken.', 'GERS301.', NULL, TRUE, NULL, NULL, 'GERM356 or GERS356.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/gers/', 'parsed', 'none_found', NULL, 'GERM356.', NULL, NULL, NULL, NULL, NULL),
    ('GERS367', 'Literature in the Climate Crisis', 3, 3, 'An investigation of the relationship between climate and art & literature. Introduction to ecological thinking followed by study of artistic and literary works thematically grouped by the four elements: Earth, Water, Air, and Fire. Readings from the German literary tradition (Goethe, Tieck, Stifter, Kafka, Frisch, Wolf) and contemporary research in the environmental humanities, with additional readings and viewings from elsewhere on the planet. Taught in English.', NULL, NULL, TRUE, NULL, NULL, 'GERM399E, CMLT399E, or GERS367.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/gers/', 'none', 'none_found', NULL, 'GERM399E.', 'CMLT399E.', NULL, NULL, '200-level General Education and/or humanities course; and sophomore standing.', 'Priority in enrollment will be given to German majors.'),
