    ('GERS379', 'Microcourse in German Studies', 1, 1, 'Exploration of diverse topics related to language, literature, and visual culture in the German-speaking world involving components of active and experiential learning. Taught in English.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/gers/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('GERS383', 'The ''Warrior'' in German Culture: From Valiant Knights to Brazen Terrorists', 3, 3, 'Acknowledging the nexus between acts of military aggression and political apparatuses, this course examines the semiotic significance of literary and cinematic manifestations of the warrior at critical junctures in German history. Taking the warrior as its focal point, this course explores the intricate web connecting various forms of military conflict, political systems of power, and social conventions within Western civilization from Antiquity to today. Taught in English.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/gers/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('GERS385', 'German Cinema', 3, 3, 'A history of German cinema from the golden age of silent films to the flourishing film culture of the 21st Century. Focuses on changing ideas of the role and purpose of national cinema, as well as the cinematic representation of nation and national identity. Taught in English.', NULL, NULL, TRUE, NULL, NULL, 'GERM385, GERS385, or CINE385.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/gers/', 'none', 'none_found', NULL, NULL, 'CINE385.', NULL, NULL, NULL, NULL),
