    ('GERS441', 'Border Crossings and Cultural Transfers', 3, 3, 'Border Crossings and Cultural Transfers emphasizes the transnational and global dimensions of German culture, analyzing the interrelationship of dominant and minority cultures within Germany and/or the impact of German cultures abroad. Topics include migration, exile, (post)colonialism, and globalization. Taught in German.', 'GERS320 or GERS322.', NULL, TRUE, NULL, NULL, 'GERM441 or GERS441.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/gers/', 'parsed', 'none_found', NULL, 'GERM441.', NULL, NULL, NULL, NULL, NULL),
    ('GERS442', 'Gender and Sexuality in German Literature and Society', 3, 3, 'Gender and Sexuality in German Literature and Society analyzes gender and sexuality as key discourses for understanding German-speaking literatures, cultures, and societies. Topics include the history of sexuality; death and desire; and representations of gender in German literature. Taught in German.', 'GERS320 or GERS322.', NULL, TRUE, NULL, NULL, 'GERM442 or GERS442.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/gers/', 'parsed', 'none_found', NULL, 'GERM442.', NULL, NULL, NULL, NULL, NULL),
    ('GERS443', 'Literature as Cultural Discourse', 3, 3, 'Investigates literature as cultural discourse in the construction of knowledge, emphasizing a discursive approach to analyzing a range of literary texts. Taught in German.', 'GERS320 or GERS322.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/gers/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('GERS444', 'The German-Jewish Experience', 3, 3, 'Focuses on the German-Jewish experience as a key dimension of European history, literature, and culture. Topics include Heinrich Heine, German-Jewish authors and texts, and the Holocaust in literature and film.', 'GERS320 or GERS322.', NULL, TRUE, NULL, NULL, 'GERM444 or GERS444.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/gers/', 'parsed', 'none_found', NULL, 'GERM444.', NULL, NULL, NULL, NULL, 'Taught in German.'),
