    ('GERS458', 'Literary or Media Genres', 3, 3, 'Literary or Media Genres studies the formal and stylistic dimensions of specific genres, emphasizing genre as a social, political, and aesthetic category. Topics include pop literature; the history of German drama; and German film genres among others.', 'GERS320 or GERS322.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/gers/', 'parsed', 'none_found', NULL, 'GERM458.', NULL, NULL, '6 credits if content differs.', NULL, 'Taught in German.'),
    ('GERS473', 'Variation in Contemporary German Language', 3, 3, 'Examines the unique, multilingual society that is modern Germany, exploring issues such as regional varieties, gendered language, language reform (and resistance to it), public and media speech, the influence of American English on colloquial speech and in specific fields, and the problems of immigrant communities acquiring both dialect and standard German.', 'GERS302; or permission of instructor.', NULL, FALSE, NULL, NULL, 'GERS473 or GERS673.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/gers/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('GERS489', 'Social Issues in German Culture', 3, 3, 'Special topics course examining the cultural constructions and representations of important social, political, and linguistic issues, investigating their connection to German values and institutions. Taught in German.', 'GERS320 or GERS322.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/gers/', 'parsed', 'none_found', NULL, 'GERM489.', NULL, NULL, '6 credits if content differs.', NULL, NULL),
