    ('GREK399', 'Topics in Advanced Modern Greek Language & Culture', 3, 3, 'Development of communicative skills in advanced Modern Greek. Topics will be drawn from the social and folk life of modern Greece.', 'GREK212; or permission of ARHU-Classics department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/grek/', 'partial', 'none_found', NULL, NULL, NULL, NULL, '6 credits.', NULL, NULL),
    ('GREK401', 'Intermediate Ancient Greek', 4, 4, 'The third and last part of the introductory sequence to ancient Greek, the language shared by Homer, Aristophanes, Aristotle, Hippocrates, Ptolemy, Archimedes, Euclid, and Paul the Apostle, among many others whose ideas and influence have shaped our world. Students will conclude their review of the major points of grammar. strengthen their reading comprehension with select texts of Classical and New Testament (Koine) Greek, and learn about basic aspects of Athenian life and culture in the fifth century BC.', NULL, NULL, TRUE, NULL, 'Restricted to Graduate Students.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/grek/', 'none', 'none_found', NULL, NULL, NULL, 'GREK201.', NULL, NULL, 'This course is restricted to Graduate Students; please consult with the DGS of Classics. Undergraduates who wish to study intermediate Greek should register for GREK201.'),
    ('GREK411', 'Modern Greek Literature and History', 3, 3, 'Students will study historical and political events in Greece during the 19th and 20th centuries through the viewpoint of the man of letters. Poetry, prose, plays, and essays reflect national emancipation, social reconstruction, and political struggles. Readings and discussion are in Modern Greek.', 'Students must have earned a grade of C- or better in a 300-level Modern Greek course.', NULL, FALSE, NULL, 'Permission of instructor.', 'GREK311 or GREK411.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/grek/', 'unstructured', 'none_found', NULL, 'GREK311.', NULL, NULL, NULL, NULL, NULL),
