    ('HONR218', 'Special Topics in Honors College Study Abroad', 1, 6, 'Special topics courses taken in the Honors College as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, 'Minimum cumulative GPA of 3.20.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/honr/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
