    ('HONR298A', 'Impacts of Globalization', 3, 3, 'Introduces students to key global concepts, discusses a range of perspectives on globalization and cultural competence, and offers an applied learning experience.', 'CPBE100; or by permission.', NULL, FALSE, NULL, 'Students must be matriculated into the College Park Scholars Business, Society & Entrepreneurship (CPBE) program; or by permission.', 'CPBE270 or HONR298A.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/honr/', 'partial', 'none_found', NULL, NULL, 'CPBE270.', NULL, NULL, NULL, NULL),
    ('HONR300', 'Intergroup Dialogue Facilitator Development & Practicum', 3, 3, 'Facilitation is an artform and a science. This course is designed to introduce students to foundational dialogue facilitation skills and social justice frameworks needed to effectively facilitate group interactions across and within social differences. Students will apply the skills learned by facilitating a multi-session dialogue course with either the Common Ground or the Words of Engagement Intergroup Dialogue Program (WeIDP).', NULL, NULL, TRUE, NULL, 'Permission of the Counseling, Higher Education, and Special Education department.', 'WEID300, CPSP300, HONR300, or EDDI300.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/honr/', 'none', 'none_found', NULL, 'WEID300.', 'EDDI300, CPSP300.', NULL, NULL, NULL, 'Students must be given permission to enroll and be admitted to the intergroup dialogue facilitator program.'),
    ('HONR318', 'Advanced Honors Seminar', 3, 3, 'A series of seminars, often interdisciplinary in character, and sometimes team taught. The subjects will vary from semester to semester.', NULL, NULL, TRUE, NULL, 'Permission of University Honors Program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/honr/', 'none', 'none_found', NULL, NULL, NULL, NULL, '9 credits if content differs.', NULL, NULL),
