    ('HONR368A', 'MGA Legislative Seminar', 3, 3, 'Prepares students to intern for the Maryland General Assembly. Introduces standard legislative genres and assigns extended practice in researching legislative issues.', 'Students who have taken courses with comparable content may contact the department; or ENGL101.', NULL, FALSE, 'FSPW', 'Permission of ARHU-English department.', 'HONR368A or ENGL381.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/honr/', 'unstructured', 'verified', '202608', NULL, 'ENGL381.', NULL, NULL, NULL, 'Application required. Contact english@umd.edu for more information.'),
    ('HONR379', 'Honors Independent Study', 1, 6, 'Involves reading or research directed by individual faculty, especially in areas outside of the student''s major. Open only to University honors students.', NULL, NULL, TRUE, NULL, 'Permission of University Honors Program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/honr/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('HONR379W', 'Maryland General Assembly Writing Internship', 6, 6, 'Experiential learning at the Maryland General Assembly (early January through early April). Interns participate in standard office tasks, research legislative issues, and draft legislative texts such as constituent letters, notes on bills, newsletters, policy memos, and testimony. Specific assignments vary according to the host legislator''s needs and the intern''s schedule.', 'ENGL381 or HONR368A.', NULL, TRUE, 'DSSP', 'Minimum cumulative GPA of 3.0; and must have earned a minimum of 60 credits; and must be admitted to the MGA program.', 'ENGL388M or HONR379W.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/honr/', 'parsed', 'verified', '202601', NULL, 'ENGL388M.', NULL, NULL, NULL, NULL),
    ('HONR386', 'Experiential Learning', 3, 6, '', 'Must have a Learning Proposal approved by the Office of Experiential Learning Programs, faculty sponsor, and student''s internship sponsor.', NULL, FALSE, NULL, 'Junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/honr/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
