    ('ITAL203', 'Intensive Intermediate Italian', 4, 4, 'Covers speaking, reading, writing, listening, and culture of Italian-speaking world.', 'ITAL103; or must have appropriate World Language Placement (WLP) score.', NULL, FALSE, NULL, 'Must not have completed ITAL122; and must not be a fluent/native speaker of Italian.', 'ITAL203 or ITAL122.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ital/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ITAL204', 'Advanced Intermediate Italian', 3, 3, 'An intensive study of Italian language and culture. This course completes the sequence of ITAL 103 and 203. After a brief review of important material of Intermediate Italian (ITAL 203), we will cover the last four chapters of Parliamo italiano (Unita 9-12). ITAL 204 is designed to reinforce and deepen the students'' knowledge of Italian and its idiomatic usage, and to improve their reading and writing skills through a more in-depth study of more complex grammatical forms. Students are encouraged to practice Italian using grammatical concepts in an active manner. There will be oral and written exercises, short readings, and vocabulary expansion. Special attention will be given to readings, oral comprehension and written compositions. To improve their listening and reading comprehension, students will also view and analyze film clips, and read short articles in newspapers and magazines on current events and global issues pertaining to Italy and the European Union.', 'ITAL203 or equivalent; or must have appropriate World Language Placement (WLP) score.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ital/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ITAL207', 'Speaking and Writing in Italian', 3, 3, 'An intensive upper intermediate language course that focuses on Italian speaking and writing. The course, which is taught entirely in Italian, is designed to reinforce and deepen the students'' knowledge of the Italian language and its idiomatic usage, and to improve their speaking ability and listening comprehension. Students will be given practice both in speaking extemporaneously and giving oral reports written on a wide range of topics dealing with contemporary Italy. One of the main objectives of the course is to prepare students to take upper level courses (300-400 levels) in Italian language, literature, and culture', 'ITAL204; or students who have taken courses with comparable content may contact the department.', NULL, FALSE, 'DSHU', 'Must not be a fluent/native speaker of Italian.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ital/', 'partial', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('ITAL211', 'Intermediate Conversation', 3, 3, 'Practice in spoken Italian based on reading and listening exercises in a variety of genres. Written assignments and exams.', 'ITAL203; or permission of ARHU-School of Languages, Literatures, and Cultures department.', NULL, FALSE, NULL, 'Must not be a fluent/native speaker of Italian.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ital/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ITAL252', 'Stories of Italy', 3, 3, 'Introduction to fictions across time and space in Italy.', 'ITAL207; or permission of ARHU-School of Languages, Literatures, and Cultures department.', NULL, FALSE, NULL, 'Must not be a fluent/native speaker of Italian.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ital/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('ITAL261', 'Cuisine, Culture, and Society in Italy Yesterday and Today', 3, 3, 'Exposes students to an important aspect of Italian culture: the art of gastronomy. Provides an in-depth understanding of the close relationship between food and culture, while enriching their knowledge of the Italian language through reading and analysis of various texts which deal with the preparation and adaptation of Italian food in different cultural settings. Taught in Italian.', 'ITAL204; or permission of ARHU-School of Languages, Literatures, and Cultures department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ital/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
