    ('KORA398', 'Special Topics in Korean Studies', 3, 3, 'Study of particular aspect of Korean language, literature, and/or culture. Topic and language of instruction to be announced when course is offered.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/kora/', 'none', 'none_found', NULL, NULL, NULL, NULL, '9 credits if content differs.', NULL, NULL),
