    ('LACS148', 'Special Topics in Latin American and Caribbean Studies', 3, 3, 'Topics to be announced when offered.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/lacs/', 'none', 'none_found', NULL, 'LASC148.', NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('LACS234', 'Issues in Latin American and Caribbean Studies I', 3, 3, 'Interdisciplinary study of major issues in Latin America and the Caribbean, including Latin America''s cultural mosaic, migration and urbanization. Democratization and the role of religions. Taught in English.', NULL, NULL, TRUE, 'DSHS or DSHU, DVUP', NULL, 'LASC234, PORT234, SPAN234, or LACS234.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/lacs/', 'none', 'verified', '202608', 'LASC234.', 'PORT234, SPAN234.', NULL, NULL, NULL, NULL),
    ('LACS235', 'Issues in Latin American and Caribbean Studies II', 3, 3, 'Major issues shaping Latin American and Caribbean societies including the changing constructions of race, ethnicity, gender and class as well as expressions of popular cultures and revolutionary practices. Taught in English.', NULL, NULL, TRUE, 'DSHS or DSHU, DVUP', NULL, 'LASC235, PORT235, SPAN235, or LACS235.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/lacs/', 'none', 'verified', '202601', 'LASC235.', 'PORT235, SPAN235.', NULL, NULL, NULL, NULL),
    ('LACS248', 'Special Topics in Latin American and Caribbean Studies', 3, 3, 'Topics to be announced when offered.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/lacs/', 'none', 'none_found', NULL, 'LASC248.', NULL, NULL, '6 credits.', NULL, NULL),
    ('LACS250', 'History of Colonial Latin America', 3, 3, 'Introductory survey of the history of Latin America from pre-Columbian Indian cultures to the beginning of the wars for independence (ca. 1810), covering cultural, political, social, and economic developments. Major themes include conquest, colonialism, indigenous culture, African slavery, religion, race and ethnicity, and gender ideologies.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'LASC250, HIST250, OR LACS250.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/lacs/', 'none', 'verified', '202608', 'LASC250.', 'HIST250.', NULL, NULL, NULL, NULL),
    ('LACS251', 'Latin America Since Independence', 3, 3, 'Introductory survey of the history of Latin America from the era of independence (c. 1810-1825) through the early 1980s. Major themes include independence and sovereignty, postcolonialism and neocolonialism, nation- and state-building, liberalism, citizenship, economic development and modernization, social organization and stratification, race and ethnicity, gender relations, identity politics, reform and revolution, authoritarianism and democratization, and inter-American relations.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'HIST251, LASC251, or LACS251.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/lacs/', 'none', 'verified', '202601', 'LASC251.', 'HIST251.', NULL, NULL, NULL, NULL),
    ('LACS269', 'Special Topics in Study Abroad II', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/lacs/', 'none', 'none_found', NULL, 'LASC269.', NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('LACS286', 'Internship in Latin American/Caribbean Studies', 1, 6, 'Internship experience with an organization that works with or studies Latin American and/or the Caribbean. This is an experiential learning course that provides semester-long training that enriches the student''s academic field of study and the LASC Certificate. Students submit a final written report of how the experience ties into their major field of study.', 'LASC234, SPAN234, LASC235, SPAN235, LACS250, HIST250, LACS251, or HIST251; and permission of Latin American and Caribbean Studies Center required.', NULL, FALSE, NULL, 'Minimum cumulative GPA of 2.5; and cannot have more than 60 credits total.', 'LASC286 or LACS286.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/lacs/', 'unstructured', 'none_found', NULL, 'LASC286.', NULL, NULL, NULL, NULL, 'The course is primarily intended for students seeking the Certificate in Latin American and Caribbean Studies, but exceptions will be considered for students with educational or career interests which lie in this area. Student internships must be approved by the Director and students must secure an appropriate faculty mentor to supervise the internship course.'),
    ('LACS348', 'Special Topics in Latin American and Caribbean Studies', 3, 3, 'Topics to be announced when offered.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/lacs/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('LACS348E', 'Caribbean Literature in English', 3, 3, 'Political and literary traditions that intersect in the fiction, poetry, and drama written in English by Caribbean writers, primarily during the 20th century.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, 'ENGL362, LASC348E, or LACS348E.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/lacs/', 'none', 'verified', '202508', NULL, 'ENGL362.', NULL, NULL, NULL, NULL),
    ('LACS369', 'Special Topics in Study Abroad III', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/lacs/', 'none', 'none_found', NULL, 'LASC369.', NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('LACS370', 'Education, Technology and Society: Ecuador in Context', 3, 3, 'Set in the UNESCO World Heritage site of Cuenca, Ecuador, students in this short-term study abroad course use theory from Science and Technology Studies (STS) to explore, discuss and critique the design, development and implementation of technology-based social programs in Ecuador. The program looks at education and technology throughout multiple lenses and contexts. Collaboration with the University of Cuenca, participating students have the opportunity for both university and field-based research and practice. UMD students work alongside students and faculty from the leaders and practitioners from UCuenca, government agencies, nongovernmental organizations, small business and local communities.', NULL, NULL, TRUE, NULL, 'Minimum cumulative GPA of 2.5.', 'ENES259T, ENES359T, CPSP279T, LASC269T, CPSS370, or LACS370.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/lacs/', 'none', 'none_found', NULL, 'ENES259T.', 'ENES359T, CPSS370.', NULL, NULL, '1 course from (ENES240, ENES200, or ENEE200).', NULL),
    ('LACS448', 'Special Topics in Latin American and Caribbean Studies', 3, 3, 'Intensive study of a selected topic related to Latin American and Caribbean Studies.', NULL, NULL, TRUE, NULL, 'Junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/lacs/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('LACS458', 'Senior Capstone Course in Latin American and Caribbean Studies', 3, 3, 'Capstone course for advanced students in the Latin American and Caribbean Studies Certificate Program or other students with appropriate preparation. Interdisciplinary topics will vary each semester.', 'LACS234 and LACS235; or permission of Latin American and Caribbean Studies Center.', NULL, FALSE, NULL, 'Must be in Latin American and Caribbean Studies Certificate program; and senior standing.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/lacs/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('LACS486', 'Internship in Latin American/Caribbean Studies', 1, 6, 'Internship experience with an organization that works with or studies Latin American and/or the Caribbean. This is an experiential learning course that provides semester-long training that enriches the student''s academic field of study and the LACS Certificate. Students submit a final written report of their experience, including critical analysis of the institutional relevance to their major field of study and to Latin American and Caribbean Studies. Students will also be asked to give an oral presentation.', 'Permission of Latin American and Caribbean Studies Center required.', NULL, FALSE, NULL, 'Minimum cumulative GPA of 2.5; and must have earned a minimum of 60 credits.', 'LASC486 OR LACS486.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/lacs/', 'unstructured', 'none_found', NULL, 'LASC486.', NULL, NULL, NULL, NULL, 'The course is primarily intended for students seeking the Certificate in Latin American and Caribbean Studies, but exceptions will be considered for students with educational or career interests which lie in this area. Student internships must be approved by the Director, and students must secure an appropriate faculty mentor for the internship course. An internship course will be approved only if a faculty supervisor is available.'),
    ('LACS499', 'Independent Study in Latin American and Caribbean Studies', 1, 3, 'Independent Study in Latin American and Caribbean Studies.', NULL, NULL, TRUE, NULL, 'Permission of instructor.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/lacs/', 'none', 'none_found', NULL, 'LASC499.', NULL, NULL, '6 credits.', NULL, NULL),
    ('LARC121', 'Computer Visualization in Design', 3, 3, 'Students are provided with the opportunity to 1) explore basic design principles and practice, 2) explore and apply computer concepts and principles, 3) learn and apply basic computer tools used in landscape architecture and allied disciplines, and 4) demonstrate competency in design vocabulary and computer applications through demonstrated deliverables used in the built environment design fields.', NULL, NULL, TRUE, 'DSSP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('LARC131', 'Computer Visualization I', 3, 3, 'Provides the opportunity to 1) explore basic design principles and practice 2) explore and apply computer concepts and principles, 3) learn and apply basic computer tools used in landscape architecture and allied disciplines and 4) demonstrate competency in design vocabulary and computer applications through demonstrated deliverables used in the built environment design fields.', NULL, NULL, TRUE, NULL, 'Permission of AGNR-Plant Science & Landscape Architecture department; and must be in Landscape Architecture program.', 'LARC120 or LARC131.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'none', 'none_found', NULL, 'LARC120.', NULL, NULL, NULL, NULL, NULL),
    ('LARC151', 'Urban Agriculture: Designing and Assessing Edible Landscapes', 3, 3, 'Students will examine the growing development of urban agriculture and edible landscapes. Urban agriculture has seen a recent growth and interest in cities across the globe. From Paris to New York, from Baltimore to Detroit, urban agriculture is an emerging land use to address a variety of needs. Redevelopment, food deserts, community engagement and environmental justice are just some of the issues and topics that are connected to the recent growth of urban agriculture. This course will take a critical examination of urban agriculture''s contribution to the food system, its input and outputs in the urban landscape, and the planning and design of urban agriculture and edible landscapes.', NULL, NULL, TRUE, 'DSSP, SCIS', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('LARC152', 'Greening Cities: Who Wins, Who Loses, and Who Cares?', 3, 3, '"Greening Cities" can have many interpretations: improving or adding urban economic activity, realizing energy efficiency, greening urban transport systems, etc. An important component of livable and sustainable cities and metropolitan ecosystems are the plants and landscapes that are inhabited by plants. With the majority of humans now living in cities, a survey of urban ecosystem principles and an examination of design and planning strategies for plant and landscape resources in urban and metropolitan regions is critical.', NULL, NULL, TRUE, 'DSSP, SCIS', NULL, 'LARC152 or PLSC289I.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'none', 'verified', '202601', 'PLSC289I.', NULL, NULL, NULL, NULL, NULL),
    ('LARC160', 'Introduction to Landscape Architecture and Environmental Design', 3, 3, 'History, theory, philosophy and current practice of the profession of landscape architecture. Explores the interactive relationship between humans and their environment by examining people''s perceptions of and changing attitude towards the landscape, as well as, an examination of how these are related to ecological and cultural influences. Topics include urban, ecological, community and creative design.', NULL, NULL, TRUE, 'DSHU or DSSP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('LARC161', 'The World Around You: People and the Environment', 3, 3, 'Explore human and environmental interactions. How do natural and built environments influence human health and well-being? Many environmental settings will be examined such as hospitals, public housing neighborhoods, school settings, retirement communities, transportation corridors, and green spaces. Learn how landscape architects and related fields work together to create environments that support individuals, families, and various community groups'' health and well-being.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('LARC162', 'Environmental Justice: Same World, Different Built Environment', 3, 3, 'Environmental Justice will be explored in the context of the built environment. What unequal public built environmental threats exist? How can these threats be prevented or eliminated? Public schools, public parks, access to clean water, air pollution, tree coverage are among the built environments examined in the course.', NULL, NULL, TRUE, 'DSHS, DVUP, SCIS', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'none', 'verified', '202601', NULL, NULL, NULL, NULL, NULL, NULL),
    ('LARC188', 'Special Topics in Landscape Architecture', 1, 3, 'A lecture course for students interested in Landscape Architecture to cover topics not formally taught in existing courses. An introductory class on a group of closely-related topics for students with an interest in this discipline.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('LARC220', 'Landscape Visualization II', 4, 4, 'Basic techniques and application of various media for graphic communication associated with landscape architecture.', NULL, 'LARC230.', TRUE, NULL, 'Permission of AGNR-Plant Science & Landscape Architecture department; and sophomore standing or higher; and must be in Landscape Architecture program.', 'LARC489R or LARC220.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'parsed', 'none_found', NULL, 'LARC489R.', NULL, NULL, NULL, NULL, NULL),
    ('LARC221', 'Digital Design Tools', 3, 3, 'The development and application of computing skills as used by the landscape architecture profession. This Computer-Aided Design and Drafting (CADD) course develops computer drafting using a variety of software programs. It also introduces students to Geographic Information Systems (GIS) mapping technologies.', 'LARC220.', NULL, TRUE, NULL, 'Must be in Landscape Architecture program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, 'LARC240 and LARC265.', NULL),
    ('LARC230', 'Design Fundamentals Studio', 5, 5, 'Introduction to the fundamentals of basic design focusing on creative problem solving associated with landscape architecture. Here you will explore design with different geometries, organizing principles, concept development, spatial definition, land formation, structures and plants. Emphasis will be given on how to represent design ideas using measured drafting techniques and presentation board organization. A series of foundational exercises will culminate in the redesign of a small public space.', 'Must have completed or be concurrently enrolled in LARC265.', 'LARC220.', TRUE, NULL, 'Permission of AGNR-Plant Science & Landscape Architecture department; and must be in Landscape Architecture program.', 'LARC141 or LARC230.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'parsed', 'none_found', NULL, 'LARC141.', NULL, NULL, NULL, NULL, NULL),
    ('LARC231', 'Site Planning and Design Studio', 5, 5, 'An examination of the influence of landscape character and site features (natural and cultural) on landscape architecture, architecture and planning through application in the studio setting.', 'LARC230.', 'LARC411 and LARC221.', TRUE, NULL, 'Must be in Landscape Architecture program.', 'LARC340 or LARC231.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'parsed', 'none_found', NULL, 'LARC340.', NULL, NULL, NULL, NULL, NULL),
    ('LARC263', 'History of Landscape Architecture', 3, 3, 'A survey of landscape architecture history from the ancient Western civilizations to the twentieth century with consideration of parallel developments in the Eastern World, European Africa and the Americas.', NULL, NULL, TRUE, 'DSHU', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'none', 'verified', '202601', NULL, NULL, NULL, NULL, NULL, NULL),
    ('LARC265', 'Site Analysis and Ecological Principles', 3, 3, 'Principles and methods of site analysis with an emphasis on the application of ecological principles in landscape architecture, architecture and planning.', 'LARC141.', 'LARC240 and LARC221.', FALSE, NULL, 'Permission of AGNR-Plant Science & Landscape Architecture department; and sophomore standing or higher; and must be in Landscape Architecture program.', 'LARC265 or ARCH460.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('LARC266', 'Site and Landscape Ecology Field Studies', 1, 1, 'Field Excursions that are essential to apply theory and principles explored in the LARC265 to real world environments.', 'Must have completed or be concurrently enrolled in LARC230 or LARC640.', 'LARC265.', FALSE, NULL, 'Sophomore standing or higher; and must be in Landscape Architecture program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'This course requires field trips.'),
    ('LARC330', 'Urban Design Studio', 5, 5, 'The landscape architect''s role within the interdisciplinary urban design process, focusing on urban site design issues. Pedestrian friendly site design and the future of sustainable development will be studied.', 'LARC231.', NULL, TRUE, 'FSOC', 'Must be in Landscape Architecture program.', 'LARC330 or LARC440.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'parsed', 'verified', '202608', 'LARC440.', NULL, NULL, NULL, NULL, NULL),
    ('LARC331', 'Regional Design and GIS Studio', 5, 5, 'An examination of the landscape architect''s role within the interdisciplinary regional design field incorporating GIS technologies, spatial modeling, and the regional design process.', 'LARC330 and LARC412.', 'LARC413.', TRUE, NULL, 'Must be in Landscape Architecture program.', 'LARC341 or LARC331.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'parsed', 'none_found', NULL, 'LARC341.', NULL, NULL, NULL, NULL, NULL),
    ('LARC388', 'Honors Thesis Research', 3, 6, 'Undergraduate honors thesis research conducted under the direction of an AGNR faculty member in partial fulfillment of the requirements of the College of AGNR Honors Program. The thesis will be defended to a faculty committee.', 'Must be in the AGNR Honors Program.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('LARC389', 'Internship in Landscape Architecture', 3, 3, 'A supervised internship where students earn credit for work experience related to their career goals. Each student must keep a work log, work on a special project, and produce a report related to this project. An evaluation from the external supervisor of the project is required. Participation requires application to the internship advisor in the preceding semester.', NULL, NULL, TRUE, NULL, 'Must be in Landscape Architecture program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits.', NULL, NULL),
    ('LARC398', 'Seminar', 1, 1, '', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('LARC411', 'Construction Technology I: Principles of Site Engineering', 4, 4, 'First of three courses in the landscape architecture engineering and construction sequence that focuses on the principles, procedures, and applications of site grading. Included in this subject area are the topics of relief visualization and representation, slope and contour calculations, grading objectives and methodology, structure siting principles, drainage principles, contour manipulation procedures, stormwater management, horizontal and vertical road alignment, and cut-fill calculations.', NULL, 'LARC231 or LARC641.', FALSE, NULL, 'Must be in Landscape Architecture program.', 'LARC320, LARC411 or LARC720.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'unstructured', 'none_found', NULL, 'LARC320.', NULL, NULL, NULL, NULL, NULL),
    ('LARC412', 'Construction Technology II: Materials and Structures', 4, 4, 'Second of three courses in the landscape architecture engineering and construction sequence focuses on site construction, soil and water-centric Best Design Practices (BDPs). Included in this subject area are the topics of construction operations and earthwork, soil erosion and sediment control, retaining wall, soil and constructed media, shoreline construction, bioretention and planting systems and green roofs', 'LARC411.', 'LARC330 or LARC642.', FALSE, NULL, 'Must be in Landscape Architecture program.', 'LARC321, LARC412 or LARC721.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'unstructured', 'none_found', NULL, 'LARC321.', NULL, NULL, NULL, NULL, NULL),
    ('LARC413', 'Construction Technology III: Water Soil-Centric Practices', 4, 4, 'Third of three courses in the landscape architecture engineering and construction sequence focuses on site construction, soil and water-centric Best Design Practices (BDPs). Included in this subject area are the topics of construction operations and earthwork, soil erosion and sediment control, retaining wall, soil and constructed media, shoreline construction, bioretention and planting systems and green roofs.', 'LARC412.', NULL, TRUE, NULL, 'Must be in Landscape Architecture program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('LARC420', 'Professional Practice', 3, 3, 'An introduction to and comparative study of the professional concerns of design firms. Focus on planning, legal, ethical, marketing and management considerations of interdisciplinary practices.', NULL, NULL, TRUE, NULL, 'Must be in Landscape Architecture program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('LARC421', 'Computer-Aided Design and Drafting (CADD): Urban Construction', 3, 3, 'This Computer-Aided Design and Drafting (CADD) course applies computer drafting using AutoCAD. It focuses on providing the technical skills for students who are working in built environment professions. Drawing types may include (but not be limited to) site plan drawings, construction detailing, grading plans, site layout plans and sheet layout conventions.', NULL, NULL, TRUE, NULL, NULL, 'LARC489O or LARC421.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'none', 'none_found', NULL, 'LARC489O.', NULL, NULL, NULL, NULL, NULL),
    ('LARC430', 'Community Design Studio', 5, 5, 'Studio that emphasizes the integration of critical thinking skills and methodologies introduced throughout the landscape architecture curriculum. Students apply design and analysis methodologies, evaluate alternative solutions, involve community residents and engage in final design development, using the master plan and site design process, report writing, and oral and graphic presentations. Final presentations are open to the university and the community.', 'LARC331 and LARC413.', NULL, TRUE, NULL, 'Senior standing; and must be in Landscape Architecture program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('LARC440', 'Urban Design Studio', 5, 5, 'The landscape architect''s role within the interdisciplinary urban design process, focusing on urban site design issues. Pedestrian friendly site design and the future of sustainable development will be studied.', 'LARC321; and LARC340; and LARC341.', NULL, FALSE, NULL, 'Must be in Landscape Architecture program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('LARC451', 'Sustainable Communities', 3, 3, 'Explores concepts, strategies and examples of community design which address the needs of a growing population while preserving the environment and its resources.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('LARC452', 'Green Infrastructure and Community Greening', 3, 3, 'A critical look and exploration of green infrastructure (GI) elements in the built environment in contributing to ecosystems services and the sustainability of the built environment. The course explores the science, issues, challenges, and the policy, planning and design solutions offered by green infrastructure.', 'PLSC110 and PLSC111; or (PLSC112 and PLSC113); or permission of instructor.', NULL, FALSE, NULL, 'Junior standing or higher.', 'LARC489G or LARC452.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'unstructured', 'none_found', NULL, 'LARC489G.', NULL, NULL, NULL, NULL, NULL),
    ('LARC453', 'Introduction to GIS and Hydrologic Modeling', 3, 3, 'Introduction to Geographic Information Systems (GIS) and their application to hydrologic modeling. Basic GIS skills are used to manipulate and analyze spatial data to populate NRCS TR-55 hydrologic model for use in sizing constructed wetlands, bio-retention cells, and minor flood zones. No prior knowledge of GIS or hydrologic modeling is required. Stormwater and erosion control permitting as well as basic design principles for Maryland Environmental Site Design standards are introduced.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('LARC454', 'Principles for Planting Design', 3, 3, 'Emphasis will be placed on the analysis of natural systems of the landscape as they relate to visual thinking and to the rigor of the design process. Planting Design will familiarize you with native habitats, reinforce the application of design principles, and assess human response to the built environment in terms of developing a planting scheme. Students will acquire an understanding of and an appreciation for complex, interdependent relationships that exist in a healthy plant community. Students will graphically represent planting plans as communication tools suitable for client and contractor discussion as well as the basic construction documentation process through plant schedules, details, technical specifications, soil analysis, cost estimating, site preparation, and landscape maintenance procedures.', 'PLSC253 and LARC220 or LARC620; or permission of instructor.', NULL, FALSE, NULL, 'Must be in Landscape Architecture program.', 'LARC454 or LARC489E.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'unstructured', 'none_found', NULL, 'LARC489E.', NULL, NULL, NULL, NULL, NULL),
    ('LARC461', 'People and the Environment', 3, 3, 'Focus is placed on human and environmental interactions. Students will look at both natural and built environments and how they influence human health and well-being. Many environmental settings will be examined. These include hospitals, public housing neighborhoods, school settings, retirement communities, transportation corridors and green spaces. We will also explore how racial and socio-economic factors affect living and working environmental conditions. Ultimately, students will be using this knowledge to create environments that support individuals, families and various community groups'' health and well-being.', NULL, NULL, TRUE, NULL, NULL, 'LARC489K or LARC461.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'none', 'none_found', NULL, 'LARC489K.', NULL, NULL, NULL, NULL, NULL),
    ('LARC470', 'Landscape Architecture Seminar', 3, 3, 'A combination of self-directed study, seminar, and lecture formats. An introduction to aspects of research methods, critical analysis, and proposal writing with a focus on urban and community design.', 'LARC321; and LARC341.', 'LARC440.', FALSE, NULL, 'Senior standing; and must be in Landscape Architecture program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('LARC471', 'Capstone Praxis Studio', 5, 5, 'A capstone experience with projects of varied thematic content that emphasize the integration of critical thinking skills and methodologies introduced throughout the landscape architecture curriculum. Students apply design and analysis methodologies, evaluate alternative solutions, involve community residents and engage in final design development, using the master plan and site design process, report writing, and oral and graphic presentations. Final presentations are open to the university and the community.', 'LARC430.', NULL, TRUE, NULL, 'Must be in Landscape Architecture program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('LARC489', 'Special Topics in Landscape Architecture', 1, 4, 'Credit according to time scheduled and organization of course. A lecture and/or studio course organized as an in-depth study of a selected specialization of landscape architecture not covered by existing courses.', 'Permission of AGNR-Plant Science & Landscape Architecture department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, '4 credits if content differs.', NULL, NULL),
    ('LARC499', 'Independent Studies in Landscape Architecture', 1, 4, 'Independent studies in landscape architecture including field, studio or library research under the direction of a faculty member.', NULL, NULL, TRUE, NULL, 'Must be in Landscape Architecture program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/larc/', 'none', 'none_found', NULL, NULL, NULL, NULL, '4 credits if content differs.', NULL, NULL),
    ('LASX301', 'Human Rights and Cultural Representations', 3, 3, 'The cultural and human responses to the violence of genocide politics in the Holocaust will serve as an excellent start point to analyze political repression in Latin America (focus on Guatemala, Uruguay, Argentina and Chile). This course discusses not only the impact of trauma, the legacy of memory and the role of the national states during dictatorships in these countries, but also how to make these experiences productive to reconstruct selves and societies.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/lasx/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'This course is offered as part of the Maryland-in-Buenos Aires study abroad program. Students must apply for this program through Education Abroad: More information at ter.ps/miba. Education Abroad processes registrations for this course on behalf of students.'),
    ('LATN101', 'Elementary Latin I', 4, 4, '', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/latn/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'A student who has two units of Latin in high school may register for LATN101 for the purposes of review, but ordinarily not for credit.'),
    ('LATN102', 'Elementary Latin II', 4, 4, '', 'Must have completed LATN101 at University of Maryland, College Park; or permission of ARHU-Classics department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/latn/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
