    ('LATN269', 'Special Topics in Study Abroad II', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/latn/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('LATN301', 'Plautus', 3, 3, 'Plautine drama. Literary, linguistic and socio-cultural aspects. Readings are in Latin.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/latn/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('LATN302', 'Ovid', 3, 3, 'Major works of Ovidian poetry. Literary and moral atmosphere of Augustan age. Readings are in Latin.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/latn/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('LATN303', 'Petronius', 3, 3, 'Reading and analysis of Petronius'' Satyricon with an emphasis on the literary climate of the Neronian Age and on the emergence of the novel as a literary genre. Readings are in Latin.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/latn/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('LATN304', 'Cicero and Sallust', 3, 3, 'Selected speeches of Cicero and selections from the historian Sallust. Rhetorical, social and political context. Readings are in Latin.', 'LATN201; or students who have taken courses with comparable content may contact the department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/latn/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('LATN306', 'Juvenal', 3, 3, 'In the early second century CE, the poet Juvenal composed his Satires, a series of bitterly critical verses railing against the supposed vices of contemporary Roman society. These poems, which are simultaneously deeply conservative and jarringly obscene, comment upon gender, class, sexuality, ethnicity, and politics in often enigmatic ways. Over the course of the semester, we will explore the strange mixture of aggression, self-deprecation, righteousness, and hypocrisy that characterizes Juvenal''s poetry. Students will develop their facility with the Latin language, while also familiarizing themselves with the literary, social, and political context in which Juvenal wrote. Students will utilize these linguistic and analytical skills to produce well-argued papers by the end of the semester.', 'LATN201; or equivalent.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/latn/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('LATN351', 'Horace and Catullus', 3, 3, 'Readings are in Latin.', 'LATN201; or students who have taken courses with comparable content may contact the department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/latn/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('LATN369', 'Special Topics in Study Abroad III', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/latn/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
