    ('MUED269', 'Special Topics in Study Abroad II', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/mued/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('MUED305', 'Marching Band Techniques', 2, 2, 'Designed to aid the student in learning how to prepare, organize, teach, and rehearse the contemporary high school marching band. Through class discussions, practical assignments, guest lecturers and audio/visual aids, students will gain a command of the terminology, pedagogy, and structure of a marching ensemble and its potential.', NULL, NULL, TRUE, NULL, 'Must be in Music Education program.', 'MUED499M or MUED305.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/mued/', 'none', 'none_found', NULL, 'MUED499M.', NULL, NULL, NULL, NULL, NULL),
    ('MUED311', 'Teaching Elementary Instrumental Music I', 2, 2, 'Prepare instrumental-emphasis music education majors to synthesize the knowledge and skills that will enable them to teach fundamental musical skills at the elementary level.', 'MUED187.', NULL, TRUE, NULL, 'Must be in Music Education program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/mued/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('MUED320', 'Teaching Secondary Instrumental Music I', 2, 2, 'Prepare instrumental-emphasis music education majors to synthesize the knowledge and skills that will enable them to extend secondary-level musical skill through planned instruction and development of teaching materials.', 'MUED187.', NULL, TRUE, NULL, 'Must be in Music Education program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/mued/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('MUED322', 'Teaching General Music I', 2, 2, 'Teaching General Music I is designed as a fundamental music methods course for students who are preparing for a career in general music. This course will focus on developmentally appropriate teaching practices for building musicianship in a general music setting.', 'MUED187 and MUED186.', NULL, TRUE, NULL, 'Must be in Music Education program.', 'MUED222 or MUED322.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/mued/', 'parsed', 'none_found', NULL, 'MUED222.', NULL, NULL, NULL, NULL, NULL),
    ('MUED333', 'Classroom Vocal Pedagogy', 2, 2, 'An introduction to the fundamentals of group vocal pedagogy for the choral and general classroom teacher, including the teaching of posture, breathing, resonance, registration, articulation and foreign language diction as appropriate to needs of the child or adolescent singer in K-12 classroom settings.', 'MUED187 and MUED186.', NULL, TRUE, NULL, 'Must be in Music Education program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/mued/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('MUED342', 'Technology for Music Education', 2, 2, 'Technology has profoundly remade nearly every facet of music, musicianship, and audience experience, including the education of music students. From the impact of recording, to the informational revolution of the internet, to the global economy, technology has accelerated the rate of change in our society and will likely continue to play a central role in the evolution of humanity. This course explores the broad dimensions of technology as they impact the lives of teachers and students in music education.', NULL, NULL, TRUE, NULL, 'Must be in Music Education program.', 'MUED342 or MUED499T.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/mued/', 'none', 'none_found', NULL, 'MUED499T.', NULL, NULL, NULL, NULL, NULL),
    ('MUED369', 'Special Topics in Study Abroad III', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/mued/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('MUED386', 'Experiential Learning', 3, 6, '', 'Must have learning proposal approved by the Office of Experiential Learning Programs, faculty sponsor, and student''s internship sponsor.', NULL, FALSE, NULL, 'Junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/mued/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('MUED411', 'Teaching Elementary Instrumental Music II', 4, 4, 'Prepare instrumental-emphasis music education majors to synthesize the knowledge and skills that will enable them to develop and/or maintain an exemplary curricular-oriented, research-based, comprehensive elementary instrumental music program.', 'MUED320 and MUED311.', NULL, TRUE, NULL, 'Must be in Music Education program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/mued/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
