    ('MUSC204', 'Popular Music in Black America', 3, 3, 'Traces black popular music in the U.S. with a special focus on spirituals, ragtime, the blues, early jazz, RB, Motown, funk, soul, and rap. Examines how these styles have been borrowed by the American music industry.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/musc/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('MUSC205', 'History of Popular Music, 1950-Present', 3, 3, 'A historical survey of rock music (blues, rock, soul, metal, rap, etc.) from circa 1950 to the present, with emphasis on popular music as music and popular music as social history.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/musc/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('MUSC210', 'The Impact of Music on Life', 3, 3, 'Music as a part of culture. Materials drawn from traditions throughout the globe to illustrate issues of historical and contemporary significance, including the impact of race, class and gender on the study of music.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, 'MUET210 or MUSC210.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/musc/', 'none', 'verified', '202608', 'MUET210.', NULL, NULL, NULL, NULL, NULL),
    ('MUSC215', 'World Popular Musics and Identity', 3, 3, 'Explore some of the most popular music genres in the world in order to learn about the roles that socially-constructed identities play in the promotion, presentation and interpretation of different types of popular music. Through historical context and performance analysis, this course invites students to consider how identities such as race, gender, sexuality, class, culture, religion, region and nation shape the development of genres and the functions they serve beyond mere entertainment.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/musc/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
