    ('MUSC251', 'Advanced Theory of Music II', 4, 4, 'A continuation of MUSC250, concentrating on late nineteenth-century chromatic harmony and an introduction to twentieth-century melody and harmony. Emphasis on sight singing, ear training, analysis and compositional skills.', 'Minimum grade of C- in MUSC250.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/musc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('MUSC260', 'Music as Global Culture', 3, 3, 'Explores how and why people create, transform, and move music around the globe. Taking a comparative approach to Western art musics and other musics of the world, course will examine a variety of musical practices in their social, political, and economic contexts. Experiential knowledge will be developed through hands-on ethnographic research.', 'MUSC151.', NULL, TRUE, 'DSHU, DVUP', 'Must be in a major within the ARHU-School of Music department.', 'MUSC220 or MUSC260.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/musc/', 'parsed', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
