    ('MUSC454', 'Jazz Improvisation II', 3, 3, 'Continuation of MUSC453 including scoring and transcription.', 'MUSC453; or students who have taken courses with comparable content may contact the department. And permission of ARHU-School of Music department.', NULL, FALSE, NULL, NULL, 'MUSC346 or MUSC454.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/musc/', 'partial', 'none_found', NULL, 'MUSC346.', NULL, NULL, NULL, NULL, NULL),
    ('MUSC455', 'Theory of Jazz', 3, 3, 'Analysis of jazz harmony, with emphasis on principles of substitution, reharmonization, and syntax. Topics may also include chord/scale relationships, phrasing and articulation, notation, and introductory arranging concepts such as orchestration and form.', 'MUSC250; or permission of ARHU-School of Music department.', NULL, FALSE, NULL, 'Must be in a major within ARHU-School of Music department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/musc/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('MUSC456', 'Jazz Arranging', 3, 3, 'A comprehensive approach to jazz arranging. Topics to include chord scale theory, voicing techniques, part and score layout, and formal construction of an arrangement.', 'MUSC455; and permission of ARHU-School of Music department.', NULL, FALSE, NULL, NULL, 'MUSC448N or MUSC456.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/musc/', 'unstructured', 'none_found', NULL, 'MUSC448N.', NULL, NULL, NULL, NULL, NULL),
    ('MUSC460', 'Tonal Counterpoint I', 3, 3, 'A course in Eighteenth-Century contrapuntal techniques, analysis and original composition of two-voice dances, preludes, and inventions. Includes an introduction to the study of fugue and canon.', 'MUSC251; or permission of ARHU-School of Music department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/musc/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('MUSC461', 'Theory and Analysis of Atonal and Twelve-tone Music', 3, 3, 'An advanced technical introduction to theory and analysis of atonal and twelve-tone music, with an emphasis on music by Schoenberg, Webern, Bartok, and Stravinsky.', 'MUSC251 and MUSC450; and permission of ARHU-School of Music department.', NULL, FALSE, NULL, 'Must be in Music Theory and Composition program. Jointly offered with MUSC661.', 'MUSC46 1 or MUSC661.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/musc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('MUSC463', 'Technology and a Career in Music', 3, 3, 'A hands-on introduction to technology as it applies to music creation and recording. Digital audio workstations, music notation software, and cloud-based music technology are used to create and manipulate musical examples with an eye toward their practical applications for professional musicians.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/musc/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, 'Ability to read music on a grand staff (treble and bass clef).', 'No previous experience with technology is required.'),
    ('MUSC464', 'The Theories of Heinrich Schenker', 3, 3, 'An advanced analysis course in tonal music with specific emphasis on the theories of the early 20th century theorist Heinrich Schenker. Specific analyses of music by Bach, Mozart, Haydn, Beethoven, Chopin, and Brahms.', 'MUSC251 and MUSC450; and permission of ARHU-School of Music department.', NULL, FALSE, NULL, 'Must not have completed MUSC651.', 'MUSC464 or MUSC651.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/musc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('MUSC467', 'Piano Pedagogy I', 3, 3, 'A study of major pedagogical treatises in music, and an evaluation of pedagogical techniques, materials, and procedures.', 'Permission of ARHU-School of Music department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/musc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
