    ('PERS251', 'Modern Iran', 3, 3, 'General sociopolitical introduction to modern Iran from establishment of the Qajar dynasty in the late 18th century to the present day. Taught in English.', NULL, NULL, TRUE, 'DSHS', NULL, 'PERS251 or HIST219X.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/pers/', 'none', 'verified', '202601', NULL, 'HIST219X.', NULL, NULL, NULL, NULL),
    ('PERS252', 'Gender and Body in Iran', 3, 3, 'Multidisciplinary approach to key topics concerning gender and body in Iran, to include insights from religion, history, sociology, anthropology, disability studies, travel literature, arts, and fashion. Taught in English.', NULL, NULL, TRUE, NULL, NULL, 'WMST298J, or PERS252.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/pers/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PERS269', 'Special Topics in Study Abroad II', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/pers/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('PERS280', 'Art Activism in Iran', 3, 3, 'Explores Iranian artists'' intent and hope for change and their critical and playful strategies of making a difference through their visual or performing arts created since 1980. While exploring key concepts, contexts, and debates by examining a variety of artworks, we explore diverse and unique transgressive stories, strategies, and styles that these works present to address themes of social justice through the art. We examine how multimedia art forms (dance, theatre, cinema, painting, digital art, and music) empower Iranian artists to practice their identity and exercise their agency as these aspects intersect with race, ethnicity, class, sexuality, ability, and education in a shifting and multilayered context.', NULL, NULL, TRUE, 'DSHU', NULL, 'ARTH389O or PERS280.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/pers/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('PERS283', 'Iranian Cinema', 3, 3, 'Introduction to Iranian cinema, society, and culture. Taught in English.', NULL, NULL, TRUE, 'DSHU', NULL, 'PERS283, CINE283 or FILM298B.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/pers/', 'none', 'verified', '202508', NULL, 'CINE283.', NULL, NULL, NULL, NULL),
