    ('PERS306', 'Intensive Advanced Persian II', 6, 6, 'Continued development of Persian language proficiency at an Advanced Mid level on ACTFL scale through a whole language approach integrating listening, speaking, reading and writing. Taught in Persian.', 'PERS305; or equivalent as determined by World Language Placement (WLP).', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/pers/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PERS311', 'Persian Media', 3, 3, 'Examines issues, values, institutions of the contemporary Persian and Persianete world, primarily through analysis and discussion of current events as reported in the written and audiovisual press. Focus will be on increasing content knowledge as well as linguistic competency in Persian. Taught in Persian.', 'PERS301; or permission of ARHU-School of Languages, Literatures, and Cultures department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/pers/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PERS312', 'Contemporary Iranian Culture', 3, 3, 'Study of the culture of contemporary Iran (post-evolution) with focus on the contemporary social, political, literary and artistic life in Iran. Taught in Persian.', 'PERS301; or students who have taken courses with comparable content may contact the department.', NULL, FALSE, NULL, 'Must not be native/fluent speaker of Persian.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/pers/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PERS353', 'Iranian Life in Literature and Film', 3, 3, 'Treats major themes in modern literature and life of Iranians. Topics examined include Iranian identity, religious traditions, modern life, and expatriate communities. Taught in English.', NULL, NULL, TRUE, 'DSHU', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/pers/', 'none', 'verified', '202508', NULL, NULL, NULL, NULL, NULL, NULL),
    ('PERS369', 'Special Topics in Study Abroad III', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/pers/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('PERS371', 'Introduction to Persian Literature in Translation', 3, 3, 'Introduction to classical and modern canons of Persian literature in historical, esthetic, and social context. Taught in English.', NULL, NULL, TRUE, 'DSHU', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/pers/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('PERS385', 'Theatre and Dance in Iran and Afghanistan', 3, 3, 'Students will learn about stories, plays, and movements in Iran and Afghanistan from past to present. Through watching performances, readings, and discussions, we explore the relationship between storytelling, body, space, and power in forming and performing identity and life experiences. Looking at case studies from traditional, popular, and western style dance and theater are an exciting part of the course. Note: This course requires no prior knowledge of Persian culture or dance and theatre studies on the part of the students.', NULL, NULL, TRUE, 'DSHU', NULL, 'TDPS358A, THET328W, PERS398A, or PERS385.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/pers/', 'none', 'verified', '202601', 'PERS398A.', 'TDPS358A, THET328W.', NULL, '3 credits if content differs.', NULL, NULL),
    ('PERS386', 'Experiential Learning', 3, 6, 'Pre-professional experience in research, analysis and writing in a work setting. Project proposal approved by faculty and internship sponsor.', NULL, NULL, TRUE, NULL, 'Permission of ARHU-School of Languages, Literatures, and Cultures department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/pers/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
