    ('PORT203', 'Intensive Intermediate Portuguese', 4, 4, 'Covers speaking, reading, writing, listening, and culture of Portuguese-speaking world.', 'PORT103; or must have appropriate World Language Placement (WLP) score.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PORT205', 'Intermediate Reading and Conversation in Portuguese I', 3, 3, 'Development of spoken Portuguese at intermediate level based on written assignments and exams on readings in a variety of genres.', 'PORT203; or permission of ARHU-School of Languages, Literatures, and Cultures department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PORT207', 'Intermediate Reading and Conversation in Portuguese II', 3, 3, 'Advanced practice of oral and written Portuguese. Reading and discussions of texts, review of grammar, and vocabulary practice.', 'PORT205; or students who have taken courses with comparable content may contact the department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PORT222', 'Cannibals, Savages and Carnivalization: The Making of Brazilian National Culture', 3, 3, 'Introduction to the main concepts, cultural movements, and ideas that have shaped Brazilian modern culture. Exploring some of the ways in which cultural cannibalism, savagery, and carnivalization have been deployed as symbolic frameworks in the construction of a national identity through analyses of film, literature, music and visual arts. Taught in English.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PORT228', 'Selected Topics in Latin American Literature and Society', 3, 6, 'Variable cultural studies topics on literature and society in contemporary Latin America. Taught in English.', NULL, NULL, TRUE, NULL, NULL, 'PORT228 or SPAN228.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'none', 'none_found', NULL, NULL, 'SPAN228.', NULL, '6 credits if content differs.', NULL, NULL),
    ('PORT229', 'Selected Topics in Latin American Culture', 1, 3, 'Varied topics in Latin America culture.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'none', 'none_found', NULL, NULL, NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('PORT230', 'Brazilian Portuguese through Film', 3, 3, 'Intermediate practice of oral and written Portuguese through discussion of Brazilian movies, along with grammar review and vocabulary exercises. Taught in Portuguese.', 'PORT205; or permission of ARHU-School of Languages, Literatures, and Cultures department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PORT234', 'Issues in Latin American and Caribbean Studies I', 3, 3, 'Interdisciplinary study of major issues in Latin America and the Caribbean, including Latin America''s cultural mosaic, migration and urbanization. Democratization and the role of religions. Taught in English.', NULL, NULL, TRUE, 'DSHS or DSHU, DVUP', NULL, 'LASC234, PORT234, SPAN234, or LACS234.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'none', 'verified', '202508', 'LASC234.', 'LACS234, SPAN234.', NULL, NULL, NULL, NULL),
    ('PORT235', 'Issues in Latin American and Caribbean Studies II', 3, 3, 'Major issues shaping Latin American and Caribbean societies including the changing constructions of race, ethnicity, gender and class as well as expressions of popular cultures and revolutionary practices. Taught in English.', NULL, NULL, TRUE, 'DSHS or DSHU, DVUP', NULL, 'LASC235, PORT235, SPAN235, or LACS235.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'none', 'verified', '202601', 'LASC235.', 'LACS235, SPAN235.', NULL, NULL, NULL, NULL),
    ('PORT269', 'Special Topics in Study Abroad II', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('PORT320', 'Survey of Portuguese Literature', 3, 3, 'Portuguese poetry, fiction and drama from the Twelfth Century to the present. Taught in English.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PORT332', 'Brazilian Cinema', 3, 3, 'Brazilian films from the late 1950s to the present with a special view to the relationship between cinema, society, historical dates, and social changes in Brazil. Taught in English.', NULL, NULL, TRUE, 'DSHU', NULL, 'PORT332 or CINE332.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'none', 'verified', '202608', NULL, 'CINE332.', NULL, NULL, NULL, NULL),
    ('PORT369', 'Special Topics in Study Abroad III', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('PORT386', 'Experiential Learning', 3, 6, '', NULL, NULL, TRUE, NULL, 'Permission of ARHU-School of Languages, Literatures, and Cultures department; and junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PORT388', 'Special Topics in Brazilian Studies', 3, 3, 'Exposes students to textual, visual and aural products to explore how Brazil has been shaped from within and abroad. Focuses on the broad meaning and impact on Brazilian culture and social formation. Taught in English.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('PORT399', 'Independent Study in Portuguese', 1, 3, 'Specific readings in literature under the supervision of a faculty member of the department.', 'Permission of ARHU-School of Languages, Literatures, and Cultures department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, '3 credits.', NULL, NULL),
    ('PORT405', 'Portuguese for Spanish Speakers', 3, 3, 'Intensive basic grammar, reading and auditory comprehension. Native or acquired fluency in Spanish required.', NULL, NULL, TRUE, NULL, 'Must have native or acquired fluency in Spanish.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PORT408', 'Special Topics in Portuguese Literature', 3, 3, 'Major themes and literary developments from the late 18th century to the present.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('PORT409', 'Special Topics in Brazilian Literature', 3, 6, 'Major themes and literary development from the late eighteenth century to the present. Specific topic to be announced each time the course is offered.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PORT410', 'Tropical Dreams: Nature and Art in Brazil', 3, 3, 'Ideas, images, and representations of the tropics have historically portrayed them as exotic, lush, underdeveloped, and resource-rich places. This course interrogates how concepts of tropicality and nature have influenced the culture, politics, and society of a particular country: Brazil. We examine how nature, a key concept in tropicality, has been represented and understood in different terms throughout history and how these representations have informed environmental discourses and attitudes. Furthermore, we critically analyze how racialized notions of the tropics that shaped structures of oppression have been constructed, perpetuated, and contested. Our objects of analysis will consist of artistic depictions of the tropical world in addition to films, music, literature, and critical thought.', NULL, NULL, TRUE, 'DSHU', NULL, 'PORT409A, SPAN609A, LACS448Y, or PORT410.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'none', 'verified', '202601', 'PORT409A.', NULL, NULL, NULL, NULL, NULL),
    ('PORT478', 'Themes and Movements of Luso-Brazilian Literature in Translation', 3, 3, 'A study of specific themes and movements either in Portuguese or Brazilian literature, as announced. Designed for students for whom the literatures would be inaccessible in Portuguese.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('PORT480', 'Machado de Assis', 3, 3, 'Fiction of Machado de Assis covering his romantic and realistic periods.', 'Permission of ARHU-School of Languages, Literatures, and Cultures department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/port/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSIT310', 'Fundamentals of Translation', 3, 3, 'Students will develop a systematic, reflective approach to translation involving both the written and spoken word. The course provides an overview of domains of translation, associated text categories, and translation tasks.', NULL, NULL, TRUE, NULL, 'Must be in the Public Service Interpreting and Translation major.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psit/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSIT320', 'Fundamentals of Interpreting', 3, 3, 'Students will develop a systematic, reflective approach to interpreting in real-world settings and gain an understanding of the use of different modes of interpreting under professional working conditions. This course also provides an overview of interpreting skills, with exercises to develop them, including focus on active listening and analysis, effective use of memory, and delivery of the target message. Interpreting strategies and techniques in both dialogue and formal consecutive settings are discussed in a range of interpreting domains and practiced in the context of real-world exercises, enabling students to develop strategies to identify, analyze, and resolve difficulties and challenges in professional practice contexts.', NULL, NULL, TRUE, NULL, 'Must be in the Public Service Interpreting and Translation major.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psit/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSIT388', 'Public Service Interpreting and Translation Practicum', 3, 3, 'Designed to help guide students in the pursuit of experiences to practice their skills in workplace settings through internships, volunteering, and practice sessions.', 'Minimum grade of C- in PSIT310 and PSIT320.', NULL, TRUE, NULL, 'Must be in the Public Service Interpreting and Translation major.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psit/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, '6 credits.', NULL, NULL),
    ('PSIT410', 'Public Service Translation', 3, 3, 'In this course, students will advance their skills in public service translation across a diversity of work areas and settings. They will be introduced to a variety of text types strengthening the skills introduced in Fundamentals of Translation. Students will also expand their command of technical vocabulary across two or more languages in the contexts of education, local and state government, health care, and legal services.', 'Minimum grade of C- in PSIT310.', NULL, TRUE, NULL, 'Must be in the Public Service Interpreting and Translation major.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psit/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSIT420', 'Public Service Interpreting', 3, 3, 'Students will advance their skills in consecutive interpreting across a diversity of public service settings. Simultaneous interpreting skills will be introduced. This course will strengthen the skills introduced in Fundamentals of Interpreting.', 'Minimum grade of C- in PSIT320.', NULL, TRUE, NULL, 'Must be in the Public Service Interpreting and Translation major.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psit/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC100', 'Introduction to Psychology', 3, 3, 'A basic introductory course intended to bring the student into contact with the major problems confronting psychology and the more important attempts at their solution.', NULL, NULL, TRUE, 'DSHS or DSNS', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC123', 'The Psychology of Getting Hired', 1, 1, 'Designed to introduce students to the science behind the hiring process and to prepare individuals with the academic and practical training required. Together we will explore psychological principles that influence the selection process and how individuals can apply them for the competitive edge that makes others Fear the Turtle!', NULL, NULL, TRUE, NULL, 'Must not be in a Robert H. Smith School of Business degree program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'Cannot be used in place of BMGT367 toward a degree program in the Robert H. Smith School of Business.'),
    ('PSYC138', 'Special Topics in Study Abroad I', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('PSYC200', 'Statistical Methods in Psychology', 3, 3, 'A basic introduction to quantitative methods used in psychological research.', 'PSYC100; and 1 course with a minimum grade of C- from (MATH120, MATH136, or MATH140).', NULL, TRUE, 'FSAR', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC202', 'Introduction to Neuroscience', 3, 3, 'In an evolutionary sense, the job of the nervous system is to produce, control, and coordinate behaviors that help an animal survive and reproduce. Neuroscience is the study of how the nervous system does that. Provides a broad introduction to neuroscience, always keeping the behavioral consequences in view.', 'Minimum grade of C- in BSCI170.', NULL, TRUE, 'DSNS', NULL, 'PSYC309U, NEUR200, PSYC202 or PSYC301.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'verified', '202605', 'PSYC309U.', 'NEUR200.', NULL, NULL, NULL, NULL),
    ('PSYC210', 'Personality and Temperament: Developmental Origins, Brain Bases, and Clinical Implications', 3, 3, 'What is known about what makes each of us unique? How do these differences contribute to enduring differences in health & wealth? We will review recent research in humans and non-humans aimed at understanding the psychological & biological mechanisms underlying stable individual differences in personality. We will discuss the phylogenetic and ontogenetic origins of temperament, measurement issues, fundamental dimensions of personality across the lifespan, neurobiological substrates of temperament/personality, mechanisms contributing to stability and change, implications for psychopathology, & broader implications for public/macroeconomic policy.', 'PSYC100.', NULL, TRUE, NULL, 'Must be in Psychology program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC221', 'Social Psychology', 3, 3, 'The influence of social factors on the individual and on interpersonal behavior. Includes topics such as conformity, attitude change, personal perception, interpersonal attraction, and group behavior.', 'PSYC100.', NULL, TRUE, 'DSHS or DSSP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC232', 'Psychology of Racism', 3, 3, 'Explores the causes, correlates, and consequences of racial prejudice in the United States and other national contexts. Using lecture, readings, and discussion, we will examine the psychological theory and research on what processes underlie and motivate racial prejudice; how racial prejudice is experienced by its targets; how racial prejudice pervades our culture and social institutions; and how racial prejudice is learned, maintained, and ultimately changed.', NULL, NULL, TRUE, NULL, 'Limited to Psychology majors; if spaces remain in the course, will open to all majors.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC234', 'Living the Good Life: The Psychology of Happiness', 3, 3, 'What are the secrets to living a happy life? Can happiness be found within the context of war, a depressed economy, violence and other major stressors? Are some people born happier than others? This course will teach you the scientific process that psychologists use to study happiness (and related emotional variables) and give you the opportunity to practice applying that process in a number of ways. You will learn how we (a) gather and critically evaluate research findings in the existing literature, (b) integrate those findings into coherent and testable theories, (c) design and conduct valid scientific research that tests those theories and extends our knowledge, and (d) effectively communicate our theories and findings to a wide range of audiences. The result of the process is a more accurate and objective understanding of happiness, and that is what prepares you to apply your scientific understanding to explain and influence a wide range of outcomes.', NULL, NULL, TRUE, 'DSHS, SCIS', NULL, 'PSYC234 or PSYC289D.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'none', 'verified', '202608', 'PSYC289D.', NULL, NULL, NULL, NULL, NULL),
    ('PSYC237', 'Psychology of Evil', 3, 3, 'Why is there evil in the world? Are some born evil, or do social, environmental and cultural forces create evil? What makes otherwise good people do evil things? The scientific study of evil epitomizes the fundamental challenge that psychology faces in dissecting the role of biology (nature) and the social context (nurture).', NULL, NULL, TRUE, 'DSHS or DSSP, SCIS', NULL, 'PSYC237 or PSYC289E.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'none', 'verified', '202605', 'PSYC289E.', NULL, NULL, NULL, NULL, NULL),
    ('PSYC238', 'Special Topics in Study Abroad II', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('PSYC262', 'Asian American Psychology', 3, 3, 'An overview of how socio-cultural influences impact the development and psychological health of Asian Americans. Other topics include how minority group status, adaptation and identity development influence various aspects of psychological functioning; the role of historic systematic racism; and, how the COVID-19 pandemic has negatively impacted Asian Americans. Students develop a deeper understanding of the role of stereotypes and racism, acculturation, racial identity development, cultural values, gender socialization, behavioral norms, family roles, stressors and social support systems on the mental health, well-being and health of Asian Americans.', NULL, NULL, TRUE, NULL, NULL, 'PSYC262, AAST262 or PSYC489Z.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'none', 'none_found', NULL, 'PSYC489Z.', 'AAST262.', NULL, NULL, NULL, NULL),
    ('PSYC300', 'Research Methods in Psychology Laboratory', 4, 4, 'A general introduction and overview to the fundamental theoretical, conceptual, and practical issues in psychological research in both the laboratory and the field.', 'PSYC200.', NULL, TRUE, 'DSSP', 'Must be in Psychology program or Social Data Science - Psychology Track.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC302', 'Fundamentals of Learning and Behavior', 3, 3, 'Overview of the fundamental types of learning that occur without formal instruction. The course covers fundamentals of classical and instrumental conditioning as studied in a variety of species in addition to more modern theories of learning. We will then explore how these principles influence diverse processes such as memory, attention, extinction, categorization, motivation, and in some cases, how they are implemented in the brain and disrupted in disease.', 'PSYC100 and BSCI170.', NULL, TRUE, NULL, 'Restricted to psychology majors during the registration period; all other majors will be placed on a hold file.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC303', 'Professional Development for Psychology Majors', 1, 1, 'An investigation of various career and graduate school opportunities available to psychology majors. Students will learn about a wide range of career fields, will learn how to utilize available resources to pursue career goals, and will take steps to advance their professional identity and development.', 'PSYC123; or permission from the instructor with a completed resume.', NULL, FALSE, NULL, 'Must have earned a minimum of 60 credits; and must be in the Psychology major.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'partial', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC304', 'Biological Psychology', 3, 3, 'Biological Psychology is the study of the physiological basis of behavior. In this course, we will first cover the basic principles of brain organization and neural transmission. We will then introduce traditional and modern research techniques in the field of behavioral neuroscience. The last portion of the course focuses on specific topics including psychopharmacology, learning and memory, emotion, stress, drug of abuse, neurological disorders (e.g., Alzheimer''s disease and Parkinson''s disease) and schizophrenia.', 'PSYC100 and BSCI170.', NULL, TRUE, 'DSNS', NULL, 'PSYC301 or PSYC304.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'verified', '202608', 'PSYC301.', NULL, NULL, NULL, NULL, NULL),
    ('PSYC307', 'Collective Behavior and Decision Making in Human and Animal Groups', 3, 3, 'Overview of the fundamental principles underlying the organization of animal societies, mathematical models describing these phenomena, and applications to human societies and decision-making. Students will engage in discussions of case studies, analyze and evaluate mathematical simulations, and apply what they have learned from animal groups to practice solving problems currently facing human society.', 'NEUR200, PSYC304 or PSYC221.', NULL, TRUE, NULL, NULL, 'PSYC207 or PSYC307.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, 'PSYC207.', NULL, NULL, NULL, 'PSYC200 or equivalent statistics course.', NULL),
    ('PSYC309', 'Special Topics in Psychology', 1, 3, 'Topics of current interest which represent extensions of or additions to topics covered in more general topical courses.', 'PSYC100.', NULL, TRUE, NULL, 'Must be in Psychology program; and sophomore standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('PSYC310', 'Perception', 3, 3, 'A survey of phenomena and theories of perception including psychological, anatomical, physiological, and environmental factors important in determining how we perceive the world. Historical background will be examined as well as contemporary research.', 'PSYC100 and BSCI170.', NULL, TRUE, NULL, 'Must be in the Psychology major, Neuroscience major, or Social Data Science major (Psychology track).', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC330', 'Child Psychopathology', 3, 3, 'Etiology, diagnosis, prevention and treatment of emotional disorders of childhood and adolescence.', 'PSYC100.', NULL, TRUE, NULL, 'Must be in Psychology program or Social Data Science - Psychology Track.', 'PSYC309B or PSYC330.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, 'PSYC309B.', NULL, NULL, NULL, NULL, NULL),
    ('PSYC332', 'Psychology of Human Sexuality', 3, 3, 'A survey of historical and contemporary psychological views on a wide variety of sexual behaviors; theory and research bearing on the relationship between life span psychological development, psychological functioning, interpersonal processes and sexual behaviors; political and social issues involved in current sexual norms and practices.', 'PSYC100.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC334', 'Psychology of Interpersonal Relationships', 3, 3, 'Research, theory and their practical applications pertaining to the development, maintenance and dissolution of human relationships. Processes critical to successful relating (e.g., communication, bargaining, conflict resolution), and issues associated with troubled dyadic relations with equal partners (e.g., jealousy, spouse abuse, divorce).', 'PSYC100.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC336', 'Psychology of Women', 3, 3, 'A study of the biology, life span development, socialization, personality, mental health, and special issues of women.', 'PSYC100.', NULL, TRUE, 'DSHS', NULL, 'PSYC336, WMST336 or WGSS 336.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'verified', '202608', 'WMST336.', 'WGSS336.', NULL, NULL, NULL, NULL),
    ('PSYC338', 'Special Topics in Study Abroad III', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('PSYC341', 'Introduction to Memory and Cognition', 3, 3, 'An introduction to the basic concepts of cognitive psychology, the scientific study of mental processes. Topics will include perception, attention, memory, reasoning, and language, with an emphasis on how findings from cognitive psychology can inform real-life thinking (e.g., memory strategies for studying, pitfalls of multitasking, and how/why our memories can fail us).', 'PSYC200 and PSYC300.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC344', 'Health Psychology', 3, 3, 'An examination of how psychological, biological, and social factors impact physical health and well-being. Students will use the biopsychosocial model to analyze topics including stress, health disparities, pain, addiction, disease states (e.g., cardiovascular disease, diabetes, cancer), and primary prevention.', 'PSYC100; or permission of instructor.', NULL, FALSE, NULL, 'Must be in the Psychology program; or must be in a major within the School of Public Health; or permission of instructor.', 'PSYC489U or PSYC344.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'partial', 'none_found', NULL, 'PSYC489U.', NULL, NULL, NULL, NULL, NULL),
    ('PSYC346', 'Death, Dying and Grieving: What Future Healthcare Professionals Need to Know', 3, 3, 'What do future healthcare professionals need to know about death dying and grieving? Theories and research related to death, dying and grieving, interventions with the dying and grieving, and communication about end-of-life issues in healthcare settings will be examined. Topics include trajectories of common illnesses, palliative and hospice care, ethical and multicultural issues, suicide, models of grieving, post-traumatic growth, and self-reflection regarding values, biases, and beliefs regarding death. This class will prepare students for careers as psychologists, physicians, nurses, or social workers as they will obtain foundational knowledge, engage in self-reflection, and practice communication skills that can be used with future clients or patients who are dying or grieving the dying/death of a loved one.', 'PSYC100.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC353', 'Adult Psychopathology', 3, 3, 'The nature, diagnosis, etiology, and treatment of mental disorders.', 'PSYC100.', NULL, TRUE, NULL, 'Must be in Psychology program or Social Data Science - Psychology Track.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC354', 'Multicultural Psychology in the U.S.', 3, 3, 'What are the psychological implications of racism, sexism, homophobia and other structures of inequality in the United States? How do socio-cultural privilege and oppression influence individual and group thoughts, feelings, and behaviors? This course will take a current events focus to understanding multicultural and social justice issues in psychology with an emphasis on self-reflection, mental health, cross-cultural communication, and strategies for social change.', 'PSYC100.', NULL, TRUE, 'DSHS', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC355', 'Developmental Psychology', 3, 3, 'Survey of research and theory of psychological development from conception through childhood, stressing physiological, conceptual and behavioral changes, and the social and biological context in which individuals develop.', 'PSYC100.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC361', 'Survey of Industrial and Organizational Psychology', 3, 3, 'A general survey of the field of industrial organizational psychology including such topics as organizational entry (recruitment, selection, training, socialization); organizational psychology (motivation, leadership, job attitudes); productivity in the workplace (performance appraisal, absenteeism, turnover), and the role that the larger environment plays in influencing work behaviors and work attitudes.', 'PSYC100.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC362', 'Introduction to Negotiation', 3, 3, 'Overview of the field of negotiation and the social-psychological and contextual factors that facilitate and inhibit successful negotiation agreements. Students will engage in a variety of negotiation exercises individually and as a team.', NULL, NULL, TRUE, NULL, 'Must be in Psychology program or Social Data Science - Psychology Track.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC381', 'Community Interventions: Domestic Violence I', 3, 3, 'Study theories and research related to the dynamics and effects of intimate partner violence on women and children. Learn about community resources and interventions for survivors of domestic violence. Examine theoretical writings and research findings regarding the effects of gender, culture, race/ethnicity, and socioeconomic status on the experiences of intimate partner violence survivors and their children.', 'PSYC100.', NULL, TRUE, NULL, 'Preference given to majors in Human Development, Psychology, and Women, Gender and Sexuality Studies.', 'PSYC318D, PSYC381, WMST498A or WGSS498A.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, 'PSYC318D.', NULL, NULL, NULL, NULL, 'Students who successfully complete this course may be eligible to enroll in PSYC319 - a service learning class in which students volunteer in the community to work with children who have experienced domestic violence and/or homelessness.'),
    ('PSYC389', 'Experiential Learning', 1, 6, 'Internship in psychology-related fields.', 'PSYC100; and permission of BSOS-Psychology department; and 9 credits in PSYC courses.', NULL, FALSE, NULL, 'Minimum cumulative GPA of 2.8; and must have earned a minimum 3.0 Psychology GPA.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, '9 credits.', NULL, NULL),
    ('PSYC391', 'Community Interventions: Domestic Violence II - Service Learning', 3, 3, 'Apply knowledge gained in PSYC318D/PSYC318 to provide interventions to individuals who have experienced domestic violence. Critical analysis of interventions and related research. Ethical and cultural considerations in the provision of services are addressed.', 'PSYC381 or PSYC318D.', NULL, FALSE, NULL, 'Preference given to majors in Psychology; Women, Gender, and Sexuality Studies; and Human Development; and permission of BSOS-Psychology department.', 'PSYC319D or PSYC391.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'unstructured', 'none_found', NULL, 'PSYC319D.', NULL, NULL, NULL, NULL, NULL),
    ('PSYC401', 'Biological Bases of Behavior Laboratory', 4, 4, 'Students will study some of the key concepts in neuroscience by combining behavioral experiments with electrode recordings from neurons controlling the behaviors. We will intensively examine concepts like creation of rhythmic behaviors (walking, flight), neurotransmitters'' control of aggression, drug effects on synaptic activity, high-speed neural circuits for effective escape from predators, and CNS maps in the visual system for directing prey capture. Students will learn microsurgery and a broad range of neural recording techniques. We work with animals (invertebrates, cold-blooded vertebrates) every week. A strong biology background will be beneficial.', 'PSYC300; and (PSYC202, NEUR200, or BSCI353).', NULL, TRUE, NULL, 'Permission of instructor; and must be in Psychology program; and must have earned a minimum of 85 credits.', 'PSYC401, NEUR405, BSCI455 or BSCI454.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC403', 'Animal Behavior', 3, 3, 'Reviews the theoretical framework underlying the study of animal behavior. The genetic, hormonal and physiological basis of behavior, and the relation to ecological and evolutionary processes will be discussed using examples that range from invertebrate animals to humans.', 'PSYC202 or NEUR200.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC404', 'Introduction to Behavioral Pharmacology', 3, 3, 'Theoretical viewpoints on the interaction of drugs and behavior. Basic principles of pharmacology, the effects of drugs on various behaviors, experimental analysis of drug dependence and abuse, and neuropharmacology and behavior.', 'PSYC202 or NEUR200.', NULL, TRUE, NULL, 'Must be in Psychology program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC406', 'Neuroethology', 3, 3, 'A merger between the disciplines of neuroscience and ethology (animal behavior) studies the behavioral functions of nervous systems using a comparative and evolutionary approach. Students will learn how the nervous system controls behavioral patterns in a variety of different organisms ranging from insects to mammals.', 'PSYC301, PSYC202 or NEUR200.', NULL, FALSE, NULL, 'Must be in Psychology program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC407', 'Behavioral Neurobiology Laboratory', 4, 4, 'In this lab course, you will collect behavioral and physiological data in humans using classic behavioral paradigms, design models of neural circuits that can explain those behaviors, record neural activity from the roach, and write lab reports describing your results and how they relate to patients with psychiatric illnesses.', 'PSYC300; and (PSYC202 or NEUR200).', NULL, TRUE, NULL, 'Must be in Psychology program; and must have earned a minimum of 85 credits.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC409', 'Topics in Neurosciences Seminar', 1, 1, 'Current research in neurosciences will be presented, read, and discussed. Emphasis will change each term.', NULL, NULL, TRUE, NULL, 'Permission of BSOS-Psychology department; and junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'none', 'none_found', NULL, NULL, NULL, NULL, '4 credits if content differs.', NULL, NULL),
    ('PSYC411', 'Introduction to Functional Magnetic Resonance Imaging', 3, 3, 'An introduction to functional magnetic resonance imaging (fMRI). Students will be taught about formulating testable hypotheses with fMRI, utilizing basic methods in fMRI studies, and understanding existing limitations of fMRI studies in the literature.', 'PSYC200 and PSYC300; and (PSYC202 or NEUR200).', NULL, TRUE, NULL, 'Must be in the Psychology major or Neuroscience major.', 'NACS728F or PSYC411.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC414', 'Science of Sleep and Biological Rhythms', 3, 3, 'Sleep is a powerful, inescapable, misunderstood, and mysterious presence in our lives. The course will begin with a review of the basics of sleep and biological rhythms with a focus on the underlying neurobiology. The bulk of the semester will be in-depth discussions of topics in sleep and circadian rhythms primarily chosen by the students. A few examples: narcolepsy, sleep in primitive cultures, lucid dreaming, racial and cultural differences in sleep and sleep disorders, the biology of sleep and circadian rhythms during adolescence, CNS control of dreaming, sleep and states of consciousness, sleeping to remember vs. sleeping to forget, legal ramifications of parasomnias, e.g. sleepwalking, and the relationships between sleep deprivation and obesity.', 'PSYC301, PSYC202, or NEUR200; or permission of instructor.', NULL, FALSE, NULL, 'Must be in a major within the BSOS-Psychology department; and restricted to psychology majors during the registration period.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC417', 'Data Science for Psychology and Neuroscience Majors', 4, 4, 'A large number of industry and academic jobs require basic programming and data analysis skills. This class represents an introduction to both. Students will learn to program in R and will briefly be introduced to Python, the two most popular programming languages for data science. Common constructs shared by a variety of procedural programming languages will be emphasized. Basic statistics and probability theory will be reviewed from a computational perspective, and more advanced topics introduced. During the course, students will simulate toy data sets which they will then analyze knowing how the data came about, as well as work with real data. The class is highly hands-on with a large number of in-class lab and homework projects. Expect to work a lot and move quickly. Because of the hands-on nature of the class, the overall focus is more on application and execution rather than theory. However, some theory is covered at a high level so that students are aware of why they are doing something, rather than mindlessly writing code.', 'PSYC200 and PSYC300; and (MATH120, MATH130, or MATH140).', NULL, FALSE, NULL, NULL, 'PSYC489D or PSYC417.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'unstructured', 'none_found', NULL, 'PSYC489D.', NULL, NULL, NULL, NULL, NULL),
    ('PSYC420', 'Experimental Psychology: Social Psychology Laboratory', 4, 4, 'A laboratory course to provide a basic understanding of experimental methods in social psychology and experience in conducting research on social processes.', 'PSYC300 and PSYC221.', NULL, TRUE, NULL, 'Must be in Psychology program or Social Data Science - Psychology Track; and must have earned a minimum of 85 credits.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC424', 'Communication and Persuasion', 3, 3, 'Effect of social communication upon behavior and attitudes. Theory and research concerning attitude change and social influence.', 'PSYC221 and PSYC200.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC425', 'Psychology and Law', 3, 3, 'An introduction to the intersection of psychology and the criminal justice system, known as the field of legal psychology. The material covered will span the course of the criminal justice process and examine each aspect from a psychological perspective beginning with profiling and moving on to eyewitness memory and judgements through perpetrator memories and interrogation techniques. These aspects will be evaluated with a research lens as well as an applied outlook.', 'PSYC100, PSYC200, and PSYC300.', NULL, TRUE, NULL, 'Must be in Psychology program or Social Data Science - Psychology Track.', 'PSYC325 or PSYC425.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC426', 'Psychology of Adolescents'' Close Relationships: Parents, Peers, and Romantic Partners', 3, 3, 'An examination of the development of close relationships during adolescence, including those with parents, peers, and romantic partners. We consider core developmental themes including nature and nurture, stability and change, and individual differences, and discuss theory, research, and clinical applications. Students gain observational skills through discussing extensive video examples of social interactions.', 'PSYC355; or permission of the instructor.', NULL, FALSE, NULL, NULL, 'PSYC426 or PSYC489B.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'partial', 'none_found', NULL, 'PSYC489B.', NULL, NULL, NULL, NULL, NULL),
    ('PSYC431', 'Human and Animal Intelligence', 3, 3, 'The study of intelligence touches upon a broad range of topics from cognition, animal behavior, philosophy, psychology, and linguistics. Through lectures, discussions, and critical evaluation of opposing arguments, we will investigate the construct of intelligence from an evolutionary perspective. An understanding of animal intelligence also has important applications for understanding cognition in general, the design of robotic controls, investigating human health, conserving endangered species, development of artificial intelligence, and assuring animal welfare.', 'PSYC300.', NULL, TRUE, NULL, NULL, 'PSYC431 or PSYC489R.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, 'PSYC489R.', NULL, NULL, NULL, NULL, NULL),
    ('PSYC432', 'Counseling Psychology: Theories, Research, and Practice', 3, 3, 'Analysis of research and intervention strategies developed and used by counseling psychologists. Historical and current trends in content and methodology.', 'PSYC200.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC433', 'Basic Helping Skills: Research and Practice', 4, 4, 'Theories and research regarding effective helping relationships, with a focus on applications to counseling and psychotherapy. Students will practice helping skills with each other and will conduct research projects evaluating their helping skills. Students should be willing to talk about personal issues in class. Attendance in labs is mandatory and contributes to the course grade; thus, students should only enroll in a lab section that they will be able to attend consistently.', 'PSYC300.', NULL, TRUE, NULL, 'Must be in Psychology program; and must have earned a minimum of 85 credits; and must not have completed or be concurrently enrolled in EDCP 310.', 'EDCP210, EDCP310, or PSYC433.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC435', 'Temperament, Personality, and Psychopathology', 3, 3, 'An advanced review of cutting-edge research in humans and animals aimed at understanding the psychological and biological mechanisms underlying stable individual differences in temperament and personality (T&P) and determining their role in adult and child psychopathology, with a major focus on anxiety disorders, depression, and addiction. We will discuss the developmental origins of T&P, measurement issues, fundamental dimensions, heritability, relevance to psychopathology and intervention (treatment and prevention), and broader implications for public policy.', 'PSYC200.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC436', 'Introduction to Clinical Psychology: From Science to Practice', 3, 3, 'Critical analysis of clinical psychology, with particular emphasis on current developments and trends.', 'PSYC300.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC437', 'The Assessment and Treatment of Addictive Behaviors', 3, 3, 'Explores the current research in assessment and treatment of addictive behaviors. Topics may include addictions in the areas of alcohol, drugs, nicotine, gambling, and eating.', 'PSYC100; and 9 credits in PSYC courses.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC438', 'Special Topics in Study Abroad IV', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('PSYC440', 'Experimental Psychology: Cognitive Processes and Legal Applications', 4, 4, 'A survey of the content, models, and methods in cognitive psychology with an emphasis on attention and encoding, recall, recognition, judgment, signal detection theory, and applying cognitive theories to situations in the legal system. Students integrate scientific theories with real-life legal situations. Course topics include research methodology in assessing and addressing cognitive mechanisms and how this understanding may help eyewitness and victim recall and recognition, perpetrator recall, assessing scientific theories of repression, and real life examples.', 'PSYC100, PSYC200, PSYC300 and PSYC341.', NULL, TRUE, NULL, 'Must be in Psychology program or Social Data Science - Psychology Track; and must have earned a minimum of 85 credits.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC442', 'Psychology of Language', 3, 3, 'Introductory survey of the psychology of language, focusing on the cognitive processes that enable us to produce and understand language. Topics include speech perception, speech production, syntactic processing, language development, language disorders, and the brain bases of language.', 'PSYC300 and PSYC341.', NULL, TRUE, NULL, 'Must be in Psychology program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC447', 'Diversity in Organizations', 3, 3, 'Overview and active discussion of issues related to diversity and discrimination in organizations from several different perspectives, including: the person(s) being stigmatized, the person(s) doing the stigmatizing, the bystander(s) witnessing stigmatization of others, and the organization. Course readings address each of these perspectives, along with an introductory unit that outlines key concepts of diversity.', 'PSYC300.', NULL, TRUE, NULL, NULL, 'PSYC489E or PSYC447.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, 'PSYC489E.', NULL, NULL, NULL, NULL, NULL),
    ('PSYC450', 'Applying Psychology to the Workplace: Industrial Organizational Psychology Laboratory', 4, 4, 'In this laboratory course, students use data analytic techniques, along with psychology theories and principles, to solve problems and provide recommendations to mock organizations. Along with learning theories in industrial-organizational psychology and statistical analysis, students will improve personal presentation skills that promote effective communication of information.', 'PSYC300.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC460', 'Psychological Foundations of Personnel Selection and Training', 3, 3, 'An examination of issues and processes involved in the design and evaluation of personnel selection and training programs in a variety of organizational settings: job, person and organizational analysis; organizational choice; development of predictors; evaluation of instructional and training systems; criteria for performance evaluation, promotion and training.', 'PSYC361 and PSYC200.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC464', 'Psychology of Leaders in Work Organizations', 3, 3, 'The psychological assumptions and implications of various theories of management and leadership. Selections and training; development of careers; influence processes; change of managerial behavior; and the impact of the larger environment, nature of product or service, and organization structure on managerial behavior.', 'PSYC200 and PSYC361.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC468', 'Field Experience and Special Assignments in Honors', 1, 3, 'An individual experience arranged by the honors student and his or her supervisor. A proposal submitted to the honors faculty in the semester preceding registration for the course should state the activities anticipated and the method of evaluation.', 'Must have permission of supervisor and honors faculty.', NULL, FALSE, NULL, 'Permission of BSOS-Psychology department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, '6 credits.', NULL, NULL),
    ('PSYC469', 'Honors Thesis Proposal Preparation', 3, 3, 'Development of honors thesis proposal by preliminary research and literature review. Presentation of formal proposal to the thesis committee.', NULL, NULL, TRUE, NULL, 'Permission of BSOS-Psychology department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'none', 'none_found', NULL, NULL, NULL, NULL, '3 credits.', NULL, NULL),
    ('PSYC478', 'Independent Study in Psychology', 1, 3, 'Course credit related to independent study (IS) activity within the Department of Psychology, such as serving as a Teaching Assistant (TA) for a faculty member or graduate student.', NULL, NULL, TRUE, NULL, 'Permission of BSOS-Psychology department; and must have earned a minimum of 9 credits in Psychology; and must have earned a minimum GPA of 3.0 in Psychology; and minimum cumulative GPA of 2.8.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'none', 'none_found', NULL, NULL, NULL, NULL, '12 credits.', NULL, NULL),
    ('PSYC479', 'Special Research Problems in Psychology', 1, 3, 'Course credit related to supervised research activity within the Department of Psychology, such as working as a Research Assistant (RA) for a faculty member or graduate student.', NULL, NULL, TRUE, NULL, 'Permission of BSOS-Psychology department; and must have earned a minimum of 9 credits in Psychology; and must have earned a minimum GPA of 3.0 in Psychology; and minimum cumulative GPA of 2.8.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'none', 'none_found', NULL, NULL, NULL, NULL, '12 credits.', NULL, NULL),
    ('PSYC488', 'Advanced Psychology I (Honors)', 3, 3, 'Seminar covering topics in sensation, perception, learning, and motivation.', 'PSYC200.', NULL, TRUE, NULL, 'Permission of BSOS-Psychology department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('PSYC489', 'Advanced Special Topics in Psychology', 3, 3, 'Treatment of a specialized topic in psychology.', 'PSYC300.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('PSYC498', 'Advanced Psychology II (Honors)', 1, 1, 'Seminar covering topics of current interest in psychology.', 'Permission of BSOS-Psychology department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, '3 credits.', NULL, NULL),
    ('PSYC499', 'Honors Thesis Research', 3, 3, '', 'PSYC469; and must have permission of thesis advisor.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/psyc/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('QMMS251', 'Introduction to Educational Statistics', 3, 3, 'Introduction to statistical reasoning; location and dispersion measures; data analysis; regression and correlation; formation of hypotheses tests.', NULL, NULL, TRUE, NULL, NULL, 'EDMS451, QMMS451 or QMMS251.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/qmms/', 'none', 'none_found', NULL, 'EDMS451 or QMMS451.', NULL, NULL, NULL, NULL, NULL),
    ('QMMS410', 'Classroom Assessment', 3, 3, 'Developing and using classroom assessments, including tests, performance assessments, rating scales, portfolios, observations and oral interactions; basic psychometric statistics; standard setting; grading; communicating assessment information; testing ethics; locating and evaluating measures; program evaluation and classroom research; assessments used for educational policy decisions.', NULL, NULL, TRUE, NULL, 'Junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/qmms/', 'none', 'none_found', NULL, 'EDMS410.', NULL, NULL, NULL, NULL, NULL),
    ('QMMS489', 'Field Experiences in Measurement and Statistics', 1, 4, 'Planned field experience in education-related activities. Credit not to be granted for experiences accrued prior to registration.', NULL, NULL, TRUE, NULL, 'Permission of EDUC-Human Development and Quantitative Methodology department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/qmms/', 'none', 'none_found', NULL, NULL, NULL, NULL, '4 credits.', NULL, NULL),
    ('QMMS498', 'Special Problems in Measurement and Statistics', 1, 3, 'Available only to education majors who have formal plans for individual study of approved problems.', NULL, NULL, TRUE, NULL, 'Permission of EDUC-Human Development and Quantitative Methodology department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/qmms/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits.', NULL, NULL),
    ('RDEV250', 'People, Planet, and Profit: Building Sustainable Places', 3, 3, 'An introduction to the four disciplines represented in the School: architecture and urban design, community planning, historic preservation, and real estate development, that work to create a more sustainable environment for the future to create a more sustainable environment for the future using our interpretation of the quadruple bottom line: socio-cultural, economic, environmental, and design sustainability. Students will be provided with an understanding of the fundamental scholarship and processes of each of these disciplines and examine the intersections between them. Additionally, they will learn by applying the approaches of the four disciplines through a series of field studies.', NULL, NULL, TRUE, 'DSSP', NULL, 'ARCH271 or RDEV250.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rdev/', 'none', 'verified', '202608', NULL, 'ARCH271.', NULL, NULL, NULL, NULL),
    ('RDEV270', 'Tax and Accounting for Real Estate Development', 3, 3, 'An understanding of key tax and accounting principles and how they impact real estate development for students in the minor in real estate development is the purpose of this course. This course is geared for science, arts and humanities students who otherwise in their major would not take an accounting course as part of their major.', NULL, NULL, TRUE, NULL, 'Must be in the Real Estate and the Built Environment Major or the Real Estate Development minor; and must have permission of ARCH-Real Estate Development; and must not be in a major in the Robert H. Smith School of Business; and must not have completed BMGT210, BMGT220, or BMGT221.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rdev/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('RDEV350', 'Real Estate Development: Introduction to Principles, Process, and Practice', 3, 3, 'An introduction to the basic principles of real estate development: How real estate and communities get built and how value is created. The emphasis is on entrepreneurship and an experiential learning approach to the entrepreneurial real estate development process, principles, and practice.', 'RDEV250 or ARCH271.', NULL, TRUE, NULL, 'Must be in the Real Estate and the Built Environment major or the Real Estate Development minor; and permission of ARCH-School of Architecture, Planning, & Preservation.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rdev/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('RDEV410', 'Legal Foundations of Real Estate', 3, 3, 'Provides students with the chance to explore various legal topics related to real estate, including government regulation, rights of property owners, financing real estate purchases, protections for certain classes of people, elements of a real estate contract, title, insurance, taxation, rights of landlords and tenants, premises liability, urban planning, land use regulation, and environmental issues.', 'RDEV250 and RDEV350.', NULL, TRUE, NULL, 'Must be in the Real Estate and the Built Environment major; and permission of ARCH-Real Estate Development; and must have earned a minimum 60 credits.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rdev/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('RDEV415', 'Principles, Process and Politics of Planning for Real Estate Development', 3, 3, 'Designed to introduce and familiarize students with planning and zoning and the associated processes and requirements that impact the real property development process and products. It will look at the roles the community and politics play in shaping the built environment and the development process.', 'RDEV250 and RDEV350.', NULL, TRUE, NULL, 'Must be in the Real Estate and Built Environment major; and permission of ARCH-Real Estate Development; and must have earned a minimum 60 credits.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rdev/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('RDEV440', 'Principles of Urban Design for Real Estate Professionals', 3, 3, 'Introduces students to the design issues associated with development of the basic real property asset classes (office, retail, and residential) and the context driven forces that shape these different development types. Also introduces non-design students to the principles of visual literacy and the capacity of different property to support development in the effort to enhance a community.', 'RDEV250 and RDEV350.', NULL, TRUE, NULL, 'Must be in Real Estate and Built Environment Major; and permission of ARCH-Real Estate Development.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rdev/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('RDEV445', 'Essentials of Architectural Design and Construction Management for Real Estate Professionals', 3, 3, 'Essential terminology, process and substantive knowledge needed by development professionals to effectively move a project through the design and construction process; includes environmental and ethical considerations throughout the process.', NULL, NULL, TRUE, NULL, 'Must be in the Real Estate and the Built Environment major; and permission of ARCH-Real Estate Development.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rdev/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('RDEV450', 'Foundations of Real Estate Finance and Investment', 3, 3, 'Real Estate Finance and Investment addresses how real estate value is established, the fundamental foundations of the time value of money, as well as more real estate specific applications of return on investment, net operating income, the components of a real estate sources and uses statement, sources of real estate equity and debt financing, commonly used debt ratios and equity returns in real estate, as well as concepts of sensitivity analysis and exit strategies.', 'Must have completed RDEV270 or an approved accounting course with a grade of C- or better; and minimum grade of C- in RDEV350.', NULL, FALSE, NULL, 'Must be enrolled in RDEV Minor; and permission of ARCH-School of Architecture, Planning, & Preservation.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rdev/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('RDEV470', 'Real Estate Development Case Studies', 3, 3, 'Real Estate Development Case Studies takes the principles learned in RDEV 250, 350 and 450 and takes an in depth look at a selection of local, national and international case studies in residential, commercial office, retail and hospital and critically analyzes the success and failure, short term and long term of the projects.', 'RDEV450.', NULL, TRUE, NULL, 'Must be in the Real Estate and the Built Environment major or Real Estate Development minor; and permission of ARCH-Real Estate Development.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rdev/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('RDEV473', 'Real Estate Case Study Competition', 3, 3, 'The Colvin Institute of Real Estate Development hosts a case study competition. The Colvin Case Study Challenge is a national intercollegiate real estate case study competition for full or part-time students enrolled in a college or a university real estate program (undergraduate or graduate or a university sanctioned real estate club/organization). The Challenge is to document a recent innovative real estate project within the team''s metropolitan region. Unlike many other case competitions, this is a post-development report and documentation of a recently completed project (or project phase). The Challenge is designed to hone professional skills and reveal the knowledge base and understanding of markets, project valuation, finance, urban design and sustainability, entitlement processes and operational issues. This course prepares students to participate in the competition.', 'RDEV250, RDEV350, and RDEV450.', NULL, TRUE, NULL, 'Must be in the Real Estate and the Built Environment major; and permission of ARCH-Real Estate Development.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rdev/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('RDEV478', 'Special Topics in Real Property Development', 1, 3, 'RDEV 478 will address one or more current topics in real property with a focus in one or more of the areas of real estate development from planning and entitlements, to design and construction, to market analysis and valuation, to finance and investment, to operations and property management, or social and economic impacts.', NULL, NULL, TRUE, NULL, 'Permission of ARCH-School of Architecture, Planning, & Preservation.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rdev/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', 'RDEV250, RDEV350, and RDEV450.', NULL),
    ('RELS120', 'Islamic Civilization', 3, 3, 'Introduction to society and culture in the Middle East since the advent of Islam: as a personal and communal faith; as artistic and literary highlights of intellectual and cultural life; and as the interplay between politics and religion under the major Islamic regimes.', NULL, NULL, TRUE, 'DSHU', NULL, 'HIST120 or RELS120.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'verified', '202608', NULL, 'HIST120.', NULL, NULL, NULL, NULL),
    ('RELS133', 'God Wills It! The Crusades in Medieval and Modern Perspectives', 3, 3, 'An examination of the identities and convictions both of the Western Europeans who participated in the Crusades and of the Easterners (Muslim, Christian, and Jewish) whom they encountered in the Holy Land. Focuses on the era of the first four great Crusades, from about 1095 to 1215. Consideration of the cultural impact of these movements on both Western Europe and the Middle East.', NULL, NULL, TRUE, NULL, NULL, 'HIST133, RELS133 or RELS289D.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'none_found', NULL, 'RELS289D.', 'HIST133.', NULL, NULL, NULL, NULL),
    ('RELS170', 'Ancient Myths and Modern Lives', 3, 3, 'What are myths and why do we tell them? What powers do myths have? We will tackle these questions by looking at the enduring and fascinating myths from ancient Greece and Rome. In addition to studying how they shaped ancient societies, we will also look at their modern influence and reflect upon the power that myths still hold in our contemporary world. Taught in English.', NULL, NULL, TRUE, 'DSHU, SCIS', NULL, 'CLAS170 or RELS170.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'verified', '202608', NULL, 'CLAS170.', NULL, NULL, NULL, 'This course cannot be taken for language credit.'),
    ('RELS171', 'Is Judaism a Religion?', 3, 3, 'Jewish identity can be framed in terms of ethnicity, culture, and religious practice, but also in terms of more contemporary social constructions including social action, political engagement, and intellectual pursuit. In the context of such diverse social and individual frames, what does it mean to identify Judaism as a religion? Attention to Jewish society in historical and global perspective will provide a backdrop for a particular focus on contemporary Jews in the United States and Israel.', NULL, NULL, TRUE, 'DSHU, DVUP, SCIS', NULL, 'JWST171 or RELS171.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'verified', '202608', NULL, 'JWST171.', NULL, NULL, NULL, NULL),
    ('RELS219', 'Special Topics in Religious Studies', 3, 3, 'Special topics in Religious Studies', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'none_found', NULL, NULL, NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('RELS219K', 'Reformers, Radicals, and Revolutionaries: The Middle East in the Twentieth Century', 3, 3, 'The 20th century was a period of dramatic changes in the Middle East. Within the global context of the two World Wars and the Cold War, countries in the region struggled with the effects of colonialism and painful processes of decolonization. The course offers a thematic-comparative approach to issues such as social and political reform, nationalism, the colonial experience, independence struggles, models of governance, political violence, and Islamism. Course lectures and the analysis and discussion of primary sources will lead students to understand that the peoples of the Middle East found answers to the challenges posed by Western dominance based on their specific historical, cultural and socio-economic circumstances.', NULL, NULL, TRUE, 'DSHS', NULL, 'RELS219K or HIST245.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'verified', '202608', NULL, 'HIST245.', NULL, NULL, NULL, NULL),
    ('RELS225', 'Religions of the Ancient Near East', 3, 3, 'Introduction to ancient Near Eastern religious systems and mythology, from the third millennium BCE through the fourth century BCE. Particular emphasis on Mesopotamia and ancient Israel.', NULL, NULL, TRUE, 'DSHU', NULL, 'JWST225, HIST219I, RELS225, or RELS219A.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'verified', '202608', 'RELS219A.', 'HIST219I, JWST225.', NULL, NULL, NULL, NULL),
    ('RELS230', 'Inventing Traditions: The Making of Rabbinic Judaism', 3, 3, 'Introduces the dramatic literary and cultural (as well as political and demographic) innovations that reshaped Judaism in late antiquity. Examines the fundamental works and genres of rabbinic literature and the religious movement that produced them. Special emphasis on the rabbinic uses of "tradition" to enhance authority and legitimacy, and to foster group identity.', NULL, NULL, TRUE, 'DSHS or DSHU, SCIS', NULL, 'HIST281, JWST230, RELS219C or RELS230.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'verified', '202508', 'RELS219C.', 'HIST281, JWST230.', NULL, NULL, NULL, NULL),
    ('RELS236', 'Philosophy of Religion', 3, 3, 'A philosophical study of some of the main problems of religious thought: the nature of religious experience, the justification of religious belief, the conflicting claims of religion and science, and the relation between religion and morality.', NULL, NULL, TRUE, NULL, NULL, 'PHIL236 or RELS236.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'none_found', NULL, NULL, 'PHIL236.', NULL, NULL, NULL, NULL),
    ('RELS250', 'Fundamental Concepts of Judaism', 3, 3, 'A conceptional introduction to Judaism, analyzing its fundamental concepts from both analytical and historical perspectives. Discussion of "normative" Judaism as well as other conceptions of Judaism. Topics include: God, the Jewish people, authority, ethics, the sacred and the profane, particularism and universalism.', NULL, NULL, TRUE, NULL, NULL, 'JWST250, PHIL234, or RELS250.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'none_found', NULL, NULL, 'JWST250, PHIL234.', NULL, NULL, NULL, NULL),
    ('RELS264', 'Introduction to the New Testament', 3, 3, 'A historical and literary introduction to the New Testament focusing on the context of the authors and the development of earliest Christianity.', NULL, NULL, TRUE, 'DSHU', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'verified', '202601', NULL, NULL, NULL, NULL, NULL, NULL),
    ('RELS269', 'Special Topics in Study Abroad II', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('RELS271', 'What is Religion?', 3, 3, 'Draws upon examples from a wide variety of religious traditions to explore the question of what religion is and how to best understand it. Engagement with diverse approaches to religion including phenomenology and the study of "the sacred"; sociology and the study of religious communities; and questions of religious experience, ritual, and identity formation.', NULL, NULL, TRUE, 'DSHU, DVCC, SCIS', NULL, 'RELS289I or RELS271.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'verified', '202601', 'RELS289I.', NULL, NULL, NULL, NULL, NULL),
    ('RELS273', 'Jesus, Mani, and Muhammad: The Dynamics of New Religious Movements', 3, 3, 'We examine three significant ancient religious figures: Jesus (d. 30s CE), Mani (d. 276 CE), and Muhammad (d. 632). All three were founders of long-lasting religions that were part of a dramatic change in the society and religion of the ancient world. Special areas of focus: the biographies of these founding figures, and how we know them; a historical approach to religious founders; and the sociology of new religious movements.', NULL, NULL, TRUE, 'DSHU, DVUP, SCIS', NULL, 'RELS273 or RELS289M or HIST289T.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'verified', '202608', 'RELS289M.', 'HIST289T.', NULL, NULL, NULL, NULL),
    ('RELS274', 'Jerusalem in Antiquity: The History of Sacred Space in a Holy City', 3, 3, 'Examines the complex history of Jerusalem''s status as a holy city, with a focus on constructions of sacred space in Judaism, Christianity, and Islam.', NULL, NULL, TRUE, 'DSHU, DVUP, SCIS', NULL, 'JWST274, RELS274, JWST289J or RELS289J.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'verified', '202608', 'JWST289J, RELS289J.', 'JWST274.', NULL, NULL, NULL, NULL),
    ('RELS289', 'New Explorations in Religious Studies', 3, 3, 'Investigation of critical and innovative responses in Religious Studies. Although the topic will vary, the course will encourage intellectual exploration by students of fundamental problems and critical methods.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('RELS289C', 'Jews, Christians, and Muslims in Medieval Spain: Tolerance, Oppression, and the Problematic Past', 3, 3, 'For 800 years, medieval Spain was home to one of the most religiously diverse societies in European history. Despite frequent hostilities, the interactions of Spanish Jews, Christians, and Muslims produced a flowering of science, theology, and literature in an often remarkably tolerant climate. Students will learn how medieval Spanish people themselves experienced interreligious contact and conflict. They will also discover the modern pressures, prejudices, and ideals that have shaped historians interpretations of medieval Spain.', NULL, NULL, TRUE, 'DSHS, DVUP, SCIS', NULL, 'HIST289A or RELS289C.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'verified', '202508', NULL, 'HIST289A.', NULL, NULL, NULL, NULL),
    ('RELS319', 'Special Topics in Religious Studies', 1, 3, 'Special topics in the study of religious history, literature, culture, and thought.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('RELS340', 'Europe in the Making: The Early Medieval West (A.D. 300-1000)', 3, 3, 'From one empire to another: Rome to Charlemagne. This period is approached as a crucible in which classical, Christian, and Germanic elements merged, yielding new experimental syntheses. This course will deal with issues of authority, cultural trends, and the formation of group solidarity.', NULL, NULL, TRUE, NULL, NULL, 'HIST330 or RELS340.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'none_found', NULL, NULL, 'HIST330.', NULL, NULL, NULL, NULL),
    ('RELS341', 'Europe in the High Middle Ages: 1000-1500', 3, 3, 'Medieval civilization in the 11th through 15th centuries. Emphasis on cultural and political developments of the high Middle Ages with study of the principal sources of medieval thought and learning, art and architecture, and political theory prior to the Renaissance.', NULL, NULL, TRUE, NULL, NULL, 'HIST331 or RELS341.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'none_found', NULL, NULL, 'HIST331.', NULL, NULL, NULL, NULL),
    ('RELS342', 'Renaissance Europe', 3, 3, 'Intellectual developments in Italy and Northern Europe from 1300 to 1550 and their influence on the arts and religion; social and economic trends, including the rise of the commercial economy in cities; the family and the role of women in society; expansion of Europe overseas and the beginnings of colonization; emergence of the state and consequent changes in political theory.', NULL, NULL, TRUE, NULL, NULL, 'HIST332 or RELS342.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'none_found', NULL, NULL, 'HIST332.', NULL, NULL, NULL, NULL),
    ('RELS343', 'The European Reformations', 3, 3, 'Examination of developments in European religion between 1450 and 1700; the late-medieval Church and its critics; rise of Protestant thought in Germany and its spread throughout Europe; reform efforts in the Catholic Church; religious wars and violence and their impact on state and society; consequences of religious reform in society and its impact on the family and women.', NULL, NULL, TRUE, NULL, NULL, 'HIST333 or RELS343.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'none_found', NULL, NULL, 'HIST333.', NULL, NULL, NULL, NULL),
    ('RELS346', 'History of Religion in America', 3, 3, 'A history of religion, religious movements, and churches in America from the early Colonial period to the present, with special attention to the relation between church and society.', NULL, NULL, TRUE, NULL, NULL, 'HIST306 or RELS346.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'none_found', NULL, NULL, 'HIST306.', NULL, NULL, NULL, NULL),
    ('RELS347', 'Tradition and Change: Jewish Religion in the Modern World', 3, 3, 'An exploration of the history of the different modern Jewish religious movements that developed in Europe, starting with messianic movements and ending with Reform and Orthodoxy. Emphasis will be placed on the influence of the academic study of Judaism on the development of modern Jewish religious ideologies and practices.', NULL, NULL, TRUE, NULL, NULL, 'RELS347, JWST347, HIST429X, or RELS419R.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'none_found', NULL, 'RELS419R.', 'JWST347, HIST429X.', NULL, NULL, NULL, NULL),
