    ('RELS371', 'Roman Religion: From Jupiter to Jesus', 3, 3, 'Survey of the major institutions of Roman state and private religion and of the diverse religions, including Judaism and Christianity, practiced in the Roman empire.', NULL, NULL, TRUE, NULL, NULL, 'CLAS331 or RELS371.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'none_found', NULL, NULL, 'CLAS331.', NULL, NULL, NULL, NULL),
    ('RELS408', 'Capstone Seminar for Religions of the Ancient Middle East', 3, 3, 'A capstone seminar for majors in Religions of the Ancient Middle East, designed to provide the intellectual framework for a substantial, interdisciplinary research project. Course topics will be thematic and students will be encouraged to explore comparative or interdisciplinary approaches.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('RELS419', 'Advanced Topics in Religious Studies', 3, 3, 'The contemporary study of religion in which topics may address specific religious traditions, regional or historical developments, or methodological and theoretical issues.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'none_found', NULL, NULL, NULL, NULL, '9 credits if content differs.', 'RELS216.', NULL),
    ('RELS427', 'The Epic of Gilgamesh', 3, 3, 'One of the most famous tales from the ancient world, the Epic of Gilgamesh inspires readers with tales of friendship and loss, mortality, and the search for meaning. The story itself grew and changed over time and took on new meanings. Through study of the epic, its development over time, and the sources it drew from, this class will examine the meaning of the Gilgamesh epic and its impact on ancient Mesopotamian culture.', 'JWST225, RELS225, HIST219I, or permission of the instructor.', NULL, FALSE, NULL, NULL, 'JWST419G, RELS419G, RELS427 or JWST427.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'unstructured', 'none_found', NULL, 'JWST419G.', 'JWST427.', NULL, NULL, 'JWST262, ENGL262, or HEBR298B.', NULL),
    ('RELS429', 'Advanced Topics in Religious History', 3, 3, 'Advanced study of religious history in a particular setting, with attention to particular themes, texts, events, or communities.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'none', 'none_found', NULL, NULL, NULL, NULL, '9 credits if content differs.', 'RELS216 or RELS289.', NULL),
    ('RELS430', 'Dead Sea Scrolls', 3, 3, 'A study of the Dead Sea Scrolls in their ancient and modern settings, and in terms of contemporary scholarly interpretations of their meaning. Interpretations of the historical significance of these documents, their connections to ancient Jewish sectarian movements, and their implications for our understanding of Judaism, Christianity, and the history of the Bible.', 'Must have completed one JWST course or one RELS course; or permission of ARHU-Meyerhoff Program & Center for Jewish Studies. Cross-listed with JWST430.', NULL, FALSE, 'DSHU or DSSP', NULL, 'JWST430 or RELS430.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'unstructured', 'verified', '202508', NULL, NULL, NULL, NULL, NULL, NULL),
