    ('RELS499', 'Independent Study in Religious Studies', 1, 3, 'An advanced independent research project for qualified students, supervised by a faculty member, on a topic not ordinarily covered in available courses.', 'Permission of ARHU-Meyerhoff Program & Center for Jewish Studies.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/rels/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('RELX101', 'Religion in a Pluralistic World', 3, 3, 'Examines the issue of religious pluralism, explores the relationship between religious truth and (in)tolerance, and examines how different religious traditions treat religious truth claims in regard to the social and political context in which they operate. Examines the interferences between the religious and the socio-political realm, both historically and in the context of the contemporary world.', NULL, NULL, TRUE, NULL, NULL, 'RELS269F or RELX101.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/relx/', 'none', 'none_found', NULL, 'RELS269F.', NULL, NULL, NULL, NULL, 'This course is offered as part of the Maryland-in-Rome study abroad program. Students must apply for this program through Education Abroad: More information at ter.ps/UMRome. Education Abroad processes registrations for this course on behalf of students.'),
    ('RUSS101', 'Intensive Elementary Russian I', 6, 6, 'This intensive first-year course is intended to develop the four skills: reading, writing, listening and speaking with an emphasis on communicative competence.', 'Must have appropriate World Language Placement (WLP) score.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/russ/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
