    ('THET488', 'Special Topics in Theatre History Before 1800', 3, 3, 'Topics in the history of world theatre and performance from the Greeks through 1800.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/thet/', 'none', 'none_found', NULL, NULL, NULL, NULL, '12 credits if content differs.', NULL, NULL),
    ('THET489', 'Special Topics in Theatre History from 1800 to Present', 3, 3, 'Topics in the history of world theatre and performance from 1800 to present.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/thet/', 'none', 'none_found', NULL, NULL, NULL, NULL, '12 credits if content differs.', NULL, NULL),
    ('THET491', 'Theatrical Rendering Using Photoshop', 3, 3, 'A studio course in rendering for the theatre. The course focuses primarily on traditional approaches to perspective drawing, space, texture, color and lighting rendering using Photoshop. Photoshop tools and techniques; preparing three-dimensional objects for accurate rendering; and techniques for Photoshop rendering and lighting of three-dimensional objects and architectural forms. This class primarily has an emphasis on rendering/uses for scenic design.', 'THET471.', NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/thet/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('THET497', 'Non-Traditional Theatre', 3, 3, 'Seminar exploring American and European experimental performance since 1960. Topics include experimental theatre, performance art, pornography and performance, gender and performance, and popular culture and performance. Topics are treated historically and theoretically. Student-produced performance projects are an important component of the seminar.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/thet/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('THET498', 'Seminar: Theatre History', 3, 3, 'Studies in theatre history from classical antiquity to the present.', 'THET488 or THET489.', NULL, TRUE, NULL, 'Senior standing; and permission of instructor.', 'THET498 or THET6 98.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/thet/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs. Jointly offered with THET698.', NULL, NULL),
    ('THET499', 'Independent Study', 1, 3, 'An independent study course in which each student completes an assigned major theatre project under close faculty supervision. Projects may culminate with term papers, scenic or costume designs, or a stage production.', NULL, NULL, TRUE, NULL, 'Permission of ARHU-School of Theatre, Dance & Performance Studies department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/thet/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits.', NULL, NULL),
    ('THEX100', 'London/Culture/Performance', 3, 3, 'Introduces students to aspects of London''s cultural resources and history and explores London as a performance site. Examines current issues in cultural politics and engages with the vast cultural resources, history, and global connections of London through analysis of a range of texts, performances and events, and sites around London.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/thex/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'This course is offered as part of the Arts & Humanities-in-London study abroad program. Students must apply for this program through Education Abroad: More information at https://globalmaryland.umd.edu/offices/education-abroad/program/11854. Education Abroad processes registrations for this course on behalf of students.'),
    ('THEX101', 'Theatre and Performance in North America', 3, 3, 'Studies contemporary drama and live art from countries including the United States, Canada, and Mexico. Explores how forms of and approaches to performance spread across a region and the globe through seminar discussions, readings, film, and television. Analyzes various performance styles and traditions including Indigenous performance, intercultural theatre, and Latinx theatre.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/thex/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'This course is offered as part of the Arts & Humanities-in-London study abroad program. Students must apply for this program through Education Abroad: More information at https://globalmaryland.umd.edu/offices/education-abroad/program/11854. Education Abroad processes registrations for this course on behalf of students.'),
    ('THEX102', 'London: Walking the City', 3, 3, 'What is a city? This course asks students to consider the different ways that we might define a city and to explore different perspectives on London inflected by mobility, migration, class and gender. Through reading a range of literary and theoretical texts, as well as walking lectures, students will develop an understanding of the role of literature, performance and cultural institutions in producing and contesting urban experience.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/thex/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'This course is offered as part of the Arts & Humanities-in-London study abroad program. Students must apply for this program through Education Abroad: More information at https://globalmaryland.umd.edu/offices/education-abroad/program/11854. Education Abroad processes registrations for this course on behalf of students.'),
    ('THEX200', 'Acting', 3, 3, 'A workshop on the fundamental techniques of acting, the course stresses methodology, discipline and development. It covers: stimulation of the actor''s imagination, analytical insight into script and characters, expressive skills of body and voice, sensitivity, revelation, and expression. Develops emotional range and personal style.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/thex/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'This course is offered as part of the Maryland-in-Rome study abroad program. Students must apply for this program through Education Abroad: More information at ter.ps/UMRome. Education Abroad processes registrations for this course on behalf of students.'),
    ('THEX300', 'Race and Racism in Performance', 3, 3, 'Explores how race is performed in theater, art, and popular culture. Examines questions about racism in performance casting and practices.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/thex/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'This course is offered as part of the Arts & Humanities-in-London study abroad program. Students must apply for this program through Education Abroad: More information at https://globalmaryland.umd.edu/offices/education-abroad/program/11854. Education Abroad processes registrations for this course on behalf of students.'),
    ('THEX301', 'Voice, Gender, Performance', 3, 3, 'How do people use their voices, and what does this reveal or conceal about their gendered identities? How do gendered voices intersect with other aspects of identity, such as region, class, nation and race? This course explores how gender is voices in a variety of different spaces by drawing on theoretical material from a range of disciplinary fields, including cultural philosophy, sociolinguistics, film studies, and psychology while equipping students to use the voice creatively through mixed learning methods and attendance at exhibitions and performances.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/thex/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'This course is offered as part of the Arts & Humanities-in-London study abroad program. Students must apply for this program through Education Abroad: More information at https://globalmaryland.umd.edu/offices/education-abroad/program/11854. Education Abroad processes registrations for this course on behalf of students.'),
    ('THEX302', 'Show Business: Theatre and Capitalism', 3, 3, 'Explores the relationship between theater and capitalism through the examination of key economic problems as they arise in the theater (e.g. "star" performers, box office, theater as entertainment, theater as a "creative industry," theater and real estate). Considers how performance offers a distinctive lens through which to think about broader movements (e.g. neoliberalism, globalization, urban development) that have become central to our everyday lives.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/thex/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'This course is offered as part of the Arts & Humanities-in-London study abroad program. Students must apply for this program through Education Abroad: More information at https://globalmaryland.umd.edu/offices/education-abroad/program/11854. Education Abroad processes registrations for this course on behalf of students.'),
    ('THEX303', 'Live Art: Then and Now', 3, 3, 'Explores the recent history of Live Art, from the 1970s to the present via the study of significant as well as overlooked artists through audiovisual documentation, oral histories/interviews, and artists'' writings, as well as significant scholarship and criticism in the field. Students will analyze performances and gain perspective on key themes for the study of Live Art, including (but not limited to) sexuality, gender, race and ethnicity, the blurring of art and life, extremity, duration, protest, and social engagement.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/thex/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'This course is offered as part of the Arts & Humanities-in-London study abroad program. Students must apply for this program through Education Abroad: More information at https://globalmaryland.umd.edu/offices/education-abroad/program/11854. Education Abroad processes registrations for this course on behalf of students.'),
    ('THEX304', 'Scriptwriting: Creativity and Technique', 6, 6, 'Delves into the world of scriptwriting through production of an original script and analysis of filmed scripts. Explores the context around reading scripts as well as how to write a short original film script with coherent dialogue, exposition and structure.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/thex/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'This course is offered as part of the Arts & Humanities-in-London study abroad program. Students must apply for this program through Education Abroad: More information at https://globalmaryland.umd.edu/offices/education-abroad/program/11854. Education Abroad processes registrations for this course on behalf of students.'),
    ('THEX305', 'The History of Emotions', 3, 3, 'We live in an era of angry voters, weeping celebrities, and governments intent on measuring happiness. The course explores the histories of feelings, emotions and passions through the study of a wide range of examples and case studies, and examines many different historical types, including intellectual history, gender history, cultural history, social history, religious history, the history of art, and the histories of science and medicine.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/thex/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'This course is offered as part of the Arts & Humanities-in-London study abroad program. Students must apply for this program through Education Abroad: More information at https://globalmaryland.umd.edu/offices/education-abroad/program/11854. Education Abroad processes registrations for this course on behalf of students.'),
    ('TLPL101', 'Inquiry Approach to Teaching STEM (Step 1)', 1, 1, 'Explore STEM teaching and learning and classroom complexity, and develop teaching skills through discussion-based, collaborative class sessions, and experiences in local schools. To explore/understand the fundamentals of inquiry teaching, students will observe, plan and teach student-centered lessons.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'Students must allow for a three-hour window between 7:45 AM and 3:15 PM in their schedule for field experiences in a local school 3-4 times during the semester. A background check is required and will be facilitated by the Terrapin Teacher program coordinator.'),
    ('TLPL102', 'Inquiry Teaching of STEM in Middle School', 2, 2, 'Second course in the Terrapin Teachers teacher preparation sequence. Students gain field experience and continue exploring teaching as a career by conducting teacher observations, and planning and implementing lessons in local, high-need middle school classrooms. Students work closely with UM master teachers to build upon the inquiry-based teaching practices developed in TLPL 101. Students work with mathematics and science curricula while attending to state and district standards, in order to develop and enact lessons that are responsive to students'' reasoning in math and science.', 'Must have completed TLPL101.', NULL, FALSE, 'DSSP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'unstructured', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, 'Attendance at each class session will be vital to student success in the course. To complete the observations and lessons, students must allow a three hour block of time during the local middle school operational hours from 7:45 am to 3:15 pm. A background check is required.'),
    ('TLPL155', 'Learning to Learn biology', 4, 4, 'This course focuses on learning, understanding, and working with core ideas in biology to engage in scientific practice and applications. In the spirit of "integrated STEM learning", this course will focus on applications of biological principles particularly as they relate to design solutions for human needs and participation in socioscientific issues. A sub-thread of the course is attention to the content of the Middle School Science Praxis exam sections on "Scientific Inquiry, Methodology, Techniques and History" (a topic that runs through the course) and "Life Sciences" to prepare students in the MSMS major to excel on this section of the Praxis. A laboratory component of the course engages students in investigations using either tangible physical and biological models or computational models. These investigations align with the content structure of the main throughline of the course.', NULL, NULL, TRUE, NULL, NULL, 'BSCI155 or TLPL155.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, NULL, 'BSCI155.', NULL, NULL, NULL, NULL),
    ('TLPL188', 'Select Topics in Education', 1, 3, 'Special and intensive treatment of current topics and issues in teaching, learning, policy, and leadership.', NULL, NULL, TRUE, NULL, 'Permission of EDUC-Teaching and Learning, Policy and Leadership department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits.', NULL, NULL),
    ('TLPL200', 'Exploring Teaching as a Career', 3, 3, 'Weekly participation as a volunteer tutor in a local school or community program with children or adolescents. Regular campus meetings assist with developing teaching skills and insight.', NULL, NULL, TRUE, 'DSSP', NULL, 'EDCI210 or TLPL200.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'verified', '202601', 'EDCI210.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL202', 'Good Stories: Teaching Narratives for Peace and Justice', 3, 3, 'Through the study and use of oral storytelling and digital technologies explore qualities and characteristics of what makes a good story and how stories can be used to advance peace and justice on both individual and social levels.', NULL, NULL, TRUE, NULL, NULL, 'EDCI246 or TLPL202.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'EDCI246.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL204', 'Latino and Black Schooling: A History', 3, 3, 'The historical, cultural, political and socio-economic factors that shape the school experience and achievement (Kindergarten - college) of Latinos and Blacks in the U.S.', NULL, NULL, TRUE, NULL, NULL, 'EDCI286 or TLPL204.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'EDCI286.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL206', 'Forbidden Books: Censorship of Children''s and Young Adult Literature', 3, 3, 'What is the relationship between censorship and intellectual freedom? This course examines the history of censorship from Plato to Fake News with a focus on contemporary censorship analyzed through historical, political, ethical, moral, philosophical, and socio-cultural perspectives. We consider the evolving definition of censorship, forms of censorship, the rationalizations and arguments for censorship, and the consequences and unintended results of censorship.', NULL, NULL, TRUE, 'DSHS, SCIS', NULL, 'TLPL288W or TLPL206.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'verified', '202608', 'TLPL288W.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL210', 'Childhood Reimagined: Learning In and Out of Schools', 3, 3, 'Surveys innovative approaches to child education, including unschooling, homeschooling, blended instruction, place-based learning, Big Picture Learning, democratic schools, microschools, self-directed learning centers, and other alternatives to traditional schools.', NULL, NULL, TRUE, 'DSHS, SCIS', NULL, 'TLPL288K or TLPL210.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'verified', '202605', 'TLPL288K.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL250', 'Historical and Philosophical Perspectives on Education', 3, 3, 'An examination of illustrative historical and philosophical examples of the interplay of ideas and events in the shaping of educational aims and practices from ancient cultures to modern technological societies.', NULL, NULL, TRUE, 'DSHU', NULL, 'EDPS210 or TLPL250.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'verified', '202608', 'EDPS210.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL251', 'Community, Learners, and Classroom Climate', 3, 3, 'Focuses on classroom community building as an ethic of caring for students and examines the connection between classroom climate and learning. Topics include students'' funds of knowledge, social-emotional competency, and the practices that maintain a safe and inclusive classroom climate. Wellness strategies to support teacher resilience are also addressed.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'This course has a field component in a local elementary school.'),
    ('TLPL252', 'Students, Schooling, and Communities', 3, 3, 'Facilitates pre-service teachers'' initial look at their personal backgrounds and the ways in which they view the world. Exploration of schools, students and their connections to communities. Draws on preservice teachers'' concurrent field experiences.', NULL, 'TLPL251.', TRUE, 'DSSP', NULL, 'EDCI297 or TLPL252.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'parsed', 'verified', '202601', 'EDCI297.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL253', 'Language Rights and Repression in Education', 3, 3, 'Many English-speaking Americans view societal monolingualism and English-speaking in schools as the standard. The proposed course will delve deeply into issues associated with language, language rights, education, and linguistic repression in schooling. The Big Question of our time this course asks is: Are access to education and native language maintenance civil rights? Human rights?', NULL, NULL, TRUE, 'DSHS, SCIS', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('TLPL254', 'Surmounting School: Democracy, Inequality, and Schooling', 3, 3, 'This Big Questions course explores the grandest challenges faced by today''s public schools and asks: How do schools shape democracy and inequality in the U.S.? At the conclusion of this course, students will propose practical educational policy recommendations aimed at addressing its big question.', NULL, NULL, TRUE, 'DSHS, SCIS', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'verified', '202601', NULL, NULL, NULL, NULL, NULL, NULL),
    ('TLPL255', 'Watch your Language! Decoding the World Around Us', 3, 3, 'This Big Questions course addresses the question: What is a "linguistic landscape"? How do we decode and interpret language on signs--buildings, roadways, flyers, storefronts, even t-shirts and what does it mean for our public spaces? How and why are languages displayed, hierarchized and used in social and school settings?', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('TLPL267', 'Education in Beta: Navigating an AI & Tech-Powered Future', 3, 3, 'How should education evolve in a rapidly advancing AI and tech-driven world to ensure a just and human future? This interdisciplinary course examines how AI and emerging technologies are reshaping teaching and learning, inviting students to imagine equitable futures for education.', NULL, NULL, TRUE, 'DSHS, SCIS', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('TLPL285', 'Shared Earth: Indigenous and Scientific Perspectives for Climate Science Education', 3, 3, 'Explore how climate science can be taught in inclusive, creative, and transformative ways by the integration of Indigenous Knowledges and western sciences. This course has been developed by UMD College of Education faculty in collaboration with scientists from the National Oceanic and Atmospheric Administration (NOAA), faculty in the University of MarylandMD''s Behavior, Ecology, Evolution, and Systematics (BEES) program, and Piscataway Conoy Tribal citizens.', NULL, NULL, TRUE, 'DSSP, SCIS', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'verified', '202605', NULL, NULL, NULL, NULL, NULL, NULL),
    ('TLPL286', 'Accelerated Introduction to STEM Teaching', 3, 3, 'Students can expect a highly collaborative, discussion-based exploration of STEM teaching and learning, classroom complexity, and social justice. Fieldwork includes four visits to a local middle school classroom to observe, facilitate discussions, and lead STEM lessons. This course is designed for students pursuing or seriously considering the middle or secondary STEM certification pathways.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'For the lab component of this course, students must reserve a three-hour window in their schedules between the hours of 8am-3pm, to be utilized approximately 10 weeks in the semester. This lab will be a combination of collaborative group work and a fieldwork component in a local partner school, which requires fingerprinting and a background check (facilitated by Terrapin Teachers).'),
    ('TLPL287', 'Inquiry Into Issues in US Public Schooling: Policies, Practice and Promise', 3, 3, 'Students will inquire into enduring issues faced by US public education, focusing on the forces and stakeholders that have shaped current policy and practice. In addition, students will work to consider the real daily consequences of policy on the lives of students and teachers. Through crafting and researching a question of interest, employing a project based learning approach, students will take a deep dive into the most vexing issues faced by public education in the United States.', NULL, NULL, TRUE, 'DSHS, SCIS', NULL, 'TLPL288T or TLPL287.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'verified', '202601', 'TLPL288T.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL288', 'Special Problems in Education', 1, 6, 'Special and intensive treatment of current topics and issues in teaching, learning, policy and leadership. Available only to freshmen and sophomore students who have definite plans for individual study of approved problems relative to their preparation for teaching.', NULL, NULL, TRUE, NULL, 'Permission of EDUC-Teaching and Learning, Policy and Leadership department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'EDPS288.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL298', 'Special Problems in Education', 1, 6, 'Exploration of current problems in teaching, learning, policy and leadership. Available only to students who have definite plans for study of approved problems.', NULL, NULL, TRUE, NULL, 'Permission of EDUC-Teaching and Learning, Policy and Leadership department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'EDCI298.', NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('TLPL300', 'Digital Learning Tools and Communities', 1, 1, 'An exploration of the digital tools available for P12 students and their teachers that enhance learning and help build classroom community. This hybrid course will prepare P12 teachers to incorporate instructional technology, digital learning resources, and social media in P12 classrooms.', NULL, NULL, TRUE, NULL, 'Minimum cumulative GPA of 2.75; and must be in one of the following programs (Elementary Education; Secondary Educ: Social Studies; Secondary Educ: Art; Secondary Educ: Mathematics; Secondary Educ: Science; Secondary Educ: English Language Arts; Secondary Educ: Foreign Languages).', 'EDCI385 or TLPL300.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'EDCI385.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL312', 'Curriculum and Instruction in Elementary Education: Mathematics', 3, 3, 'Materials and procedures to help children sense arithmetical meanings and relationships. Development of an understanding of the number system and arithmetical processes. Includes laboratory/field experiences.', 'TLPL361.', 'EDCI362, EDCI342, TLPL321, and TLPL362.', FALSE, NULL, 'Must be in Elementary Education program; and minimum cumulative GPA of 2.75; Or permission of EDUC-Teaching and Learning, Policy and Leadership department.', 'EDCI352 or TLPL312.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'unstructured', 'none_found', NULL, 'EDCI352.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL321', 'Curriculum and Instruction in Elementary Education: Science', 3, 3, 'Objectives, methods, materials and activities for teaching science in the elementary school; emphasis on teaching strategies which help children learn the processes and concepts of science. Includes laboratory/field experiences.', 'TLPL361.', 'TLPL312, EDCI362, EDCI342, and TLPL362.', FALSE, NULL, 'Must be in Elementary Education program; and minimum cumulative GPA of 2.75; Or permission of EDUC-Teaching and Learning, Policy and Leadership department.', 'EDCI372 or TLPL321.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'unstructured', 'none_found', NULL, 'EDCI372.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL332', 'Arts Integration in Elementary Classrooms', 3, 3, 'An exploration of the theories and core practices associated with integrating the arts in ways that promote student learning in the core subjects.', NULL, 'TLPL362, EDCI362, TLPL361, and EDCI489.', FALSE, NULL, 'Must be in Elementary Education program; and minimum cumulative GPA of 2.75; Or permission of EDUC-Teaching and Learning, Policy and Leadership department.', 'TLPL306 or TLPL332.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'unstructured', 'none_found', NULL, 'TLPL306.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL340', 'Introduction to Children''s Literature and Critical Literacy', 3, 3, 'Analysis of literary materials for children and youth. Timeless and ageless books, and outstanding examples of contemporary publishing. Evaluation of the contributions of individual authors, illustrators and children''s book awards.', NULL, NULL, TRUE, NULL, 'Must be in Elementary Education program; or must be a Pre-Education Major.', 'EDCI443 or TLPL340.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'EDCI443.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL341', 'Assessing Language and Literacy Development in Elementary Classrooms', 3, 3, 'An exploration of the social and cognitive processes involved in reading and writing, the developmental nature of those processes, the foundational concepts associated with effective literacy assessment, a variety of formative and summative literacy assessments, and the nature of individual differences in reading and writing.', NULL, 'TLPL479, EDHD411, and EDSP401.', TRUE, NULL, 'Must be in the Elementary Education program; and permission of EDUC-Teaching and Learning, Policy and Leadership.', 'TLPL341 or TLPL488R.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'parsed', 'none_found', NULL, 'TLPL488R.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL342', 'Promoting Skilled and Motivated Readers in Diverse Elementary Classrooms (Part 1)', 3, 3, 'An investigation of the materials, curriculum, teaching and learning practices and assessment methods associated with promoting skilled and motivated readers in diverse elementary classrooms. Teacher candidates will learn to use assessments to design instruction in the core components of reading, in line with students'' individual needs and the Maryland College and Career Ready Standards.', NULL, 'TLPL362, TLPL361, TLPL332, and TLPL479.', TRUE, NULL, 'Must be in the Elementary Education program; and permission of EDUC-Teaching and Learning, Policy and Leadership.', 'TLPL488L or TLPL342.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'parsed', 'none_found', NULL, 'TLPL488L.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL343', 'Promoting Skilled and Motivated Readers in Diverse Elementary Classrooms (Part 2)', 3, 3, 'Application of the materials, curriculum, teaching and learning practices and assessment methods associated with classroom reading programs designed to promote skilled and motivated readers in diverse elementary classrooms. Teacher candidates will learn to assess and scaffold students'' self-regulated literacy learning in line with students'' individual needs and Maryland College and Career Ready Standards.', NULL, 'TLPL312, TLPL321, TLPL446, and TLPL489.', TRUE, NULL, 'Must be in the Elementary Education program; and permission of EDUC-Teaching and Learning, Policy and Leadership.', 'TLPL343 or TLPL488F.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'parsed', 'none_found', NULL, 'TLPL488F.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL344', 'Culturally Responsive Language and Literacy Instruction in Diverse Elementary Classrooms', 3, 3, 'Application of the asset-based practices associated with culturally responsive language and literacy programs. Teacher candidates will learn to plan, guide and assess students'' integrated language and literacy practices (reading, writing, speaking and listening), with emphasis on writing instruction, in line with students'' individual needs and Maryland College and Career Ready Standards.', NULL, 'TLPL300, TLPL478, and TLPL489.', TRUE, NULL, 'Must be in the Elementary Education program; and permission of EDUC-Teaching and Learning, Policy and Leadership.', 'TLPL488I or TLPL 344.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'parsed', 'none_found', NULL, 'TLPL488I.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL360', 'Foundations of Education', 3, 3, 'Social context of education and conflicts over philosophies, values, an goals that are reflected in educational institutions in our pluralistic society. Helps teachers become reflective, critical thinkers about the social and philosophical issues they face and the choices they make.', NULL, NULL, TRUE, 'DSHS', NULL, 'EDPS301 or TLPL360.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'verified', '202608', 'EDPS301.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL361', 'Community, Learners, and Classroom Engagement', 3, 3, 'Focuses on classroom community building as an ethic of caring for students and examines the connection between classroom engagement and learning. Topics include student agency, the context and design of learning experiences, and the practices that sustain students'' engagement in learning. Wellness strategies to support teacher resilience are also addressed.', NULL, 'TLPL332, TLPL362, TLPL342, and TLPL479G.', FALSE, NULL, 'Must be in Elementary Education program; and minimum cumulative GPA of 2.75; Or permission of EDUC-Teaching and Learning, Policy and Leadership department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('TLPL362', 'Curriculum and Instruction in Elementary Education: Social Studies', 3, 3, 'Curriculum, organization and methods of teaching, evaluation of materials, and utilization of environmental resources. Emphasis on multicultural education. Includes laboratory/field experiences.', NULL, 'EDCI362, TLPL361, EDCI489, and TLPL306.', FALSE, NULL, 'Must be in Elementary Education program; and minimum cumulative GPA of 2.75; Or permission of EDUC-Teaching and Learning, Policy and Leadership department.', 'EDCI322 or TLPL362.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'unstructured', 'none_found', NULL, 'EDCI322.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL379', 'Professional Engagement In and Beyond the Secondary/MS/K-12 Classroom', 1, 1, 'Provides an early field experience (e.g., tutoring young children) in secondary school settings (e.g., middle school). Recommended for students exploring the possibility of or intending to minor in Education or major in Secondary/MS/K-12 education. Credit will not be granted for experience accrued prior to registration. This course is open to all students but best suited for those interested in a career in education. Students need to be prepared to participate in as many as 10 in-person tutoring sessions over the course of the semester. Transportation is provided.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, NULL, NULL, NULL, '3 credits.', NULL, 'Students need to be available for a half day once a week to engage in the field based tutoring experience.'),
    ('TLPL401', 'Student-Centered Curriculum and Instruction', 3, 3, 'A focus on using student-centered teaching and learning approaches in high school STEM classrooms. Students will develop and implement a multi-day series of lessons, building upon the foundations of inquiry-based practices developed in prior courses. Students will also consider the implications of cultural awareness on teaching practices broadly, as well as in the specific contexts of their fieldwork.', 'Permission of instructor; and TLPL102; and must have completed or be concurrently enrolled in TLPL414.', NULL, FALSE, 'DSSP, DVCC', NULL, 'TLPL488P or TLPL401.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'unstructured', 'verified', '202608', 'TLPL488P.', NULL, NULL, NULL, NULL, 'Field experience for this course will require students to be available for a 2-4 hour block of time at various points throughout the semester to complete observations and teach lessons between 8:00 a.m. and 3:30 p.m. A background check is required and will be facilitated through the Terrapin Teacher program coordinator.'),
    ('TLPL403', 'Teaching and Learning High School Mathematics', 3, 3, 'Methods of teaching and assessing the high school mathematics curriculum; aligning tasks and activities to curriculum standards; lesson planning; and selection and use of technology. The course also focuses on managing large group dynamics in the high school mathematics classroom.', 'Must have 2 semesters of calculus; or permission of EDUC-Teaching and Learning, Policy and Leadership department.', 'EDCI355.', FALSE, NULL, 'Must be in Secondary Educ: Mathematics program; and minimum cumulative GPA of 2.75; Or permission of EDUC-Teaching and Learning, Policy and Leadership department.', 'EDCI455 or TLPL403.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'unstructured', 'none_found', NULL, 'EDCI455.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL406', 'Teaching and Learning Mathematics in the Elementary School, Part 1', 3, 3, 'Focuses on teaching and learning whole numbers. Special emphasis will be placed on developing equitable teaching practices that enable culturally and linguistically diverse students to develop knowledge and skills that promote mathematical proficiency. Mathematical concepts: Content knowledge: some aspects of early numeracy, whole numbers and the four arithmetic operations, some aspects of algebraic thinking.', NULL, NULL, TRUE, NULL, NULL, 'TLPL607 or TLPL406.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, NULL, NULL, 'TLPL607.', NULL, NULL, NULL),
    ('TLPL407', 'Teaching and Learning Mathematics in the Elementary School, Part 2', 3, 3, 'Focuses on teaching and learning rational numbers (fractions and decimals) and developing algebraic thinking. Special emphasis will be placed on developing equitable teaching practices that enable culturally and linguistically diverse students to develop knowledge and skills that promote mathematical proficiency. Mathematical concepts: Content knowledge: rational numbers (fractions and decimals) and the four arithmetic operations, algebraic thinking, some aspects of geometry and measurement.', NULL, NULL, TRUE, NULL, NULL, 'TLPL488G or TLPL407.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('TLPL413', 'Teaching and Learning Middle School Mathematics', 3, 3, 'Methods of teaching and assessing the middle school mathematics curriculum. Understanding the conceptual difficulties students have in moving from whole numbers to rational numbers, additive thinking to multiplicative thinking, and arithmetic to algebra. Lesson planning and selection of technology and other materials are applied in the context of supervised tutoring of students having difficulty in middle school mathematics. Lab and field experience required. Supervised tutoring takes place on site at a local middle school therefore TLPL413 students will be expected to travel to a local middle school for 8-10 of the class meetings.', NULL, NULL, TRUE, 'DSSP', 'Minimum cumulative GPA of 2.75; and permission of EDUC-Teaching and Learning, Policy and Leadership department.', 'EDCI457 or TLPL413.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'verified', '202508', 'EDCI457.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL414', 'Knowing and Learning in Mathematics and Science', 3, 3, 'Special and intensive treatment of current topics and issues in mathematics and science teaching and learning, policy and leadership. The overall goal of the course is to orient future teachers to the discourses and theories that shape what we know about how students learn math and science.', 'Must have completed or be concurrently enrolled in TLPL102.', NULL, TRUE, 'DSHS', NULL, 'TLPL488M or TLPL414.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'parsed', 'verified', '202608', 'TLPL488M.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL415', 'Perspectives in Science', 3, 3, 'Overview of the history of science and philosophical perspectives on science, particularly as they apply to science teaching.', 'Permission of instructor.', NULL, FALSE, NULL, NULL, 'TLPL488W or TLPL415.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'unstructured', 'none_found', NULL, 'TLPL488W.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL418', 'Teaching Residency', 3, 9, 'An extended teaching internship in an Elementary Professional Development School. School placements to be arranged.', 'Must have completed or be concurrently enrolled in TLPL352, TLPL363, TLPL372, TLPL415.', NULL, FALSE, NULL, 'Restricted to Elementary Education majors with permission of the Department; 2.75 GPA required.', 'TLPL418 or EDCI481.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, '12 credits.', NULL, NULL),
    ('TLPL420', 'Knowledge, Reasoning, and Learning in Science', 3, 3, 'For prospective science teachers. Investigations of the nature of knowledge, reasoning, and learning in middle and secondary science. Readings from cognitive science and science education research; studies of student thinking in interview and classroom observations; analyses of curricula. Includes laboratory and field experiences.', NULL, NULL, TRUE, 'DSSP', 'Minimum cumulative GPA of 2.75; and permission of EDUC-Teaching and Learning, Policy and Leadership department.', 'TLPL420 or EDCI411.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'verified', '202608', 'EDCI411.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL421', 'Practices in Secondary School Science Teaching', 2, 2, 'Analyses of student thinking, instructional interpretations, strategies, and techniques in the teaching internship.', 'TLPL425.', 'EDCI471 and EDCI474.', FALSE, NULL, 'Permission of EDUC-Teaching and Learning, Policy and Leadership department; and must be in Secondary Educ: Science program. Or minimum cumulative GPA of 2.75.', 'TLPL421 or EDCI480.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'unstructured', 'none_found', NULL, 'EDCI480.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL423', 'Interdisciplinary Teaching in the Middle Grades I', 3, 3, 'For prospective middle school teachers. Studying and planning interdisciplinary instructional practices in middle school. Utilizes context and experiences from students'' field placements. Use of technology and incorporation of technology into instruction.', 'TLPL413 and TLPL420; or permission of instructor.', NULL, FALSE, NULL, 'Minimum cumulative GPA of 2.75; and must be in the Middle School Teacher Education Program, major code 0804P.', 'EDCI413 or TLPL423.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'partial', 'none_found', NULL, 'EDCI413.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL424', 'Interdisciplinary Teaching in the Middle Grades II', 3, 3, 'For prospective middle school teachers. Planning and implementing interdisciplinary instructional practices in middle school. Draws on the context of and experiences in the student teaching placement. Use of technology and incorporation of technology into instruction.', 'TLPL423.', 'TLPL489.', TRUE, NULL, 'Minimum cumulative GPA of 2.75; and must be in the Middle School Teacher Education Program.', 'EDCI414 or TLPL424.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'parsed', 'none_found', NULL, 'EDCI414.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL425', 'Learning and Teaching in Science', 3, 3, 'Studies of student learning and instructional practices in science teaching.', 'TLPL420; or permission of instructor.', NULL, FALSE, NULL, 'Must be in Secondary Educ: Science program.', 'EDCI470 or TLPL425.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'partial', 'none_found', NULL, 'EDCI470.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL433', 'Foundations of Art Education', 3, 3, 'Introduction to the field of Art Education and the role of the visual arts in grades PreK-12 for today''s diverse school populations. The fundamental, historical and philosophic components of art education with an emphasis on arts disciplines and curriculum. Includes a school-based practicum. For those considering art education as a major.', NULL, NULL, TRUE, NULL, 'Minimum cumulative GPA of 2.75.', 'EDCI403 or TLPL433.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'EDCI403.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL435', 'Art Education Methods I', 3, 3, 'Methods I provides future art teachers with a knowledge base of the theories and best practices of effective pedagogy for: teaching methods and strategies, diversity, motivational techniques, classroom management, assessment and evaluation methods, and accommodating all students including those with special needs.', NULL, NULL, TRUE, 'DSSP', 'Minimum cumulative GPA of 2.75; and permission of EDUC-Teaching and Learning, Policy and Leadership department. And must be in Secondary Educ: Art program; or must be in Secondary Educ: Art pre-major program.', 'EDCI405 or TLPL435.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'verified', '202601', 'EDCI405.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL436', 'Studio Processes and Materials: 2D', 3, 3, 'A discussion/studio format used to develop skills, materials, resources and education strategies for using technology and two-dimensional art in K-12 programs.', 'ARTT210.', NULL, TRUE, NULL, 'Minimum cumulative GPA of 2.75; and permission of EDUC-Teaching and Learning, Policy and Leadership department; and junior standing or higher; and must not be in any of the following programs (Early Childhood Education; Elementary Education; Secondary Educ: Science; Secondary Educ: English Language Arts; Secondary Educ: Mathematics; Secondary Educ: Foreign Languages; Secondary Educ: Social Studies; Physical Education; Music Education; Special Education).', 'EDCI406 or TLPL436.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'parsed', 'none_found', NULL, 'EDCI406.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL437', 'Studio Processes and Materials: 3D', 3, 3, 'A lecture-studio course to develop skills, material resources, and educational strategies for three-dimensional projects in school settings.', NULL, NULL, TRUE, NULL, 'Must be in Secondary Educ: Art program; or must be a Pre-Art Education Major.', 'EDCI407 or EDCI437.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'EDCI407.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL440', 'Foundations of Educating Multilingual Learners', 3, 3, 'Investigates historical, theoretical, and public policy issues and current practice in the field of education as it relates to multilingual learners (also known as English Language Learners, English Learners) in K-12 and other settings.', NULL, NULL, TRUE, 'DVUP', NULL, 'EDCI432 or TLPL440.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'verified', '202608', 'EDCI432.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL441', 'Methods for Teaching Multilingual Learners', 3, 3, 'Addresses best practices for supporting multilingual learners across academic contexts. It draws on current research regarding methods of teaching multilingual learners in PreK12 settings. Students analyze and apply classroom instruction.', NULL, NULL, TRUE, 'DVCC', NULL, 'EDCI434 or TLPL441.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'verified', '202601', 'EDCI434.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL442', 'Foundations of Literacy and Biliteracy Development', 3, 3, 'An overview of the research on literacy and biliteracy development for English learners. Specifically, the course explores the theoretical models and processes of teaching reading and writing, current literacy/biliteracy issues, assessment, and strategies for developing literacy and biliteracy skills for English learners.', NULL, NULL, TRUE, NULL, NULL, 'EDCI435 or TLPL442.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'EDCI435.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL443', 'Cross-Cultural Communication and Multilingual Learners', 3, 3, 'Participants will research and critically reflect upon aspects of culture as a basis to understand students and to develop principles to guide culturally inclusive teaching decisions. Participants will better understand the role of culture and language in schooling in order to create classrooms where culturally and linguistically diverse students (also known as English Language Learners, English Learners) can succeed.', NULL, NULL, TRUE, 'DVCC', NULL, 'EDCI436 or TLPL443.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'verified', '202608', 'EDCI436.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL444', 'Teaching and Understanding English Grammar with Multilingual Learners', 3, 3, 'Students will analyze the major grammatical structures of American English and the role of teaching grammar and developing effective classroom methods and techniques for multilingual learners. To do so, students will be exposed to diverse theories, approaches, methods, and practical techniques of grammar instruction in order to assist multilingual learners (also known as English Language Learners, English Learners) K-12 classrooms.', NULL, NULL, TRUE, NULL, NULL, 'EDCI437 or TLPL444.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'EDCI437.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL445', 'Methods I: World Language Methods and Technology', 3, 3, 'Explores Dual Language/World Language Methods and Second Language/Bilingual development. Implications for teaching and initial lesson design are explored through on-campus seminars as well as guided field experiences. Students should reserve a regular half-day per week for the field experience in local schools.', NULL, NULL, TRUE, 'DSSP', 'Minimum cumulative GPA of 2.75; and permission of EDUC-Teaching and Learning, Policy and Leadership department.', 'TLPL445 or TLPL695.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('TLPL446', 'Language Variation and Multilingualism in Elementary Classrooms', 3, 3, 'Issues in language variation and multilingualism in elementary classrooms, schools and communities with a focus on classroom practice, assessment, and policy.', NULL, NULL, TRUE, NULL, 'Must be in Elementary Education program; and minimum cumulative GPA of 2.75. Or permission of EDUC-Teaching and Learning, Policy and Leadership department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('TLPL447', 'Art Education Methods II', 3, 3, 'Methods II builds upon the pedagogical foundation of Methods I and provides future art teachers with the means for developing pre K-12 art lessons and unit plans for a balanced qualitative art program for today''s diverse and inclusive schools and classrooms.', 'TLPL435; or students who have taken courses with comparable content may contact the department.', NULL, FALSE, NULL, 'Minimum cumulative GPA of 2.75; and must be in Secondary Educ: Art program.', 'EDCI423, EDCI603, TLPL447 or TLPL633.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'partial', 'none_found', NULL, 'EDCI423.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL450', 'Advanced World Language Methods and Technology', 3, 3, 'Teaches advanced best practices for effective world language instruction. Topics include: using authentic assessment and materials, applying national standards, teaching writing and culture, motivating students, providing strategy instruction, infusing technology, preparing for PreK-12 employment, and creating a professional portfolio.', 'TLPL445.', 'EDCI438.', TRUE, NULL, 'Must be in Secondary Educ: Foreign Languages program; and minimum cumulative GPA of 2.75. Or permission of EDUC-Teaching and Learning, Policy and Leadership department.', 'EDCI433, EDCI688A, TLPL450 or TLPL696.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'parsed', 'none_found', NULL, 'EDCI433.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL451', 'Teaching and Learning in Secondary Education: English', 3, 3, 'An introduction for prospective middle and secondary English teachers into the basic issues, concepts, orientations, and processes that shape the teaching of English for diverse students in schools. Candidates explore their own perspectives in relation to local and national trends and develop basic teaching understanding and skills through on-campus seminars, teaching laboratory experiences, and guided field experiences. Students should reserve one full day or two half days per week for field experience.', NULL, NULL, TRUE, 'DSSP', NULL, 'EDCI416 or TLPL451.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'verified', '202608', 'EDCI416.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL452', 'Bases for English Language Instruction', 3, 3, 'Examines current theory, research, best practice, curricula and materials focused on the teaching of English language to native and non-native English learners. Topics include morphology, syntax, semantics, vocabulary, pragmatics, argument, discourse structure, dialects, edited academic English, English language proficiency (listening, speaking, reading, writing) assessment, and instructional planning. English Language Learner (TESOL and SIOP) and special needs (inclusion) pupil issues considered.', NULL, NULL, TRUE, NULL, 'Must be in Secondary Educ: English Language Arts program; and minimum cumulative GPA of 2.75; and permission of EDUC-Teaching and Learning, Policy and Leadership department.', 'EDCI417 or TLPL452.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'EDCI417.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL453', 'Life in Two Languages: Understanding Bilingual Communities and Individuals', 3, 3, 'Overview of society and individual multilingualism. Topics include diglossia, language shift, codeswitching, bilingual first language acquisition, language attrition, dual language education policy and practice.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('TLPL456', 'Teaching Writing', 3, 3, 'Examines current theory, research, best practice, curricula and materials for teaching written communication in grades K-12. Focuses on analytical, argumentative, informative/explanatory, literary analysis, narrative, descriptive, and research writing. Emphasizes instructional planning, assessment, writer problem-solving strategies, information search, development, organization and style appropriate to task, purpose and audience for both non-digital and digital text. English Language Learner and special needs pupil issues considered.', NULL, 'EDCI447.', FALSE, NULL, 'Must be in Secondary Educ: English Language Arts program; and minimum cumulative GPA of 2.75. Or permission of EDUC-Teaching and Learning, Policy and Leadership department.', 'EDCI467 or TLPL456.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'unstructured', 'none_found', NULL, 'EDCI467.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL457', 'Literature for Adolescents', 3, 3, 'Reading and analysis of fiction and nonfiction; methods for critically assessing quality and appeal; current theory and methods of instruction; research on response to literature; curriculum design and selection of books.', NULL, NULL, TRUE, 'DSHU', 'Minimum cumulative GPA of 2.75; and permission of EDUC-Teaching and Learning, Policy and Leadership department.', 'EDCI466 or TLPL457.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'verified', '202608', 'EDCI466.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL460', 'Materials and Instruction for Creating Skilled and Motivated Readers, Part I', 3, 3, 'Explains the educational research that addresses the acquisition of reading and its underlying processes, including research-based reading instruction and materials. Learn how to create a literacy learning environment that helps diverse learners become skilled and motivated readers through phonemic awareness, phonics, fluency, comprehension, vocabulary, and whole and small-group instructional approaches.', NULL, NULL, TRUE, NULL, 'Must be in Elementary Education program; and junior standing or higher. Or permission of EDUC-Teaching and Learning, Policy and Leadership department.', 'EDCI461 or TLPL460.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'EDCI461.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL461', 'Materials and Instruction for Creating Skilled and Motivated Readers, Part II', 3, 3, 'Selecting, evaluating, and using a variety of materials to create skilled and motivated readers in the elementary grades, particularly in diverse classroom settings; Topics include word analysis, spelling, writing, reading comprehension strategies, directed reading lessons, and explicit instruction.', 'TLPL361 and TLPL460.', 'TLPL312, EDCI342, TLPL321, and TLPL362.', FALSE, NULL, 'Minimum cumulative GPA of 2.75; and permission of EDUC-Teaching and Learning, Policy and Leadership department; and must be in Elementary Education program.', 'EDCI462 or TLPL461.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'unstructured', 'none_found', NULL, 'EDCI462.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL462', 'Reading in the Secondary School', 3, 3, 'Provides secondary school teachers with understanding the need for and approaches to teaching students to read and learn from content area texts.', NULL, NULL, TRUE, NULL, 'Minimum cumulative GPA of 2.75; and must be in one of the following programs (Middle School Education; Secondary Educ: Science; Secondary Educ: English Language Arts; Secondary Educ: Mathematics; Secondary Educ: Foreign Languages; Secondary Educ: Social Studies; Secondary Educ: Art) ; and permission of department required for post-baccalaureate students.', 'EDCI463 or TLPL462.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'EDCI463.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL470', 'Knowledge, Reasoning, and Learning in Secondary Social Studies', 3, 3, 'An exploration of the nature of knowledge and reasoning in social studies disciplines as well as how students learn social studies. Assessment and investigation of students'' conceptions and misconceptions as well as their disciplinary thinking. Implications for teaching and initial lesson design are explored through on-campus seminars as well as guided field experiences. Students should reserve a regular half-day per week for the field experience in local schools. This course is required for admission to the secondary social studies double major.', NULL, NULL, TRUE, NULL, 'Permission of EDUC-Teaching and Learning, Policy and Leadership department; and minimum cumulative GPA of 2.75.', 'EDCI426 or TLPL470.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'EDCI426.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL471', 'Curriculum, Teaching, and Assessment in Secondary Social Studies', 3, 3, 'An exploration of curriculum development, teaching, and assessment in secondary history/social studies. Focus on identifying students'' conceptions of social studies topics and designing lessons that advance students'' disciplinary thinking and understanding.', 'TLPL470.', 'EDCI428.', TRUE, 'DSSP', 'Must be in Secondary Educ: Social Studies program; and minimum cumulative GPA of 2.75. Or permission of EDUC-Center for Learning & Educational Technology.', 'EDCI427 or TLPL471.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'parsed', 'verified', '202608', 'EDCI427.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL475', 'Equitable Classrooms', 2, 2, 'An exploration and application of major theoretical frameworks surrounding equity and critical pedagogy. Creating habits of mind that help teachers see all students as capable of achieving at high levels. Draws on the concurrent field experience.', 'TLPL252, TLPL413, and TLPL420.', 'EDCI360 and TLPL423.', FALSE, NULL, 'Minimum cumulative GPA of 2.75; and must be in Middle School Education program.', 'EDCI424 or TLPL475.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'unstructured', 'none_found', NULL, 'EDCI424.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL476', 'Equity and Pedagogy', 2, 2, 'An exploration and application of major theoretical frameworks surrounding equity and critical pedagogy. Pedagogical decision making that leads to greater equity and improved student learning for all students. Draws on the concurrent student teaching experience.', 'TLPL475.', 'TLPL424 and EDCI460.', FALSE, NULL, 'Minimum cumulative GPA of 2.75; and must be in one of the following programs (Middle School Education; Early Childhood Education; Elementary Education; Secondary Educ: Science; Secondary Educ: English Language Arts; Secondary Educ: Mathematics; Secondary Educ: Foreign Languages; Secondary Educ: Social Studies; Physical Education; Music Education; Secondary Educ: Art; Special Education).', 'EDCI425 or TLPL476.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'unstructured', 'none_found', NULL, 'EDCI425.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL477', 'Teaching Academically, Culturally, and Linguistically Diverse Students in Middle School and Secondary Education', 2, 2, 'Instruction on methods of teaching academically, culturally, and linguistically diverse students in middle school and secondary classrooms.', NULL, NULL, TRUE, NULL, 'Must be in the teacher education program; or permission of EDUC-Teaching and Learning, Policy and Leadership department.', 'TLPL488B or TLPL477.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'TLPL488B.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL478', 'Professional Seminar in Education', 1, 3, 'Seminar on the issues and problems teacher candidates encounter in classrooms. Exploration of the skills and strategies that best address these challenges.', NULL, NULL, TRUE, NULL, 'Must be in a major within the EDUC-Teaching and Learning, Policy and Leadership department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'EDCI488.', NULL, NULL, '4 credits.', NULL, NULL),
    ('TLPL479', 'Field Experiences in Education', 1, 4, 'Field experiences in approved eduation setting with appropriate supervision. Credit not to be granted for experience accrued prior to registration. Open only to students admitted to approved teacher education programs.', NULL, NULL, TRUE, NULL, 'Permission of EDUC-Teaching and Learning, Policy and Leadership department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'EDCI489.', NULL, NULL, '2 credits.', NULL, NULL),
    ('TLPL481', 'Embracing Diversity in the Classroom Community', 3, 3, 'An exploration of the richness and complexity of student diversity that teacher candidates will encounter in PK12 classrooms. Students will engage in critical reflection around diversity and equity issues.', NULL, NULL, TRUE, NULL, 'Admission to teacher education program; or permission of EDUC-Teaching and Learning, Policy and Leadership department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('TLPL488', 'Special Topics in Education', 1, 3, 'Special and intensive treatment of current topics and issues in teaching, learning, policy and leadership.', NULL, NULL, TRUE, NULL, 'Permission of EDUC-Teaching and Learning, Policy and Leadership department.', 'EDPS488 or TLPL488.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'EDPS488.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL489', 'Internship in Education', 1, 12, 'Internship or residency experiences in school settings with appropriate supervision. Credit not to be granted for experience accrued prior to registration. Open only to students admitted to approved teacher education programs.', NULL, NULL, TRUE, NULL, 'Permission of EDUC-Teaching and Learning, Policy and Leadership department.', 'EDPS489 or TLPL489.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'EDPS489.', NULL, NULL, '12 credits.', NULL, NULL),
    ('TLPL498', 'Special Problems in Education', 1, 3, 'Exploration of current problems in teaching, learning, policy and leadership. Available only to students who have definite plans for study of approved problems.', NULL, NULL, TRUE, NULL, 'Permission of EDUC-Teaching and Learning, Policy and Leadership department.', 'EDPS498 or TLPL498.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'EDPS498.', NULL, NULL, NULL, NULL, NULL),
    ('TLPL499', 'Workshops, Clinics, and Institutes', 1, 6, 'The following type of educational enterprise may be scheduled under this course heading: Workshops conducted by the College of Education (or developed cooperatively with other colleges and universities) and not otherwise covered in the present course listing; clinical experiences in pupil-testing centers, reading clinics, speech therapy laboratories, and special education centers; institutes developed around specific topics or problems and intended for designated groups such as school superintendents, principals, and supervisors.', NULL, NULL, TRUE, NULL, NULL, 'EDPS499 or TLPL499.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tlpl/', 'none', 'none_found', NULL, 'EDPS499.', NULL, NULL, NULL, NULL, NULL),
    ('TLTC310', 'Leadership in Collaborative Learning Groups', 3, 3, 'Experiential learning opportunity that applies principles of leadership, peer mentoring, and learning theory to the planning and facilitation of peer-led collaborative learning sessions. Incorporates research, reasoning, evidence, and feedback to develop a reflective practice.', NULL, NULL, TRUE, 'DSSP', 'Restricted to students selected to participate in the Guided Study Sessions through the Teaching and Learning Transformation Center.', 'HESI318N or TLTC310.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tltc/', 'none', 'verified', '202608', 'HESI318N.', NULL, NULL, NULL, NULL, NULL),
    ('TLTC333', 'Fundamentals of Academic Peer Mentoring', 1, 1, 'How should scientific research influence the way we study and advance the academic performance of others? Learn about the scholarship of teaching and learning and develop the applied skills to support active learning as an academic peer mentor. Whether or not you ultimately pursue a career as an educator, the more effectively you can coach and support the performance of other people, and the more successful you will be. Guided online and face-to-face participation will culminate in a portfolio of your teaching activities and professional development.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tltc/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'This course is intended to be taken only once, in a student''s first semester as an AMP.'),
    ('TLTC399', 'Independent Study in Academic Peer Mentoring', 1, 3, 'Earn academic credit for the time spent supporting a course in TLTC''s Academic Peer Mentoring Program (AMP).', 'Must have completed or be concurrently enrolled in TLTC333.', NULL, TRUE, NULL, 'Permission of TLTC required - enrollment restriction.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tltc/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, '6 credits.', NULL, NULL),
    ('TLTC499', 'Independent Study in Teaching and Learning', 1, 3, 'Earn academic credit for the time spent supporting TLTC''s educational development programs and/or engaging in the scholarship of teaching and learning.', NULL, NULL, TRUE, NULL, 'Permission of TLTC required - enrollment restriction.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/tltc/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits.', NULL, NULL),
    ('UMEI001', 'English as a Foreign Language: Beginning', 12, 12, 'Intensive course for the non-native speaker of English who has little or no previous knowledge of English. Focus on the rapid acquisition of the basic features of English grammar and pronunciation and on speaking and understanding American English; reading and writing appropriate to the level will be included. Special fee required for this course. This course does not carry credit towards any degree at the University and does not count in the retention plan.', NULL, NULL, TRUE, NULL, 'Permission of EDUC-Dean-Maryland English Institute department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/umei/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('UMEI002', 'English as a Foreign Language: Intermediate I', 12, 12, 'Intensive course for the non-native speaker of English who has had some previous instruction in English. Emphasis on improving listening and speaking skills, on mastering intermediate grammatical structures, and on expanding vocabulary. Includes practice in reading and writing appropriate to the level. Special fee required for this course. This course does not carry credit towards any degree at the University and does not count in the retention plan.', NULL, NULL, TRUE, NULL, 'Permission of EDUC-Dean-Maryland English Institute department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/umei/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('UMEI003', 'English as a Foreign Language: Intermediate II', 12, 12, 'Intensive course for the non-native speaker of English who has mastered the essential structures of English grammar. Emphasis on improving communicative skills for a wide range of linguistic situations, on rapid expansion of vocabulary, and on improving reading comprehension and basic writing skills. Special fee required for this course. This course does not carry credit towards any degree at the University and does not count in the retention plan.', NULL, NULL, TRUE, NULL, 'Permission of EDUC-Dean-Maryland English Institute department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/umei/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('UMEI004', 'English as a Foreign Language: Intermediate III', 12, 12, 'Intensive course for the non-native speaker of English who has a good command of the basic features of spoken and written English. Emphasis on refining speaking and listening skills, on improving reading speed and comprehension of academic texts, and on developing writing skills for academic courses. Special fee required for this course. This course does not carry credit towards any degree at the University and does not count in the retention plan.', NULL, NULL, TRUE, NULL, 'Permission of EDUC-Dean-Maryland English Institute department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/umei/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('UMEI005', 'Advanced English as a Foreign Language', 6, 6, 'Semi-intensive course for the nearly proficient non-native speaker of English needing additional language instruction prior to undertaking full-time academic study. Speaking and listening skills; improvement of reading speed and comprehension; and development of writing skills. Special fee required for this course. This course does not carry credit towards any degree at the University and does not count in the retention plan.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/umei/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('UMEI011', 'Integrated English: Elementary', 5, 10, 'English as a Second Language course for students at the elementary level.', 'Placement exam; and permission of EDUC-Dean-Maryland English Institute department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/umei/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('UMEI012', 'Integrated English: Intermediate', 5, 10, 'English as a Second Language course for students at the intermediate level.', 'Placement exam; and permission of EDUC-Dean-Maryland English Institute department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/umei/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('UMEI013', 'Integrated English: Advanced', 5, 10, 'English as a Second Language for students at the advanced level.', 'Placement exam; and permission of EDUC-Dean-Maryland English Institute department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/umei/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('UMEI028', 'Special Topics in English as a Second Language', 1, 2, 'Focuses on particular English language topics for ESL student as indicated by title. Course intended to be taken concurrently with UMEI011, UMEI012, or UMEI013; but may be taken independently with special permission.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/umei/', 'none', 'none_found', NULL, NULL, NULL, NULL, '18 credits if content differs.', NULL, NULL),
    ('UNIV100', 'The Student in the University', 1, 1, 'Introduces students to University life. In a small classroom setting, students will explore how to successfully bridge the gap between high school and college. Study skills, career decision-making, and student development processes will be explored.', NULL, NULL, TRUE, NULL, NULL, 'EDCP108O or UNIV100.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/univ/', 'none', 'none_found', NULL, 'EDCP108O.', NULL, NULL, NULL, NULL, NULL),
    ('UNIV102', 'Confidence Building and Study Skills in Mathematics', 2, 2, 'A mathematics preparatory class designed to facilitate a student''s transition toward fundamental studies mathematics, including study skills and strategies for success.', NULL, NULL, TRUE, NULL, 'Must be in uTerp Individual Admits program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/univ/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('UNIV104', 'Reading and Writing at the College Level', 1, 1, 'A workshop designed to enhance students'' college level reading and writing abilities to include study skills and strategies for success.', NULL, NULL, TRUE, NULL, 'Must be in uTerp Individual Admits program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/univ/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('UNIV106', 'The Transfer Student in the University', 1, 1, 'This course is designed to assist students in making a successful transition to the University of Maryland (UMD) and to serve as an extended orientation to campus living and learning.', NULL, NULL, TRUE, NULL, 'Must be a first-semester transfer student.', 'UNIV106 or EDCP108G.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/univ/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('UNIV107', 'Science Technology Engineering Mathematics Colloquium', 1, 1, 'For students interested in pursuing a STEM related major. Introduces students to the fundamentals of career and major exploration and career development within the various disciplines of STEM.', NULL, NULL, TRUE, NULL, 'Must be a current student in Letters & Sciences.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/univ/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('UNIV108', 'Business Exploration Series Colloquium', 1, 1, 'For students interested in pursuing a business career. Students learn the fundamentals of career development and what the internship/job search process entails.', NULL, NULL, TRUE, NULL, 'Must be a current student in Letters and Science.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/univ/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('UNIV110', 'Grand Challenges of Our Time', 1, 1, 'An introduction to and solutions to society''s grand challenges. Students meet with President Pines once a week and then in small discussion sections with two instructors. Previous topics have included literacy, Black Lives Matter, Covid, environmental justice, poverty, and voting and civic engagement.', NULL, NULL, TRUE, NULL, 'Must have Freshmen standing; and permission of instructor.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/univ/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('UNIV190', 'National Scholarships for International Goals', 1, 1, 'Prepares first- and second-year students with international interests such as study abroad, language learning, and international careers to apply for nationally competitive scholarships, including how to write an effective personal statement. The course will help students focus and explore their interests, and connect these interests to current events. It will be of particular interest to students preparing for service-oriented and internationally focused careers.', NULL, NULL, TRUE, NULL, 'Freshman or Sophomore Standing.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/univ/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('UNIV218', 'Study Abroad Exploration', 3, 3, 'Topics and assignments will vary by travel site.', NULL, NULL, TRUE, NULL, 'Must be in designated Study Abroad programs.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/univ/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('UNIV269', 'Connecting Across Cultures', 1, 1, 'An examination of culture to guide study abroad students through the stages of cross cultural adjustment and to promote cultural competency by providing the motivation, knowledge and skills necessary to work with diverse individuals and teams.', NULL, NULL, TRUE, NULL, 'Must be in a study abroad program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/univ/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('UNIV318', 'Special Topics in Study Abroad', 3, 3, 'Topics and assignments will vary by travel site, as indicated by subtitles such as Italian Art, Chinese History, and French Theater.', NULL, NULL, TRUE, NULL, 'Must be in a designated Study Abroad program; and must not have six credits of CPSP379 if College Park Scholar student; and freshman standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/univ/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('UNIV339', 'McNair Research Methods and Writing', 2, 6, 'As an introduction to qualitative and quantitatvie research methods, students will be taught how to: (1) create, analyze, and disseminate knowledge conceptually and empirically; (2) write a research document; (3) use the IRB process; (4) develop research posters; (5) read and evaluate research studies; (6) read and understand statistics; (7) conduct interviews, develop surveys, and design experiments; and (8) communicate effectively to public audiences.', NULL, NULL, TRUE, NULL, 'Must have earned a minimum of 60 credits.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/univ/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('UNIV348', 'Federal Semester Seminar', 3, 3, 'This topical seminar will approach Federal policy formation through a combination of framework-based and content-specific considerations. Content and themes will vary. The Federal Semester is an offering of the Office of Undergraduate Studies in conjunction with several academic colleges and the University Career Center.', NULL, NULL, TRUE, NULL, 'Must be in the Federal Semester program; and permission of UGST-Undergraduate Studies; and junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/univ/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('UNIV349', 'Federal Semester Experiential Learning', 1, 6, 'This is the internship component of the Federal Semester program, an offering of the Office of Undergraduate Studies in conjunction with several academic colleges and the University Career Center.', 'UNIV348.', NULL, TRUE, NULL, 'Must be in the Federal Semester program; and must have a Learning proposal approved by the Office of Undergraduate Studies and student''s internship sponsor; and junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/univ/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('UNIV362', 'Designing Your Life after College', 2, 2, 'Helps students anticipate and prepare for changes in finances, social life, health, and career dynamics they are likely to experience as they transition from college to working full-time. It focuses on understanding what resources students have as they enter the workforce as critical for navigating post-graduation changes successfully. It offers an overview of financial, risk management and professional development approaches to increase students'' confidence regarding post-graduation decisions; in addition, it develops their creative problem solving and reflection skills to help them align the outcomes of their decisions with their values.', NULL, NULL, TRUE, NULL, 'Must have earned a minimum of 60 credits.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/univ/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('UNIV378', 'Beyond the Classroom Experiential Learning', 1, 3, 'This is the internship component of the Beyond the Classroom program in which students hold internships at organizations such as governmental units and non-profit agencies.', 'UNIV325.', NULL, FALSE, NULL, 'Must be in the Beyond the Classroom program; and must have proposal approved by director of Beyond the Classroom.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/univ/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('UNIV389', 'Special Topics in Undergraduate Studies', 3, 3, 'Courses will focus on interdisciplinary topics and will be planned in cooperation with Undergraduate Studies.', NULL, NULL, TRUE, NULL, 'Freshman standing.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/univ/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('UNIV399', 'Experiential Learning in Undergraduate Studies', 1, 3, 'Experiential learning offered in conjunction with certain designated Office of Undergraduate Studies programs.', NULL, NULL, TRUE, NULL, 'Must have a Learning proposal approved by the Office of Undergraduate Studies and student''s internship sponsor; and junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/univ/', 'none', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('URSP250', 'The Sustainable City: Exploring Opportunities and Challenges', 3, 3, 'An exploration, through an interdisciplinary approach, of a number of issues related to making cities more sustainable in terms of environmental protection, economic opportunity, and social justice. The course assist students to develop skills in critical analysis and systems thinking and to use those skills in analyzing sustainability related problems and potential solutions, and to expand students'' understanding of the political implications of crafting and moving towards a sustainable urban future.', NULL, NULL, TRUE, 'DSSP, SCIS', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ursp/', 'none', 'verified', '202608', NULL, NULL, NULL, NULL, NULL, NULL),
    ('URSP372', 'Diversity and the City', 3, 3, 'Exploration of the different needs of diverse economic, racial/ethnic, and gender groups that live and work in cities, the historical background of differences, the impact of societal structures and group cultures, and how public and private policies do and can affect different groups.', NULL, NULL, TRUE, 'DVUP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ursp/', 'none', 'verified', '202601', NULL, NULL, NULL, NULL, NULL, NULL),
    ('URSP488', 'Selected Topics in Urban Studies and Planning', 1, 3, 'Topics of special interest to advanced urban studies students.', 'Permission of ARCH-Urban Studies & Planning Program program.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/ursp/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('USLT201', 'U.S. Latina/o Studies I: An Historical Overview to the 1960''s', 3, 3, 'Interdisciplinary course focusing on demographics, terminology and social constructs of race, class, ethnicity, indigeneity, gender, and sexuality associated with the historical and political roots of US Latinidades. Examines the formation, evolution an adaptation of US Latina/o communities as critical field of inquiry.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/uslt/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('USLT202', 'US Latina/o Studies II: A Contemporary Overview 1960''s to present', 3, 3, 'Interdisciplinary course on emerging populations of Latinos in the 20th century with a focus on the multiple waves of latino immigration as a result of neocolonialism, imperialism, globalization and transnationalism. Examines the positioning of immigrant waves in the political, sociocultural and historical contexts of US Latinidades.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/uslt/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('USLT269', 'Special Topics in Study Abroad II', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/uslt/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('USLT320', 'Afro-Latinx Diasporas', 3, 3, 'Examines the history of the African diaspora and the Afro-Latinx populations in the United States. Explores transnational migrations, comparative slave systems, labor, community formation, gender, sexuality, popular culture, and the changing meanings of blackness and latinidad.', NULL, NULL, TRUE, NULL, NULL, 'USLT319A, USLT320, or AMST328E.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/uslt/', 'none', 'none_found', NULL, 'USLT319A.', NULL, NULL, NULL, NULL, NULL),
    ('USLT369', 'Special Topics in Study Abroad III', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/uslt/', 'none', 'none_found', NULL, NULL, NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('USLT401', 'Latinas/os and US Popular Culture', 3, 3, 'An examination of the relationship between Latinas/os and popular culture in the United States. Using theoretical lenses drawn from cultural studies, visual culture studies, critical race theory, borderlands theory, and feminism, the course analyzes multiple texts from time frames past and present. Explores issues such as exclusion from and inclusion within US identity, transnational identifications and cultural flows, ethnoracial stereotyping and resistance to it, and intersections of Latina/o identity with aspects of class, race, sexuality, and gender. Investigates art, TV, music, cinema, and everyday lived experience.', NULL, NULL, TRUE, NULL, NULL, 'USLT401, USLT498B, or AMST498M.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/uslt/', 'none', 'none_found', NULL, 'USLT498B.', NULL, NULL, NULL, NULL, NULL),
    ('USLT403', 'Citizens, Refugees, and Immigrants', 3, 3, 'Citizenship, Refugee and Immigrant are guiding categories that often define the Latina/o community in the United States. Employing this analytical lens, this course critically engages with notions of exclusion and inclusion, which included documentation, status, race, gender, and power. To better understand how these ideas and processes work, students are introduced to the history of Latina/o migration, US immigration policies, racial formation theory, gender construction, borderland theory, and the politics of territoriality.', NULL, NULL, TRUE, NULL, NULL, 'USLT403, USLT498I, AMST498N, or IMMR419D.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/uslt/', 'none', 'none_found', NULL, 'USLT498I.', NULL, NULL, NULL, NULL, NULL),
    ('USLT420', 'U.S. Latinas/os on the Silver Screen: The Silent Era to the Present Day.', 3, 3, 'Combining media theory and film history, this course considers the film industry''s relationship to Latinidad, examining issues such as the shift from silent film to sound, the impact made on Latina/o images by the Second World War, and Latinas/os in the Red Scare. The second half of the course turns its attention to self-representation by Latina/o filmmakers and empathetic images created by whites in and after the 1970s. Some of the questions that the course addresses include: How have Latinas/os been depicted in Hollywood history? How have inter-American foreign relations shaped the US Latina/o image? How have Latina/o filmmakers confronted issues such as racism and sexism in the United States?', NULL, NULL, TRUE, NULL, NULL, 'USLT420, USLT498A or AMST498G.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/uslt/', 'none', 'none_found', NULL, 'USLT498A.', NULL, NULL, NULL, NULL, NULL),
    ('USLT430', 'Globalization and the Diversifying U.S.', 3, 3, 'While often talked about as a recent phenomenon and one focused on capital, the ebbs and flows of globalization has a long history among Latina/o communities in the United States. The impact and consequences of globalization can be seen in US foreign policy in Latin America. For instance, Operation Bootstrap in Puerto Rico and the Maquiladores on the Mexico and U.S. border. At the same time, it has shaped immigration policies and the social. political and cultural experiences of Latina/o workers in the U.S. Often blamed for "taking " jobs, this course takes a deeper look at the concrete reasons for the rise of globalism and its impact on Latina/o communities in the US.', NULL, NULL, TRUE, NULL, NULL, 'USLT430, USLT498N, AMST498W, or IMMR419J.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/uslt/', 'none', 'none_found', NULL, 'USLT498N.', NULL, NULL, NULL, NULL, NULL),
    ('USLT450', 'Central Americans and the United States: Culture, Politics, and Community', 3, 3, 'With attention to history, memory, politics, and culture, this course examines the relationships, conflicts, and exchanges of people and power between the United States and the Central American isthmus. We will investigate the role of the US government and military, as well as US corporate interests and US-backed dictatorships, in the culture, politics, and economy of nations including El Salvador, Nicaragua, Guatemala, and Honduras. Through literature, feature films, documentary films, theatre, poetry, and other mediums, the class will analyze responses to this history in Central American cultural productions originating both from the isthmus and from Central Americans living in the United States. In addition to US interventions in the Americas, the course will examine migration from Central America to North America and will conclude by exploring the lives and activities of Central Americans living in the USA.', NULL, NULL, TRUE, NULL, NULL, 'AMST498C, USLT450 or USLT498D.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/uslt/', 'none', 'none_found', NULL, 'USLT498D.', NULL, NULL, NULL, NULL, NULL),
    ('USLT460', 'Revolutions and Diasporas', 3, 3, 'How have revolutions in Latin America influenced the history of US immigration, refugee, and asylum policies? How have they changed US history, culture, experience, geography, politics and the future? This course examines both the history of major revolutions in Latin America and their impact on Latinx diasporic and immigrant communities in the US. It investigates questions of slavery and freedom US expansionism, radical politics, Third World liberation movements, and the politics of asylum and US immigration policies. Students in the course will learn transnationalist, diasporic, borderlands and other forms of Latinx historical methods. In addition, the course will focus on race, class, gender, sexuality, and the politics of location.', NULL, NULL, TRUE, NULL, NULL, 'USLT460, USLT498R, or AMST498B .', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/uslt/', 'none', 'none_found', NULL, 'USLT498R.', NULL, NULL, NULL, NULL, NULL),
    ('USLT480', 'Race and Nation in U.S. Cinema', 3, 3, 'From the 1915 release of D.W. Griffith''s The Birth of a Nation to the present, cinema has been a crucial medium through which cultural producers have advanced and contested concepts of ethnoracial and national identity in the US. This course adopts a historically-grounded practice of media criticism to understand the ideology and iconography of both Hollywood''s studio system and independent cinema. The course requires students to examine film and identity through multiple, racial, methodological and theoretical lenses, including film history, and film and media theory. Focus will be the cinematic politics and poetics of racial exclusion and inclusion, empathy and disidentification, power and resistance, and the shaping of a national "imagined community." We will pursue how ideas about class, sexuality, gender, and disability have informed ideologies concerning race and nation. Classes will be divided between lecture, film viewings, and, most importantly, class discussions.', NULL, NULL, TRUE, NULL, NULL, 'AMST498P, USLT480, or USLT498C.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/uslt/', 'none', 'none_found', NULL, 'USLT498C.', NULL, NULL, NULL, NULL, NULL),
    ('USLT488', 'US Latina/o Senior Seminar', 3, 3, 'A variable topics seminar that exposes students to interdisciplinary critical readings, writings, and research in U.S. Latina/o Studies. Interdisciplinary research methodologies are broadly addressed. Students will gain skills and practice in reading critical analytic texts and will develop writing skills.', NULL, NULL, TRUE, NULL, 'Senior standing; and permission of instructor.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/uslt/', 'none', 'none_found', NULL, NULL, NULL, NULL, '9 credits if content differs.', 'USLT202 or USLT201.', NULL),
    ('USLT498', 'US Latina/o Studies: Special Topics', 3, 3, 'Specific content to be announced when courses are offered.', 'USLT202 or USLT201.', NULL, TRUE, NULL, 'Junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/uslt/', 'parsed', 'none_found', NULL, NULL, NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('VIPS208', 'Starting with Vertically Integrated Projects', 1, 2, 'Team members beginning their experience with VIP@Maryland will engage on interdisciplinary and vertically-integrated teams with a focus on research, design, industry competition, entrepreneurship, and community engagement projects related to active research and exploration areas of UMD faculty members. Students will also participate in lectures and professional development activities that include topics related to design, research, documentation and technical writing, communication, leadership and teamwork, ethics, project management, intellectual property, information literacy, and introduction to a broad range of applicable research topics, technologies and development tools. Students are expected to maintain involvement with the same project team for multiple terms.', NULL, NULL, TRUE, NULL, 'Permission of ENGR-Dean-Office of Global Engineering Leadership.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/vips/', 'none', 'none_found', NULL, NULL, NULL, NULL, '8 credits.', NULL, 'Students must apply through the VIP@Maryland application process in order to join a VIP team. For more information: go.umd.edu/vipmaryland.'),
    ('VIPS308', 'Engaging with Vertically Integrated Projects', 1, 2, 'Team members will expand their role and responsibilities on their selected VIP@Maryland team. They will engage on interdisciplinary and vertically-integrated teams with a focus on research, design, industry competition, entrepreneurship, and community engagement projects related to active research and exploration areas of UMD faculty members. Students will also participate in lectures and professional development activities that include topics related to design, research, documentation and technical writing, communication, leadership and teamwork, ethics, project management, intellectual property, information literacy, and introduction to a broad range of applicable research topics, technologies and development tools. Students are expected to maintain involvement with the same project team for multiple terms.', NULL, NULL, TRUE, NULL, 'Permission of ENGR-Dean-Office of Global Engineering Leadership.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/vips/', 'none', 'none_found', NULL, NULL, NULL, NULL, '8 credits.', NULL, 'Students must apply through the VIP@Maryland application process in order to join a VIP team. For more information visit: go.umd.edu/vipmaryland.'),
    ('VIPS408', 'Leading with Vertically Integrated Projects', 1, 2, 'Advanced team members will take on mentorship and leaderships roles within their VIP@Maryland project. They will engage on interdisciplinary and vertically-integrated teams with a focus on research, design, industry competition, entrepreneurship, and community engagement projects related to active research and exploration areas of UMD faculty members. Students will also participate in lectures and professional development activities that include topics related to design, research, documentation and technical writing, communication, leadership and teamwork, ethics, project management, intellectual property, information literacy, and introduction to a broad range of applicable research topics, technologies and development tools. Students are expected to maintain involvement with the same project team for multiple terms.', NULL, NULL, TRUE, NULL, 'Permission of ENGR-Dean-Office of Global Engineering Leadership.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/vips/', 'none', 'none_found', NULL, NULL, NULL, NULL, '12 credits.', NULL, 'Students must apply through the VIP@Maryland application process in order to join a VIP team. For more information: go.umd.edu/vipmaryland.'),
    ('WEID138', 'Bridging Divides thru Intergroup Dialogue Across Disciplines', 1, 1, 'Through deliberate reflections on the past and current patterns of exclusion and inclusion within your disciplinary field, you will develop skills for engaging in equitable and inclusive processes and practices that can transform your collaborations and approach to your discipline. This course engages students, from multiple social identity groups, in facilitated dialogue that focus on the tensions, similarities, and differences of experience that exist within, between, and/or across groups.', NULL, NULL, TRUE, NULL, 'CPSP110 restricted to students in College Park Scholars.', 'EDDI110 or CPSP110.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/weid/', 'none', 'none_found', NULL, NULL, 'EDDI110.', NULL, NULL, NULL, NULL),
    ('WEID139', 'Navigating Difference through Intergroup Dialogue', 1, 1, 'The goal of intergroup dialogue is for students to develop comfort with, and skill for, discourse on controversial, difficult, and divisive topics in an effort to foster positive, meaningful, and sustained cross-group relationships. Whereas in debate, students learn to listen to gain advantage, in intergroup dialogue, students learn to listen to gain understanding. In so doing, students develop increased capacity for interaction across difference, heightened intergroup awareness and sensitivity, and greater commitment to community engagement.', 'Completion of on-line enrollment form.', NULL, FALSE, NULL, NULL, 'CHSE338, EDHI338, ENES338 or WEID139.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/weid/', 'unstructured', 'none_found', NULL, 'CHSE338.', 'ENES338.', NULL, '6 credits.', NULL, NULL),
    ('WGSS105', 'Introduction to Disability Studies', 3, 3, 'Explores theories of disability justice as they intersect with feminist and antiracist struggles. Analyzing how disability has been an important aspect of institutions and social experience in the United States and beyond, the course considers how disability activists have responded to ableism by developing art, political strategies, and subcultures that promote a more just society built for a wider variety of human bodies.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, 'WGSS105, AMST215, or AMST298D.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'verified', '202605', 'AMST298D.', 'AMST215.', NULL, NULL, NULL, NULL),
    ('WGSS115', 'Gender, Race and Computing', 3, 3, 'Race and gender have shaped computing from its earliest histories to contemporary debates over bias in search algorithms, surveillance, and AI. As computational processes shape ever more dimensions of everyday life from the personal to the global scale, understanding how they operate and how power operates within them grows ever more important. Combating racism and sexism is not as simple as ensuring the pool of programmers and engineers is more diverse; structures of power are embedded in digital technologies as they are in all aspects of our society, and we must learn to perceive their operation if we hope to transform them. We will examine how racism and sexism operate in the field of computer science and in everyday uses of digital technologies, while studying how feminist and racial justice movements have created alternative approaches. This class is for anyone who wishes to better understand the relationships between digital technology, structural power, and social justice.', NULL, NULL, TRUE, 'DSSP, DVUP', 'Must not have taken CMSC216 or higher.', 'WGSS115 or CMSC115.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'verified', '202601', NULL, 'CMSC115.', NULL, NULL, NULL, NULL),
    ('WGSS200', 'Gender, Power, and Society', 3, 3, 'Examines constructions of race, class, sexuality, ability, and gender relations from a social science multi-disciplinary perspective. The course interrogates the ways that systems of hierarchy and privilege are created, enforced, and intersect through the language of race, class, sexuality, and national belonging. The course will provide students with the skills to examine how systems of power manifest in areas such as poverty, division of labor, health disparities, policing, violence. In addition to examining the impact of systems of power, students will reflect on their own location within the exercise of racialized, and gendered power relations. This course encourages students to understand and critique these systems both personally and politically.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'WMST200 or WGSS200.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'verified', '202608', 'WMST200.', NULL, NULL, NULL, NULL, NULL),
    ('WGSS201', 'Queer Worlds: Studies in Gender and Sexuality', 3, 3, 'An interdisciplinary study of the historical and social contexts of queer and trans life. Explores the social meanings of sex and gender in our current moment; traces the formation of LGBTQ+ social and cultural movements; unpacks the categorization of genders and sexualities.', NULL, NULL, TRUE, NULL, NULL, 'LGBT200 or WGSS201.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, NULL, 'LGBT200.', NULL, NULL, NULL, NULL),
    ('WGSS205', 'Reproductive Justice: An Introduction', 3, 3, 'Developed by feminists of color, reproductive justice frameworks offer a roadmap for economic, social, and medical justice advocacy attentive to the intersections of race, class, gender, sexuality, and disability. This course reviews the historical, legal, and social bases of reproductive rights in the U.S.; discusses the history of feminist organizing for reproductive freedom; surveys critical theories of reproductive justice that go beyond abortion law to advocate for broader social transformation; and evaluates the possible futures of intersectional feminist activism after the overturning of Roe v. Wade.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'WGSS205, AMST298J, or AAAS298E.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'verified', '202608', NULL, 'AAAS298E, AMST298J.', NULL, NULL, NULL, NULL),
    ('WGSS210', 'Love, Labor, and Citizenship: Women in America to 1880', 3, 3, 'An examination of the economic, family, and political roles of colonial slave, immigrant and frontier women in America from the pre-industrial colonial period through the early stages of 19th-century industrialization and urbanization.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'HIST210, WMST210 or WGSS210.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'verified', '202605', 'WMST210.', 'HIST210.', NULL, NULL, NULL, NULL),
    ('WGSS211', 'Women in America Since 1880', 3, 3, 'An examination of women''s changing roles in working class and middle class families, the effects of industrialization on women''s economic activities and status, and women''s involvement in political and social struggles, including those for women''s rights, birth control, and civil rights.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'HIST211, WMST211 or WGSS211.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'verified', '202608', 'WMST211.', 'HIST211.', NULL, NULL, NULL, NULL),
    ('WGSS212', 'Women in Western Europe 1750-Present', 3, 3, 'An analysis of the economic, family, and political roles of European women from 1750 to the present. The effects of industrialization on women''s work and status, the demographic parameters of women''s lives, and women''s participation in political events from market riots to suffrage struggles.', NULL, NULL, TRUE, NULL, NULL, 'HIST212, WMST212 or WGSS212.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST212.', 'HIST212.', NULL, NULL, NULL, NULL),
    ('WGSS221', 'Gender in Sequence: Queering Comics', 3, 3, 'Comics push the boundaries of representation in art, tempting curious readers with the hybrid possibilities that come from combining words and images. American comics have been met with restrictions due to reactionary fears about corrupting children. However, comics have a long history of challenging the status quo and forging a space for queer, women, and other marginalized communities to share their experiences through sequential art. With a focus on comics, zines, and self-published narrative images by trans, queer, and women artists, students explore the possibilities of comics as a medium of subversion and possibility. Read comics by Alison Bechdel, Bishakh Som, Lynda Barry, Julie Doucet, and others, and explore the image-texts that reshaped queer arts and literature. Students create their own comics in the tradition of boundary breaking narrative art. Prior experience in drawing is not required for success in this class.', NULL, NULL, TRUE, NULL, NULL, 'WGSS221 or LGBT221.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, NULL, 'LGBT221.', NULL, NULL, NULL, NULL),
    ('WGSS230', 'Introduction to Humanities, Health, and Medicine', 3, 3, 'An overview of the historical, cultural, ethical, and spiritual dimensions of medicine, human health, disease, and death from the points of view of various humanistic disciplines.', NULL, NULL, TRUE, 'DSHU', 'Permission of ARHU-History Department.', 'ARHU230 , ENGL289C, ENGL254, ARHU298A, HIST219N, or WGSS230.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'verified', '202601', NULL, 'ARHU230, ENGL254, HIST219N.', NULL, NULL, NULL, NULL),
    ('WGSS238', 'Topics in LGBTQ+ Studies', 3, 3, 'Topics in the LGBTQ+ Studies program taught in the Harriet Tubman Department of Women, Gender, and Sexuality Studies.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, NULL, 'LGBT238.', NULL, '9 credits if content differs.', NULL, NULL),
    ('WGSS250', 'Gender, Art, and Culture', 3, 3, 'Provides students with a critical introduction to the ways that art and art activism have served as a conduit to understanding and challenging systems of inequity and practices of normativity. Interrogating the categories of gender, sexuality, race, class, ability, the course will provide students with an examination of how artists have responded to pressing social justice issues of their eras. While the course centers visual art, students will also engage genres such as music, plays, literature, digital and performance art as arenas of social change.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, 'WMST250 or WGSS250.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'verified', '202608', 'WMST250.', NULL, NULL, NULL, NULL, NULL),
    ('WGSS255', 'Reading Women Writing', 3, 3, 'Explores literary and cultural expressions by women and their receptions within a range of historical periods and genres. Topics such as what does a woman need in order to write, what role does gender play in the production, consumption, and interpretation of texts, and to what extent do women comprise a distinct literary subculture. Interpretation of texts will be guided by feminist and gender theory, ways of reading that have emerged as important to literary studies over the last four decades.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, 'ENGL250, WMST255 or WGSS255.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'verified', '202608', 'WMST255.', 'ENGL250.', NULL, NULL, NULL, NULL),
    ('WGSS263', 'Introduction to Black Women''s Studies', 3, 3, 'Interdisciplinary exploration of Black women, culture and society in the United States. Drawn primarily from the social sciences and history with complementary material from literature and the arts.', NULL, NULL, TRUE, NULL, NULL, 'WMST263, AASP298I, WGSS263, AAAS263 or AASP263.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST263.', 'AAAS263.', NULL, NULL, NULL, NULL),
    ('WGSS264', 'Quare/Queer Contentions: Exploration of Sexualities in the Black Community', 3, 3, 'Centering the subjectivities of queer people of color generally and more specifically, Black people (as the word "quare" invites us to do), Quare/Queer Contentions takes up key moments within the history of the Black community and asks us to consider the work and presence of LGBTQ people in these moments. The course also contends with the everyday experiences of LGBTQ subjects in the Black community. Quare/Queer Contentions, therefore, interrogates the material realities of Black queer people in the context of family, religion, cultural/creative work, among others. Interdisciplinary in orientation, the course will employ primary and secondary texts, film, art, autobiographical narratives and policy data.', NULL, NULL, TRUE, NULL, NULL, 'LGBT264, AASP264, AAAS264, WMST264 or WGSS264.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, NULL, 'LGBT264, AAAS264.', NULL, NULL, NULL, NULL),
    ('WGSS265', 'Constructions of Manhood and Womanhood in the Black Community', 3, 3, 'Investigates the ways that African Americans are represented and constructed in public and private spheres and explores the social constructions and representations of Black manhood and womanhood from various disciplinary perspectives.', NULL, NULL, TRUE, 'DSHS, DVUP', NULL, 'WMST265, AASP298B, AAAS265, WGSS265 or AASP265.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'verified', '202601', 'WMST265.', 'AAAS265.', NULL, NULL, NULL, NULL),
    ('WGSS267', 'Introduction to Black Women''s Cultural Studies', 3, 3, 'An introduction to black women''s cultural production and to an understanding of how the social norms and ideals about women within black communities and in the larger society have shaped black women''s own self-perceptions and behaviors and thus their cultural production.', NULL, NULL, TRUE, NULL, NULL, 'WMST267 or WGSS267.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST267.', NULL, NULL, NULL, NULL, NULL),
    ('WGSS269', 'Special Topics in Study Abroad II', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST269.', NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('WGSS271', 'Monsters and Racism: Black Horror and Speculative Fiction', 3, 3, 'The previous decade has been considered a renaissance for Black Horror. From Get Out to Lovecraft Country, the genre has enjoyed unprecedented mainstream media buzz and accolades. This course looks at contemporary Black horror and speculative fiction as cultural texts which put into question our notions of human(e) and inhuman(e) through critiques of white supremacy and accompanying oppressions. Students will learn a host of critical skills through close reading and analysis of literature and film by Black creators such as Jordan Peele, Misha Green, Toni Morrison, Jewelle Gomez, and Octavia Butler. With the ability to interpret cultural texts using literary criticism, film analysis, history, cultural studies, ethnic studies, feminist theory, and the social sciences, students will connect these texts to continuing historical and contemporary issues of racial and cultural oppression such as medical discrimination, policing and criminalization, misogynoir, and racialized capitalism.', NULL, NULL, TRUE, 'DSHU', NULL, 'AAAS271, ENGL289J, HONR299Y, HNUH238W, WGSS271 or WGSS298W.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'verified', '202608', 'HNUH238W.', 'AAAS271, ENGL289J.', NULL, NULL, NULL, NULL),
    ('WGSS275', 'World Literature by Women', 3, 3, 'Comparative study of selected works by women writers of several countries, exploring points of intersection and divergence in women''s literary representations.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, 'WMST275, CMLT275 or WGSS275.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'verified', '202608', 'WMST275.', 'CMLT275.', NULL, NULL, NULL, NULL),
    ('WGSS280', 'Gender and Science in Film and Media', 3, 3, 'Isaac Asimov once said of science fiction that it is the genre that "deals with the reaction of human beings to changes in science and technology." With this definition in mind, we will embark on a critical exploration of sci-fi film and other media, using it as a lens for analyzing society''s deepest fears and most furtive hopes. Our investigation will center on the liminal space between hegemonic culture and its prescribed excesses. These liminal spaces--between self and other, disability and enhancement, cultural hybridization, and gender crossing--shift in response to real-world sociopolitical tensions. We will consider feminist and anti-racist media scholars'' concerns over representation, authorship and ideology alongside questions of technological change. Students will use analytical and creative assignments to explore not only how the scientific imaginary serves as fertile ground for feminist, disability, and anti-racist critique, but also provides a locus for alternative futures.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, 'ENGL289I or WGSS280.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'verified', '202508', NULL, 'ENGL289I.', NULL, NULL, NULL, NULL),
    ('WGSS288', 'Special Topics in LGBTQ Studies', 3, 3, 'Study of particular themes and issues in LGBTQ studies.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, NULL, 'LGBT288.', NULL, '9 credits if content differs.', NULL, NULL),
    ('WGSS290', 'Bodies in Contention', 3, 3, 'Explores the contributions of feminist scholarship in framing and resolving contemporary controversies concerning gendered bodies. It includes the ways in which knowledge about the human body has been shaped by cultural ideas of gender, race, sexuality and ability.', NULL, NULL, TRUE, 'DSHS, DVUP, SCIS', NULL, 'WMST298D or WGSS290.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'verified', '202608', 'WMST298D.', NULL, NULL, NULL, NULL, NULL),
    ('WGSS291', 'Racialized Gender and Rebel Media', 3, 3, 'An introduction to the interdisciplinary field of women''s studies and an exploration of the ways in which media has been used as a platform for racial justice, feminist activism, and cultural transformation, with a principal focus on the expressions of women of color. The goals of the course are to explore how different forms of media shape the stories which circulate about race, femininities, masculinities, ethnicities, sexualities, religiosity, power and difference, and to examine how various media formats been used to disrupt dominant stories, to tell new stories, and to create differing understandings of citizenship.', NULL, NULL, TRUE, 'DSSP', NULL, 'WGSS291 or WMST298N.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'verified', '202608', 'WMST298N.', NULL, NULL, NULL, NULL, NULL),
    ('WGSS298', 'Special Topics in Women, Gender, and Sexuality Studies', 1, 3, 'Thematic exploration of a topic in women, gender, and sexuality studies.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST298.', NULL, NULL, '6 credits if content differs.', NULL, NULL),
    ('WGSS298L', 'History of Sexuality in America', 3, 3, 'Explores the social construction of sexualities from the first colonial settlement to the modern era in the United States. Analyzes the implications of these understandings for power relations in U.S history.', NULL, NULL, TRUE, NULL, NULL, 'HIST213, WMST298L or WGSS298L.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, NULL, 'HIST213.', NULL, NULL, NULL, NULL),
    ('WGSS298N', 'The Politics of Sexuality in America: A Historical Approach', 3, 3, 'Why do particular issues about sexuality hold such an important place in American political debates? What animates these controversies and what can a historical perspective on these issues add to our understanding of modern sexual politics? This class explores the historical sexual politics that undergird contemporary debates concerning sexuality in America. It focuses on topics that garner significant public attention - Reproductive rights - LGBTQ rights - Sexting - and explores the histories that undergird Americans disagreements.', NULL, NULL, TRUE, NULL, NULL, 'HIST289N or WGSS298N.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, NULL, 'HIST289N.', NULL, NULL, NULL, NULL),
    ('WGSS301', 'Feminist Knowledge Production', 3, 3, 'An introductory research skill-building course rooted in the ethical and political questions we ask when we work in communities struggling for a more just future. We will consider the fundamentals of scholarly research -- library skills, conceptualizing a research question, evaluating sources, understanding citation -- before we move on to consider broader ethical concerns about research and issues that arise in collaborative learning and community based projects. Anti-colonial, critical race, feminist, and queer theories, and ethics of research will be foundational to this class.', '3 credits from the WGSS Intro requirement course list: LGBT200, WGSS201, WGSS105, WGSS200, WGSS205, WGSS250, or WGSS263.', NULL, FALSE, NULL, 'Must be in an undergraduate program in the Harriet Tubman Department of Women, Gender, and Sexuality Studies.', 'WMST301 or WGSS301.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'unstructured', 'none_found', NULL, 'WMST301.', NULL, NULL, NULL, NULL, NULL),
    ('WGSS302', 'Feminist, Critical Race, and Queer Theories', 3, 3, 'Introduces students to some of the major concepts in feminist, critical race, and queer theories. It examines the questions: What is theory? What forms does theory take? What is the relationship between theory and practice? What is the role of theory in political and social action? In art? In personal life? What does it mean to do theory?', '6 credits in LGBT, WMST, WGSS or courses that are cross-listed with these.', NULL, FALSE, NULL, NULL, 'WMST302, WGSS302 or WMST400.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'unstructured', 'none_found', NULL, 'WMST302.', NULL, NULL, NULL, NULL, NULL),
    ('WGSS305', 'Disability Justice', 3, 3, 'Disability Justice examines disability as a category of analysis within intersecting systems of race, gender, sexuality, and class. Tracing the emergence of disability justice from feminist, queer, and critical race theory, the course engages humanistic methods to analyze historical and contemporary movements, social theory, and cultural production. Students will conduct independent and collaborative research projects, apply textual and archival analysis to activist and theoretical materials, and complete case studies on education, policy, or technology. Through critical writing, peer workshops, and community-based projects, students will develop the interpretive and practical skills necessary to connect humanistic inquiry with the principles of access, interdependence, and collective liberation.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, 'WGSS319D or WGSS305.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'verified', '202608', 'WGSS319D.', NULL, NULL, NULL, NULL, NULL),
    ('WGSS310', 'Transgender Studies', 3, 3, 'Introduces students to the interdisciplinary field of transgender studies, providing a history of the field and engaging current debates within it. Students will explore the emergence and consolidation of trans identities, practices, cultures, and knowledges across medical, historical, sociological, cultural, and artistic contexts, paying particular attention to dynamics of race, class, and ability, to global and transnational difference, and to the implications of transgender studies for understanding gender and sexuality overall.', 'LGBT200 .', NULL, TRUE, NULL, NULL, 'LGBT310, WMST310 or WGSS310.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'parsed', 'none_found', NULL, NULL, 'LGBT310.', NULL, NULL, NULL, NULL),
    ('WGSS314', 'Black Women in United States History', 3, 3, 'Black American women''s history from slavery to the present. Focused on gaining a fuller understanding of the effect of race, class and gender on the life cycles and multiple roles of Black women as mothers, daughters, wives, workers and social-change agents.', NULL, NULL, TRUE, NULL, 'Sophomore standing or higher.', 'AASP313, AAAS313, WMST314 or WGSS314.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST314.', 'AAAS313.', NULL, NULL, NULL, NULL),
    ('WGSS315', 'Intro to Fat Studies: Fatness, Blackness and Their Intersections', 3, 3, 'Examines fatness as an area of human difference subject to privilege and discrimination that intersects with other systems of oppression based on gender, race, class, sexual orientation, and ability. Though we will look at fatness as intersectional, this course will particularly highlight the relationship between fatness and Blackness. We approach this area of study through an interdisciplinary humanities and social-science lens which emphasizes fatness as a social justice issue. The course closes with an examination of fat liberation as liberation for all bodies with a particular emphasis on performing arts and activism as a vehicle for liberation and challenging fatmisia.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'verified', '202601', NULL, NULL, NULL, NULL, NULL, NULL),
    ('WGSS319', 'Workshops in Gender, Race, and Queer Studies', 3, 3, 'Topics will change each semester but all workshops will be designed to have students think transdisciplinarily and interdisciplinarily about a specific topic or issue and to understand how differing approaches shape knowledge. Assignments within the workshops are aimed at students developing their skills in forms of presentation beyond the written essay, e.g. oral argument, digital or creative projects. Collaborative work must be central to all workshop courses; these collaborative activities do not preclude the possibility of individual research/writing assignments but the Workshops should emphasize conversation, debate, collaboration, and critique more so than the individually authored essay.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST319.', NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('WGSS320', 'Women in Classical Antiquity', 3, 3, 'A study of women''s image and reality in ancient Greek and Roman societies through an examination of literary, linguistic, historical, legal, and artistic evidence; special emphasis in women''s role in the family, views of female sexuality, and the place of women in creative art. Readings in primary sources in translation and modern critical writings.', NULL, NULL, TRUE, 'DSHU, DVUP', NULL, 'CLAS320, WMST320, WGSS320 or HIST328W.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'verified', '202601', NULL, 'CLAS320, HIST328W.', NULL, NULL, NULL, NULL),
    ('WGSS325', 'The Sociology of Gender', 3, 3, 'Focuses on gender as a system of social stratification. We will examine theories and research about the institutional and cultural scaffolding that differentiates gender groups in our society. We will learn about how gender permeates major institutions, such as education, employment, family, and the State. We will explore the social forces that shape our perceptions of sex, gender, and sexuality and examine how these affect interpersonal relationships. Throughout the course, we will examine the commonalities and variations of gendered experiences across racial and ethnic groups, socioeconomic status, and sexuality. By the end of the class, you should have an informed understanding of the ways in which gender shapes our lives, experiences, and outcomes.', NULL, NULL, TRUE, NULL, NULL, 'SOCY325, WMST325 or WGSS325.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST325.', 'SOCY325.', NULL, NULL, NULL, NULL),
    ('WGSS326', 'Biology of Reproduction', 3, 3, 'The biology of the reproductive system with emphasis on mammals and, in particular, on human reproduction. Hormone actions, sperm production, ovulation, sexual differentiation, sexual behavior, contraception, pregnancy, lactation, maternal behavior and menopause.', 'BSCI170 and (BSCI180 or BSCI171); or permission of the Harriet Tubman Department of Women, Gender, and Sexuality Studies; or permission of CMNS-Biological Sciences UG Program.', NULL, FALSE, NULL, NULL, 'BSCI342, WMST326 or WGSS326.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'unstructured', 'none_found', NULL, 'WMST326.', 'BSCI342.', NULL, NULL, NULL, NULL),
    ('WGSS327', 'LGBTQ Film and Media', 3, 3, 'Comparative analysis of forms, themes, and the politics of representation in film and video by and/or about LGBTQ people.', NULL, NULL, TRUE, NULL, 'Junior standing or higher.', 'LGBT327, ENGL359F, or WGSS327.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, NULL, 'LGBT327, ENGL359F.', NULL, NULL, NULL, NULL),
    ('WGSS330', 'Indigenous Feminisms', 3, 3, 'Students will engage with scholarship concerning Indigenous conceptions of gender, sexuality, family, and governance. In each unit, participants will study traditional practices, conceptions, and expressions of Indigenous feminisms; identify the disruptive tactics of settler colonialism, centering the resilience and resurgence of Indigenous communities. In a collaborative "pod" framework, students will engage in discussions and projects throughout the term. By the end of the course, students will craft a creative project reflecting their insights and intended contribution to Indigenous feminist movements. Key focal points include the deep dive into traditional conceptions of gender, the impact of colonial interventions, the complexities of Indigenous sexualities, familial adaptations under colonial strain, Indigenous governance, and Indigenous-led resistance and reclamation such as pipeline protests, protection of sacred Mauna Kea, and the MMIW movement.', NULL, NULL, TRUE, NULL, NULL, 'WGSS379I, WGSS330, or AMST328Q.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WGSS379I.', 'AMST328Q.', NULL, NULL, NULL, NULL),
    ('WGSS336', 'Psychology of Women', 3, 3, 'A study of the biology, life span development, socialization, personality, mental health, and special issues of women.', 'PSYC100.', NULL, TRUE, 'DSHS', NULL, 'PSYC336, WMST336 or WGSS 336.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'parsed', 'verified', '202608', 'WMST336.', 'PSYC336.', NULL, NULL, NULL, NULL),
    ('WGSS338', 'Topics in LGBTQ Studies', 3, 3, 'Topics course in LGBTQ Studies', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, NULL, 'LGBT338.', NULL, '9 credits if content differs.', NULL, NULL),
    ('WGSS348', 'Literary Works by Women', 3, 3, 'The context, form, style and meaning of literary works by women.', 'Must have completed at least one lower-level English literature course and one other lower-level English course; or Permission of the Harriet Tubman Department of Women, Gender, and Sexuality Studies.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'unstructured', 'none_found', NULL, 'WMST348.', 'ENGL348.', NULL, '6 credits if content differs.', NULL, NULL),
    ('WGSS358', 'Undergraduate Teaching Assistantship', 3, 3, 'Students work under the supervision of a faculty mentor to assist with an undergraduate LGBT or WGSS course while also becoming conversant in feminist, critical race, and queer pedagogical debates and approaches.', NULL, NULL, TRUE, NULL, 'Permission of the Harriet Tubman Department of Women, Gender, and Sexuality Studies.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST358.', NULL, NULL, '9 credits.', NULL, NULL),
    ('WGSS360', 'Caribbean Women', 3, 3, 'An interdisciplinary analysis of the lives and experiences of women across the Caribbean region, through an examination of their roles in individual, national, social and cultural formations. Special emphasis on contemporary women''s issues and organizations.', NULL, NULL, TRUE, NULL, NULL, 'WGSS360, WMST360, AAAS361 or AASP361.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST360.', 'AAAS361.', NULL, NULL, NULL, NULL),
    ('WGSS368', 'Undergraduate WGSS Internship', 3, 6, 'Undergraduate Internship in a position related to women, gender, and sexuality studies and overseen by a member of the WGSS faculty.', NULL, NULL, TRUE, NULL, 'Permission of the Harriet Tubman Department of Women, Gender, and Sexuality Studies; and must have Learning Proposal approved by WGSS Academic Advisor; and junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST386 and WMST368.', NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('WGSS369', 'Special Topics in Study Abroad III', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST369.', NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('WGSS370', 'Black Feminist Thought', 3, 3, 'Examines the ideas, words and actions of Black women writers, speakers, artists, and activists in the United States.', '1 course in AASP; or 1 course in WGSS.', NULL, FALSE, NULL, NULL, 'WMST370, WGSS370, AAAS371 or AASP371.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'unstructured', 'none_found', NULL, 'WMST370.', 'AAAS371.', NULL, NULL, NULL, NULL),
    ('WGSS378', 'Undergraduate Research and Creative Works Assistantship', 1, 3, 'The Undergraduate Research Assistant provides an opportunity to develop a deep understanding of specific research methods and topics while involving the student in a professional role that requires ethical responsibility. The precise syllabus for the URA will be personalized to the student''s interests and abilities, as well as to the specific research project and the Faculty Mentor''s expectations. The student will meet with the Faculty Mentor prior to enrolling for a URA in order to determine the responsibilities and learning goals for the semester.', NULL, NULL, TRUE, NULL, 'Permission of the Harriet Tubman Department of Women, Gender, and Sexuality Studies.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST378.', NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('WGSS379', 'Topics in Women, Gender, and Sexuality Studies', 1, 3, 'Thematic exploration of a topic in women, gender, and sexuality studies.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST379.', NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('WGSS408', 'Literature by Women Before 1800', 3, 3, 'Selected writings by women in the medieval and early modern era.', 'Must have two ENGL or WGSS courses beyond Fundamental Studies; or must have permission of the English Department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'unstructured', 'none_found', NULL, NULL, 'ENGL408.', NULL, '9 credits if content differs.', NULL, NULL),
    ('WGSS410', 'Women of the African Diaspora', 3, 3, 'Explores the lives, experiences, and cultures of women of Africa and the African diaspora--African-America, the Caribbean, and Afro-Latin America. A variety of resources and materials will be used providing a distinctive interdisciplinary perspective.', NULL, NULL, TRUE, NULL, NULL, 'WMST410 or WGSS410.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST410.', NULL, NULL, NULL, NULL, NULL),
    ('WGSS411', 'Black Queer Studies', 3, 3, 'Black Queer Studies is an intersectional and interdisciplinary approach to LGBTQ+ Studies and Black Studies. In this course, we will center Blackness to meditate upon the overlapping and interwoven categories of race, gender, and sexuality with the goal of decoupling whiteness from LGBTQ+ studies and decoupling heterosexuality from Black studies. We will look at texts from the humanities and social sciences as well literature and film in order to trace topical trajectories of Black queer thought. We will explore the meaning of queerness in relation to blackness, touch upon moments in black queer history, analyze questions of black queer representation and erasure, and press upon "hot button" topics such as queer identity and the black church, African and global queer and trans identities, Blackness and homophobia, white LGBTQ+ racism, and Black queer pleasure. Throughout we will consider how Black queer liberation can and has provided tools and a guide for our collective liberation.', NULL, NULL, TRUE, NULL, NULL, 'LGBT411, WGSS411, LGBT448L, or AAAS416.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'LGBT448L.', 'LGBT411, AAAS416.', NULL, NULL, NULL, NULL),
    ('WGSS422', 'Asian American Women and Gender', 3, 3, 'Examines Asian/American cultural production along with theories of gender and sexuality in the field of Asian American Studies. We consider how Asian American femininities/masculinities are conceived and circulated, drawing from a diverse selection of twentieth-century and contemporary texts, films and images that connect Asian American bodies to ideas of absence, danger, inscrutability, hyper- or hypo-sexuality, and virulence. Beginning with early to mid-twentieth century representations, the course attends to theories that clarify the contested relationship between the East/West and Asia/U.S. Also examined are the methods through which bodies differentiated by sex, gender, and race are managed, surveilled, and rehabilitated, with close attention to the enduring legacies of American expansionism and conquest, anti-immigration policies in the U.S., and twentieth-century wars and occupations in Asia. The course engages Women of Color feminisms, queer theory, and disability studies.', NULL, NULL, TRUE, NULL, NULL, 'AAST498G, AAST422, or WGSS 422.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'AAST498G.', 'AAST422.', NULL, NULL, NULL, NULL),
    ('WGSS425', 'Gender Roles and Social Institutions', 3, 3, 'Relationship between gender roles and the structure of one or more social institutions (e.g., the economy, the family, the political system, religion, education). The incorporation of gender roles into social institutions; perpetuation or transformation of sex roles by social institutions; how changing gender roles affect social institutions.', NULL, NULL, TRUE, NULL, NULL, 'SOCY425, WMST425 or WGSS425.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST425.', NULL, NULL, NULL, NULL, NULL),
    ('WGSS428', 'Topics in Women, Gender, and Sexuality Studies', 1, 3, 'Thematic exploration of a topic in women, gender, and sexuality studies.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST428.', NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('WGSS438', 'Advanced Topics in LGBTQ Studies', 3, 3, 'Advanced Topics in LGBTQ Studies', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, NULL, 'LGBT438.', NULL, '9 credits.', NULL, NULL),
    ('WGSS441', 'Feminism, AI, and Health', 3, 3, 'Situated at the intersection of feminist theory, AI, and health care, this interdisciplinary course will investigate the sociopolitical and ethical implications of emerging technologies in medical contexts. Drawing on feminist critiques of technology, we will explore how systems of oppression--including sexism, racism, ableism, and colonialism--shape the design, deployment, and impact of AI in health care. Students will engage with scholarly texts, discussions, and activities to analyze the historical entanglement of gender, race, and health care; the epistemic foundations of feminist knowledge production; the ethics of datafication and surveillance; and the transformative potential of feminist praxis. Coursework will include case studies, debates, and a final project envisioning inclusive, justice-oriented futures for AI in health care.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('WGSS444', 'Feminist Critical Theory', 3, 3, 'Issues in contemporary feminist thought that have particular relevance to textual studies, such as theories of language, literature, culture, interpretation, and identity.', 'WMST200, WGSS200, WMST250, WGSS250, or ENGL250.', NULL, FALSE, NULL, NULL, 'ENGL444, WMST444 or WGSS444.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'unstructured', 'none_found', NULL, 'WMST444.', 'ENGL444.', NULL, NULL, NULL, NULL),
    ('WGSS448', 'Literature by Women of Color', 3, 3, 'Literature by women of color in the United States, Britain, and in colonial and post-colonial countries.', 'Must have two ENGL or WGSS courses beyond Fundamental Studies; or must have permission of the English Department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'unstructured', 'none_found', NULL, NULL, 'ENGL448.', NULL, '9 credits if content differs.', NULL, NULL),
    ('WGSS449', 'Special Topics in LGBTQ Studies', 3, 3, 'In-depth study of particular themes and issues in LGBTQ studies.', 'LGBT200; or permission of LGBT Studies Program.', NULL, FALSE, NULL, 'Junior standing or higher.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'partial', 'none_found', NULL, NULL, 'LGBT448.', NULL, '9 credits if content differs.', NULL, NULL),
    ('WGSS452', 'Women in the Media', 3, 3, 'Participation and portrayal of women in the mass media from colonial to contemporary times.', NULL, NULL, TRUE, NULL, NULL, 'JOUR452, WMST452 or WGSS452.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST 452.', 'JOUR452.', NULL, NULL, NULL, NULL),
    ('WGSS455', 'Women in Medieval Culture and Society', 3, 3, 'Medieval women''s identity and cultural roles: the condition, rank and rights of medieval women; their access to power; a study of women''s writings and the constraints of social constructs upon the female authorial voice; and contemporary assumptions about women.', NULL, NULL, TRUE, NULL, NULL, 'HIST495, WMST455 or WGSS455.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST455.', 'HIST495.', NULL, NULL, NULL, NULL),
    ('WGSS456', 'Women and Society in the Middle East', 3, 3, 'Examines the customs, values and institutions that have shaped women''s experience in the Middle East in the past and in the contemporary Middle East.', NULL, NULL, TRUE, NULL, NULL, 'HIST492, WMST456 or WGSS456.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST456.', 'HIST492.', NULL, NULL, 'Prior coursework in Middle East studies or gender studies.', NULL),
    ('WGSS458', 'Literature by Women After 1800', 3, 3, 'Selected writings by women after 1800.', 'Must have two ENGL or WGSS courses beyond Fundamental Studies; or must have permission of the English Department.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'unstructured', 'none_found', NULL, NULL, 'ENGL458.', NULL, '9 credits if content differs.', NULL, NULL),
    ('WGSS468', 'Feminist Cultural Studies', 3, 3, 'Each version of this course focuses on one or several forms of popular culture -- such as TV, music, film, cyber-culture, or genre fiction (for example, science fiction) -- and demonstrates how feminists value, critique and explain such forms. Tools of feminist cultural studies include economic and social analyses of power, race, sexuality, gender, class, nationality, religion, technology, and globalization processes.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST468.', NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('WGSS469', 'Study Abroad Special Topics IV', 1, 6, 'Special topics course taken as part of an approved study abroad program.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST469.', NULL, NULL, '15 credits if content differs.', NULL, NULL),
    ('WGSS471', 'Women''s Health', 3, 3, 'Women''s health issues and the barriers faced by women striving to achieve a healthy lifestyle. Emphasis is placed on socio-cultural, historical, political, economic, and behavioral factors. Students will examine topics including access to healthcare, women in the workforce, women''s sexual and reproductive health, preventive health, screenings and wellness, and the interpersonal and social aspects of women''s health. This course is designed to support students in their personal exploration of attitudes, knowledge, and values related to women''s health and to assist them as they analyze their individual behaviors.', NULL, NULL, TRUE, NULL, 'Must be in a program in the Harriet Tubman Department of Women, Gender, and Sexuality Studies; or must be in a major within SPHL-Behavioral & Community Health department.', 'HLTH471, WMST471, or WGSS471.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST471.', 'HLTH471.', NULL, NULL, NULL, NULL),
    ('WGSS475', 'Magical Black Femmes: Queering Black Femininity', 3, 3, 'Queer femme identity, rooted in 1940s and 1950s bar culture, continues to resonate. Often linked with butch, femme is a queer, feminine expression that challenges the binary tying femininity to cisgender, heterosexual women. Femme exists outside that frame. Black women have long moved beyond white heteropatriarchal norms, and Black femmes of all genders have turned that resistance into power. This course explores Black femme identity as a radical critique of gender, sexuality, and whiteness. Through cultural studies and humanities methods, we will examine femme''s complexity and how it unsettles what we assume about queerness, femininity, and identity.', NULL, NULL, TRUE, NULL, NULL, 'LGBT475, WGSS475, AAAS475 or LGBT448E.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'LGBT448E.', 'LGBT475, AAAS475.', NULL, NULL, 'LGBT200 or another LGBT course.', NULL),
    ('WGSS486', 'Advanced Feminist, Critical Race, and Queer Theories', 3, 3, 'Provides undergraduates with a survey of foundational texts in the intersecting fields of feminist, critical race, and queer studies, as well as an overview of current scholarship in order to give students an opportunity to understand the origins and the development of these fields. This course is especially recommended for students interested in pursuing graduate education. Our discussions will be focused on the trajectories of these intellectual conversations as they have developed in the academy.', 'WMST301 or permission of the Harriet Tubman Department of Women, Gender, and Sexuality Studies.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('WGSS487', 'Advanced Projects Seminar in Gender, Race, and Queer Studies', 3, 3, 'A research seminar that allows students to focus their developed skills on a single topic of their own choosing while meeting regularly in seminar to discuss, critique, support, and learn from their peers'' projects and assessments. Students choose a topic based on their own interests and prior coursework, perform advanced research appropriate to the question, and formulate an appropriate method of presentation of their research findings. The culminating presentation may take the form of a written paper or a creative, digital, or activist project.', 'WGSS301.', NULL, TRUE, NULL, 'Must be in an undergraduate program in the Harriet Tubman Department of Women, Gender, and Sexuality Studies.', 'WMST487 or WGSS487.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'parsed', 'none_found', NULL, 'WMST487.', NULL, NULL, NULL, NULL, NULL),
    ('WGSS488', 'Advanced Seminar', 3, 3, 'Seminar for advanced majors in women''s studies or other students with appropriate preparation. Interdisciplinary topics will vary each semester.', NULL, NULL, TRUE, NULL, 'Permission of the Harriet Tubman Department of Women, Gender, and Sexuality Studies.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, NULL, NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('WGSS489', 'Individual Research in Gender, Race and Queer Studies', 3, 3, 'Allows students who wish to continue the research they began in WMST487 or WGSS487 to do so under the guidance of an individual faculty mentor. Each student taking this class will develop an individual syllabus based on the project on which they are working, with the goal of developing a work of scholarship specific to their interests that can serve as an entry point for graduate study or professional work.', 'WMST487 or WGSS487.', NULL, FALSE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'unstructured', 'none_found', NULL, NULL, NULL, NULL, '9 credits.', NULL, NULL),
    ('WGSS491', 'Judaism and the Construction of Gender', 3, 3, 'The study of Jewish culture, religious practice, communal authority, and literature through the frame of such critical categories of analysis as gender, sexuality, masculinity, power, ethics, and the feminine.', '1 course in JWST; or 1 course in LGBT; or 1 course in WMST or WGSS.', NULL, FALSE, NULL, NULL, 'JWST491, WMST491 or WGSS491.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'unstructured', 'none_found', NULL, 'WMST491.', 'JWST491.', NULL, NULL, NULL, NULL),
    ('WGSS492', 'Sex, Gender, and Jewish Identity', 3, 3, 'An exploration of Jewish embodiment, including dynamics related to biological sex, culturally-framed gender, and sexuality. Topics of discussion may include transgender and intersex Jews, stereotypes and gender performance, modesty, genetics, and body alteration. Focus is on contemporary Jewish culture, framed within the larger historical and textual tradition.', '1 course in WGSS; or 1 course in JWST; or 1 course in LGBT; or permission of instructor.', NULL, FALSE, NULL, NULL, 'JWST492, JWST409G, LGBT448W, WMST498W or WGSS492.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'unstructured', 'none_found', NULL, 'WMST498W and JWST409G.', 'JWST492, LGBT448W.', NULL, NULL, NULL, NULL),
    ('WGSS496', 'African-American Women Filmmakers', 3, 3, 'Examines the cinematic artistry of African-American women filmmakers and the ways in which these films address the dual and inseparable roles of race and gender.', NULL, NULL, TRUE, NULL, NULL, 'WMST496 or WGSS496.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST496.', NULL, NULL, NULL, NULL, NULL),
    ('WGSS497', 'Professional Development', 1, 1, 'To assist students in thinking about the next step post-undergraduate degree and to think long term about the importance of their WMST degree in lifelong career, personal, and political development. This course will provide students an opportunity to reflect upon where they are going beyond the B.A. and develop ways to communicate how their coursework and experiences at UMD have prepared them for the next step. The course will focus on the practicalities of resume writing, internship or job searches, etc. but also on the specific challenges/opportunities of translating interdisciplinary training to professional internship or beyond-the B.A. sites. Students may take this course in preparation for their internship (working to select an appropriate internship that can translate well to post-undergraduate aspirations) or they may take it post-internship as they determine their post-graduation steps.', '12 credits in LGBT, WMST or WGSS courses.', NULL, FALSE, NULL, 'Must have completed a minimum of 75 credits.', 'WMST497 or WGSS497.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'unstructured', 'none_found', NULL, 'WMST497.', NULL, NULL, NULL, NULL, NULL),
    ('WGSS498', 'Advanced Special Topics in Women, Gender, and Sexuality Studies', 1, 3, 'Advanced study of a thematic topic in women, gender, and sexuality studies.', NULL, NULL, TRUE, NULL, 'Permission of the Harriet Tubman Department of Women, Gender, and Sexuality Studies.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'none', 'none_found', NULL, 'WMST498.', NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('WGSS499', 'Independent Study', 1, 3, 'Research and writing or specific readings on a topic selected by the student and supervised by a faculty member of the Women''s Studies Department.', '1 course in WMST or WGSS.', NULL, FALSE, NULL, 'Permission of the Harriet Tubman Department of Women, Gender, and Sexuality Studies.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wgss/', 'unstructured', 'none_found', NULL, 'WMST499.', NULL, NULL, '9 credits if content differs.', NULL, NULL),
    ('WMSX200', 'Gender, Equality, and Sexuality in Scandinavia', 3, 3, 'Sweden is one of the most gender equal countries in the world and is well-known for its progressive culture supported by forward-thinking laws and legislation. This course explores how concepts of gender, body, sexuality and race intersect in current debates about changing family structures, children''s rights, and new ethical dilemmas in a changing Scandinavia.', NULL, NULL, TRUE, NULL, NULL, 'WMSX200 or LGBX200.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wmsx/', 'none', 'none_found', NULL, NULL, 'LGBX200.', NULL, NULL, NULL, 'This course is offered as part of the Maryland-in-Stockholm study abroad program. Students must apply for this program through Education Abroad: More information at ter.ps/UMStockholm. Education Abroad processes registrations for this course on behalf of students.'),
    ('WMSX201', 'Sex Education and Sexual Reform in Europe', 3, 3, 'Provides insight to the ways in which sexual reform and sex education has shaped not only the history of sexuality in Europe, but also the very core of the various national identities. We will look into the different movements, campaigns, policies, and public debates regarding sexuality. We will discover the ways in which sex and sexuality are conveyed in sexual education aimed at children and youth by reading and watching examples of sex educational material.', NULL, NULL, TRUE, NULL, NULL, 'WMSX201 or LGBX201.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wmsx/', 'none', 'none_found', NULL, NULL, 'LGBX201.', NULL, NULL, NULL, 'This course is offered as part of the Maryland-in-Stockholm study abroad program. Students must apply for this program through Education Abroad: More information at ter.ps/UMStockholm. Education Abroad processes registrations for this course on behalf of students.'),
    ('WMSX202', 'Transgender in Scandinavia', 3, 3, 'This course explores the history of trans activism with a special focus on Sweden, and how legislative and medical discourses change how we think about gender identities and rights. We also explore topics such as transphobia, gender disclosure and HIV criminalization laws, reproductive rights, gender-neutral pronouns, transgender children and their families, and how race and class intersect with being trans.', NULL, NULL, TRUE, NULL, NULL, 'WMSX202 or LGBX202.', '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wmsx/', 'none', 'none_found', NULL, NULL, 'LGBX202.', NULL, NULL, NULL, 'This course is offered as part of the Maryland-in-Stockholm study abroad program. Students must apply for this program through Education Abroad: More information at ter.ps/UMStockholm. Education Abroad processes registrations for this course on behalf of students.'),
    ('WMSX203', 'Economics of Gender', 3, 3, 'Decisions around marriage, children, and work are taken by everyone on the planet. In this class we look at the economic elements that forge those choices. Moreover, while women''s roles have changed beyond recognition in a century, we are still plagued with a dramatic under-representation of women in senior economic roles and the fact that they appear underpaid vis a vis men for doing the same work. This course looks at the factors influencing such issues, providing often surprising results.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wmsx/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'This course is offered as part of the Maryland-in-Stockholm study abroad program. Students must apply for this program through Education Abroad: More information at ter.ps/UMStockholm. Education Abroad processes registrations for this course on behalf of students.'),
    ('WMSX204', 'Nice Girls, Bad Girls, and Bitches: British Women and Gender from the Vote to Thatcher', 3, 3, 'Explores the words and experiences of British women in a century of rapid social, economic and cultural transformation - when what it meant to be a ''British woman'' was itself revolutionized, through decolonization and immigration. We will determine the constraints on women in war and peace, politics, education and paid work, marriage, motherhood and family, and celebrate rebels and non-conformists.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wmsx/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'This course is offered as part of the Arts & Humanities-in-London study abroad program. Students must apply for this program through Education Abroad: More information at https://globalmaryland.umd.edu/offices/education-abroad/program/11854. Education Abroad processes registrations for this course on behalf of students.'),
    ('WMSX300', 'Feminism(s)', 6, 6, 'Engages with contemporary feminist thought through literature, literary criticism, history and theory of feminism. It examines the significant debates and key concepts of feminist thought through a range of political and philosophical texts and encourages students to develop their own critical understanding of gender and equality issues in the contemporary period. Explores feminism in relation to Marxism, psychoanalysis, sexuality, post-structuralism, neo-liberalism and international feminism.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wmsx/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'This course is offered as part of the ARHU-in-London study abroad program. Students must apply for this program through Education Abroad: More information at globalmaryland.umd.edu/offices/education-abroad/program/11854. Education Abroad processes registrations for this course on behalf of students.'),
    ('WMSX301', 'The Rising Generation: Youth, Age and Protest in Post-War Britain', 3, 3, 'Explores important empirical and methodological questions about age, gender and sexuality, using a case study of post-war Britain. Considers the histories of "muted groups" such as children, adolescents, women and LGBT people, while thinking about how the language used about such groups is used to structure power relations in society. Engages with the ways conservatives and radicals used the language of age and life-stage to construct visions of the future, and how the experience of childhood, adolescence, adulthood and old age changed in Britain between 1945 and 1979.', NULL, NULL, TRUE, NULL, NULL, NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/wmsx/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('XPER433', 'Xperiment to Address Grand Challenges', 3, 3, 'Students will collaborate with each other using creative approaches to address complex real-world challenges. You will develop skills for interdisciplinary teamwork, problem-solving, and idea testing through hands-on experiences and guided discussions and reflections. By the end, you will form a multidisciplinary team of co-innovators ready to design a solution to a well-defined, real-world problem.', NULL, NULL, TRUE, NULL, 'Permission required by the xFoundry Program.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/xper/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'For more information, and to request permission to enroll, visit https://xfoundry.umd.edu/xperience.'),
    ('XPER444', 'Xperiment II: Bringing Your Idea to Life', 3, 3, 'Students will work in teams to design, develop, and iterate on solutions for the grand challenge problem. This course aims to equip students with the strategic skills essential for the successful design and implementation of effective solutions. They will explore methodologies for validating the feasibility and viability of proposed solutions, with a strong emphasis on conducting thorough customer feedback analysis to refine and validate product concepts. By the end of this course, students will have a working and tested prototype of their solution, showcasing their applied knowledge and practical skills in addressing complex challenges. This is the second course in xFoundry''s signature academic program.', NULL, NULL, TRUE, NULL, 'Must be in the Xperience academic program; and permission of department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/xper/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, 'For more information on Xperiment, visit: xfoundry.umd.edu/programs/xperience/xperiment.'),
    ('XPER455', 'Xperiment III: Scaling Your Grand Challenge Solution', 3, 3, 'Student teams will refine their grand challenge solutions with feedback from mentors, design testing frameworks, and analyze results to guide decision-making. They will explore advanced marketing strategies, craft compelling messages and apply insights from successful campaigns to enhance project visibility. Additionally, the course emphasizes the necessary communication skills for conveying goals and outcomes alongside insights into revenue models for sustainable financial viability. By the end of this course, students will have designed a Minimum Viable Product', NULL, NULL, TRUE, NULL, 'Must be a student accepted into xFoundry''s Xperiment Academic Track and permission of department.', NULL, '2026-2027', 'https://academiccatalog.umd.edu/undergraduate/approved-courses/xper/', 'none', 'none_found', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO courses (university_id, code, name, credits_min, credits_max, description, prerequisite_text, corequisite_text, prerequisites_complete, gen_ed_text, restriction_text, credit_only_granted_for, catalog_year, source_url, prerequisite_status, gen_ed_status, gen_ed_term, formerly, cross_listed_with, jointly_offered_with, repeatable_to, recommended, additional_information)
SELECT (SELECT id FROM universities WHERE name = 'University of Maryland, College Park'), * FROM import_courses
ON CONFLICT (university_id, code) DO UPDATE SET name = EXCLUDED.name, credits_min = EXCLUDED.credits_min, credits_max = EXCLUDED.credits_max, description = EXCLUDED.description, prerequisite_text = EXCLUDED.prerequisite_text, corequisite_text = EXCLUDED.corequisite_text, prerequisites_complete = EXCLUDED.prerequisites_complete, gen_ed_text = EXCLUDED.gen_ed_text, restriction_text = EXCLUDED.restriction_text, credit_only_granted_for = EXCLUDED.credit_only_granted_for, catalog_year = EXCLUDED.catalog_year, source_url = EXCLUDED.source_url, prerequisite_status = EXCLUDED.prerequisite_status, gen_ed_status = EXCLUDED.gen_ed_status, gen_ed_term = EXCLUDED.gen_ed_term, formerly = EXCLUDED.formerly, cross_listed_with = EXCLUDED.cross_listed_with, jointly_offered_with = EXCLUDED.jointly_offered_with, repeatable_to = EXCLUDED.repeatable_to, recommended = EXCLUDED.recommended, additional_information = EXCLUDED.additional_information, in_current_catalog = TRUE;
-- Courses no longer in the catalog are kept for students who completed them.
UPDATE courses SET in_current_catalog = FALSE WHERE university_id = (SELECT id FROM universities WHERE name = 'University of Maryland, College Park')
    AND code NOT IN (SELECT code FROM import_courses);

-- Derived data is rebuilt. No student data references these tables.
DELETE FROM prerequisite_groups WHERE course_id IN (SELECT id FROM courses WHERE university_id = (SELECT id FROM universities WHERE name = 'University of Maryland, College Park'));
DELETE FROM course_gen_ed WHERE course_id IN (SELECT id FROM courses WHERE university_id = (SELECT id FROM universities WHERE name = 'University of Maryland, College Park'));
DELETE FROM course_restrictions WHERE course_id IN (SELECT id FROM courses WHERE university_id = (SELECT id FROM universities WHERE name = 'University of Maryland, College Park'));
DELETE FROM course_exclusions WHERE course_id IN (SELECT id FROM courses WHERE university_id = (SELECT id FROM universities WHERE name = 'University of Maryland, College Park'));
DELETE FROM requirements WHERE university_id = (SELECT id FROM universities WHERE name = 'University of Maryland, College Park')
    OR program_id IN (SELECT id FROM programs WHERE university_id = (SELECT id FROM universities WHERE name = 'University of Maryland, College Park'));

